window.BARALHOS['en'] = {"versao":1,"idioma":"en","curso":"en-pt","leva":"5f927f46","total":1000,"cards":[{"idioma":"en","id":"en-p001","tipo":"palavra","en":"to pretend","pt":"fingir","aceitas":["fingir","simular","fazer de conta","fazer que"],"aceitasEn":["to pretend","pretend","to make believe"],"distratores":["prometer","planejar","prender","adivinhar"],"nivel":"B1","tags":["falso-amigo","verbo"],"nota":"«Pretend» é fingir, fazer de conta. Quem pretende fazer algo «intends to» ou «plans to».\n🇺🇸 to pretend → 🇧🇷 fingir\n🇺🇸 to intend → 🇧🇷 pretender","v":"c5749451"},{"idioma":"en","id":"en-u001","tipo":"frase","requer":"en-p001","en":"He pretended to be asleep.","pt":"Ele fingiu estar dormindo.","aceitas":["ele fingiu estar dormindo","fingiu estar dormindo","ele fingiu que estava dormindo","ele fez de conta que estava dormindo","ele fingiu dormir"],"aceitasEn":["he pretended to be asleep","he pretended he was asleep","he was pretending to be asleep"],"distratores":["Ele jurou estar dormindo.","Ele parecia estar dormindo.","Ele negou estar dormindo.","Ele admitiu estar dormindo."],"nivel":"B1","tags":["falso-amigo","cotidiano"],"nota":"Depois de «pretend» vem «to» + verbo, ou uma oração inteira: «he pretended that he was asleep». Sozinho também se usa: «I'm not asleep, I'm pretending».","v":"4ad2d412"},{"idioma":"en","id":"en-p002","tipo":"palavra","en":"actually","pt":"na verdade","aceitas":["na verdade","na realidade","de fato","pra falar a verdade"],"aceitasEn":["actually","in fact","in reality"],"distratores":["atualmente","hoje em dia","com certeza","por acaso"],"nivel":"A2","tags":["falso-amigo"],"nota":"«Actually» corrige ou contraria o que se acabou de dizer. O nosso «atualmente» é «currently» ou «nowadays».\n🇺🇸 actually → 🇧🇷 na verdade\n🇺🇸 currently → 🇧🇷 atualmente","v":"952a4fd6"},{"idioma":"en","id":"en-u002","tipo":"frase","requer":"en-p002","en":"Actually, I don't agree.","pt":"Na verdade, eu não concordo.","aceitas":["na verdade eu nao concordo","na verdade nao concordo","na realidade nao concordo","de fato nao concordo","pra falar a verdade nao concordo"],"aceitasEn":["actually i dont agree","actually i do not agree","in fact i dont agree"],"distratores":["Atualmente, eu não concordo.","Por enquanto, eu não concordo.","Com certeza, eu não concordo.","Por acaso, eu não concordo."],"nivel":"A2","tags":["falso-amigo","cotidiano"],"nota":"«Actually» abre a frase para discordar sem brigar — é o nosso «na verdade» de quem vai contrariar com jeito.","v":"4c9d6fd3"},{"idioma":"en","id":"en-p003","tipo":"palavra","en":"the shelf","pt":"a prateleira","aceitas":["a prateleira","a estante"],"aceitasEn":["the shelf","shelf"],"distratores":["a gaveta","o armário","a bandeja","o degrau"],"nivel":"A2","tags":["casa","substantivo"],"nota":"«Shelf» é a tábua; o móvel inteiro é «bookcase». O plural é irregular, como o de «wolf»: «two shelves».","v":"98d84162"},{"idioma":"en","id":"en-u003","tipo":"frase","requer":"en-p003","en":"Put the books on the shelf.","pt":"Ponha os livros na prateleira.","aceitas":["ponha os livros na prateleira","poe os livros na prateleira","coloque os livros na prateleira","coloca os livros na prateleira","bote os livros na prateleira"],"aceitasEn":["put the books on the shelf","put the books onto the shelf"],"distratores":["Ponha os livros na gaveta.","Ponha os livros na mesa.","Ponha os livros na caixa.","Ponha os livros na mochila."],"nivel":"A2","tags":["casa","cotidiano"],"nota":"Em cima de superfície é «on»: «on the shelf», «on the table». «In the shelf» seria dentro da tábua.","v":"52fa9623"},{"idioma":"en","id":"en-p004","tipo":"palavra","en":"to afford","pt":"ter dinheiro para","aceitas":["ter dinheiro para","poder pagar","ter condicoes de pagar","bancar","ter grana para"],"aceitasEn":["to afford","afford","to be able to afford"],"distratores":["ter vontade de","ter tempo para","ter coragem de","ter permissão para"],"nivel":"B2","tags":["verbo","economia"],"nota":"«Afford» quase sempre vem com «can»: «I can't afford it». E não é só dinheiro — «I can't afford to wait» é não poder se dar ao luxo de esperar.","v":"4f9baba4"},{"idioma":"en","id":"en-u004","tipo":"frase","requer":"en-p004","en":"I can't afford a new car.","pt":"Não tenho dinheiro para um carro novo.","aceitas":["nao tenho dinheiro para um carro novo","nao posso pagar um carro novo","nao tenho como comprar um carro novo","nao da para eu comprar um carro novo","nao tenho condicoes de comprar um carro novo"],"aceitasEn":["i cant afford a new car","i cannot afford a new car","i cant afford to buy a new car"],"distratores":["Não tenho vontade de comprar um carro novo.","Não tenho tempo de escolher um carro novo.","Não tenho espaço para um carro novo.","Não tenho coragem de comprar um carro novo."],"nivel":"B2","tags":["economia","cotidiano"],"nota":"O inglês não tem verbo para «ter dinheiro para»: resolve tudo com «afford», e por isso ele aparece muito mais do que se imagina.","v":"47090006"},{"idioma":"en","id":"en-p005","tipo":"palavra","en":"eventually","pt":"por fim","aceitas":["por fim","no fim","no final","com o tempo","mais cedo ou mais tarde","acabou acontecendo"],"aceitasEn":["eventually","in the end","sooner or later"],"distratores":["eventualmente","de vez em quando","por acaso","de repente"],"nivel":"B1","tags":["falso-amigo"],"nota":"«Eventually» é o que acaba acontecendo depois de um tempo. O nosso «eventualmente», de vez em quando, é «occasionally».\n🇺🇸 eventually → 🇧🇷 por fim\n🇺🇸 occasionally → 🇧🇷 eventualmente","v":"c6cb52fd"},{"idioma":"en","id":"en-u005","tipo":"frase","requer":"en-p005","en":"We eventually found the place.","pt":"No fim, achamos o lugar.","aceitas":["no fim achamos o lugar","no final achamos o lugar","acabamos achando o lugar","por fim encontramos o lugar","no fim encontramos o lugar","acabamos encontrando o lugar"],"aceitasEn":["we eventually found the place","eventually we found the place","we found the place in the end"],"distratores":["Eventualmente, achamos o lugar.","De vez em quando, achamos o lugar.","Por acaso, achamos o lugar.","De repente, achamos o lugar."],"nivel":"B1","tags":["falso-amigo","cotidiano"],"nota":"«Eventually» traz a ideia de demora: procuramos, custou, e no fim achamos. Fica antes do verbo ou no começo da frase.","v":"5a3902e7"},{"idioma":"en","id":"en-p006","tipo":"palavra","en":"the sink","pt":"a pia","aceitas":["a pia","a cuba"],"aceitasEn":["the sink","sink","the kitchen sink"],"distratores":["a torneira","o ralo","a banheira","o balde"],"nivel":"A2","tags":["casa","substantivo"],"nota":"«Sink» é a pia da cozinha e a do banheiro. A torneira é «the faucet» nos Estados Unidos e «the tap» na Inglaterra.","v":"635d7c9f"},{"idioma":"en","id":"en-u006","tipo":"frase","requer":"en-p006","en":"The dishes are in the sink.","pt":"A louça está na pia.","aceitas":["a louca esta na pia","os pratos estao na pia","tem louca na pia","a louca ta na pia"],"aceitasEn":["the dishes are in the sink","the plates are in the sink"],"distratores":["A louça está na mesa.","A louça está na gaveta.","A louça está na máquina.","A louça está na bancada."],"nivel":"A2","tags":["casa","cotidiano"],"nota":"Dentro da pia é «in the sink», e não «on». «The dishes» é a louça toda; um prato só é «a dish» ou «a plate».","v":"9b168f15"},{"idioma":"en","id":"en-p007","tipo":"palavra","en":"to support","pt":"apoiar","aceitas":["apoiar","dar apoio","sustentar","torcer por"],"aceitasEn":["to support","support","to back"],"distratores":["supervisionar","supor","suprir","substituir"],"nivel":"B1","tags":["falso-amigo","verbo"],"nota":"«Support» é apoiar, e também sustentar quem depende de você. Suportar, no sentido de aguentar, é «to bear» ou «to put up with».\n🇺🇸 to support → 🇧🇷 apoiar\n🇺🇸 to bear → 🇧🇷 suportar","v":"3b95608b"},{"idioma":"en","id":"en-u007","tipo":"frase","requer":"en-p007","en":"My family supports me.","pt":"Minha família me apoia.","aceitas":["minha familia me apoia","a minha familia me apoia","minha familia me da apoio","minha familia esta do meu lado"],"aceitasEn":["my family supports me","my family support me","my family is behind me"],"distratores":["Minha família me suporta.","Minha família me tolera.","Minha família me entende.","Minha família me cobra."],"nivel":"B1","tags":["falso-amigo","família"],"nota":"Do lado do outro: «I support you» é estou com você. Quem aguenta mau humor «puts up with» — o inglês separa as duas coisas que o português junta em «suportar».","v":"9421c0c4"},{"idioma":"en","id":"en-p008","tipo":"palavra","en":"the spoon","pt":"a colher","aceitas":["a colher"],"aceitasEn":["the spoon","spoon"],"distratores":["o garfo","a faca","o prato","a xícara"],"nivel":"A1","tags":["comida","casa","substantivo"],"nota":"«Fork» é garfo, «knife» é faca (o k não se pronuncia) e «spoon» é colher. A de cafezinho é «teaspoon».","v":"4144df58"},{"idioma":"en","id":"en-u008","tipo":"frase","requer":"en-p008","en":"I need a spoon for the soup.","pt":"Preciso de uma colher para a sopa.","aceitas":["preciso de uma colher para a sopa","preciso de uma colher pra sopa","queria uma colher para a sopa","eu preciso de colher para a sopa"],"aceitasEn":["i need a spoon for the soup","i need a spoon to eat the soup"],"distratores":["Preciso de um garfo para a sopa.","Preciso de uma faca para a sopa.","Preciso de um prato para a sopa.","Preciso de um guardanapo para a sopa."],"nivel":"A1","tags":["comida","cotidiano"],"nota":"Objeto contável pede artigo: «a spoon», e nunca «I need spoon». No plural, «spoons», sem artigo nenhum.","v":"60d7c7d0"},{"idioma":"en","id":"en-f001","tipo":"frase","en":"I'm looking forward to it.","pt":"Mal posso esperar.","aceitas":["mal posso esperar","estou ansioso por isso","estou ansiosa por isso","nao vejo a hora","to ansioso por isso","estou doido para isso"],"aceitasEn":["im looking forward to it","i am looking forward to it","i cant wait"],"distratores":["Tenho que esperar um pouco.","Vou esperar sentado.","Estou cansado de esperar.","Espero que sim."],"nivel":"B1","tags":["expressão","cotidiano"],"nota":"Depois de «look forward to» vem substantivo ou verbo em -ing: «I'm looking forward to seeing you». É também o fecho educado de e-mail: «I look forward to hearing from you».","v":"411c28be"},{"idioma":"en","id":"en-f002","tipo":"frase","en":"We ran out of milk.","pt":"Acabou o leite.","aceitas":["acabou o leite","ficamos sem leite","o leite acabou","acabou o nosso leite","nao tem mais leite"],"aceitasEn":["we ran out of milk","weve run out of milk","we have run out of milk"],"distratores":["Derramamos o leite.","Compramos leite demais.","Esquecemos o leite.","Sobrou leite."],"nivel":"B1","tags":["phrasal verb","comida"],"nota":"«Run out of» é acabar o estoque de alguma coisa. Sem o «of» o sujeito muda: «the milk ran out» é o leite que acabou, e «he ran out» é ele que saiu correndo.","v":"f8c7a58d"},{"idioma":"en","id":"en-f003","tipo":"frase","en":"It's up to you.","pt":"Você que sabe.","aceitas":["voce que sabe","voce decide","fica a seu criterio","a decisao e sua","como voce quiser","depende de voce"],"aceitasEn":["its up to you","it is up to you","thats up to you"],"distratores":["Estou contando com você.","Já falei com você.","Isso é culpa sua.","Chegou a sua vez."],"nivel":"B1","tags":["expressão","cotidiano"],"nota":"«Up to» aqui é de quem é a decisão. A mesma dupla em «What are you up to?» é outra coisa: o que você anda aprontando.","v":"2c79c6a3"},{"idioma":"en","id":"en-f004","tipo":"frase","en":"I have to put up with him.","pt":"Tenho que aguentar ele.","aceitas":["tenho que aguentar ele","tenho que aguenta lo","preciso aguentar ele","tenho que suportar ele","nao tem jeito tenho que aguentar ele"],"aceitasEn":["i have to put up with him","ive got to put up with him","i have to put up with the guy"],"distratores":["Tenho que ajudar ele.","Tenho que enfrentar ele.","Tenho que evitar ele.","Tenho que obedecer ele."],"nivel":"B2","tags":["phrasal verb","cotidiano"],"nota":"«Put up with» é aguentar gente ou situação, e as três palavras andam sempre juntas. «Put up» sozinho é hospedar: «they put me up for the night».","v":"208b85fd"},{"idioma":"en","id":"en-f005","tipo":"frase","en":"How long have you lived here?","pt":"Há quanto tempo você mora aqui?","aceitas":["ha quanto tempo voce mora aqui","faz quanto tempo que voce mora aqui","voce mora aqui ha quanto tempo","ha quanto tempo voce vive aqui","tem quanto tempo que voce mora aqui"],"aceitasEn":["how long have you lived here","how long have you been living here"],"distratores":["Quanto tempo você morou aqui?","Quando você veio morar aqui?","Até quando você vai morar aqui?","Por quanto tempo você vai morar aqui?"],"nivel":"B1","tags":["gramática","present perfect"],"nota":"O que começou antes e continua até hoje vai no present perfect: «I have lived here for ten years». O português resolve com o presente e um «há», e por isso a forma inglesa não ocorre a ninguém.","v":"4846903b"},{"idioma":"en","id":"en-f006","tipo":"frase","en":"It depends on the weather.","pt":"Depende do tempo.","aceitas":["depende do tempo","depende do clima","vai depender do tempo"],"aceitasEn":["it depends on the weather","that depends on the weather"],"distratores":["Combina com o tempo.","Muda com o tempo.","Fala do tempo.","Reclama do tempo."],"nivel":"A2","tags":["preposição","gramática"],"nota":"«Depend» pede «on», sempre: «it depends on you», «it depends on the price». Sozinho, no fim da frase, também se diz: «it depends».","v":"2b9e67cb"},{"idioma":"en","id":"en-f007","tipo":"frase","en":"I used to smoke.","pt":"Eu fumava.","aceitas":["eu fumava","fumava","eu costumava fumar","antes eu fumava"],"aceitasEn":["i used to smoke","i used to be a smoker"],"distratores":["Eu fumei.","Eu fumo.","Eu costumo fumar.","Eu fumaria."],"nivel":"B1","tags":["gramática","imperfeito"],"nota":"«Used to» é o hábito que acabou: «I used to smoke, but I quit». Não existe no presente — para o hábito de hoje é «I usually smoke».","v":"99eeeee8"},{"idioma":"en","id":"en-f008","tipo":"frase","en":"Never mind.","pt":"Deixa pra lá.","aceitas":["deixa pra la","deixa quieto","esquece","deixa isso pra la","nao esquenta","tanto faz"],"aceitasEn":["never mind","nevermind","dont worry about it"],"distratores":["Nunca se importe.","Nunca pense nisso.","Não é da sua conta.","Nem me lembro mais."],"nivel":"B1","tags":["expressão","cotidiano"],"nota":"«Never mind» encerra o assunto: esquece, não precisa responder. Serve também para retirar o que se acabou de dizer, quando a resposta já veio sozinha.","v":"020d5c60"},{"idioma":"en","id":"en-v001","tipo":"frase","en":"I brought the wine.","pt":"Eu trouxe o vinho.","aceitas":["eu trouxe o vinho","trouxe o vinho","eu trouxe vinho"],"aceitasEn":["i brought the wine","i have brought the wine"],"distratores":["Eu trago o vinho.","Eu trarei o vinho.","Eu traria o vinho.","Eu tinha trazido o vinho."],"formasEn":{"I bring the wine":"presente","I will bring the wine":"futuro","I would bring the wine":"condicional","I had brought the wine":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","irregular","bring","pretérito"],"nota":"«Bring» faz «brought» no passado e no particípio — uma forma só para os dois. Trazer é «bring», para cá; levar é «take», para lá.","v":"4bdb82a7"},{"idioma":"en","id":"en-v002","tipo":"frase","en":"I have already eaten.","pt":"Eu já comi.","aceitas":["eu ja comi","ja comi","eu comi ja"],"aceitasEn":["i have already eaten","ive already eaten","i already ate"],"distratores":["Eu como sempre.","Eu vou comer já.","Eu tinha comido.","Eu estou comendo."],"formasEn":{"I eat every day":"presente","I will eat later":"futuro","I had eaten before":"mais-que-perfeito","I am eating now":"gerúndio"},"nivel":"B1","tags":["conjugação","present perfect","eat","irregular"],"nota":"«Eat» faz «ate» no passado e «eaten» no particípio. Com «already», o inglês americano também aceita o passado simples: «I already ate».","v":"3eaa4603"},{"idioma":"en","id":"en-v003","tipo":"frase","en":"He taught me to drive.","pt":"Ele me ensinou a dirigir.","aceitas":["ele me ensinou a dirigir","me ensinou a dirigir","ele me ensinou a guiar","ele que me ensinou a dirigir"],"aceitasEn":["he taught me to drive","he taught me how to drive"],"distratores":["Ele me ensina a dirigir.","Ele vai me ensinar a dirigir.","Ele me ensinaria a dirigir.","Ele tinha me ensinado a dirigir."],"formasEn":{"He teaches me to drive":"presente","He will teach me to drive":"futuro","He would teach me to drive":"condicional","He had taught me to drive":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","teach","pretérito"],"nota":"«Teach» faz «taught», e o «augh» se lê como um «ó» comprido. Ensinar é «teach», aprender é «learn» — o inglês nunca usa um pelo outro.","v":"fa4b6809"},{"idioma":"en","id":"en-v004","tipo":"frase","en":"They caught the train.","pt":"Eles pegaram o trem.","aceitas":["eles pegaram o trem","pegaram o trem","eles tomaram o trem","eles alcancaram o trem"],"aceitasEn":["they caught the train","they got the train"],"distratores":["Eles pegam o trem.","Eles vão pegar o trem.","Eles pegariam o trem.","Eles tinham pegado o trem."],"formasEn":{"They catch the train":"presente","They will catch the train":"futuro","They would catch the train":"condicional","They had caught the train":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","irregular","catch","viagem"],"nota":"«Catch» faz «caught», que rima com «taught». Serve para pegar o trem, pegar uma bola e pegar um resfriado: «I caught a cold».","v":"8023a228"},{"idioma":"en","id":"en-v005","tipo":"frase","en":"I would have told you.","pt":"Eu teria te contado.","aceitas":["eu teria te contado","teria te contado","eu teria contado para voce","eu teria te falado"],"aceitasEn":["i would have told you","id have told you"],"distratores":["Eu tinha te contado.","Eu te contarei.","Eu te contaria.","Eu te contei."],"formasEn":{"I told you":"pretérito","I will tell you":"futuro","I would tell you":"condicional","I had told you":"mais-que-perfeito"},"nivel":"B2","tags":["conjugação","condicional","tell","irregular"],"nota":"«Would have» + particípio é o que teria acontecido e não aconteceu. Costuma vir com um «if» de passado: «I would have told you if I had known».","v":"3aa3337d"},{"idioma":"en","id":"en-v006","tipo":"frase","en":"Where did you buy that?","pt":"Onde você comprou isso?","aceitas":["onde voce comprou isso","onde comprou isso","onde e que voce comprou isso","voce comprou isso onde"],"aceitasEn":["where did you buy that","where did you get that"],"distratores":["Onde você compra isso?","Onde você vai comprar isso?","Onde você compraria isso?","Onde você tinha comprado isso?"],"formasEn":{"Where do you buy that":"presente","Where will you buy that":"futuro","Where would you buy that":"condicional","Where had you bought that":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","gramática","buy","pretérito"],"nota":"Na pergunta e na negativa, o passado simples pede «did» e o verbo volta ao infinitivo: «did you buy», nunca «did you bought».","v":"df653c2c"},{"idioma":"en","id":"en-p009","tipo":"palavra","en":"actual","pt":"verdadeiro","aceitas":["verdadeiro","real","efetivo","de verdade","propriamente dito"],"aceitasEn":["actual","the actual"],"distratores":["atual","moderno","aproximado","possível"],"nivel":"B1","tags":["falso-amigo","adjetivo"],"nota":"«Actual» é o que é de verdade, por oposição ao suposto: «the actual price» é o preço que se paga mesmo. Quem quer dizer atual usa «current» ou «present». É o par de «actually», que é «na verdade».\n🇺🇸 actual → 🇧🇷 verdadeiro, real\n🇺🇸 current → 🇧🇷 atual","v":"cd6fb108"},{"idioma":"en","id":"en-u009","tipo":"frase","requer":"en-p009","en":"What was the actual cost?","pt":"Qual foi o custo real?","aceitas":["qual foi o custo real","qual foi o custo verdadeiro","qual foi o custo de verdade","quanto custou de verdade"],"aceitasEn":["what was the actual cost","what was the actual price"],"distratores":["Qual foi o custo atual?","Qual foi o custo médio?","Qual foi o custo final?","Qual foi o custo previsto?"],"nivel":"B1","tags":["falso-amigo","economia"],"nota":"«Actual» vem antes do substantivo e serve para separar o número anunciado do número de verdade — é a palavra de quem desconfia da conta.","v":"021b40df"},{"idioma":"en","id":"en-p010","tipo":"palavra","en":"the library","pt":"a biblioteca","aceitas":["a biblioteca","biblioteca"],"aceitasEn":["the library","library","a library"],"distratores":["a livraria","a papelaria","a editora","o arquivo"],"nivel":"A2","tags":["falso-amigo","cidade","substantivo"],"nota":"Na biblioteca se pega emprestado; na livraria se compra, e livraria é «bookstore».\n🇺🇸 the library → 🇧🇷 a biblioteca\n🇺🇸 the bookstore → 🇧🇷 a livraria","v":"31344a8b"},{"idioma":"en","id":"en-u010","tipo":"frase","requer":"en-p010","en":"I study at the library.","pt":"Eu estudo na biblioteca.","aceitas":["eu estudo na biblioteca","estudo na biblioteca","eu estudo numa biblioteca"],"aceitasEn":["i study at the library","i study in the library"],"distratores":["Eu estudo na livraria.","Eu estudo na cozinha.","Eu estudo na padaria.","Eu estudo na varanda."],"nivel":"A2","tags":["falso-amigo","escola"],"nota":"Lugar onde se faz alguma coisa pede «at»: «at the library», «at school», «at work». «In the library» também se diz, mas põe o foco em estar dentro do prédio.","v":"3de2a8e9"},{"idioma":"en","id":"en-p011","tipo":"palavra","en":"the parents","pt":"os pais","aceitas":["os pais","pais","o pai e a mae"],"aceitasEn":["the parents","parents","my parents"],"distratores":["os parentes","os avós","os padrinhos","os sogros"],"nivel":"A1","tags":["falso-amigo","família","substantivo"],"nota":"«Parents» são o pai e a mãe, e mais ninguém. Parente é «relative».\n🇺🇸 the parents → 🇧🇷 os pais\n🇺🇸 the relatives → 🇧🇷 os parentes","v":"683effce"},{"idioma":"en","id":"en-u011","tipo":"frase","requer":"en-p011","en":"My parents live far away.","pt":"Meus pais moram longe.","aceitas":["meus pais moram longe","os meus pais moram longe","meus pais vivem longe","meus pais moram bem longe"],"aceitasEn":["my parents live far away","my parents live a long way away"],"distratores":["Meus parentes moram longe.","Meus avós moram longe.","Meus primos moram longe.","Meus sogros moram longe."],"nivel":"A1","tags":["falso-amigo","família"],"nota":"«Far» sozinho quase não aparece em frase afirmativa: diz-se «far away» ou «a long way». «My parents live far» soa truncado a quem fala inglês.","v":"217c087e"},{"idioma":"en","id":"en-p012","tipo":"palavra","en":"to attend","pt":"comparecer a","aceitas":["comparecer a","comparecer","ir a","estar presente em","participar de"],"aceitasEn":["to attend","attend"],"distratores":["convocar","presidir","adiar","cancelar"],"nivel":"B2","tags":["falso-amigo","verbo"],"nota":"«Attend» é estar lá: numa aula, numa reunião, num casamento. Atender o telefone é «answer», atender um cliente é «serve», e atender a um pedido é «meet».\n🇺🇸 to attend → 🇧🇷 comparecer a\n🇺🇸 to answer → 🇧🇷 atender","v":"6959b2a5"},{"idioma":"en","id":"en-u012","tipo":"frase","requer":"en-p012","en":"Two hundred people attended the concert.","pt":"Duzentas pessoas compareceram ao show.","aceitas":["duzentas pessoas compareceram ao show","duzentas pessoas foram ao show","duzentas pessoas estiveram no show","duzentas pessoas assistiram ao show"],"aceitasEn":["two hundred people attended the concert","200 people attended the concert"],"distratores":["Duzentas pessoas aplaudiram o show.","Duzentas pessoas organizaram o show.","Duzentas pessoas abandonaram o show.","Duzentas pessoas gravaram o show."],"nivel":"B2","tags":["falso-amigo","cultura"],"nota":"Em inglês «attend» pega o objeto direto: «attend the concert», sem preposição nenhuma. Quem traduz o «a» de comparecer a escreve «attend to the concert», que quer dizer outra coisa — cuidar dele.","v":"d9eb5297"},{"idioma":"en","id":"en-p013","tipo":"palavra","en":"the exit","pt":"a saída","aceitas":["a saida","saida"],"aceitasEn":["the exit","exit","the way out"],"distratores":["o êxito","o sucesso","a entrada","o acesso"],"nivel":"A2","tags":["falso-amigo","cidade","substantivo"],"nota":"É a palavra escrita em cima da porta, e também o trevo de saída da estrada. Êxito é «success».\n🇺🇸 the exit → 🇧🇷 a saída\n🇺🇸 the success → 🇧🇷 o êxito","v":"c415fb36"},{"idioma":"en","id":"en-u013","tipo":"frase","requer":"en-p013","en":"Where is the emergency exit?","pt":"Onde fica a saída de emergência?","aceitas":["onde fica a saida de emergencia","onde e a saida de emergencia","onde esta a saida de emergencia"],"aceitasEn":["where is the emergency exit","wheres the emergency exit"],"distratores":["Onde fica a entrada de emergência?","Onde fica a escada de emergência?","Onde fica o telefone de emergência?","Onde fica o botão de emergência?"],"nivel":"A2","tags":["falso-amigo","viagem"],"nota":"Em inglês o primeiro substantivo vira adjetivo do segundo e fica invariável: «emergency exit», «bus station», «coffee cup». Nada de «exit of emergency».","v":"1fda1c41"},{"idioma":"en","id":"en-p014","tipo":"palavra","en":"sensible","pt":"sensato","aceitas":["sensato","ajuizado","de bom senso","com juizo","razoavel"],"aceitasEn":["sensible","a sensible"],"distratores":["sensível","emotivo","óbvio","cuidadoso"],"nivel":"B2","tags":["falso-amigo","adjetivo"],"nota":"«Sensible» é quem decide com a cabeça no lugar. Quem se emociona fácil é «sensitive».\n🇺🇸 sensible → 🇧🇷 sensato\n🇺🇸 sensitive → 🇧🇷 sensível","v":"1753a335"},{"idioma":"en","id":"en-u014","tipo":"frase","requer":"en-p014","en":"That was a sensible decision.","pt":"Foi uma decisão sensata.","aceitas":["foi uma decisao sensata","essa foi uma decisao sensata","foi uma decisao ajuizada","foi uma decisao de bom senso"],"aceitasEn":["that was a sensible decision","it was a sensible decision"],"distratores":["Foi uma decisão sensível.","Foi uma decisão arriscada.","Foi uma decisão apressada.","Foi uma decisão corajosa."],"nivel":"B2","tags":["falso-amigo","social"],"nota":"«Sensible» anda com decisão, escolha, conselho e sapato: «sensible shoes» são os sapatos confortáveis de quem foi pensando no dia inteiro.","v":"4672b11a"},{"idioma":"en","id":"en-p015","tipo":"palavra","en":"the fabric","pt":"o tecido","aceitas":["o tecido","tecido","o pano"],"aceitasEn":["the fabric","fabric","the cloth"],"distratores":["a fábrica","o fabricante","o tapete","a cortina"],"nivel":"B2","tags":["falso-amigo","objetos","substantivo"],"nota":"«Fabric» é o pano, o que se corta e se costura. Fábrica é «factory», e fabricar é «to manufacture».\n🇺🇸 the fabric → 🇧🇷 o tecido\n🇺🇸 the factory → 🇧🇷 a fábrica","v":"45c2c22c"},{"idioma":"en","id":"en-u015","tipo":"frase","requer":"en-p015","en":"I bought two meters of fabric.","pt":"Comprei dois metros de tecido.","aceitas":["comprei dois metros de tecido","eu comprei dois metros de tecido","comprei dois metros de pano"],"aceitasEn":["i bought two meters of fabric","i bought two metres of fabric","i bought 2 meters of fabric"],"distratores":["Comprei dois metros de corda.","Comprei dois metros de fio.","Comprei dois metros de fita.","Comprei dois metros de renda."],"nivel":"B2","tags":["falso-amigo","roupa"],"nota":"«Fabric» é incontável: compra-se «some fabric», «two meters of fabric», e nunca «two fabrics». Nos Estados Unidos se escreve «meter»; na Inglaterra, «metre».","v":"e82ed8c4"},{"idioma":"en","id":"en-p016","tipo":"palavra","en":"to resume","pt":"retomar","aceitas":["retomar","recomecar","continuar","voltar a","prosseguir"],"aceitasEn":["to resume","resume"],"distratores":["resumir","encurtar","adiar","concluir"],"nivel":"B2","tags":["falso-amigo","verbo","trabalho"],"nota":"«Resume» é pegar de novo o que ficou pela metade: o trabalho, a viagem, a partida. Resumir é «to summarize».\n🇺🇸 to resume → 🇧🇷 retomar\n🇺🇸 to summarize → 🇧🇷 resumir","v":"0cdb95ab"},{"idioma":"en","id":"en-u016","tipo":"frase","requer":"en-p016","en":"Let's resume the meeting.","pt":"Vamos retomar a reunião.","aceitas":["vamos retomar a reuniao","vamos recomecar a reuniao","vamos continuar a reuniao","vamos voltar a reuniao"],"aceitasEn":["lets resume the meeting","let us resume the meeting"],"distratores":["Vamos resumir a reunião.","Vamos encerrar a reunião.","Vamos adiar a reunião.","Vamos gravar a reunião."],"nivel":"B2","tags":["falso-amigo","trabalho"],"nota":"Com nome, o falso amigo é outro: «a résumé» é o currículo, e é assim que se chama nos Estados Unidos — na Inglaterra é «a CV».","v":"fcf0f2ef"},{"idioma":"en","id":"en-p017","tipo":"palavra","en":"the lecture","pt":"a palestra","aceitas":["a palestra","palestra","a conferencia","a aula","a prelecao"],"aceitasEn":["the lecture","lecture","a lecture"],"distratores":["a leitura","a reunião","a missa","a prova"],"nivel":"B1","tags":["falso-amigo","escola","substantivo"],"nota":"«Lecture» é alguém falando para uma plateia: a palestra do congresso e a aula expositiva da faculdade. Leitura é «reading».\n🇺🇸 the lecture → 🇧🇷 a palestra\n🇺🇸 the reading → 🇧🇷 a leitura","v":"35e2a48a"},{"idioma":"en","id":"en-u017","tipo":"frase","requer":"en-p017","en":"The lecture starts at eight.","pt":"A palestra começa às oito.","aceitas":["a palestra comeca as oito","a palestra e as oito","a conferencia comeca as oito","a aula comeca as oito"],"aceitasEn":["the lecture starts at eight","the lecture begins at eight","the lecture starts at 8"],"distratores":["A leitura começa às oito.","A reunião começa às oito.","A missa começa às oito.","A prova começa às oito."],"nivel":"B1","tags":["falso-amigo","escola"],"nota":"Hora certa pede «at»: «at eight», «at noon», «at midnight». O dia pede «on» e o mês pede «in».","v":"de885860"},{"idioma":"en","id":"en-p018","tipo":"palavra","en":"to record","pt":"gravar","aceitas":["gravar","registrar","filmar","anotar"],"aceitasEn":["to record","record"],"distratores":["recordar","lembrar","apagar","transmitir"],"nivel":"B1","tags":["falso-amigo","verbo","tecnologia"],"nota":"«Record» é pôr no papel ou na fita: gravar a aula, registrar a temperatura. Recordar é «to remember».\n🇺🇸 to record → 🇧🇷 gravar\n🇺🇸 to remember → 🇧🇷 recordar","v":"e23665c9"},{"idioma":"en","id":"en-u018","tipo":"frase","requer":"en-p018","en":"They recorded the whole concert.","pt":"Eles gravaram o show inteiro.","aceitas":["eles gravaram o show inteiro","gravaram o show inteiro","eles gravaram o show todo","eles filmaram o show inteiro"],"aceitasEn":["they recorded the whole concert","they recorded the entire concert"],"distratores":["Eles recordaram o show inteiro.","Eles lembraram o show inteiro.","Eles cancelaram o show inteiro.","Eles pagaram o show inteiro."],"nivel":"B1","tags":["falso-amigo","cultura"],"nota":"Como verbo, a sílaba forte é a segunda: re-CORD. Como nome, é a primeira: RE-cord, que é tanto o disco quanto o recorde do esporte.","v":"2e91ab62"},{"idioma":"en","id":"en-p019","tipo":"palavra","en":"the drawer","pt":"a gaveta","aceitas":["a gaveta","gaveta"],"aceitasEn":["the drawer","drawer","a drawer"],"distratores":["a prateleira","a estante","a mochila","a geladeira"],"nivel":"A2","tags":["casa","objetos","substantivo"],"nota":"Vem de «to draw», que antes de desenhar queria dizer puxar — a gaveta é o que se puxa. A cômoda inteira é «a chest of drawers».","v":"7f180f58"},{"idioma":"en","id":"en-u019","tipo":"frase","requer":"en-p019","en":"The keys are in the drawer.","pt":"As chaves estão na gaveta.","aceitas":["as chaves estao na gaveta","as chaves estao dentro da gaveta","as chaves ficam na gaveta"],"aceitasEn":["the keys are in the drawer","the keys are inside the drawer"],"distratores":["As chaves estão na prateleira.","As chaves estão na mochila.","As chaves estão na geladeira.","As chaves estão na entrada."],"nivel":"A2","tags":["casa","cotidiano"],"nota":"Dentro de um móvel fechado é «in the drawer»; em cima de uma superfície é «on the shelf», «on the table». O inglês separa o que o português resolve com «na».","v":"3d26ccc7"},{"idioma":"en","id":"en-p020","tipo":"palavra","en":"the pillow","pt":"o travesseiro","aceitas":["o travesseiro","travesseiro"],"aceitasEn":["the pillow","pillow","a pillow"],"distratores":["o colchão","o edredom","o lençol","o tapete"],"nivel":"A2","tags":["casa","objetos","substantivo"],"nota":"«Pillow» é o da cama. O da poltrona é «a cushion». A fronha, que quase ninguém sabe dizer, é «a pillowcase».","v":"6f83467e"},{"idioma":"en","id":"en-u020","tipo":"frase","requer":"en-p020","en":"This pillow is too soft.","pt":"Esse travesseiro é mole demais.","aceitas":["esse travesseiro e mole demais","este travesseiro e mole demais","esse travesseiro e muito mole","esse travesseiro e macio demais"],"aceitasEn":["this pillow is too soft","the pillow is too soft"],"distratores":["Esse colchão é mole demais.","Esse edredom é mole demais.","Esse sofá é mole demais.","Esse tapete é mole demais."],"nivel":"A2","tags":["casa","cotidiano"],"nota":"«Too» é o demais que atrapalha; «very» é só muito. «This pillow is very soft» é elogio, «too soft» é reclamação.","v":"f3d6f6b1"},{"idioma":"en","id":"en-p021","tipo":"palavra","en":"the faucet","pt":"a torneira","aceitas":["a torneira","torneira"],"aceitasEn":["the faucet","faucet"],"distratores":["a mangueira","a descarga","a chaleira","a peneira"],"nivel":"A2","tags":["casa","objetos","substantivo"],"nota":"«Faucet» é a palavra dos Estados Unidos; na Inglaterra e na Austrália é «tap», que também é a torneira do chope. As duas valem como resposta.","regionaisEn":{"the tap":"na Inglaterra","tap":"na Inglaterra"},"v":"20e554e8"},{"idioma":"en","id":"en-u021","tipo":"frase","requer":"en-p021","en":"Turn off the faucet.","pt":"Feche a torneira.","aceitas":["feche a torneira","fecha a torneira","desliga a torneira","desligue a torneira"],"aceitasEn":["turn off the faucet","shut off the faucet"],"distratores":["Feche a janela.","Feche a porta.","Feche a gaveta.","Feche a cortina."],"nivel":"A2","tags":["casa","cotidiano"],"nota":"O inglês não usa «close» para o que tem fluxo: água, gás, luz e rádio se desligam com «turn off», e se abrem com «turn on». «Close the faucet» não se diz.","regionaisEn":{"turn off the tap":"na Inglaterra"},"v":"8213c9c3"},{"idioma":"en","id":"en-p022","tipo":"palavra","en":"the wallet","pt":"a carteira","aceitas":["a carteira","carteira"],"aceitasEn":["the wallet","wallet","a wallet"],"distratores":["a bolsa","a mochila","a agenda","a pasta"],"nivel":"A2","tags":["objetos","substantivo","economia"],"nota":"«Wallet» é só a de guardar dinheiro, no bolso. A carteira de motorista é «a driver's license», e a carteira da escola é «a desk».","v":"192cc668"},{"idioma":"en","id":"en-u022","tipo":"frase","requer":"en-p022","en":"I left my wallet at home.","pt":"Esqueci a carteira em casa.","aceitas":["esqueci a carteira em casa","deixei a carteira em casa","eu esqueci minha carteira em casa","esqueci minha carteira em casa"],"aceitasEn":["i left my wallet at home","i forgot my wallet at home"],"distratores":["Esqueci a mochila em casa.","Esqueci a chave em casa.","Esqueci a agenda em casa.","Esqueci a sombrinha em casa."],"nivel":"A2","tags":["objetos","cotidiano"],"nota":"Objeto esquecido em algum lugar pede «leave», não «forget»: «I left it at home». «Forget» serve quando não se diz onde: «I forgot my wallet».","v":"a8858c8e"},{"idioma":"en","id":"en-p023","tipo":"palavra","en":"the blanket","pt":"o cobertor","aceitas":["o cobertor","cobertor","a coberta"],"aceitasEn":["the blanket","blanket","a blanket"],"distratores":["o lençol","o colchão","o tapete","o casaco"],"nivel":"A2","tags":["casa","objetos","substantivo"],"nota":"«Blanket» é o cobertor de lã, grosso. O de baixo, fino, é «a sheet», e o de penas é «a duvet» ou «a comforter».","v":"d9eaf472"},{"idioma":"en","id":"en-u023","tipo":"frase","requer":"en-p023","en":"I need another blanket.","pt":"Preciso de outro cobertor.","aceitas":["preciso de outro cobertor","eu preciso de outro cobertor","preciso de mais um cobertor"],"aceitasEn":["i need another blanket","i need one more blanket"],"distratores":["Preciso de outro lençol.","Preciso de outro colchão.","Preciso de outro casaco.","Preciso de outro tapete."],"nivel":"A2","tags":["casa","cotidiano"],"nota":"«Another» é uma palavra só, e já carrega o «um»: «another blanket», mais um. Com plural ou incontável se usa «more»: «more blankets», «more water».","v":"6e2fa176"},{"idioma":"en","id":"en-p024","tipo":"palavra","en":"the aisle","pt":"o corredor","aceitas":["o corredor","corredor"],"aceitasEn":["the aisle","aisle","an aisle"],"distratores":["o assento","o banheiro","o degrau","o portão"],"nivel":"B1","tags":["viagem","cidade","substantivo"],"nota":"É o corredor entre fileiras: do avião, do supermercado, da igreja. O «s» não se pronuncia — soa como «I'll». O corredor de casa é «a hallway».","v":"edca0448"},{"idioma":"en","id":"en-u024","tipo":"frase","requer":"en-p024","en":"I'd like an aisle seat.","pt":"Queria um lugar no corredor.","aceitas":["queria um lugar no corredor","eu queria um lugar no corredor","queria um assento no corredor","gostaria de um lugar no corredor"],"aceitasEn":["id like an aisle seat","i would like an aisle seat"],"distratores":["Queria um lugar na janela.","Queria um lugar na frente.","Queria um lugar no fundo.","Queria um lugar mais barato."],"nivel":"B1","tags":["viagem","formal"],"nota":"«I'd like» é o pedido educado de balcão, e é mais curto do que parece: «I would like». Quem diz «I want» soa a criança pedindo.","v":"2a9a230f"},{"idioma":"en","id":"en-p025","tipo":"palavra","en":"the sidewalk","pt":"a calçada","aceitas":["a calcada","calcada","o passeio"],"aceitasEn":["the sidewalk","sidewalk"],"distratores":["a rua","a praça","a esquina","a avenida"],"nivel":"A2","tags":["cidade","substantivo"],"nota":"«Sidewalk» é dos Estados Unidos; na Inglaterra é «pavement» — que nos Estados Unidos quer dizer o asfalto da rua, justamente o contrário.","regionaisEn":{"the pavement":"na Inglaterra","pavement":"na Inglaterra"},"v":"e3c80dd6"},{"idioma":"en","id":"en-u025","tipo":"frase","requer":"en-p025","en":"The sidewalk was full of people.","pt":"A calçada estava cheia de gente.","aceitas":["a calcada estava cheia de gente","a calcada estava lotada","a calcada estava cheia de pessoas"],"aceitasEn":["the sidewalk was full of people"],"distratores":["A rua estava cheia de gente.","A praça estava cheia de gente.","A escada estava cheia de gente.","A varanda estava cheia de gente."],"nivel":"A2","tags":["cidade","cotidiano"],"nota":"«People» é plural por natureza e pede verbo no plural: «people are», nunca «people is». Uma pessoa só é «a person».","regionaisEn":{"the pavement was full of people":"na Inglaterra"},"v":"f7629307"},{"idioma":"en","id":"en-p026","tipo":"palavra","en":"to borrow","pt":"pegar emprestado","aceitas":["pegar emprestado","tomar emprestado","pedir emprestado","pegar algo emprestado"],"aceitasEn":["to borrow","borrow"],"distratores":["emprestar","devolver","alugar","doar"],"nivel":"B1","tags":["verbo","cotidiano"],"nota":"É o lado de quem recebe. Nem o português nem o inglês deixam adivinhar o outro: quem dá empresta, «lend», e quem pega toma emprestado, «borrow». Em inglês são dois verbos diferentes, e trocá-los inverte a frase.","v":"3c042a33"},{"idioma":"en","id":"en-u026","tipo":"frase","requer":"en-p026","en":"Can I borrow your pen?","pt":"Posso pegar sua caneta emprestada?","aceitas":["posso pegar sua caneta emprestada","posso pegar emprestada sua caneta","me empresta sua caneta","posso pegar tua caneta emprestada"],"aceitasEn":["can i borrow your pen","could i borrow your pen","may i borrow your pen"],"distratores":["Posso ficar com sua caneta?","Posso ver sua caneta?","Posso guardar sua caneta?","Posso comprar sua caneta?"],"nivel":"B1","tags":["cotidiano","social"],"nota":"«Borrow» pede o objeto logo depois, sem preposição: «borrow your pen». De quem se pegou vai com «from»: «I borrowed it from my brother».","v":"6741e932"},{"idioma":"en","id":"en-p027","tipo":"palavra","en":"to lend","pt":"emprestar","aceitas":["emprestar","ceder","emprestar algo"],"aceitasEn":["to lend","lend"],"distratores":["tomar emprestado","devolver","alugar","guardar"],"nivel":"B1","tags":["verbo","cotidiano"],"nota":"É o lado de quem dá, o par de «borrow». No passado faz «lent», sem regra: «I lent him the book».","v":"6e96e4fe"},{"idioma":"en","id":"en-u027","tipo":"frase","requer":"en-p027","en":"He never lends me his car.","pt":"Ele nunca me empresta o carro dele.","aceitas":["ele nunca me empresta o carro dele","ele nunca me empresta o carro","ele nunca empresta o carro dele pra mim","ele nunca me cede o carro dele"],"aceitasEn":["he never lends me his car","he never lends his car to me"],"distratores":["Ele nunca me vende o carro dele.","Ele nunca me mostra o carro dele.","Ele nunca me entrega o carro dele.","Ele nunca me devolve o carro dele."],"nivel":"B1","tags":["cotidiano","objetos"],"nota":"«Lend» aceita duas ordens, e as duas soam bem: «he lent me his car» e «he lent his car to me». A primeira é a de todo dia.","v":"b252f5c0"},{"idioma":"en","id":"en-p028","tipo":"palavra","en":"to complain","pt":"reclamar","aceitas":["reclamar","queixar-se","se queixar","resmungar"],"aceitasEn":["to complain","complain"],"distratores":["elogiar","avisar","explicar","concordar"],"nivel":"B1","tags":["verbo","social"],"nota":"O assunto da reclamação vai com «about»: «complain about the noise». A pessoa a quem se reclama vai com «to»: «complain to the manager».","v":"8849d52d"},{"idioma":"en","id":"en-u028","tipo":"frase","requer":"en-p028","en":"He always complains about the food.","pt":"Ele sempre reclama da comida.","aceitas":["ele sempre reclama da comida","ele vive reclamando da comida","ele so reclama da comida","ele sempre se queixa da comida"],"aceitasEn":["he always complains about the food","he is always complaining about the food"],"distratores":["Ele sempre fala da comida.","Ele sempre cuida da comida.","Ele sempre desconfia da comida.","Ele sempre esquece da comida."],"nivel":"B1","tags":["social","comida"],"nota":"«Always» fica entre o sujeito e o verbo: «he always complains». Com o verbo no contínuo, «he is always complaining», a frase ganha uma pitada de impaciência.","v":"4e83e8a6"},{"idioma":"en","id":"en-p029","tipo":"palavra","en":"the homework","pt":"a lição de casa","aceitas":["a licao de casa","licao de casa","o dever de casa","a tarefa de casa","a tarefa"],"aceitasEn":["the homework","homework","my homework"],"distratores":["o boletim da escola","a prova de matemática","a lista de material","a reunião de pais"],"nivel":"A2","tags":["escola","substantivo"],"nota":"É incontável: não existe «a homework» nem «homeworks». Diz-se «some homework», «a lot of homework», e, para uma só, «a piece of homework».","v":"aed60071"},{"idioma":"en","id":"en-u029","tipo":"frase","requer":"en-p029","en":"Do your homework first.","pt":"Faça a lição de casa primeiro.","aceitas":["faca a licao de casa primeiro","faz a licao de casa primeiro","faca primeiro a licao de casa","faca a tarefa de casa primeiro"],"aceitasEn":["do your homework first","do the homework first"],"distratores":["Faça a mala de viagem primeiro.","Faça a lista de compras primeiro.","Faça a prova de História primeiro.","Faça o curso de inglês primeiro."],"nivel":"A2","tags":["escola","cotidiano"],"nota":"Lição de casa se faz com «do», não com «make»: «do your homework». «Make» é para o que se cria do nada — «make a cake», «make a mess».","v":"c2546218"},{"idioma":"en","id":"en-p030","tipo":"palavra","en":"to hurry","pt":"se apressar","aceitas":["se apressar","apressar-se","ter pressa","correr","andar logo"],"aceitasEn":["to hurry","hurry","to hurry up"],"distratores":["se atrasar","se acalmar","se cansar","se perder"],"nivel":"A2","tags":["verbo","cotidiano"],"nota":"Na ordem de quem está esperando vem com «up»: «hurry up!». E a pressa como substantivo é outra construção: «I'm in a hurry», estou com pressa.","v":"ca731e07"},{"idioma":"en","id":"en-u030","tipo":"frase","requer":"en-p030","en":"You don't have to hurry.","pt":"Você não precisa se apressar.","aceitas":["voce nao precisa se apressar","nao precisa se apressar","voce nao precisa ter pressa","voce nao precisa correr"],"aceitasEn":["you dont have to hurry","you do not have to hurry","you neednt hurry"],"distratores":["Você não precisa se preocupar.","Você não precisa se desculpar.","Você não precisa se levantar.","Você não precisa se explicar."],"nivel":"A2","tags":["cotidiano","social"],"nota":"«Don't have to» é não precisar; «mustn't» é não poder. A distância entre as duas é grande, e é o erro mais caro do inglês de quem começa.","v":"4f954732"},{"idioma":"en","id":"en-f009","tipo":"frase","en":"I gave up smoking.","pt":"Parei de fumar.","aceitas":["parei de fumar","eu parei de fumar","larguei o cigarro","desisti de fumar","abandonei o cigarro"],"aceitasEn":["i gave up smoking","i have given up smoking","i quit smoking"],"distratores":["Voltei a fumar.","Comecei a fumar.","Tentei parar de fumar.","Diminuí o cigarro."],"nivel":"B1","tags":["phrasal verb","saúde"],"nota":"Depois de «give up» o verbo vai no gerúndio: «give up smoking», «give up trying». É a regra de quase todo phrasal verb seguido de outro verbo.","v":"8c5a2815"},{"idioma":"en","id":"en-f010","tipo":"frase","en":"She turned down the offer.","pt":"Ela recusou a oferta.","aceitas":["ela recusou a oferta","recusou a oferta","ela rejeitou a oferta","ela nao aceitou a oferta"],"aceitasEn":["she turned down the offer","she turned the offer down"],"distratores":["Ela aceitou a oferta.","Ela aumentou a oferta.","Ela abaixou o volume.","Ela adiou a resposta."],"nivel":"B1","tags":["phrasal verb","trabalho"],"nota":"«Turn down» tem os dois sentidos: abaixar o volume e recusar um convite. Com objeto curto, ele se separa — «turn it down» —, e com pronome a separação é obrigatória.","v":"39d1d30a"},{"idioma":"en","id":"en-f011","tipo":"frase","en":"I came across an old photo.","pt":"Achei uma foto antiga por acaso.","aceitas":["achei uma foto antiga por acaso","encontrei uma foto antiga por acaso","dei de cara com uma foto antiga","esbarrei numa foto antiga"],"aceitasEn":["i came across an old photo","i came across an old picture"],"distratores":["Procurei uma foto antiga por toda parte.","Joguei uma foto antiga fora sem querer.","Guardei uma foto antiga por muitos anos.","Rasguei uma foto antiga sem pensar."],"nivel":"B2","tags":["phrasal verb","cotidiano"],"nota":"«Come across» é o encontro sem procura, e serve tanto para coisa quanto para pessoa. Dito de alguém, muda de sentido: «he comes across as rude» é a impressão que ele passa.","v":"34a79759"},{"idioma":"en","id":"en-f012","tipo":"frase","en":"We'll figure it out.","pt":"A gente dá um jeito.","aceitas":["a gente da um jeito","nos damos um jeito","a gente resolve","vamos dar um jeito","a gente descobre"],"aceitasEn":["well figure it out","we will figure it out"],"distratores":["A gente pede ajuda.","A gente deixa pra lá.","A gente tenta de novo.","A gente desiste disso."],"nivel":"B1","tags":["phrasal verb","expressão"],"nota":"«Figure out» é entender depois de quebrar a cabeça: o problema, a conta, a pessoa. Com pronome, ele obriga a separação: «figure it out», nunca «figure out it».","v":"cfc9485c"},{"idioma":"en","id":"en-f013","tipo":"frase","en":"He didn't show up.","pt":"Ele não apareceu.","aceitas":["ele nao apareceu","nao apareceu","ele nao deu as caras","ele deu o cano"],"aceitasEn":["he didnt show up","he did not show up","he never showed up"],"distratores":["Ele não avisou.","Ele não entendeu.","Ele não concordou.","Ele não insistiu."],"nivel":"B1","tags":["phrasal verb","social"],"nota":"«Show up» é aparecer onde se era esperado, e não tem objeto: ninguém «shows up something». O contrário é «stand somebody up», dar o cano em alguém.","v":"d861dcf4"},{"idioma":"en","id":"en-f014","tipo":"frase","en":"I get along with my sister.","pt":"Me dou bem com minha irmã.","aceitas":["me dou bem com minha irma","eu me dou bem com minha irma","me dou bem com a minha irma","eu e minha irma nos damos bem"],"aceitasEn":["i get along with my sister","i get on with my sister"],"distratores":["Moro junto com minha irmã.","Saio sempre com minha irmã.","Brigo muito com minha irmã.","Pareço muito com minha irmã."],"nivel":"B1","tags":["phrasal verb","família"],"nota":"Nos Estados Unidos é «get along»; na Inglaterra, «get on». O bem e o mal vêm depois: «get along well», «get along badly».","v":"d5d9eaec"},{"idioma":"en","id":"en-f015","tipo":"frase","en":"Can you look after the dog?","pt":"Você pode cuidar do cachorro?","aceitas":["voce pode cuidar do cachorro","pode cuidar do cachorro","voce podia cuidar do cachorro","da pra voce cuidar do cachorro"],"aceitasEn":["can you look after the dog","could you look after the dog","can you take care of the dog"],"distratores":["Você pode procurar o cachorro?","Você pode passear com o cachorro?","Você pode alimentar o cachorro?","Você pode levar o cachorro?"],"nivel":"B1","tags":["phrasal verb","animais"],"nota":"«Look» muda de sentido conforme a preposição: «look at» é olhar, «look for» é procurar, «look after» é cuidar e «look up» é consultar. A preposição é que manda.","v":"54bfd0aa"},{"idioma":"en","id":"en-f016","tipo":"frase","en":"Take off your shoes.","pt":"Tire os sapatos.","aceitas":["tire os sapatos","tira os sapatos","tire seus sapatos","pode tirar os sapatos"],"aceitasEn":["take off your shoes","take your shoes off"],"distratores":["Calce os sapatos.","Guarde os sapatos.","Limpe os sapatos.","Amarre os sapatos."],"nivel":"A2","tags":["phrasal verb","roupa"],"nota":"«Take off» é tirar roupa e sapato, e é também o avião decolando. O contrário, vestir, é «put on».","v":"c438cfe5"},{"idioma":"en","id":"en-f017","tipo":"frase","en":"The meeting was called off.","pt":"A reunião foi cancelada.","aceitas":["a reuniao foi cancelada","cancelaram a reuniao","a reuniao foi desmarcada","desmarcaram a reuniao"],"aceitasEn":["the meeting was called off","they called off the meeting","the meeting was cancelled"],"distratores":["A reunião foi adiada.","A reunião foi gravada.","A reunião foi convocada.","A reunião foi encerrada."],"nivel":"B1","tags":["phrasal verb","trabalho"],"nota":"«Call off» é cancelar o que estava marcado: a reunião, a greve, o casamento, a busca. Convocar, que a palavra «call» sugere, é «call» sozinho.","v":"46e5f1de"},{"idioma":"en","id":"en-f018","tipo":"frase","en":"I'll look it up.","pt":"Vou pesquisar isso.","aceitas":["vou pesquisar isso","vou procurar isso","vou dar uma olhada nisso","vou consultar isso","eu pesquiso isso"],"aceitasEn":["ill look it up","i will look it up"],"distratores":["Vou olhar pra cima.","Vou anotar isso.","Vou repetir isso.","Vou traduzir isso."],"nivel":"B1","tags":["phrasal verb","tecnologia"],"nota":"«Look up» é procurar informação onde ela está guardada: no dicionário, na agenda, na internet. Serve para a palavra e para o número de telefone, não para a chave perdida.","v":"69222b9e"},{"idioma":"en","id":"en-f019","tipo":"frase","en":"Hold on a second.","pt":"Espera um segundo.","aceitas":["espera um segundo","espere um segundo","perai um segundo","so um segundo","espera um pouquinho"],"aceitasEn":["hold on a second","hold on a sec","hang on a second"],"distratores":["Segura firme um segundo.","Solta por um segundo.","Escuta um segundo.","Respira um segundo."],"nivel":"A2","tags":["phrasal verb","cotidiano"],"nota":"É o que se diz ao telefone e na fila. «Hold on» sozinho também serve, e «hang on» é o mesmo em conversa. Já «hold on to something» é agarrar-se mesmo.","v":"50257364"},{"idioma":"en","id":"en-f020","tipo":"frase","en":"Watch out!","pt":"Cuidado!","aceitas":["cuidado","presta atencao","olha o perigo","toma cuidado"],"aceitasEn":["watch out","look out"],"distratores":["Olha lá!","Sai fora!","Vamos ver!","Repara bem!"],"nivel":"A2","tags":["phrasal verb","expressão"],"nota":"É o grito de aviso, no susto. «Look out!» é igualzinho. Para recomendar cuidado com calma, diz-se «be careful».","v":"8390b00a"},{"idioma":"en","id":"en-f021","tipo":"frase","en":"She's married to a teacher.","pt":"Ela é casada com um professor.","aceitas":["ela e casada com um professor","e casada com um professor","ela se casou com um professor","ela e casada com um professor sim"],"aceitasEn":["shes married to a teacher","she is married to a teacher"],"distratores":["Ela é noiva de um professor.","Ela é filha de um professor.","Ela é aluna de um professor.","Ela é vizinha de um professor."],"nivel":"B1","tags":["preposição","família"],"nota":"Em inglês casa-se «to» alguém, e não «with»: «married to a teacher». «Married with» existe, mas quer dizer outra coisa — «married with two children», casado e com dois filhos.","v":"f5f406fc"},{"idioma":"en","id":"en-f022","tipo":"frase","en":"She's good at math.","pt":"Ela é boa em matemática.","aceitas":["ela e boa em matematica","ela e boa de matematica","ela vai bem em matematica","ela manda bem em matematica"],"aceitasEn":["shes good at math","she is good at math"],"distratores":["Ela é fraca em matemática.","Ela é professora de matemática.","Ela gosta de matemática.","Ela odeia matemática."],"nivel":"A2","tags":["preposição","escola"],"nota":"Ser bom numa coisa pede «at»: «good at math», «bad at sports», «terrible at names». Nos Estados Unidos a matéria é «math»; na Inglaterra, «maths».","regionaisEn":{"shes good at maths":"na Inglaterra"},"v":"2d482f87"},{"idioma":"en","id":"en-f023","tipo":"frase","en":"I'm interested in history.","pt":"Me interesso por história.","aceitas":["me interesso por historia","eu me interesso por historia","tenho interesse por historia","gosto de historia"],"aceitasEn":["im interested in history","i am interested in history"],"distratores":["Eu estudo história.","Eu dou aula de história.","Eu não entendo de história.","Eu detesto história."],"nivel":"A2","tags":["preposição","cultura"],"nota":"«Interested in», sempre. E a pessoa é «interested», enquanto a coisa é «interesting»: quem diz «I am interesting» está dizendo que é fascinante.","v":"230ab6b4"},{"idioma":"en","id":"en-f024","tipo":"frase","en":"We arrived at the airport.","pt":"Chegamos ao aeroporto.","aceitas":["chegamos ao aeroporto","nos chegamos ao aeroporto","a gente chegou ao aeroporto","chegamos no aeroporto"],"aceitasEn":["we arrived at the airport","we got to the airport"],"distratores":["Saímos do aeroporto.","Passamos pelo aeroporto.","Moramos perto do aeroporto.","Fomos até o aeroporto."],"nivel":"A2","tags":["preposição","viagem"],"nota":"«Arrive» nunca leva «to». Lugar fechado e cidade pedem «in» — «arrive in Brazil» —, e ponto de passagem pede «at»: «arrive at the airport», «at the station».","v":"193b09d3"},{"idioma":"en","id":"en-f025","tipo":"frase","en":"Nobody listens to me.","pt":"Ninguém me escuta.","aceitas":["ninguem me escuta","ninguem me ouve","ninguem me da ouvidos","ninguem escuta o que eu falo"],"aceitasEn":["nobody listens to me","no one listens to me"],"distratores":["Ninguém me entende.","Ninguém me avisa.","Ninguém me espera.","Ninguém me procura."],"nivel":"A2","tags":["preposição","social"],"nota":"«Listen» sempre pede «to» antes de quem se escuta: «listen to me», «listen to music». Sem objeto ele vai sozinho: «listen!».","v":"c7910a5b"},{"idioma":"en","id":"en-f026","tipo":"frase","en":"I'm waiting for the bus.","pt":"Estou esperando o ônibus.","aceitas":["estou esperando o onibus","to esperando o onibus","eu estou esperando o onibus","estou na espera do onibus"],"aceitasEn":["im waiting for the bus","i am waiting for the bus"],"distratores":["Estou procurando o ônibus.","Estou pegando o ônibus.","Estou perdendo o ônibus.","Estou descendo do ônibus."],"nivel":"A2","tags":["preposição","viagem"],"nota":"«Wait» pede «for» antes do que se espera: «wait for the bus», «wait for me». Sem «for», «wait a minute» é o único caso comum.","v":"e7a4a8a5"},{"idioma":"en","id":"en-f027","tipo":"frase","en":"There are a lot of people here.","pt":"Tem muita gente aqui.","aceitas":["tem muita gente aqui","ha muita gente aqui","tem um monte de gente aqui","tem muita gente por aqui"],"aceitasEn":["there are a lot of people here","there are lots of people here","theres a lot of people here"],"distratores":["Cabe muita gente aqui.","Mora muita gente aqui.","Passa muita gente aqui.","Falta gente aqui."],"nivel":"A1","tags":["gramática","cotidiano"],"nota":"O «tem» que não é de ninguém é «there is» no singular e «there are» no plural — e o inglês concorda com o que vem depois, coisa que nem o português nem o espanhol fazem.","v":"43fe186c"},{"idioma":"en","id":"en-f028","tipo":"frase","en":"I've been here since Monday.","pt":"Estou aqui desde segunda.","aceitas":["estou aqui desde segunda","eu estou aqui desde segunda","estou aqui desde segunda-feira","cheguei aqui na segunda e estou ate agora"],"aceitasEn":["ive been here since monday","i have been here since monday"],"distratores":["Estive aqui na segunda.","Cheguei aqui na segunda.","Fico aqui até segunda.","Volto aqui na segunda."],"nivel":"B1","tags":["present perfect","gramática"],"nota":"«Since» marca o começo — desde segunda —, e «for» marca a duração — «for three days». O que começou antes e continua agora vai no present perfect, e nunca no presente: «I am here since Monday» não existe.","v":"83602f3d"},{"idioma":"en","id":"en-f029","tipo":"frase","en":"She gave me some advice.","pt":"Ela me deu um conselho.","aceitas":["ela me deu um conselho","me deu um conselho","ela me deu uns conselhos","ela me aconselhou"],"aceitasEn":["she gave me some advice","she gave me advice"],"distratores":["Ela me deu um susto.","Ela me deu um recado.","Ela me deu um abraço.","Ela me deu um exemplo."],"nivel":"B1","tags":["gramática","social"],"nota":"«Advice» é incontável: não existe «an advice» nem «advices». Para contar, usa-se «a piece of advice». Acontece o mesmo com «information», «furniture» e «news».","v":"62305eab"},{"idioma":"en","id":"en-f030","tipo":"frase","en":"I don't have much time.","pt":"Não tenho muito tempo.","aceitas":["nao tenho muito tempo","eu nao tenho muito tempo","tenho pouco tempo","nao tenho tempo sobrando"],"aceitasEn":["i dont have much time","i do not have much time","i havent got much time"],"distratores":["Não tenho muito dinheiro.","Não tenho muita paciência.","Não tenho muita pressa.","Não tenho muita escolha."],"nivel":"A2","tags":["gramática","cotidiano"],"nota":"«Much» vai com o que não se conta — tempo, água, dinheiro — e «many» com o que se conta: «many people», «many hours». Em frase afirmativa os dois soam formais, e se troca por «a lot of».","v":"6deadf1c"},{"idioma":"en","id":"en-f031","tipo":"frase","en":"How much does it cost?","pt":"Quanto custa?","aceitas":["quanto custa","quanto e","quanto que custa","qual e o preco"],"aceitasEn":["how much does it cost","how much is it"],"distratores":["Quanto demora?","Quanto pesa?","Quanto sobra?","Quanto falta?"],"nivel":"A1","tags":["gramática","economia"],"nota":"Na pergunta, quem carrega o tempo e a pessoa é o «does», e por isso o verbo volta à forma nua: «does it cost», e não «does it costs».","v":"0a93e558"},{"idioma":"en","id":"en-f032","tipo":"frase","en":"If I had money, I would travel.","pt":"Se eu tivesse dinheiro, viajaria.","aceitas":["se eu tivesse dinheiro viajaria","se eu tivesse dinheiro eu viajaria","se eu tivesse dinheiro eu ia viajar","se tivesse dinheiro viajava"],"aceitasEn":["if i had money i would travel","if i had money id travel"],"distratores":["Se eu tiver dinheiro, vou viajar.","Se eu tivesse viajado, teria dinheiro.","Quando eu tiver dinheiro, eu viajo.","Se eu tenho dinheiro, eu viajo."],"nivel":"B1","tags":["condicional","gramática"],"nota":"O inglês faz a condição irreal com o passado simples — «if I had» — e a consequência com «would». Nada de «if I would have»: o «would» fica só do outro lado da vírgula.","v":"f364db37"},{"idioma":"en","id":"en-f033","tipo":"frase","en":"I wish I could go.","pt":"Queria poder ir.","aceitas":["queria poder ir","eu queria poder ir","quem me dera poder ir","gostaria de poder ir","pena que eu nao posso ir"],"aceitasEn":["i wish i could go","i wish that i could go"],"distratores":["Espero poder ir.","Prometo que vou.","Duvido que eu vá.","Preciso poder ir."],"nivel":"B2","tags":["subjuntivo","gramática"],"nota":"«Wish» é a lamentação pelo que não é; «hope» é a esperança pelo que ainda pode ser. Depois de «wish», o verbo recua um tempo: «I wish I could», «I wish I had».","v":"c537d26b"},{"idioma":"en","id":"en-f034","tipo":"frase","en":"You should have told me.","pt":"Você devia ter me contado.","aceitas":["voce devia ter me contado","voce deveria ter me contado","voce tinha que ter me contado","voce devia ter me avisado"],"aceitasEn":["you should have told me","you shouldve told me"],"distratores":["Você devia me contar.","Você precisava me contar.","Você podia ter me contado.","Você queria me contar."],"nivel":"B2","tags":["condicional","social"],"nota":"«Should have» + particípio é a censura pelo que não se fez. Na fala vira «should've», que soa quase como «shoulda» — e é por isso que muita gente escreve «should of», que é erro.","v":"827ec6b3"},{"idioma":"en","id":"en-f035","tipo":"frase","en":"Do you have any questions?","pt":"Você tem alguma pergunta?","aceitas":["voce tem alguma pergunta","tem alguma pergunta","voce tem alguma duvida","alguma pergunta"],"aceitasEn":["do you have any questions","have you got any questions","any questions"],"distratores":["Você tem a resposta certa?","Você entendeu a pergunta?","Você fez alguma pergunta?","Você respondeu a pergunta?"],"nivel":"A2","tags":["gramática","escola"],"nota":"«Any» é o «algum» da pergunta e da negativa; na afirmativa o lugar dele é de «some». Quem diz «do you have some questions» já está esperando que haja.","v":"2a45c1cc"},{"idioma":"en","id":"en-f036","tipo":"frase","en":"He's been working all day.","pt":"Ele está trabalhando o dia inteiro.","aceitas":["ele esta trabalhando o dia inteiro","ele trabalhou o dia inteiro","ele esta trabalhando o dia todo","ele esta desde cedo trabalhando"],"aceitasEn":["hes been working all day","he has been working all day"],"distratores":["Ele vai trabalhar o dia inteiro.","Ele trabalha todo dia.","Ele trabalhava o dia inteiro.","Ele parou de trabalhar hoje."],"nivel":"B2","tags":["present perfect","trabalho"],"nota":"«Have been + -ing» mostra a atividade que vem durando e ainda se sente: o cansaço, a sujeira, a demora. É o tempo de quem chega e vê o outro acabando.","v":"dd1925a7"},{"idioma":"en","id":"en-f037","tipo":"frase","en":"It's not a big deal.","pt":"Não é nada de mais.","aceitas":["nao e nada de mais","nao e nada demais","nao e grande coisa","nao tem problema","nao foi nada"],"aceitasEn":["its not a big deal","it is not a big deal","no big deal"],"distratores":["Não é um bom negócio.","Não foi um acordo justo.","Não é nada urgente.","Não é bem assim."],"nivel":"B1","tags":["expressão","social"],"nota":"«Deal» é negócio e acordo, mas em «a big deal» já perdeu o comércio: é o que merece alvoroço. Serve para tranquilizar quem pediu desculpa e para debochar de quem se gaba.","v":"837a763f"},{"idioma":"en","id":"en-f038","tipo":"frase","en":"I'm just kidding.","pt":"Tô brincando.","aceitas":["to brincando","estou brincando","e brincadeira","to de brincadeira","e so zoeira"],"aceitasEn":["im just kidding","i am just kidding","just kidding","im kidding"],"distratores":["Tô falando sério.","Tô só perguntando.","Tô quase pronto.","Tô indo embora."],"nivel":"A2","tags":["expressão","gíria"],"nota":"«Kid» como verbo é brincar de mentirinha; como nome é criança. Na conversa se corta para «just kidding» ou só «kidding», logo depois da piada que não pegou.","v":"630dd1f5"},{"idioma":"en","id":"en-f039","tipo":"frase","en":"Make yourself at home.","pt":"Fique à vontade.","aceitas":["fique a vontade","fica a vontade","sinta-se em casa","se sinta em casa","esteja a vontade"],"aceitasEn":["make yourself at home","make yourselves at home"],"distratores":["Vá para casa.","Faça você mesmo.","Arrume a sua casa.","Volte outro dia."],"nivel":"B1","tags":["expressão","social"],"nota":"É o que o anfitrião diz na porta. A construção «make yourself + adjetivo» rende outras: «make yourself comfortable», «make yourself useful».","v":"790c08a2"},{"idioma":"en","id":"en-f040","tipo":"frase","en":"I can't make it tonight.","pt":"Não vou conseguir ir hoje à noite.","aceitas":["nao vou conseguir ir hoje a noite","nao vou poder ir hoje a noite","hoje a noite eu nao consigo","nao da pra eu ir hoje a noite"],"aceitasEn":["i cant make it tonight","i can not make it tonight","i wont be able to make it tonight"],"distratores":["Não vou fazer isso hoje à noite.","Não vou ficar até de noite.","Não vou sair de casa hoje.","Não vou chegar cedo hoje."],"nivel":"B1","tags":["expressão","social"],"nota":"«Make it» é conseguir chegar, ou conseguir sobreviver: «he made it to the top», «the dog made it». Nada a ver com fazer alguma coisa.","v":"557692b9"},{"idioma":"en","id":"en-f041","tipo":"frase","en":"That rings a bell.","pt":"Isso me diz alguma coisa.","aceitas":["isso me diz alguma coisa","isso me soa familiar","ja ouvi falar disso","isso me lembra alguma coisa","isso nao me e estranho"],"aceitasEn":["that rings a bell","it rings a bell"],"distratores":["Isso toca a campainha.","Isso faz muito barulho.","Isso não me diz nada.","Isso me dá vontade de rir."],"nivel":"B2","tags":["expressão","cotidiano"],"nota":"A imagem é a do sininho que toca lá no fundo da memória: reconhece-se o nome sem lembrar de onde. Para dizer o contrário, «it doesn't ring a bell».","v":"7b8c3208"},{"idioma":"en","id":"en-f042","tipo":"frase","en":"It's worth it.","pt":"Vale a pena.","aceitas":["vale a pena","vale a pena sim","compensa","vale o esforco"],"aceitasEn":["its worth it","it is worth it","its worthwhile"],"distratores":["Custa caro.","É de graça.","Não tem preço.","Dá muito trabalho."],"nivel":"B1","tags":["expressão","cotidiano"],"nota":"«Worth» não é verbo: anda sempre com «be». Depois dele o verbo vai no gerúndio — «it's worth trying», vale a pena tentar.","v":"29c50d93"},{"idioma":"en","id":"en-f043","tipo":"frase","en":"I miss you.","pt":"Estou com saudade de você.","aceitas":["estou com saudade de voce","to com saudade de voce","sinto sua falta","tenho saudade de voce","sinto falta de voce"],"aceitasEn":["i miss you","i miss you so much"],"distratores":["Estou com raiva de você.","Estou com ciúme de você.","Estou com medo de você.","Estou atrás de você."],"nivel":"A2","tags":["expressão","família"],"nota":"Repare em quem é o sujeito: em inglês quem sente é que vem na frente — «I miss you» —, ao contrário do português, em que a saudade é minha mas a falta é sua. O outro sentido de «miss» é perder: «I missed the bus».","v":"c2b18061"},{"idioma":"en","id":"en-f044","tipo":"frase","en":"Let me know.","pt":"Me avisa.","aceitas":["me avisa","me avise","me diga depois","me fala depois","me conta depois"],"aceitasEn":["let me know","just let me know"],"distratores":["Me deixa saber.","Me conta tudo.","Me espera aí.","Me ajuda nisso."],"nivel":"A2","tags":["expressão","social"],"nota":"É o fecho de toda conversa combinada. Traduzido ao pé da letra vira «deixe-me saber», que ninguém diz — o português resolve com «me avisa».","v":"b98822cf"},{"idioma":"en","id":"en-v007","tipo":"frase","en":"I went to the beach.","pt":"Eu fui à praia.","aceitas":["eu fui a praia","fui a praia","eu fui na praia","fui para a praia"],"aceitasEn":["i went to the beach"],"distratores":["Eu vou à praia.","Eu irei à praia.","Eu iria à praia.","Eu tinha ido à praia."],"formasEn":{"I go to the beach":"presente","I will go to the beach":"futuro","I would go to the beach":"condicional","I had gone to the beach":"mais-que-perfeito"},"nivel":"A1","tags":["conjugação","irregular","go","pretérito"],"nota":"«Go» faz «went» no passado — uma forma que não tem nada a ver com o verbo, porque vem de outro verbo antigo, «wend». O particípio é «gone».","v":"a670532c"},{"idioma":"en","id":"en-v008","tipo":"frase","en":"She took my umbrella.","pt":"Ela levou meu guarda-chuva.","aceitas":["ela levou meu guarda-chuva","levou meu guarda-chuva","ela pegou meu guarda-chuva","ela levou o meu guarda-chuva"],"aceitasEn":["she took my umbrella"],"distratores":["Ela leva meu guarda-chuva.","Ela levará meu guarda-chuva.","Ela levaria meu guarda-chuva.","Ela tinha levado meu guarda-chuva."],"formasEn":{"She takes my umbrella":"presente","She will take my umbrella":"futuro","She would take my umbrella":"condicional","She had taken my umbrella":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","irregular","take","pretérito"],"nota":"«Take» é levar daqui para lá, e «bring» é trazer de lá para cá — o par muda conforme onde está quem fala. No passado, «took»; no particípio, «taken».","v":"cbdc99cd"},{"idioma":"en","id":"en-v009","tipo":"frase","en":"They gave us a discount.","pt":"Eles nos deram um desconto.","aceitas":["eles nos deram um desconto","nos deram um desconto","eles deram um desconto pra gente","deram um desconto pra gente"],"aceitasEn":["they gave us a discount"],"distratores":["Eles nos dão um desconto.","Eles nos darão um desconto.","Eles nos dariam um desconto.","Eles nos tinham dado um desconto."],"formasEn":{"They give us a discount":"presente","They will give us a discount":"futuro","They would give us a discount":"condicional","They had given us a discount":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","irregular","give","pretérito","economia"],"nota":"«Give» aceita duas ordens: «give us a discount» e «give a discount to us». Com dois objetos curtos, a primeira é sempre a que se ouve. Passado «gave», particípio «given».","v":"87aae86f"},{"idioma":"en","id":"en-v010","tipo":"frase","en":"I made a mistake.","pt":"Eu cometi um erro.","aceitas":["eu cometi um erro","cometi um erro","eu errei","eu fiz uma besteira","eu me enganei"],"aceitasEn":["i made a mistake"],"distratores":["Eu cometo um erro.","Eu cometerei um erro.","Eu cometeria um erro.","Eu tinha cometido um erro."],"formasEn":{"I make a mistake":"presente","I will make a mistake":"futuro","I would make a mistake":"condicional","I had made a mistake":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","irregular","make","pretérito"],"nota":"Erro se comete com «make», nunca com «do»: «make a mistake». «Make» é o que se cria — bolo, barulho, dinheiro —, e «do» é a atividade: «do the dishes», «do your homework».","v":"62fb5799"},{"idioma":"en","id":"en-v011","tipo":"frase","en":"He came late.","pt":"Ele chegou tarde.","aceitas":["ele chegou tarde","chegou tarde","ele veio tarde","ele chegou atrasado"],"aceitasEn":["he came late"],"distratores":["Ele chega tarde.","Ele chegará tarde.","Ele chegaria tarde.","Ele tinha chegado tarde."],"formasEn":{"He comes late":"presente","He will come late":"futuro","He would come late":"condicional","He had come late":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","irregular","come","pretérito"],"nota":"«Come» faz «came» no passado e volta a «come» no particípio: a forma do meio é a única diferente. «Late» sozinho é tarde; «lately» é ultimamente.","v":"97944678"},{"idioma":"en","id":"en-v012","tipo":"frase","en":"I saw the movie.","pt":"Eu vi o filme.","aceitas":["eu vi o filme","vi o filme","eu assisti ao filme","eu assisti o filme"],"aceitasEn":["i saw the movie","i saw the film"],"distratores":["Eu vejo o filme.","Eu verei o filme.","Eu veria o filme.","Eu tinha visto o filme."],"formasEn":{"I see the movie":"presente","I will see the movie":"futuro","I would see the movie":"condicional","I had seen the movie":"mais-que-perfeito"},"nivel":"A1","tags":["conjugação","irregular","see","pretérito"],"nota":"«See», «saw», «seen» — três formas diferentes, e a do meio nunca vem com «have». Nos Estados Unidos o filme é «movie»; na Inglaterra, «film».","v":"0a36034c"},{"idioma":"en","id":"en-v013","tipo":"frase","en":"I knew the answer.","pt":"Eu sabia a resposta.","aceitas":["eu sabia a resposta","sabia a resposta","eu conhecia a resposta"],"aceitasEn":["i knew the answer"],"distratores":["Eu sei a resposta.","Eu saberei a resposta.","Eu saberia a resposta.","Eu tinha sabido a resposta."],"formasEn":{"I know the answer":"presente","I will know the answer":"futuro","I would know the answer":"condicional","I had known the answer":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","know","imperfeito"],"nota":"Um verbo só para saber e para conhecer: «I know the answer», «I know your sister». O passado é «knew», com o «k» mudo, e o particípio, «known».","v":"daf91ab3"},{"idioma":"en","id":"en-v014","tipo":"frase","en":"I thought about it.","pt":"Eu pensei nisso.","aceitas":["eu pensei nisso","pensei nisso","eu pensei sobre isso","eu refleti sobre isso"],"aceitasEn":["i thought about it"],"distratores":["Eu penso nisso.","Eu pensarei nisso.","Eu pensaria nisso.","Eu tinha pensado nisso."],"formasEn":{"I think about it":"presente","I will think about it":"futuro","I would think about it":"condicional","I had thought about it":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","irregular","think","pretérito"],"nota":"«Think about» é ficar pensando; «think of» é ter em mente, ou lembrar na hora. «Thought» serve de passado e de particípio, e é também o substantivo pensamento.","v":"278f6b3a"},{"idioma":"en","id":"en-v015","tipo":"frase","en":"I found the keys.","pt":"Eu achei as chaves.","aceitas":["eu achei as chaves","achei as chaves","eu encontrei as chaves","encontrei as chaves"],"aceitasEn":["i found the keys"],"distratores":["Eu acho as chaves.","Eu acharei as chaves.","Eu acharia as chaves.","Eu tinha achado as chaves."],"formasEn":{"I find the keys":"presente","I will find the keys":"futuro","I would find the keys":"condicional","I had found the keys":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","irregular","find","pretérito"],"nota":"«Find» é achar de procurar; achar de opinar é «think». «I find it difficult» é achar difícil, depois de experimentar — não é opinião solta. Passado e particípio são «found».","v":"3870ec03"},{"idioma":"en","id":"en-v016","tipo":"frase","en":"She left early.","pt":"Ela saiu cedo.","aceitas":["ela saiu cedo","saiu cedo","ela foi embora cedo","ela partiu cedo"],"aceitasEn":["she left early"],"distratores":["Ela sai cedo.","Ela sairá cedo.","Ela sairia cedo.","Ela tinha saído cedo."],"formasEn":{"She leaves early":"presente","She will leave early":"futuro","She would leave early":"condicional","She had left early":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","irregular","leave","pretérito"],"nota":"«Leave» é ir embora e é também deixar alguma coisa: «she left early», «she left her bag». Passado e particípio, «left» — a mesma palavra de esquerda.","v":"498ce7f1"},{"idioma":"en","id":"en-v017","tipo":"frase","en":"He put it on the table.","pt":"Ele pôs na mesa.","aceitas":["ele pos na mesa","ele colocou na mesa","ele botou na mesa","ele pos isso na mesa","ele deixou na mesa"],"aceitasEn":["he put it on the table"],"distratores":["Ele põe na mesa.","Ele porá na mesa.","Ele poria na mesa.","Ele tinha posto na mesa."],"formasEn":{"He will put it on the table":"futuro","He would put it on the table":"condicional","He had put it on the table":"mais-que-perfeito","He will have put it on the table":"futuro perfeito"},"nivel":"A2","tags":["conjugação","irregular","put","pretérito"],"nota":"«Put», «put», «put»: as três formas são a mesma palavra. Só o «s» da terceira pessoa separa o presente do passado — «he puts» é hoje, «he put» é ontem.","v":"cfae52b1"},{"idioma":"en","id":"en-v018","tipo":"frase","en":"He has written three books.","pt":"Ele escreveu três livros.","aceitas":["ele escreveu tres livros","escreveu tres livros","ele ja escreveu tres livros","ele tem tres livros escritos"],"aceitasEn":["he has written three books","hes written three books"],"distratores":["Ele escreve três livros.","Ele escreverá três livros.","Ele escreveria três livros.","Ele tinha escrito três livros."],"formasEn":{"He writes three books":"presente","He will write three books":"futuro","He would write three books":"condicional","He had written three books":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","present perfect","write","irregular"],"nota":"O present perfect conta o que já se fez até agora, sem dizer quando: a obra do autor vivo. Com a data — «in 2010» — a frase volta para o passado simples, «he wrote».","v":"e47edc70"},{"idioma":"en","id":"en-v019","tipo":"frase","en":"Have you spoken to him?","pt":"Você falou com ele?","aceitas":["voce falou com ele","ja falou com ele","voce ja falou com ele","voce chegou a falar com ele"],"aceitasEn":["have you spoken to him","have you talked to him"],"distratores":["Você fala com ele?","Você falará com ele?","Você falaria com ele?","Você tinha falado com ele?"],"formasEn":{"Do you speak to him":"presente","Will you speak to him":"futuro","Would you speak to him":"condicional","Had you spoken to him":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","present perfect","speak","irregular"],"nota":"Na pergunta do present perfect, quem vai para a frente é o «have»: «have you spoken?». E fala-se «to» alguém — «speak to him» —, ou «with», que é mais americano.","v":"2dfb3dbd"},{"idioma":"en","id":"en-v020","tipo":"frase","en":"I broke my leg.","pt":"Eu quebrei a perna.","aceitas":["eu quebrei a perna","quebrei a perna","eu quebrei minha perna","eu fraturei a perna"],"aceitasEn":["i broke my leg"],"distratores":["Eu quebro a perna.","Eu quebrarei a perna.","Eu quebraria a perna.","Eu tinha quebrado a perna."],"formasEn":{"I break my leg":"presente","I will break my leg":"futuro","I would break my leg":"condicional","I had broken my leg":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","irregular","break","saúde"],"nota":"Parte do corpo em inglês leva possessivo, e não artigo: «my leg», «your hand», «his head». «I broke the leg» faz pensar na perna da mesa.","v":"622704d4"},{"idioma":"en","id":"en-v021","tipo":"frase","en":"She drove all night.","pt":"Ela dirigiu a noite toda.","aceitas":["ela dirigiu a noite toda","dirigiu a noite toda","ela dirigiu a noite inteira","ela guiou a noite toda"],"aceitasEn":["she drove all night"],"distratores":["Ela dirige a noite toda.","Ela dirigirá a noite toda.","Ela dirigiria a noite toda.","Ela tinha dirigido a noite toda."],"formasEn":{"She drives all night":"presente","She will drive all night":"futuro","She would drive all night":"condicional","She had driven all night":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","drive","viagem"],"nota":"«Drive», «drove», «driven» — o mesmo desenho de «write», «wrote», «written». E «drive» também é levar alguém de carro: «I'll drive you home».","v":"f66eb0a4"},{"idioma":"en","id":"en-v022","tipo":"frase","en":"I felt sick.","pt":"Eu me senti mal.","aceitas":["eu me senti mal","me senti mal","eu passei mal","eu fiquei enjoado"],"aceitasEn":["i felt sick","i felt ill"],"distratores":["Eu me sinto mal.","Eu me sentirei mal.","Eu me sentiria mal.","Eu tinha me sentido mal."],"formasEn":{"I feel sick":"presente","I will feel sick":"futuro","I would feel sick":"condicional","I had felt sick":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","irregular","feel","saúde"],"nota":"«Feel» não é reflexivo em inglês: «I feel sick», sem «myself». Quem diz «I feel myself» está dizendo outra coisa bem diferente. Passado e particípio, «felt».","v":"c82b204c"},{"idioma":"en","id":"en-v023","tipo":"frase","en":"I've lost my keys.","pt":"Perdi minhas chaves.","aceitas":["perdi minhas chaves","eu perdi minhas chaves","perdi as minhas chaves","perdi minhas chaves e nao acho"],"aceitasEn":["ive lost my keys","i have lost my keys"],"distratores":["Perco minhas chaves.","Perderei minhas chaves.","Perderia minhas chaves.","Tinha perdido minhas chaves."],"formasEn":{"I lose my keys":"presente","I will lose my keys":"futuro","I would lose my keys":"condicional","I had lost my keys":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","present perfect","lose","irregular"],"nota":"O present perfect é o passado que ainda incomoda: perdi as chaves e continuo sem elas. Se já apareceram, a frase passa a ser «I lost my keys».","v":"e93c3589"},{"idioma":"en","id":"en-v024","tipo":"frase","en":"Who paid the bill?","pt":"Quem pagou a conta?","aceitas":["quem pagou a conta","quem que pagou a conta","quem pagou"],"aceitasEn":["who paid the bill","who paid the check"],"distratores":["Quem paga a conta?","Quem pagará a conta?","Quem pagaria a conta?","Quem tinha pago a conta?"],"formasEn":{"Who pays the bill":"presente","Who will pay the bill":"futuro","Who would pay the bill":"condicional","Who had paid the bill":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","irregular","pay","economia"],"nota":"Quando «who» é o sujeito, a pergunta não leva «did»: «who paid?», e não «who did pay?». Paga-se a conta e a pessoa direto, mas o que se compra vai com «for»: «I paid for the coffee».","v":"530a2d29"},{"idioma":"en","id":"en-v025","tipo":"frase","en":"I didn't understand.","pt":"Eu não entendi.","aceitas":["eu nao entendi","nao entendi","eu nao compreendi","nao peguei nada"],"aceitasEn":["i didnt understand","i did not understand"],"distratores":["Eu não entendo.","Eu não entenderei.","Eu não entenderia.","Eu não tinha entendido."],"formasEn":{"I do not understand":"presente","I will not understand":"futuro","I would not understand":"condicional","I had not understood":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","irregular","understand","gramática"],"nota":"Quem carrega o passado é o «did», e por isso o verbo fica nu: «I didn't understand», nunca «I didn't understood». O mesmo vale na pergunta.","v":"40ce183c"},{"idioma":"en","id":"en-v026","tipo":"frase","en":"I got a new job.","pt":"Consegui um emprego novo.","aceitas":["consegui um emprego novo","eu consegui um emprego novo","arrumei um emprego novo","consegui um trabalho novo"],"aceitasEn":["i got a new job"],"distratores":["Consigo um emprego novo.","Conseguirei um emprego novo.","Conseguiria um emprego novo.","Tinha conseguido um emprego novo."],"formasEn":{"I get a new job":"presente","I will get a new job":"futuro","I would get a new job":"condicional","I had gotten a new job":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","get","trabalho"],"nota":"«Get» é o verbo faz-tudo: conseguir, receber, comprar, chegar, ficar. O passado é «got», e o particípio é «gotten» nos Estados Unidos e «got» na Inglaterra.","v":"b4714350"},{"idioma":"en","id":"en-p031","tipo":"palavra","en":"the college","pt":"a faculdade","aceitas":["a faculdade","faculdade","a universidade","a facul"],"aceitasEn":["the college","college","a college"],"distratores":["o colégio","a escola","o internato","o cursinho"],"nivel":"B1","tags":["falso-amigo","escola","substantivo"],"nota":"Nos Estados Unidos «college» é a faculdade, e «go to college» é fazer curso superior. Colégio é «high school».\n🇺🇸 the college → 🇧🇷 a faculdade\n🇺🇸 the high school → 🇧🇷 o colégio","v":"6b53ea64"},{"idioma":"en","id":"en-u031","tipo":"frase","requer":"en-p031","en":"She's in her first year of college.","pt":"Ela está no primeiro ano da faculdade.","aceitas":["ela esta no primeiro ano da faculdade","esta no primeiro ano da faculdade","ela ta no primeiro ano da faculdade","ela esta no primeiro ano da universidade"],"aceitasEn":["shes in her first year of college","she is in her first year of college"],"distratores":["Ela está no primeiro ano do colégio.","Ela está no primeiro ano do mestrado.","Ela está no primeiro ano do estágio.","Ela está no primeiro ano do curso técnico."],"nivel":"B1","tags":["falso-amigo","escola"],"nota":"Os quatro anos têm nome próprio: «freshman», «sophomore», «junior» e «senior» — e servem tanto para a faculdade quanto para o colégio americano.","v":"4077de64"},{"idioma":"en","id":"en-p032","tipo":"palavra","en":"embarrassed","pt":"envergonhado","aceitas":["envergonhado","envergonhada","sem graca","constrangido","com vergonha"],"aceitasEn":["embarrassed","so embarrassed"],"distratores":["enrolado","confuso","distraído","atrapalhado"],"nivel":"B1","tags":["falso-amigo","adjetivo"],"nota":"A pessoa fica «embarrassed»; a situação é que é «embarrassing». Confundir os dois é dizer que você é constrangedor.","v":"cdc50221"},{"idioma":"en","id":"en-u032","tipo":"frase","requer":"en-p032","en":"I was so embarrassed.","pt":"Fiquei com tanta vergonha.","aceitas":["fiquei com tanta vergonha","fiquei com muita vergonha","que vergonha que eu passei","fiquei super sem graca"],"aceitasEn":["i was so embarrassed","i was really embarrassed"],"distratores":["Fiquei com tanta raiva.","Fiquei com tanto medo.","Fiquei com tanta inveja.","Fiquei com tanta pressa."],"nivel":"B1","tags":["falso-amigo","social"],"nota":"«So» antes de adjetivo é o «tanto» da queixa e do espanto: «so embarrassed», «so tired», «so good». Com substantivo no meio vira «such»: «such a mess».","v":"423b384e"},{"idioma":"en","id":"en-p033","tipo":"palavra","en":"large","pt":"grande","aceitas":["grande","amplo","espacoso","grandao"],"aceitasEn":["large","big"],"distratores":["largo","comprido","estreito","alto"],"nivel":"A2","tags":["falso-amigo","adjetivo"],"nota":"«Large» é grande, de tamanho — a camiseta G, o copo maior. Largo é «wide».\n🇺🇸 large → 🇧🇷 grande\n🇺🇸 wide → 🇧🇷 largo","v":"4df0bd04"},{"idioma":"en","id":"en-u033","tipo":"frase","requer":"en-p033","en":"I'd like a large coffee.","pt":"Queria um café grande.","aceitas":["queria um cafe grande","eu queria um cafe grande","gostaria de um cafe grande","queria um cafe grandao"],"aceitasEn":["id like a large coffee","i would like a large coffee"],"distratores":["Queria um café forte.","Queria um café quente.","Queria um café doce.","Queria um café simples."],"nivel":"A2","tags":["falso-amigo","comida"],"nota":"Nos copos e nas camisetas os tamanhos são «small», «medium» e «large» — e nas cafeterias americanas muitas vezes só há «tall», «grande» e «venti», que é italiano de propaganda.","v":"98ddbe20"},{"idioma":"en","id":"en-p034","tipo":"palavra","en":"the costume","pt":"a fantasia","aceitas":["a fantasia","fantasia","a roupa de festa"],"aceitasEn":["the costume","costume","a costume"],"distratores":["o costume","o hábito","o penteado","o uniforme"],"nivel":"B1","tags":["falso-amigo","roupa","substantivo"],"nota":"É a roupa de quem se veste de outra pessoa: no carnaval, no teatro, no Halloween. Costume é «habit» ou «custom».\n🇺🇸 the costume → 🇧🇷 a fantasia\n🇺🇸 the habit → 🇧🇷 o costume","v":"056bfad1"},{"idioma":"en","id":"en-u034","tipo":"frase","requer":"en-p034","en":"He wore a pirate costume.","pt":"Ele usou uma fantasia de pirata.","aceitas":["ele usou uma fantasia de pirata","ele estava de fantasia de pirata","ele foi fantasiado de pirata","ele vestiu uma fantasia de pirata"],"aceitasEn":["he wore a pirate costume","he was wearing a pirate costume"],"distratores":["Ele usou um chapéu de pirata.","Ele usou uma tatuagem de pirata.","Ele usou uma máscara de pirata.","Ele usou uma bandeira de pirata."],"nivel":"B1","tags":["falso-amigo","cultura"],"nota":"Roupa se usa com «wear», que no passado faz «wore». Vestir-se é «get dressed», e fantasiar-se é «dress up».","v":"7519e8f4"},{"idioma":"en","id":"en-p035","tipo":"palavra","en":"the injury","pt":"a lesão","aceitas":["a lesao","lesao","o ferimento","o machucado","a contusao"],"aceitasEn":["the injury","injury","an injury"],"distratores":["a cirurgia","o insulto","a doença","a cicatriz"],"nivel":"B2","tags":["falso-amigo","saúde","substantivo"],"nota":"É o dano no corpo: o jogador machucado, o acidente com feridos. Injúria, a ofensa, é «insult».\n🇺🇸 the injury → 🇧🇷 a lesão\n🇺🇸 the insult → 🇧🇷 a injúria","v":"bd17467c"},{"idioma":"en","id":"en-u035","tipo":"frase","requer":"en-p035","en":"He recovered from the injury.","pt":"Ele se recuperou da lesão.","aceitas":["ele se recuperou da lesao","se recuperou da lesao","ele se curou da lesao","ele voltou da lesao"],"aceitasEn":["he recovered from the injury","he has recovered from the injury"],"distratores":["Ele se recuperou da cirurgia.","Ele se recuperou da doença.","Ele se recuperou da viagem.","Ele se recuperou do susto."],"nivel":"B2","tags":["falso-amigo","saúde"],"nota":"«Recover from», sempre com «from». E quem se machucou fica «injured»; quem adoeceu fica «ill» ou «sick».","v":"ab758e01"},{"idioma":"en","id":"en-p036","tipo":"palavra","en":"sympathetic","pt":"compreensivo","aceitas":["compreensivo","solidario","acolhedor","que se compadece"],"aceitasEn":["sympathetic","understanding"],"distratores":["simpático","agradável","engraçado","carismático"],"nivel":"B2","tags":["falso-amigo","adjetivo","social"],"nota":"«Sympathetic» é quem se põe no lugar de quem sofre. Simpático, de agradável, é «nice» ou «friendly».\n🇺🇸 sympathetic → 🇧🇷 compreensivo\n🇺🇸 nice → 🇧🇷 simpático","v":"76a995bd"},{"idioma":"en","id":"en-u036","tipo":"frase","requer":"en-p036","en":"My boss was very sympathetic.","pt":"Meu chefe foi muito compreensivo.","aceitas":["meu chefe foi muito compreensivo","meu chefe foi bem compreensivo","meu chefe foi muito solidario"],"aceitasEn":["my boss was very sympathetic","my boss was really sympathetic"],"distratores":["Meu chefe foi muito simpático.","Meu chefe foi muito rígido.","Meu chefe foi muito injusto.","Meu chefe foi muito generoso."],"nivel":"B2","tags":["falso-amigo","trabalho"],"nota":"O verbo da mesma família é «sympathize with», que é compreender o lado de alguém, e não gostar dele.","v":"7873f1c8"},{"idioma":"en","id":"en-p037","tipo":"palavra","en":"eventual","pt":"final","aceitas":["final","que acaba acontecendo","derradeiro","ultimo"],"aceitasEn":["eventual","the eventual"],"distratores":["eventual","ocasional","provável","imediato"],"nivel":"B2","tags":["falso-amigo","adjetivo"],"nota":"«Eventual» é o que vem no fim, depois de tudo — o campeão da temporada, o desfecho da história. O eventual do português, que às vezes acontece, é «occasional».\n🇺🇸 eventual → 🇧🇷 final\n🇺🇸 occasional → 🇧🇷 eventual","v":"404d239f"},{"idioma":"en","id":"en-u037","tipo":"frase","requer":"en-p037","en":"The eventual result was a draw.","pt":"O resultado final foi um empate.","aceitas":["o resultado final foi um empate","no fim deu empate","o resultado final foi empate","acabou empatado"],"aceitasEn":["the eventual result was a draw","the eventual result was a tie"],"distratores":["O resultado eventual foi um empate.","O resultado parcial foi um empate.","O resultado oficial foi um empate.","O resultado justo foi um empate."],"nivel":"B2","tags":["falso-amigo","cultura"],"nota":"Empate no futebol é «a draw» na Inglaterra e «a tie» nos Estados Unidos. As duas se entendem em qualquer lugar.","v":"fa3f16ef"},{"idioma":"en","id":"en-p038","tipo":"palavra","en":"the disgust","pt":"o nojo","aceitas":["o nojo","nojo","a repugnancia","a repulsa"],"aceitasEn":["the disgust","disgust"],"distratores":["o desgosto","a tristeza","o cansaço","o susto"],"nivel":"B2","tags":["falso-amigo","substantivo","social"],"nota":"É o que se sente diante de comida estragada ou de uma injustiça — a cara fechada de repulsa. Desgosto, a tristeza funda, é «sorrow» ou «grief».\n🇺🇸 the disgust → 🇧🇷 o nojo\n🇺🇸 the sorrow → 🇧🇷 o desgosto","v":"f89b1e8b"},{"idioma":"en","id":"en-u038","tipo":"frase","requer":"en-p038","en":"She looked at me in disgust.","pt":"Ela me olhou com nojo.","aceitas":["ela me olhou com nojo","me olhou com nojo","ela olhou pra mim com nojo","ela me olhou com repulsa"],"aceitasEn":["she looked at me in disgust","she looked at me with disgust"],"distratores":["Ela me olhou com pena.","Ela me olhou com raiva.","Ela me olhou com carinho.","Ela me olhou com medo."],"nivel":"B2","tags":["falso-amigo","social"],"nota":"Aqui o «in» é o «com» do sentimento: «in disgust», «in horror», «in surprise». E olha-se «at» alguém — «look at me» —, nunca «look me».","v":"9587a6d8"},{"idioma":"en","id":"en-p039","tipo":"palavra","en":"to warn","pt":"avisar","aceitas":["avisar","alertar","prevenir","advertir","dar um aviso"],"aceitasEn":["to warn","warn"],"distratores":["ameaçar","aconselhar","proibir","castigar"],"nivel":"B1","tags":["verbo","social"],"nota":"«Warn» é avisar do perigo, e não do horário: para combinar a hora usa-se «let me know» ou «tell me». O assunto vai com «about»: «warn me about the traffic».","v":"002207df"},{"idioma":"en","id":"en-u039","tipo":"frase","requer":"en-p039","en":"I warned him about the dog.","pt":"Eu avisei ele sobre o cachorro.","aceitas":["eu avisei ele sobre o cachorro","avisei ele sobre o cachorro","eu o avisei sobre o cachorro","eu avisei ele do cachorro"],"aceitasEn":["i warned him about the dog","i warned him of the dog"],"distratores":["Eu perguntei a ele sobre o cachorro.","Eu reclamei com ele sobre o cachorro.","Eu menti para ele sobre o cachorro.","Eu briguei com ele por causa do cachorro."],"nivel":"B1","tags":["social","animais"],"nota":"A pessoa avisada vem logo depois do verbo, sem preposição: «warn him». Para pedir que não se faça algo, «warn him not to touch the dog».","v":"50e0c80c"},{"idioma":"en","id":"en-p040","tipo":"palavra","en":"the deception","pt":"o engano","aceitas":["o engano","engano","a fraude","a trapaca","o embuste"],"aceitasEn":["the deception","deception"],"distratores":["a decepção","a desilusão","a confusão","a demissão"],"nivel":"B2","tags":["falso-amigo","substantivo","jurídico"],"nota":"«Deception» é a mentira armada para enganar alguém. Decepção, a expectativa frustrada, é «disappointment».\n🇺🇸 the deception → 🇧🇷 o engano\n🇺🇸 the disappointment → 🇧🇷 a decepção","v":"13f0a6ee"},{"idioma":"en","id":"en-u040","tipo":"frase","requer":"en-p040","en":"It was all a deception.","pt":"Era tudo um engano.","aceitas":["era tudo um engano","era tudo uma farsa","foi tudo um engano","era tudo mentira"],"aceitasEn":["it was all a deception","it was all deception"],"distratores":["Era tudo uma decepção.","Era tudo uma brincadeira.","Era tudo um exagero.","Era tudo um mal-entendido."],"nivel":"B2","tags":["falso-amigo","social"],"nota":"O verbo é «deceive», enganar de propósito, e não se confunde com «receive» apesar da rima. Quem cai no engano é «deceived».","v":"388c63b6"},{"idioma":"en","id":"en-p041","tipo":"palavra","en":"the hanger","pt":"o cabide","aceitas":["o cabide","cabide"],"aceitasEn":["the hanger","hanger","a coat hanger"],"distratores":["o gancho","o prendedor","o armário","o varal"],"nivel":"B1","tags":["casa","roupa","substantivo"],"nota":"Vem de «to hang», pendurar, que no passado faz «hung». Cuidado para não confundir com «hangar», que é o do avião e leva outro som.","v":"cc4bf78e"},{"idioma":"en","id":"en-u041","tipo":"frase","requer":"en-p041","en":"Put the shirt on a hanger.","pt":"Ponha a camisa no cabide.","aceitas":["ponha a camisa no cabide","poe a camisa no cabide","coloque a camisa no cabide","pendure a camisa no cabide"],"aceitasEn":["put the shirt on a hanger","put the shirt on the hanger"],"distratores":["Ponha a camisa no varal.","Ponha a camisa na gaveta.","Ponha a camisa na mala.","Ponha a camisa na máquina."],"nivel":"B1","tags":["casa","roupa"],"nota":"No cabide é «on a hanger», com «on», porque a camisa fica apoiada em cima dele. Na gaveta é «in the drawer».","v":"226f35a9"},{"idioma":"en","id":"en-p042","tipo":"palavra","en":"the sleeve","pt":"a manga da camisa","aceitas":["a manga","manga","a manga da camisa","a manga da roupa"],"aceitasEn":["the sleeve","sleeve","a sleeve"],"distratores":["a gola da camisa","a barra da calça","a etiqueta da camisa","a costura da camisa"],"nivel":"A2","tags":["roupa","substantivo"],"nota":"A fruta e a roupa são a mesma palavra em português, e em inglês não: a manga da camisa é «sleeve» e a fruta é «mango». Sem manga é «sleeveless».\n🇺🇸 the sleeve → 🇧🇷 a manga da roupa\n🇺🇸 the mango → 🇧🇷 a manga de comer","v":"37088558"},{"idioma":"en","id":"en-u042","tipo":"frase","requer":"en-p042","en":"The sleeves are too long.","pt":"As mangas estão compridas demais.","aceitas":["as mangas estao compridas demais","as mangas estao muito compridas","as mangas ficaram compridas demais","as mangas estao longas demais"],"aceitasEn":["the sleeves are too long","the sleeves are very long"],"distratores":["As calças estão compridas demais.","As saias estão compridas demais.","As barras estão compridas demais.","As alças estão compridas demais."],"nivel":"A2","tags":["roupa","cotidiano"],"nota":"Na prova de roupa, o que não serve é «too long», «too tight», «too big». E arregaçar as mangas é «roll up your sleeves», que também vale no sentido de pôr a mão na massa.","v":"921fe489"},{"idioma":"en","id":"en-p043","tipo":"palavra","en":"the straw","pt":"o canudo","aceitas":["o canudo","canudo","o canudinho"],"aceitasEn":["the straw","straw","a straw"],"distratores":["o guardanapo","o palito","o copo","o garfo"],"nivel":"B1","tags":["comida","objetos","substantivo"],"nota":"A mesma palavra é a palha do campo, e foi de lá que veio o canudo: os primeiros eram de palha mesmo. O último gole difícil é «the last straw», a gota d'água.","v":"75df8981"},{"idioma":"en","id":"en-u043","tipo":"frase","requer":"en-p043","en":"Can I have a straw?","pt":"Pode me dar um canudo?","aceitas":["pode me dar um canudo","me da um canudo","voce pode me dar um canudo","tem canudo"],"aceitasEn":["can i have a straw","could i have a straw","may i have a straw"],"distratores":["Pode me dar um guardanapo?","Pode me dar um palito?","Pode me dar um copo?","Pode me dar um garfo?"],"nivel":"B1","tags":["comida","cotidiano"],"nota":"«Can I have» é como se pede qualquer coisa no balcão — comida, conta, informação. Traduzido ao pé da letra soa a «posso ter», mas é o «me dá» de todo dia.","v":"7b0c3b85"},{"idioma":"en","id":"en-p044","tipo":"palavra","en":"the ceiling","pt":"o teto","aceitas":["o teto","teto","o forro"],"aceitasEn":["the ceiling","ceiling","a ceiling"],"distratores":["o chão","o telhado","o piso","o porão"],"nivel":"A2","tags":["casa","substantivo"],"nota":"«Ceiling» é o teto visto de dentro; visto de fora, o telhado, é «the roof». O inglês separa os dois, e o português resolve os dois com «teto».","v":"b40a701f"},{"idioma":"en","id":"en-u044","tipo":"frase","requer":"en-p044","en":"There's a lamp on the ceiling.","pt":"Tem uma lâmpada no teto.","aceitas":["tem uma lampada no teto","ha uma lampada no teto","tem uma luminaria no teto","tem uma lampada pendurada no teto"],"aceitasEn":["theres a lamp on the ceiling","there is a lamp on the ceiling"],"distratores":["Tem uma lâmpada na parede.","Tem uma lâmpada na mesa.","Tem uma lâmpada na escada.","Tem uma lâmpada na varanda."],"nivel":"A2","tags":["casa","cotidiano"],"nota":"No teto é «on the ceiling», com «on», ainda que a lâmpada esteja pendurada de cabeça para baixo: o inglês pensa na superfície em que a coisa está presa.","v":"edb16fe6"},{"idioma":"en","id":"en-p045","tipo":"palavra","en":"the trash can","pt":"a lixeira","aceitas":["a lixeira","lixeira","o cesto de lixo","a cesta de lixo"],"aceitasEn":["the trash can","trash can","the garbage can","the bin"],"distratores":["a vassoura","a peneira","a caixa","a prateleira"],"nivel":"A2","tags":["casa","objetos","substantivo"],"nota":"Nos Estados Unidos o lixo é «trash» ou «garbage», e o cesto é «trash can». Na Inglaterra o lixo é «rubbish» e o cesto é só «bin».","v":"b222a15d"},{"idioma":"en","id":"en-u045","tipo":"frase","requer":"en-p045","en":"Throw it in the trash can.","pt":"Joga isso na lixeira.","aceitas":["joga isso na lixeira","jogue isso na lixeira","poe isso na lixeira","joga fora na lixeira"],"aceitasEn":["throw it in the trash can","throw it in the trash","throw it in the bin"],"distratores":["Joga isso na pia.","Joga isso na caixa.","Joga isso na sacola.","Joga isso na mochila."],"nivel":"A2","tags":["casa","cotidiano"],"nota":"Jogar fora é «throw away» quando não se diz onde, e «throw in the trash» quando se diz. «Throw out» também serve, e vale para pessoa: «they threw him out».","v":"df6f36ca"},{"idioma":"en","id":"en-p046","tipo":"palavra","en":"the neighborhood","pt":"o bairro","aceitas":["o bairro","bairro","a vizinhanca","a redondeza"],"aceitasEn":["the neighborhood","neighborhood","the neighbourhood"],"distratores":["o vizinho","o centro","o subúrbio","o condomínio"],"nivel":"A2","tags":["cidade","substantivo"],"nota":"Escreve-se «neighborhood» nos Estados Unidos e «neighbourhood» na Inglaterra — a mesma diferença de «color» e «colour». E serve também para a gente que mora lá: «the whole neighborhood came».","v":"949c9534"},{"idioma":"en","id":"en-u046","tipo":"frase","requer":"en-p046","en":"I grew up in this neighborhood.","pt":"Eu cresci neste bairro.","aceitas":["eu cresci neste bairro","cresci neste bairro","eu me criei neste bairro","eu cresci nesse bairro"],"aceitasEn":["i grew up in this neighborhood","i grew up in this neighbourhood"],"distratores":["Eu cresci neste prédio.","Eu cresci neste sítio.","Eu cresci neste colégio.","Eu cresci neste país."],"nivel":"A2","tags":["cidade","família"],"nota":"«Grow up» é crescer de virar adulto; crescer de ficar maior é «grow» sozinho. A planta «grows», a criança «grows up».","v":"41bdf4e7"},{"idioma":"en","id":"en-p047","tipo":"palavra","en":"the schedule","pt":"o horário","aceitas":["o horario","horario","a agenda","a programacao","o cronograma"],"aceitasEn":["the schedule","schedule","a schedule"],"distratores":["o prazo","o cartaz","o formulário","o resumo"],"nivel":"B1","tags":["trabalho","substantivo","cotidiano"],"nota":"É uma das palavras que mais denunciam de onde a pessoa aprendeu inglês: nos Estados Unidos soa «skédjul» e na Inglaterra, «chédiul». Serve também de verbo: «to schedule a meeting», marcar uma reunião.","v":"6b4e6f3d"},{"idioma":"en","id":"en-u047","tipo":"frase","requer":"en-p047","en":"Let me check my schedule.","pt":"Deixa eu ver minha agenda.","aceitas":["deixa eu ver minha agenda","deixe eu ver minha agenda","deixa eu olhar minha agenda","vou ver minha agenda"],"aceitasEn":["let me check my schedule","let me check my diary"],"distratores":["Deixa eu ver minha carteira.","Deixa eu ver minha mochila.","Deixa eu ver minha conta.","Deixa eu ver minha mensagem."],"nivel":"B1","tags":["trabalho","cotidiano"],"nota":"«Check» é conferir, dar uma olhada: a agenda, a conta, o e-mail, as horas. Na Inglaterra a agenda de papel também é «a diary», que nos Estados Unidos é só o diário íntimo.","v":"c80b7fb7"},{"idioma":"en","id":"en-p048","tipo":"palavra","en":"to mind","pt":"se importar","aceitas":["se importar","importar-se","se incomodar","ligar para","fazer questao"],"aceitasEn":["to mind","mind"],"distratores":["se lembrar","se preparar","se arrepender","se acostumar"],"nivel":"B1","tags":["verbo","social"],"nota":"Cuidado com a resposta: a «do you mind if I smoke?» quem responde «no» está dizendo que pode. Dizer «yes» é recusar.","v":"6a2d87ad"},{"idioma":"en","id":"en-u048","tipo":"frase","requer":"en-p048","en":"Do you mind if I open the window?","pt":"Você se importa se eu abrir a janela?","aceitas":["voce se importa se eu abrir a janela","se importa se eu abrir a janela","voce se incomoda se eu abrir a janela","posso abrir a janela"],"aceitasEn":["do you mind if i open the window","would you mind if i opened the window"],"distratores":["Você prefere que eu abra a janela?","Você consegue abrir a janela?","Você sabe como abrir a janela?","Você quer que eu feche a janela?"],"nivel":"B1","tags":["social","formal"],"nota":"Depois de «do you mind» vem o presente — «if I open» —, e depois de «would you mind», o passado: «if I opened». O segundo é mais cerimonioso.","v":"7629b8bb"},{"idioma":"en","id":"en-p049","tipo":"palavra","en":"to waste","pt":"desperdiçar","aceitas":["desperdicar","perder","jogar fora","gastar a toa","esbanjar"],"aceitasEn":["to waste","waste"],"distratores":["aproveitar","economizar","guardar","investir"],"nivel":"B1","tags":["verbo","economia"],"nota":"Desperdiça-se tempo, dinheiro, comida e talento: «waste time», «waste money». Como nome, «waste» é o lixo e o desperdício, e «a waste of time» é perda de tempo.","v":"cbb7e831"},{"idioma":"en","id":"en-u049","tipo":"frase","requer":"en-p049","en":"Don't waste your time.","pt":"Não perca seu tempo.","aceitas":["nao perca seu tempo","nao perca o seu tempo","nao perde seu tempo","nao desperdice seu tempo"],"aceitasEn":["dont waste your time","do not waste your time"],"distratores":["Não perca sua vez.","Não perca a esperança.","Não perca a linha.","Não perca o ônibus."],"nivel":"B1","tags":["cotidiano","social"],"nota":"Em português o verbo é «perder»; em inglês, «perder tempo» é «waste time», e «lose time» quase não se diz. «Lose» é perder o que se tinha: as chaves, o jogo, o emprego.","v":"02f5c2a3"},{"idioma":"en","id":"en-p050","tipo":"palavra","en":"to achieve","pt":"alcançar","aceitas":["alcancar","conseguir","atingir","realizar","obter"],"aceitasEn":["to achieve","achieve"],"distratores":["tentar","planejar","desistir","prometer"],"nivel":"B1","tags":["verbo","trabalho"],"nota":"«Achieve» pede sempre um objeto — um objetivo, um resultado, um sonho —, e nunca vem sozinho. O nome é «achievement», a conquista.","v":"c11ee7b2"},{"idioma":"en","id":"en-u050","tipo":"frase","requer":"en-p050","en":"She achieved her goal.","pt":"Ela alcançou seu objetivo.","aceitas":["ela alcancou seu objetivo","ela atingiu seu objetivo","ela conseguiu o que queria","ela alcancou o objetivo dela"],"aceitasEn":["she achieved her goal","she achieved her goals"],"distratores":["Ela mudou seu objetivo.","Ela explicou seu objetivo.","Ela abandonou seu objetivo.","Ela escolheu seu objetivo."],"nivel":"B1","tags":["trabalho","social"],"nota":"«Goal» é o objetivo e é também o gol do futebol — a mesma palavra para a meta e para a baliza.","v":"d3ecf3a5"},{"idioma":"en","id":"en-p051","tipo":"palavra","en":"tough","pt":"difícil","aceitas":["dificil","duro","puxado","complicado","pesado"],"aceitasEn":["tough","hard"],"distratores":["macio","leve","simples","raro"],"nivel":"B1","tags":["adjetivo","social"],"nota":"Serve para o que exige esforço — «a tough decision», «a tough year» — e também para a carne que não se corta. O «gh» é mudo e a palavra soa «tâf».","v":"fa6049d3"},{"idioma":"en","id":"en-u051","tipo":"frase","requer":"en-p051","en":"It's been a tough year.","pt":"Foi um ano difícil.","aceitas":["foi um ano dificil","foi um ano duro","foi um ano puxado","esse ano foi dificil"],"aceitasEn":["its been a tough year","it has been a tough year"],"distratores":["Foi um ano curto.","Foi um ano estranho.","Foi um ano cheio.","Foi um ano tranquilo."],"nivel":"B1","tags":["social","cotidiano"],"nota":"O ano ainda não acabou, e por isso o present perfect: «it's been». Com o ano fechado, a frase vira «it was a tough year».","v":"83c273e2"},{"idioma":"en","id":"en-p052","tipo":"palavra","en":"to quit","pt":"largar","aceitas":["largar","parar","pedir demissao","abandonar","desistir de"],"aceitasEn":["to quit","quit"],"distratores":["contratar","promover","aposentar","transferir"],"nivel":"B1","tags":["verbo","trabalho"],"nota":"Larga-se o emprego, o cigarro e o curso. Com outro verbo atrás, ele vai no gerúndio: «quit smoking». E é dos poucos verbos com as três formas iguais: «quit», «quit», «quit».","v":"c9cf3a77"},{"idioma":"en","id":"en-u052","tipo":"frase","requer":"en-p052","en":"He quit his job last month.","pt":"Ele pediu demissão mês passado.","aceitas":["ele pediu demissao mes passado","ele largou o emprego mes passado","ele saiu do emprego mes passado","ele pediu as contas mes passado"],"aceitasEn":["he quit his job last month","he quit last month"],"distratores":["Ele mudou de emprego mês passado.","Ele foi promovido mês passado.","Ele foi demitido mês passado.","Ele se aposentou mês passado."],"nivel":"B1","tags":["trabalho","cotidiano"],"nota":"Quem sai por vontade própria «quits»; quem é mandado embora «is fired» ou «gets laid off». Confundir os dois muda toda a história.","v":"58ad24c7"},{"idioma":"en","id":"en-f045","tipo":"frase","en":"My car broke down.","pt":"Meu carro quebrou.","aceitas":["meu carro quebrou","o meu carro quebrou","meu carro deu problema","meu carro pifou"],"aceitasEn":["my car broke down","my car has broken down"],"distratores":["Meu carro sumiu.","Meu carro capotou.","Meu carro pegou fogo.","Meu carro foi rebocado."],"nivel":"B1","tags":["phrasal verb","viagem"],"nota":"«Break down» é a máquina que para de funcionar: o carro, a geladeira, o elevador. Dito de gente, é desabar em choro. O nome é «a breakdown».","v":"e2a11340"},{"idioma":"en","id":"en-f046","tipo":"frase","en":"She takes after her mother.","pt":"Ela puxou à mãe.","aceitas":["ela puxou a mae","ela puxou a mae dela","ela saiu a mae","ela e a cara da mae","ela se parece com a mae"],"aceitasEn":["she takes after her mother","she takes after her mom"],"distratores":["Ela cuida da mãe.","Ela vai atrás da mãe.","Ela mora com a mãe.","Ela obedece à mãe."],"nivel":"B2","tags":["phrasal verb","família"],"nota":"«Take after» é parecer-se com um parente, de nascença — nunca com um estranho. Para a semelhança comum, «look like»: «she looks like her mother».","v":"67d9883f"},{"idioma":"en","id":"en-f047","tipo":"frase","en":"Don't put it off.","pt":"Não deixe para depois.","aceitas":["nao deixe para depois","nao deixa pra depois","nao adie isso","nao empurre com a barriga"],"aceitasEn":["dont put it off","do not put it off"],"distratores":["Não jogue isso no lixo.","Não guarde isso na gaveta.","Não tire isso da mesa.","Não coloque isso no chão."],"nivel":"B1","tags":["phrasal verb","trabalho"],"nota":"«Put» muda inteiro com a partícula: «put off» é adiar, «put on» é vestir, «put up with» é aguentar e «put away» é guardar.","v":"465ba8df"},{"idioma":"en","id":"en-f048","tipo":"frase","en":"In the end, I gave in.","pt":"No fim, eu cedi.","aceitas":["no fim eu cedi","no final eu cedi","no fim das contas eu cedi","acabei cedendo"],"aceitasEn":["in the end i gave in","in the end i gave in to him"],"distratores":["No fim, eu desisti.","No fim, eu insisti.","No fim, eu me arrependi.","No fim, eu entreguei tudo."],"nivel":"B2","tags":["phrasal verb","social"],"nota":"«Give in» é ceder na discussão, parar de resistir a quem insiste. «Give up» é desistir do que se estava fazendo. Um é sobre o outro; o outro é sobre a tarefa.","v":"a42dab53"},{"idioma":"en","id":"en-f049","tipo":"frase","en":"He hung up on me.","pt":"Ele desligou na minha cara.","aceitas":["ele desligou na minha cara","ele me desligou na cara","ele desligou o telefone na minha cara","ele bateu o telefone"],"aceitasEn":["he hung up on me","he hung up the phone on me"],"distratores":["Ele gritou comigo ao telefone.","Ele me ligou de madrugada.","Ele mentiu para mim ao telefone.","Ele me deixou esperando na linha."],"nivel":"B1","tags":["phrasal verb","tecnologia"],"nota":"«Hang up» é desligar o telefone; com «on» mais alguém, é desligar na cara. O passado é «hung», o mesmo de pendurar — que é de onde a palavra vem, do tempo do gancho.","v":"a5984a49"},{"idioma":"en","id":"en-f050","tipo":"frase","en":"It turned out well.","pt":"Acabou dando certo.","aceitas":["acabou dando certo","deu certo no fim","no fim deu certo","acabou bem"],"aceitasEn":["it turned out well","it turned out fine"],"distratores":["Começou bem demais.","Terminou cedo demais.","Ficou pela metade.","Deu tudo errado."],"nivel":"B1","tags":["phrasal verb","cotidiano"],"nota":"«Turn out» é o que se descobre no fim: «it turned out to be easy», «it turns out that he knew». Conta o desfecho que ninguém esperava.","v":"9e91d948"},{"idioma":"en","id":"en-f051","tipo":"frase","en":"I work out three times a week.","pt":"Eu malho três vezes por semana.","aceitas":["eu malho tres vezes por semana","eu treino tres vezes por semana","eu faco academia tres vezes por semana","malho tres vezes por semana"],"aceitasEn":["i work out three times a week","i work out 3 times a week"],"distratores":["Eu viajo três vezes por semana.","Eu cozinho três vezes por semana.","Eu estudo três vezes por semana.","Eu corro três vezes por semana."],"nivel":"B1","tags":["phrasal verb","saúde"],"nota":"A frequência vai com «a»: «three times a week», «twice a month», «once a year». E «work out» também é dar certo e calcular: «it worked out», «work out the total».","v":"ef86bdf4"},{"idioma":"en","id":"en-f052","tipo":"frase","en":"Don't bring that up again.","pt":"Não toque nesse assunto de novo.","aceitas":["nao toque nesse assunto de novo","nao fale nisso de novo","nao levante esse assunto de novo","nao venha com isso de novo"],"aceitasEn":["dont bring that up again","do not bring that up again"],"distratores":["Não traga isso aqui de novo.","Não fale alto sobre isso de novo.","Não escreva sobre isso de novo.","Não brinque com isso de novo."],"nivel":"B2","tags":["phrasal verb","social"],"nota":"«Bring up» é pôr um assunto na mesa. O mesmo verbo é criar uma criança: «she brought up three kids» — e aí o sentido é levantar alguém até a idade adulta.","v":"2dc2b599"},{"idioma":"en","id":"en-f053","tipo":"frase","en":"Carry on.","pt":"Pode continuar.","aceitas":["pode continuar","continue","pode seguir","segue em frente"],"aceitasEn":["carry on","carry on with it","go on"],"distratores":["Pode levar.","Pode esperar.","Pode começar.","Pode entrar."],"nivel":"B1","tags":["phrasal verb","cotidiano"],"nota":"É mais britânico que americano, e serve de incentivo e de licença. Como nome, «carry-on» é outra coisa: a bagagem de mão do avião.","v":"f373c1a4"},{"idioma":"en","id":"en-f054","tipo":"frase","en":"He passed out.","pt":"Ele desmaiou.","aceitas":["ele desmaiou","desmaiou","ele apagou","ele caiu duro"],"aceitasEn":["he passed out","he passed out cold"],"distratores":["Ele passou direto.","Ele foi aprovado.","Ele saiu correndo.","Ele apagou a luz."],"nivel":"B2","tags":["phrasal verb","saúde"],"nota":"«Pass out» é perder os sentidos — e também distribuir alguma coisa para todos. Não confundir com «pass away», que é falecer.","v":"faa4f439"},{"idioma":"en","id":"en-f055","tipo":"frase","en":"I'm afraid of spiders.","pt":"Tenho medo de aranha.","aceitas":["tenho medo de aranha","eu tenho medo de aranha","tenho medo de aranhas","morro de medo de aranha"],"aceitasEn":["im afraid of spiders","i am afraid of spiders","im scared of spiders"],"distratores":["Tenho nojo de aranha.","Tenho alergia a aranha.","Tenho pena de aranha.","Tenho aranha em casa."],"nivel":"A2","tags":["preposição","animais"],"nota":"«Afraid of», sempre com «of». E «I'm afraid» sozinho, no começo da frase, não é medo: é o «lamento informar» da má notícia educada.","v":"19817692"},{"idioma":"en","id":"en-f056","tipo":"frase","en":"I'm proud of you.","pt":"Tenho orgulho de você.","aceitas":["tenho orgulho de voce","estou orgulhoso de voce","que orgulho de voce","tenho orgulho de ti"],"aceitasEn":["im proud of you","i am proud of you"],"distratores":["Tenho ciúme de você.","Tenho pena de você.","Tenho inveja de você.","Tenho raiva de você."],"nivel":"A2","tags":["preposição","família"],"nota":"«Proud of» antes de nome ou pessoa, e «proud to» antes de verbo: «proud to be here». É frase de pai, de treinador e de professor.","v":"e522e52d"},{"idioma":"en","id":"en-f057","tipo":"frase","en":"This belongs to me.","pt":"Isso é meu.","aceitas":["isso e meu","isto e meu","isso me pertence","isso ai e meu"],"aceitasEn":["this belongs to me","it belongs to me"],"distratores":["Isso é para mim.","Isso é igual ao meu.","Isso é comigo.","Isso parece o meu."],"nivel":"A2","tags":["preposição","objetos"],"nota":"«Belong» pede «to» e nunca aparece no contínuo: «this belongs to me», e nunca «is belonging». É um dos verbos de estado, como «know», «want» e «love».","v":"89bedb41"},{"idioma":"en","id":"en-f058","tipo":"frase","en":"I apologized for being late.","pt":"Pedi desculpa por ter chegado tarde.","aceitas":["pedi desculpa por ter chegado tarde","me desculpei por ter chegado tarde","pedi desculpas por chegar tarde","me desculpei pelo atraso"],"aceitasEn":["i apologized for being late","i apologised for being late"],"distratores":["Menti sobre ter chegado tarde.","Reclamei de ter chegado tarde.","Avisei que ia chegar tarde.","Expliquei por que cheguei tarde."],"nivel":"B1","tags":["preposição","social"],"nota":"Pede-se desculpa «for» alguma coisa e «to» alguém: «I apologized to her for being late». Depois de «for» o verbo vai no gerúndio, sempre.","v":"19483857"},{"idioma":"en","id":"en-f059","tipo":"frase","en":"I agree with you.","pt":"Concordo com você.","aceitas":["concordo com voce","eu concordo com voce","concordo contigo","tambem acho"],"aceitasEn":["i agree with you","i agree"],"distratores":["Discordo de você.","Entendo você.","Acredito em você.","Confio em você."],"nivel":"A2","tags":["preposição","social"],"nota":"«Agree» é verbo inteiro, e não adjetivo: diz-se «I agree», nunca «I am agree». Concorda-se «with» uma pessoa, «on» um plano e «to» uma proposta.","v":"34da93a0"},{"idioma":"en","id":"en-f060","tipo":"frase","en":"We're on time.","pt":"Estamos no horário.","aceitas":["estamos no horario","estamos na hora","estamos dentro do horario","chegamos na hora"],"aceitasEn":["were on time","we are on time"],"distratores":["Estamos atrasados.","Estamos adiantados.","Estamos sem tempo.","Estamos com pressa."],"nivel":"B1","tags":["preposição","viagem"],"nota":"«On time» é na hora marcada: o trem das oito saiu às oito. «In time» é a tempo de fazer algo: cheguei antes de a porta fechar. Uma letra, dois sentidos.","v":"1710db81"},{"idioma":"en","id":"en-f061","tipo":"frase","en":"It's made of wood.","pt":"É de madeira.","aceitas":["e de madeira","isso e de madeira","e feito de madeira","e todo de madeira"],"aceitasEn":["its made of wood","it is made of wood"],"distratores":["É parecido com madeira.","É pintado de madeira.","É coberto de madeira.","É cheio de madeira."],"nivel":"A2","tags":["preposição","objetos"],"nota":"«Made of» quando ainda se enxerga o material — a mesa de madeira. «Made from» quando ele se transformou — o papel, que também vem da madeira e já não parece.","v":"1f1e00ac"},{"idioma":"en","id":"en-f062","tipo":"frase","en":"I'm looking for my glasses.","pt":"Estou procurando meus óculos.","aceitas":["estou procurando meus oculos","to procurando meus oculos","estou atras dos meus oculos","procuro meus oculos"],"aceitasEn":["im looking for my glasses","i am looking for my glasses"],"distratores":["Estou usando meus óculos.","Estou limpando meus óculos.","Estou consertando meus óculos.","Estou guardando meus óculos."],"nivel":"A2","tags":["preposição","objetos"],"nota":"«Look for» é procurar, e o «for» é obrigatório. E «glasses» só existe no plural, como «trousers» e «scissors»: para contar, «a pair of glasses».","v":"0342c1dc"},{"idioma":"en","id":"en-f063","tipo":"frase","en":"It's going to rain.","pt":"Vai chover.","aceitas":["vai chover","ta pra chover","vai chover ja ja","acho que vai chover"],"aceitasEn":["its going to rain","it is going to rain","its gonna rain"],"distratores":["Vai esfriar.","Vai clarear.","Vai ventar.","Vai parar de chover."],"nivel":"A2","tags":["futuro","gramática"],"nota":"«Going to» é o futuro que já se vê chegando — as nuvens estão lá. «Will» é a decisão tomada na hora: «I'll get the umbrella».","v":"98140e23"},{"idioma":"en","id":"en-f064","tipo":"frase","en":"The house was built in 1920.","pt":"A casa foi construída em 1920.","aceitas":["a casa foi construida em 1920","construiram a casa em 1920","a casa e de 1920","a casa foi feita em 1920"],"aceitasEn":["the house was built in 1920","they built the house in 1920"],"distratores":["A casa foi vendida em 1920.","A casa foi reformada em 1920.","A casa foi comprada em 1920.","A casa foi demolida em 1920."],"nivel":"B1","tags":["gramática","casa"],"nota":"A voz passiva é «be» mais o particípio, e o inglês a usa muito mais do que o português, que prefere o «se» ou o sujeito indeterminado. Quem fez aparece com «by», se aparecer.","v":"620d1398"},{"idioma":"en","id":"en-f065","tipo":"frase","en":"You're from Brazil, aren't you?","pt":"Você é do Brasil, né?","aceitas":["voce e do brasil ne","voce e do brasil nao e","voce e brasileiro ne","voce e do brasil certo"],"aceitasEn":["youre from brazil arent you","you are from brazil arent you"],"distratores":["Você é do Brasil ou não?","Você já foi ao Brasil, né?","Você quer ir ao Brasil, né?","Você mora no Brasil, né?"],"nivel":"B1","tags":["gramática","social"],"nota":"O rabinho da pergunta vira do avesso: frase afirmativa pede fecho negativo, e vice-versa. Onde o português põe sempre «né», o inglês muda o verbo a cada frase: «isn't it», «don't you», «can't he».","v":"7b18e135"},{"idioma":"en","id":"en-f066","tipo":"frase","en":"This one is cheaper than that one.","pt":"Este é mais barato que aquele.","aceitas":["este e mais barato que aquele","esse e mais barato que aquele","este aqui e mais barato que aquele","este custa menos que aquele"],"aceitasEn":["this one is cheaper than that one","this is cheaper than that"],"distratores":["Este é tão barato quanto aquele.","Este é o mais barato de todos.","Este é mais caro que aquele.","Este é quase tão caro quanto aquele."],"nivel":"A2","tags":["gramática","economia"],"nota":"Adjetivo curto ganha «-er»: «cheaper», «bigger», «faster». Adjetivo longo pede «more»: «more expensive», «more difficult». E a comparação fecha com «than», que não é «that».","v":"a89f802b"},{"idioma":"en","id":"en-f067","tipo":"frase","en":"It's the best movie I've ever seen.","pt":"É o melhor filme que eu já vi.","aceitas":["e o melhor filme que eu ja vi","e o melhor filme que ja vi","o melhor filme que eu ja vi na vida","e o melhor filme que eu vi"],"aceitasEn":["its the best movie ive ever seen","it is the best movie i have ever seen"],"distratores":["É o pior filme que eu já vi.","É o filme mais longo que eu já vi.","É o único filme que eu já vi.","É o primeiro filme que eu já vi."],"nivel":"B1","tags":["gramática","cultura"],"nota":"No superlativo, «ever» é o «já» do balanço de toda a vida — e só aparece com o present perfect: «the best I've ever seen», «the worst I've ever had».","v":"afbfd08a"},{"idioma":"en","id":"en-f068","tipo":"frase","en":"How long does it take?","pt":"Quanto tempo leva?","aceitas":["quanto tempo leva","quanto tempo demora","leva quanto tempo","quanto tempo e"],"aceitasEn":["how long does it take","how long will it take"],"distratores":["Quanto tempo falta?","Quanto tempo passou?","Quanto tempo você tem?","Quanto tempo ficou?"],"nivel":"A2","tags":["gramática","viagem"],"nota":"Para tempo de percurso e de tarefa, o verbo é «take», e o sujeito é o «it» que não é ninguém: «it takes two hours». Com a pessoa na frente: «it took me two hours».","v":"fd512904"},{"idioma":"en","id":"en-f069","tipo":"frase","en":"He said he was tired.","pt":"Ele disse que estava cansado.","aceitas":["ele disse que estava cansado","disse que estava cansado","ele falou que estava cansado","ele disse estar cansado"],"aceitasEn":["he said he was tired","he said that he was tired"],"distratores":["Ele disse que ficou cansado.","Ele disse que estaria cansado.","Ele perguntou se eu estava cansado.","Ele achou que eu estava cansado."],"nivel":"B1","tags":["gramática","social"],"nota":"Ao contar o que alguém disse, o verbo recua um tempo: «I am tired» vira «he said he was tired». E «say» não pede pessoa, «tell» pede: «he told me».","v":"e1913576"},{"idioma":"en","id":"en-f070","tipo":"frase","en":"I don't either.","pt":"Eu também não.","aceitas":["eu tambem nao","tambem nao","nem eu","eu nao tambem"],"aceitasEn":["i dont either","me neither","neither do i"],"distratores":["Eu também.","Eu acho que não.","Eu não sei.","Eu prefiro que não."],"nivel":"B1","tags":["gramática","social"],"nota":"Para concordar com uma frase negativa há três maneiras, e todas valem: «I don't either», «me neither» e «neither do I». A última inverte a ordem, como na pergunta.","v":"5ab0f7a7"},{"idioma":"en","id":"en-f071","tipo":"frase","en":"So do I.","pt":"Eu também.","aceitas":["eu tambem","tambem","eu tambem sim","comigo e igual"],"aceitasEn":["so do i","me too","i do too"],"distratores":["Eu também não.","Eu acho que sim.","Eu não sei.","Eu prefiro assim."],"nivel":"B1","tags":["gramática","social"],"nota":"O verbo que vem depois de «so» é o mesmo da frase anterior: «I like it» pede «so do I», «I'm tired» pede «so am I», «I can swim» pede «so can I».","v":"c0a6374e"},{"idioma":"en","id":"en-f072","tipo":"frase","en":"We don't have enough chairs.","pt":"Não temos cadeiras suficientes.","aceitas":["nao temos cadeiras suficientes","nao tem cadeira suficiente","faltam cadeiras","nao ha cadeiras suficientes"],"aceitasEn":["we dont have enough chairs","we do not have enough chairs"],"distratores":["Não temos cadeiras confortáveis.","Não temos cadeiras iguais.","Não temos cadeiras de sobra.","Não temos cadeiras novas."],"nivel":"B1","tags":["gramática","casa"],"nota":"«Enough» é a única palavra do inglês que muda de lugar: antes do substantivo — «enough chairs» — e depois do adjetivo — «big enough», «old enough».","v":"c2127bb4"},{"idioma":"en","id":"en-f073","tipo":"frase","en":"It's too expensive to buy.","pt":"É caro demais para comprar.","aceitas":["e caro demais para comprar","e muito caro para comprar","e caro demais pra comprar","ta caro demais para comprar"],"aceitasEn":["its too expensive to buy","it is too expensive to buy"],"distratores":["É barato o bastante para comprar.","É bonito demais para vender.","É cedo demais para comprar.","É difícil demais de achar."],"nivel":"B1","tags":["gramática","economia"],"nota":"«Too... to» é o «demais para» que impede: caro demais, tarde demais. O par oposto é «enough to»: «cheap enough to buy», barato o bastante.","v":"48656b81"},{"idioma":"en","id":"en-f074","tipo":"frase","en":"Let's go out tonight.","pt":"Vamos sair hoje à noite.","aceitas":["vamos sair hoje a noite","bora sair hoje a noite","vamos sair essa noite","que tal sair hoje a noite"],"aceitasEn":["lets go out tonight","let us go out tonight"],"distratores":["Vamos ficar em casa hoje à noite.","Vamos jantar cedo hoje à noite.","Vamos dormir cedo hoje à noite.","Vamos trabalhar hoje à noite."],"nivel":"A2","tags":["gramática","social"],"nota":"«Let's» é «let us» encurtado, e é o convite que já conta com o outro. Depois dele o verbo vai nu, sem «to»: «let's go», «let's eat».","v":"8ae191e3"},{"idioma":"en","id":"en-f075","tipo":"frase","en":"I'm on my way.","pt":"Estou a caminho.","aceitas":["estou a caminho","to a caminho","estou indo","ja estou indo","to indo ja"],"aceitasEn":["im on my way","i am on my way","omw"],"distratores":["Estou no caminho certo.","Estou perdido no caminho.","Estou esperando na esquina.","Estou preso no trânsito."],"nivel":"A2","tags":["expressão","cotidiano"],"nota":"É a mensagem de quem está atrasado, e nas conversas de celular vira só «omw». O possessivo acompanha quem fala: «he's on his way», «we're on our way».","v":"e4a2aac8"},{"idioma":"en","id":"en-f076","tipo":"frase","en":"Take your time.","pt":"Sem pressa.","aceitas":["sem pressa","vai com calma","nao precisa ter pressa","pode ir devagar","fique a vontade no seu tempo"],"aceitasEn":["take your time","theres no rush"],"distratores":["Não temos tempo.","Me dá um tempo.","O tempo é curto.","Chega de enrolação."],"nivel":"A2","tags":["expressão","social"],"nota":"Traduzido palavra por palavra viraria «pegue o seu tempo», que não quer dizer nada. É exatamente o contrário de «hurry up».","v":"57e46014"},{"idioma":"en","id":"en-f077","tipo":"frase","en":"It's about time.","pt":"Já era hora.","aceitas":["ja era hora","ate que enfim","ja nao era sem tempo","demorou hein"],"aceitasEn":["its about time","it is about time"],"distratores":["É quase a hora.","Está na hora certa.","É sobre o horário.","Falta pouco para a hora."],"nivel":"B2","tags":["expressão","social"],"nota":"Não é informação de relógio: é reclamação de quem esperou demais, dita com meio sorriso. O «about» aqui não é «sobre».","v":"f4a553c3"},{"idioma":"en","id":"en-f078","tipo":"frase","en":"No wonder.","pt":"Não é à toa.","aceitas":["nao e a toa","com razao","agora entendi","nao e por acaso","por isso"],"aceitasEn":["no wonder","no wonder then"],"distratores":["Não tem graça.","Não faz sentido.","Não é bem assim.","Não tem jeito."],"nivel":"B1","tags":["expressão","social"],"nota":"«Wonder» é o espanto, a maravilha — as sete maravilhas do mundo são «the seven wonders». «No wonder» é dizer que não há o que estranhar: a explicação acabou de aparecer.","v":"475327f5"},{"idioma":"en","id":"en-f079","tipo":"frase","en":"Sounds good.","pt":"Por mim tudo bem.","aceitas":["por mim tudo bem","parece bom","boa ideia","fechado","ta otimo"],"aceitasEn":["sounds good","sounds good to me","sounds like a plan"],"distratores":["Parece caro.","Soa estranho.","Não ouvi direito.","Fala mais alto."],"nivel":"A2","tags":["expressão","social"],"nota":"Nada a ver com som: é como se aceita um convite ou um plano. A variante mais animada é «sounds like a plan».","v":"e0d2139f"},{"idioma":"en","id":"en-f080","tipo":"frase","en":"Same here.","pt":"Comigo também.","aceitas":["comigo tambem","aqui tambem","comigo e a mesma coisa","pra mim tambem","o mesmo aqui"],"aceitasEn":["same here","same for me"],"distratores":["Aqui é igual.","Aqui é o mesmo lugar.","Bem aqui.","É o mesmo de sempre."],"nivel":"B1","tags":["expressão","social"],"nota":"Serve para concordar com um sentimento e também para repetir um pedido no restaurante: o segundo a pedir diz «same here» e ganha o mesmo prato.","v":"68b59d18"},{"idioma":"en","id":"en-v027","tipo":"frase","en":"I sat in the front row.","pt":"Eu sentei na primeira fila.","aceitas":["eu sentei na primeira fila","sentei na primeira fila","eu me sentei na primeira fila","eu sentei na fila da frente"],"aceitasEn":["i sat in the front row"],"distratores":["Eu sento na primeira fila.","Eu sentarei na primeira fila.","Eu sentaria na primeira fila.","Eu tinha sentado na primeira fila."],"formasEn":{"I sit in the front row":"presente","I will sit in the front row":"futuro","I would sit in the front row":"condicional","I had sat in the front row":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","irregular","sit","pretérito"],"nota":"«Sit», «sat», «sat». O ato de sentar é «sit down»; estar sentado é «be sitting». O inglês separa o movimento do estado, que o português junta em «sentar».","v":"95fbbafa"},{"idioma":"en","id":"en-v028","tipo":"frase","en":"She stood in line for an hour.","pt":"Ela ficou uma hora na fila.","aceitas":["ela ficou uma hora na fila","ficou uma hora na fila","ela esperou uma hora na fila","ela passou uma hora na fila"],"aceitasEn":["she stood in line for an hour","she queued for an hour"],"distratores":["Ela fica uma hora na fila.","Ela ficará uma hora na fila.","Ela ficaria uma hora na fila.","Ela tinha ficado uma hora na fila."],"formasEn":{"She stands in line for an hour":"presente","She will stand in line for an hour":"futuro","She would stand in line for an hour":"condicional","She had stood in line for an hour":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","stand","pretérito"],"nota":"«Stand», «stood», «stood». Fazer fila é «stand in line» nos Estados Unidos e «queue» na Inglaterra. E «I can't stand it» não é ficar de pé: é não aguentar.","v":"017a7874"},{"idioma":"en","id":"en-v029","tipo":"frase","en":"He read the whole book.","pt":"Ele leu o livro inteiro.","aceitas":["ele leu o livro inteiro","leu o livro inteiro","ele leu o livro todo","ele leu o livro de cabo a rabo"],"aceitasEn":["he read the whole book"],"distratores":["Ele lê o livro inteiro.","Ele lerá o livro inteiro.","Ele leria o livro inteiro.","Ele tinha lido o livro inteiro."],"formasEn":{"He will read the whole book":"futuro","He would read the whole book":"condicional","He had read the whole book":"mais-que-perfeito","He will have read the whole book":"futuro perfeito"},"nivel":"A2","tags":["conjugação","irregular","read","pretérito"],"nota":"As três formas se escrevem igual — «read», «read», «read» —, mas o passado se pronuncia «red», como a cor. No papel, só o resto da frase diz o tempo.","v":"ee3191f6"},{"idioma":"en","id":"en-v030","tipo":"frase","en":"I heard a noise.","pt":"Eu ouvi um barulho.","aceitas":["eu ouvi um barulho","ouvi um barulho","eu escutei um barulho","eu ouvi um ruido"],"aceitasEn":["i heard a noise"],"distratores":["Eu ouço um barulho.","Eu ouvirei um barulho.","Eu ouviria um barulho.","Eu tinha ouvido um barulho."],"formasEn":{"I hear a noise":"presente","I will hear a noise":"futuro","I would hear a noise":"condicional","I had heard a noise":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","irregular","hear","pretérito"],"nota":"«Hear», «heard», «heard». Ouvir é o que acontece sem querer; escutar, de propósito, é «listen». O barulho a gente «hears», a música a gente «listens to».","v":"2674cb8b"},{"idioma":"en","id":"en-v031","tipo":"frase","en":"They met at the station.","pt":"Eles se encontraram na estação.","aceitas":["eles se encontraram na estacao","se encontraram na estacao","eles se viram na estacao","eles se conheceram na estacao"],"aceitasEn":["they met at the station"],"distratores":["Eles se encontram na estação.","Eles se encontrarão na estação.","Eles se encontrariam na estação.","Eles tinham se encontrado na estação."],"formasEn":{"They meet at the station":"presente","They will meet at the station":"futuro","They would meet at the station":"condicional","They had met at the station":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","irregular","meet","viagem"],"nota":"«Meet», «met», «met». O mesmo verbo serve para conhecer alguém pela primeira vez e para se encontrar com quem já se conhece — o que separa os dois é o contexto.","v":"c1445f96"},{"idioma":"en","id":"en-v032","tipo":"frase","en":"They won the game.","pt":"Eles ganharam o jogo.","aceitas":["eles ganharam o jogo","ganharam o jogo","eles venceram o jogo","eles ganharam a partida"],"aceitasEn":["they won the game","they won the match"],"distratores":["Eles ganham o jogo.","Eles ganharão o jogo.","Eles ganhariam o jogo.","Eles tinham ganhado o jogo."],"formasEn":{"They win the game":"presente","They will win the game":"futuro","They would win the game":"condicional","They had won the game":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","irregular","win","cultura"],"nota":"«Win», «won», «won». Ganha-se o jogo, o prêmio, a eleição — mas não se ganha o adversário: a ele se «beat». «We won the game, we beat them».","v":"19f56dbb"},{"idioma":"en","id":"en-v033","tipo":"frase","en":"She sent me a message.","pt":"Ela me mandou uma mensagem.","aceitas":["ela me mandou uma mensagem","me mandou uma mensagem","ela me enviou uma mensagem","ela mandou uma mensagem pra mim"],"aceitasEn":["she sent me a message","she sent a message to me"],"distratores":["Ela me manda uma mensagem.","Ela me mandará uma mensagem.","Ela me mandaria uma mensagem.","Ela tinha me mandado uma mensagem."],"formasEn":{"She sends me a message":"presente","She will send me a message":"futuro","She would send me a message":"condicional","She had sent me a message":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","irregular","send","tecnologia"],"nota":"«Send», «sent», «sent». Como «give», aceita as duas ordens: «send me a message» e «send a message to me». A primeira é a da conversa.","v":"5f99ced2"},{"idioma":"en","id":"en-v034","tipo":"frase","en":"He sold the car.","pt":"Ele vendeu o carro.","aceitas":["ele vendeu o carro","vendeu o carro","ele vendeu o carro dele","ele acabou vendendo o carro"],"aceitasEn":["he sold the car"],"distratores":["Ele vende o carro.","Ele venderá o carro.","Ele venderia o carro.","Ele tinha vendido o carro."],"formasEn":{"He sells the car":"presente","He will sell the car":"futuro","He would sell the car":"condicional","He had sold the car":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","irregular","sell","economia"],"nota":"«Sell», «sold», «sold» — o mesmo desenho de «tell», «told», «told». E «sold out» é o que esgotou: o show, o ingresso, a loja.","v":"ae259ded"},{"idioma":"en","id":"en-v035","tipo":"frase","en":"I spent all my money.","pt":"Eu gastei todo o meu dinheiro.","aceitas":["eu gastei todo o meu dinheiro","gastei todo o meu dinheiro","eu gastei todo meu dinheiro","eu torrei todo o meu dinheiro"],"aceitasEn":["i spent all my money"],"distratores":["Eu gasto todo o meu dinheiro.","Eu gastarei todo o meu dinheiro.","Eu gastaria todo o meu dinheiro.","Eu tinha gastado todo o meu dinheiro."],"formasEn":{"I spend all my money":"presente","I will spend all my money":"futuro","I would spend all my money":"condicional","I had spent all my money":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","spend","economia"],"nota":"«Spend», «spent», «spent». O mesmo verbo gasta dinheiro e passa tempo: «spend money», «spend the weekend» — onde o português usa dois verbos diferentes.","v":"e239e10c"},{"idioma":"en","id":"en-v036","tipo":"frase","en":"He kept the receipt.","pt":"Ele guardou o recibo.","aceitas":["ele guardou o recibo","guardou o recibo","ele ficou com o recibo","ele manteve o recibo"],"aceitasEn":["he kept the receipt"],"distratores":["Ele guarda o recibo.","Ele guardará o recibo.","Ele guardaria o recibo.","Ele tinha guardado o recibo."],"formasEn":{"He keeps the receipt":"presente","He will keep the receipt":"futuro","He would keep the receipt":"condicional","He had kept the receipt":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","keep","economia"],"nota":"«Keep», «kept», «kept». Com outro verbo atrás no gerúndio, vira insistência: «keep talking», continuar falando; «keep trying», não parar de tentar.","v":"af403398"},{"idioma":"en","id":"en-v037","tipo":"frase","en":"She held my hand.","pt":"Ela segurou minha mão.","aceitas":["ela segurou minha mao","segurou minha mao","ela pegou na minha mao","ela segurou a minha mao"],"aceitasEn":["she held my hand"],"distratores":["Ela segura minha mão.","Ela segurará minha mão.","Ela seguraria minha mão.","Ela tinha segurado minha mão."],"formasEn":{"She holds my hand":"presente","She will hold my hand":"futuro","She would hold my hand":"condicional","She had held my hand":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","hold","corpo"],"nota":"«Hold», «held», «held». Segura-se a mão, a porta, o copo e a respiração: «hold your breath». Ao telefone, «hold on» é esperar na linha.","v":"673ab832"},{"idioma":"en","id":"en-v038","tipo":"frase","en":"They chose the red one.","pt":"Eles escolheram o vermelho.","aceitas":["eles escolheram o vermelho","escolheram o vermelho","eles ficaram com o vermelho","eles optaram pelo vermelho"],"aceitasEn":["they chose the red one"],"distratores":["Eles escolhem o vermelho.","Eles escolherão o vermelho.","Eles escolheriam o vermelho.","Eles tinham escolhido o vermelho."],"formasEn":{"They choose the red one":"presente","They will choose the red one":"futuro","They would choose the red one":"condicional","They had chosen the red one":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","choose","cotidiano"],"nota":"«Choose», «chose», «chosen» — três grafias e três sons, e nenhuma delas é o nome: a escolha é «a choice», com «c».","v":"09d38922"},{"idioma":"en","id":"en-v039","tipo":"frase","en":"The city grew very fast.","pt":"A cidade cresceu muito rápido.","aceitas":["a cidade cresceu muito rapido","a cidade cresceu rapido demais","a cidade cresceu muito depressa"],"aceitasEn":["the city grew very fast","the city grew very quickly"],"distratores":["A cidade cresce muito rápido.","A cidade crescerá muito rápido.","A cidade cresceria muito rápido.","A cidade tinha crescido muito rápido."],"formasEn":{"The city grows very fast":"presente","The city will grow very fast":"futuro","The city would grow very fast":"condicional","The city had grown very fast":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","grow","cidade"],"nota":"«Grow», «grew», «grown». «Fast» é advérbio e adjetivo ao mesmo tempo, sem «-ly»: «a fast car», «it grew fast».","v":"e1bea323"},{"idioma":"en","id":"en-v040","tipo":"frase","en":"I forgot his name.","pt":"Esqueci o nome dele.","aceitas":["esqueci o nome dele","eu esqueci o nome dele","me esqueci do nome dele","esqueci como ele se chama"],"aceitasEn":["i forgot his name","i have forgotten his name"],"distratores":["Esqueço o nome dele.","Esquecerei o nome dele.","Esqueceria o nome dele.","Tinha esquecido o nome dele."],"formasEn":{"I forget his name":"presente","I will forget his name":"futuro","I would forget his name":"condicional","I had forgotten his name":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","irregular","forget","cotidiano"],"nota":"«Forget», «forgot», «forgotten». E o inglês não tem o «se me esqueceu» que joga a culpa no esquecimento: o sujeito é sempre quem esqueceu.","v":"0ae2f96a"},{"idioma":"en","id":"en-v041","tipo":"frase","en":"He fell off the ladder.","pt":"Ele caiu da escada.","aceitas":["ele caiu da escada","caiu da escada","ele despencou da escada","ele caiu de cima da escada"],"aceitasEn":["he fell off the ladder","he fell from the ladder"],"distratores":["Ele cai da escada.","Ele cairá da escada.","Ele cairia da escada.","Ele tinha caído da escada."],"formasEn":{"He falls off the ladder":"presente","He will fall off the ladder":"futuro","He would fall off the ladder":"condicional","He had fallen off the ladder":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","fall","saúde"],"nota":"«Fall», «fell», «fallen». Cair de cima de alguma coisa é «fall off»; cair dentro é «fall into». E «fall» é também o outono, nos Estados Unidos.","v":"dc219a06"},{"idioma":"en","id":"en-v042","tipo":"frase","en":"The class began at nine.","pt":"A aula começou às nove.","aceitas":["a aula comecou as nove","a aula teve inicio as nove","a aula comecou as 9"],"aceitasEn":["the class began at nine","the class started at nine"],"distratores":["A aula começa às nove.","A aula começará às nove.","A aula começaria às nove.","A aula tinha começado às nove."],"formasEn":{"The class begins at nine":"presente","The class will begin at nine":"futuro","The class would begin at nine":"condicional","The class had begun at nine":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","irregular","begin","escola"],"nota":"«Begin», «began», «begun» — o mesmo desenho de «drink», «drank», «drunk» e de «sing», «sang», «sung». «Start» é o sinônimo de todo dia, e é regular.","v":"56ceb4cd"},{"idioma":"en","id":"en-v043","tipo":"frase","en":"They built the bridge in two years.","pt":"Eles construíram a ponte em dois anos.","aceitas":["eles construiram a ponte em dois anos","construiram a ponte em dois anos","eles fizeram a ponte em dois anos","eles levantaram a ponte em dois anos"],"aceitasEn":["they built the bridge in two years"],"distratores":["Eles constroem a ponte em dois anos.","Eles construirão a ponte em dois anos.","Eles construiriam a ponte em dois anos.","Eles tinham construído a ponte em dois anos."],"formasEn":{"They build the bridge in two years":"presente","They will build the bridge in two years":"futuro","They would build the bridge in two years":"condicional","They had built the bridge in two years":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","build","cidade"],"nota":"«Build», «built», «built». O prédio é «a building», que é o mesmo gerúndio virado substantivo. E o tempo que uma obra leva vai com «in»: «in two years».","v":"a7dc3029"},{"idioma":"en","id":"en-v044","tipo":"frase","en":"She slept on the couch.","pt":"Ela dormiu no sofá.","aceitas":["ela dormiu no sofa","dormiu no sofa","ela passou a noite no sofa","ela foi dormir no sofa"],"aceitasEn":["she slept on the couch","she slept on the sofa"],"distratores":["Ela dorme no sofá.","Ela dormirá no sofá.","Ela dormiria no sofá.","Ela tinha dormido no sofá."],"formasEn":{"She sleeps on the couch":"presente","She will sleep on the couch":"futuro","She would sleep on the couch":"condicional","She had slept on the couch":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","irregular","sleep","casa"],"nota":"«Sleep», «slept», «slept». Dormir demais e perder a hora é «oversleep»; dormir até tarde de propósito é «sleep in». O sofá é «couch» nos Estados Unidos e «sofa» em toda parte.","v":"a4d3632d"},{"idioma":"en","id":"en-v045","tipo":"frase","en":"He cut his finger.","pt":"Ele cortou o dedo.","aceitas":["ele cortou o dedo","cortou o dedo","ele cortou o dedo dele","ele se cortou no dedo"],"aceitasEn":["he cut his finger"],"distratores":["Ele corta o dedo.","Ele cortará o dedo.","Ele cortaria o dedo.","Ele tinha cortado o dedo."],"formasEn":{"He will cut his finger":"futuro","He would cut his finger":"condicional","He had cut his finger":"mais-que-perfeito","He will have cut his finger":"futuro perfeito"},"nivel":"A2","tags":["conjugação","irregular","cut","corpo"],"nota":"«Cut», «cut», «cut» — três formas iguais, como «put» e «quit». E o dedo leva possessivo: «his finger», nunca «the finger».","v":"44334370"},{"idioma":"en","id":"en-v046","tipo":"frase","en":"He became a doctor.","pt":"Ele se tornou médico.","aceitas":["ele se tornou medico","ele virou medico","se tornou medico","ele ficou medico","ele se formou medico"],"aceitasEn":["he became a doctor"],"distratores":["Ele se torna médico.","Ele se tornará médico.","Ele se tornaria médico.","Ele tinha se tornado médico."],"formasEn":{"He becomes a doctor":"presente","He will become a doctor":"futuro","He would become a doctor":"condicional","He had become a doctor":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","become","profissões"],"nota":"«Become», «became», «become» — a terceira forma volta à primeira. Serve para a mudança que fica: profissão, fama, caráter. Para a mudança passageira, «get»: «he got angry».","v":"6d3c49ea"},{"idioma":"en","id":"en-p053","tipo":"palavra","en":"to realize","pt":"perceber","aceitas":["perceber","dar-se conta","se dar conta","notar"],"aceitasEn":["to realize","realize"],"distratores":["resolver","imaginar","adivinhar","esclarecer"],"nivel":"B2","tags":["falso-amigo","verbo"],"nota":"«Realize» é a ficha caindo, não a tarefa cumprida. Quem realiza um sonho ou um projeto em inglês faz «carry out», «fulfill» ou «make it happen».\n🇺🇸 realize → 🇧🇷 perceber, dar-se conta\n🇺🇸 carry out → 🇧🇷 realizar","regionaisEn":{"to realise":"na Inglaterra","realise":"na Inglaterra"},"v":"6f023e93"},{"idioma":"en","id":"en-u053","tipo":"frase","requer":"en-p053","en":"I suddenly realized my mistake.","pt":"De repente percebi meu erro.","aceitas":["de repente percebi meu erro","de repente eu percebi meu erro","de repente me dei conta do meu erro","de repente notei meu erro"],"aceitasEn":["i suddenly realized my mistake"],"distratores":["De repente esqueci meu erro.","De repente admiti meu erro.","De repente contei meu erro.","De repente corrigi meu erro."],"nivel":"B2","tags":["falso-amigo","verbo"],"nota":"«Suddenly» pode ir no começo da frase ou antes do verbo: «Suddenly I realized» e «I suddenly realized» valem as duas. Depois do verbo, não.","regionaisEn":{"i suddenly realised my mistake":"na Inglaterra"},"v":"6edad119"},{"idioma":"en","id":"en-p054","tipo":"palavra","en":"comprehensive","pt":"abrangente","aceitas":["abrangente","completo","exaustivo","amplo"],"aceitasEn":["comprehensive"],"distratores":["compreensivo","acessível","obrigatório","provisório"],"nivel":"C1","tags":["falso-amigo","adjetivo"],"nota":"«Comprehensive» é o que cobre tudo: um seguro «comprehensive» não deixa nada de fora. Quem é compreensivo com os outros é «understanding».\n🇺🇸 comprehensive → 🇧🇷 abrangente, completo\n🇺🇸 understanding → 🇧🇷 compreensivo","v":"3bc12fe6"},{"idioma":"en","id":"en-u054","tipo":"frase","requer":"en-p054","en":"She wrote a comprehensive report.","pt":"Ela escreveu um relatório abrangente.","aceitas":["ela escreveu um relatorio abrangente","escreveu um relatorio abrangente","ela escreveu um relatorio completo","ela fez um relatorio abrangente"],"aceitasEn":["she wrote a comprehensive report"],"distratores":["Ela escreveu um relatório compreensivo.","Ela escreveu um relatório provisório.","Ela escreveu um relatório obrigatório.","Ela escreveu um relatório acessível."],"nivel":"C1","tags":["falso-amigo","trabalho"],"nota":"«Comprehensive» anda com «report», «study», «guide», «list» e «insurance». É a palavra do que não deixou nada de fora.","v":"e1a4ffbe"},{"idioma":"en","id":"en-p055","tipo":"palavra","en":"to claim","pt":"alegar","aceitas":["alegar","afirmar","sustentar","reivindicar"],"aceitasEn":["to claim","claim"],"distratores":["clamar","elogiar","duvidar","prometer"],"nivel":"B2","tags":["falso-amigo","verbo"],"nota":"«Claim» é dizer que é assim e assumir o que se disse — o repórter escreve «he claims» quando não se compromete com a versão. Clamar por socorro é «cry out».\n🇺🇸 claim → 🇧🇷 alegar, afirmar\n🇺🇸 cry out → 🇧🇷 clamar","v":"455d34b0"},{"idioma":"en","id":"en-u055","tipo":"frase","requer":"en-p055","en":"He claims he was at home.","pt":"Ele alega que estava em casa.","aceitas":["ele alega que estava em casa","alega que estava em casa","ele afirma que estava em casa","ele sustenta que estava em casa"],"aceitasEn":["he claims he was at home","he claims that he was at home"],"distratores":["Ele jura que estava em casa.","Ele esqueceu que estava em casa.","Ele avisou que estava em casa.","Ele lembra que estava em casa."],"nivel":"B2","tags":["falso-amigo","jurídico"],"nota":"Depois de «claim» o «that» costuma cair: «He claims he was at home». O verbo seguinte vai para o passado, mesmo quando o que se alega ainda vale.","v":"b2b6893a"},{"idioma":"en","id":"en-p056","tipo":"palavra","en":"to assist","pt":"ajudar","aceitas":["ajudar","auxiliar","socorrer","dar assistencia","prestar auxilio"],"aceitasEn":["to assist","assist"],"distratores":["assistir","consultar","atrapalhar","vigiar"],"nivel":"B2","tags":["falso-amigo","verbo"],"nota":"«Assist» é ajudar, e só. Assistir a um filme é «watch»; assistir a uma aula é «attend». O inglês guarda «assist» para o registro de trabalho: «assist the surgeon», «assist a customer».\n🇺🇸 assist → 🇧🇷 ajudar\n🇺🇸 watch → 🇧🇷 assistir","v":"b3330ce0"},{"idioma":"en","id":"en-u056","tipo":"frase","requer":"en-p056","en":"A nurse assisted the surgeon.","pt":"Uma enfermeira ajudou o cirurgião.","aceitas":["uma enfermeira ajudou o cirurgiao","uma enfermeira auxiliou o cirurgiao","a enfermeira ajudou o cirurgiao"],"aceitasEn":["a nurse assisted the surgeon"],"distratores":["Uma enfermeira chamou o cirurgião.","Uma enfermeira avisou o cirurgião.","Uma enfermeira substituiu o cirurgião.","Uma enfermeira procurou o cirurgião."],"nivel":"B2","tags":["falso-amigo","saúde"],"nota":"«Assist» não leva preposição: «assist the surgeon», «assist a customer». Já o «help» de todo dia pede o verbo nu depois do objeto: «help me carry this».","v":"9298a858"},{"idioma":"en","id":"en-p057","tipo":"palavra","en":"ultimately","pt":"no fim das contas","aceitas":["no fim das contas","no final das contas","em ultima analise","afinal","no fim"],"aceitasEn":["ultimately"],"distratores":["ultimamente","de vez em quando","por outro lado","pelo visto"],"nivel":"C1","tags":["falso-amigo","formal"],"nota":"«Ultimately» é o que fica quando se tira o resto: o que de fato decide, o que sobra no fim. Ultimamente, no sentido de agora há pouco, é «lately» ou «recently».\n🇺🇸 ultimately → 🇧🇷 no fim das contas\n🇺🇸 lately → 🇧🇷 ultimamente","v":"3f5511a6"},{"idioma":"en","id":"en-u057","tipo":"frase","requer":"en-p057","en":"Ultimately, it's your decision.","pt":"No fim das contas, a decisão é sua.","aceitas":["no fim das contas a decisao e sua","no final das contas a decisao e sua","afinal a decisao e sua","em ultima analise a decisao e sua","no fim a decisao e sua"],"aceitasEn":["ultimately its your decision","ultimately it is your decision"],"distratores":["Ultimamente, a decisão é sua.","De vez em quando, a decisão é sua.","Por outro lado, a decisão é sua.","Pelo visto, a decisão é sua."],"nivel":"C1","tags":["falso-amigo","formal"],"nota":"No começo da frase «ultimately» leva vírgula e vale pela frase inteira. No meio, cola no verbo: «It will ultimately depend on the price».","v":"7bc397ca"},{"idioma":"en","id":"en-p058","tipo":"palavra","en":"the casualty","pt":"a vítima","aceitas":["a vitima","o ferido","a baixa"],"aceitasEn":["the casualty","casualty"],"distratores":["a casualidade","a coincidência","a testemunha","a suspeita"],"nivel":"C1","tags":["falso-amigo","substantivo"],"nota":"«Casualty» é quem se machucou ou morreu num acidente, num desastre ou na guerra. Casualidade, no sentido de acaso, é «coincidence» ou «chance».\n🇺🇸 casualty → 🇧🇷 a vítima\n🇺🇸 coincidence → 🇧🇷 a casualidade","v":"a492b27c"},{"idioma":"en","id":"en-u058","tipo":"frase","requer":"en-p058","en":"There were no casualties.","pt":"Não houve vítimas.","aceitas":["nao houve vitimas","nao teve vitimas","nao houve feridos","nao houve nenhuma vitima"],"aceitasEn":["there were no casualties"],"distratores":["Não houve casualidades.","Não houve coincidências.","Não houve testemunhas.","Não houve suspeitas."],"nivel":"C1","tags":["falso-amigo","mídia"],"nota":"«Casualty» é palavra de notícia e de boletim: «no casualties», «civilian casualties». No hospital britânico, «the casualty department» é o pronto-socorro.","v":"d783e1db"},{"idioma":"en","id":"en-p059","tipo":"palavra","en":"the argument","pt":"a discussão","aceitas":["a discussao","a briga","o bate boca","o barraco","o argumento"],"aceitasEn":["the argument","argument"],"distratores":["a conversa","a desculpa","a proposta","a explicação"],"nivel":"B2","tags":["falso-amigo","social"],"nota":"«We had an argument» é briga, não debate. O argumento de uma tese também é «argument», mas no dia a dia a palavra cheira a voz alterada. Tratar um assunto com calma é «discuss».\n🇺🇸 argument → 🇧🇷 a discussão, a briga\n🇺🇸 discussion → 🇧🇷 a conversa, o debate","v":"e7c5ce40"},{"idioma":"en","id":"en-u059","tipo":"frase","requer":"en-p059","en":"We had an argument last night.","pt":"Tivemos uma discussão ontem à noite.","aceitas":["tivemos uma discussao ontem a noite","nos tivemos uma discussao ontem a noite","brigamos ontem a noite","tivemos uma briga ontem a noite"],"aceitasEn":["we had an argument last night"],"distratores":["Tivemos uma conversa ontem à noite.","Tivemos uma reunião ontem à noite.","Tivemos uma surpresa ontem à noite.","Tivemos uma ideia ontem à noite."],"nivel":"B2","tags":["falso-amigo","social"],"nota":"Briga em inglês se «tem»: «have an argument», «have a fight», e «have a row» no britânico. Com quem se brigou entra depois: «I had an argument with him».","v":"652fa4da"},{"idioma":"en","id":"en-p060","tipo":"palavra","en":"to advertise","pt":"anunciar","aceitas":["anunciar","divulgar","fazer propaganda","fazer publicidade","promover"],"aceitasEn":["to advertise","advertise"],"distratores":["advertir","aconselhar","adivinhar","reclamar"],"nivel":"B2","tags":["falso-amigo","verbo"],"nota":"«Advertise» é pôr anúncio, não avisar. Advertir alguém de um perigo é «warn». O anúncio é «an ad» (ou «an advert», no britânico), e a propaganda toda é «advertising».\n🇺🇸 advertise → 🇧🇷 anunciar\n🇺🇸 warn → 🇧🇷 advertir, avisar","v":"9272dc8a"},{"idioma":"en","id":"en-u060","tipo":"frase","requer":"en-p060","en":"They advertised the job online.","pt":"Eles anunciaram a vaga na internet.","aceitas":["eles anunciaram a vaga na internet","anunciaram a vaga na internet","eles divulgaram a vaga na internet","eles anunciaram a vaga online"],"aceitasEn":["they advertised the job online"],"distratores":["Eles procuraram a vaga na internet.","Eles aceitaram a vaga na internet.","Eles perderam a vaga na internet.","Eles encontraram a vaga na internet."],"nivel":"B2","tags":["falso-amigo","trabalho"],"nota":"«Advertise» anda com o que se oferece: «advertise a job», «advertise a product». Quem procura, e não oferece, põe o «for»: «advertise for a roommate».","v":"5d656ef4"},{"idioma":"en","id":"en-p061","tipo":"palavra","en":"the sibling","pt":"o irmão ou a irmã","aceitas":["o irmao ou a irma","irmao ou irma","o irmao","a irma"],"aceitasEn":["the sibling","sibling"],"distratores":["o primo ou a prima","o tio ou a tia","o sobrinho ou a sobrinha","o avô ou a avó"],"nivel":"B2","tags":["substantivo","família"],"nota":"O inglês tem uma palavra para irmão-ou-irmã sem dizer o sexo, e o português não tem. «How many siblings do you have?» é «Quantos irmãos você tem?» — no plural o português já mistura os dois.","v":"67f707cb"},{"idioma":"en","id":"en-u061","tipo":"frase","requer":"en-p061","en":"I have two siblings.","pt":"Eu tenho dois irmãos.","aceitas":["eu tenho dois irmaos","tenho dois irmaos","tenho dois irmaos ao todo"],"aceitasEn":["i have two siblings","ive got two siblings","i have got two siblings"],"distratores":["Eu tenho dois primos.","Eu tenho dois tios.","Eu tenho dois sobrinhos.","Eu tenho dois filhos."],"nivel":"B2","tags":["substantivo","família"],"nota":"«Sibling» é palavra de formulário e de conversa séria; entre amigos diz-se «brothers and sisters». As duas frases dizem a mesma coisa.","v":"a6e2f0a3"},{"idioma":"en","id":"en-p062","tipo":"palavra","en":"the commute","pt":"o trajeto de casa ao trabalho","aceitas":["o trajeto de casa ao trabalho","o trajeto ate o trabalho","o caminho para o trabalho","o deslocamento diario"],"aceitasEn":["the commute","commute"],"distratores":["o horário de entrada no trabalho","o intervalo do almoço no trabalho","o primeiro dia de trabalho","o uniforme obrigatório do trabalho"],"nivel":"C1","tags":["substantivo","trabalho"],"nota":"O inglês tem um substantivo para o que o português precisa de uma frase inteira: a ida e a volta de casa ao trabalho, todo dia. O verbo é o mesmo: «I commute by train».","v":"c1a28afa"},{"idioma":"en","id":"en-u062","tipo":"frase","requer":"en-p062","en":"I have a long commute.","pt":"Meu trajeto até o trabalho é longo.","aceitas":["meu trajeto ate o trabalho e longo","meu trajeto para o trabalho e longo","meu caminho ate o trabalho e longo","tenho um trajeto longo ate o trabalho"],"aceitasEn":["i have a long commute"],"distratores":["Meu intervalo no trabalho é longo.","Meu contrato de trabalho é longo.","Meu turno no trabalho é longo.","Meu treinamento no trabalho é longo."],"nivel":"C1","tags":["substantivo","trabalho"],"nota":"«A long commute» é a queixa mais comum de quem mora longe. Quem faz o trajeto é «a commuter», e a hora em que todos o fazem ao mesmo tempo é «rush hour».","v":"ab8a1afe"},{"idioma":"en","id":"en-p063","tipo":"palavra","en":"the deadline","pt":"o prazo final","aceitas":["o prazo final","o prazo","a data limite","o prazo de entrega"],"aceitasEn":["the deadline","deadline"],"distratores":["o horário marcado","o atraso na entrega","o adiamento do contrato","o encontro seguinte"],"nivel":"B2","tags":["substantivo","trabalho"],"nota":"«Deadline» é a linha que não se atravessa: o prazo depois do qual não adianta mais entregar. Cumprir é «meet the deadline»; perder é «miss the deadline».","v":"e8e5df0a"},{"idioma":"en","id":"en-u063","tipo":"frase","requer":"en-p063","en":"We missed the deadline.","pt":"Nós perdemos o prazo.","aceitas":["nos perdemos o prazo","perdemos o prazo","nao cumprimos o prazo","perdemos o prazo final","estouramos o prazo"],"aceitasEn":["we missed the deadline"],"distratores":["Nós perdemos o horário marcado.","Nós perdemos o contrato.","Nós perdemos o encontro.","Nós perdemos o desconto."],"nivel":"B2","tags":["substantivo","trabalho"],"nota":"O prazo, em inglês, se encontra ou se perde: «meet the deadline», «miss the deadline». E quando ele aperta, «the deadline is looming».","v":"d59e2108"},{"idioma":"en","id":"en-p064","tipo":"palavra","en":"overwhelmed","pt":"sobrecarregado","aceitas":["sobrecarregado","sobrecarregada","soterrado","atolado"],"aceitasEn":["overwhelmed"],"distratores":["desanimado","distraído","desempregado","apressado"],"nivel":"C1","tags":["adjetivo","trabalho"],"nota":"«Overwhelmed» é estar debaixo de mais do que se aguenta — de trabalho, de informação, de gente. Serve também para a emoção boa: «overwhelmed with gratitude».","v":"6019007f"},{"idioma":"en","id":"en-u064","tipo":"frase","requer":"en-p064","en":"I feel completely overwhelmed.","pt":"Estou me sentindo completamente sobrecarregado.","aceitas":["estou me sentindo completamente sobrecarregado","estou completamente sobrecarregado","me sinto completamente sobrecarregado","estou me sentindo completamente sobrecarregada","estou completamente sobrecarregada","me sinto completamente sobrecarregada","estou me sentindo completamente atolado"],"aceitasEn":["i feel completely overwhelmed"],"distratores":["Estou me sentindo completamente perdido.","Estou me sentindo completamente sozinho.","Estou me sentindo completamente enganado.","Estou me sentindo completamente recuperado."],"nivel":"C1","tags":["adjetivo","trabalho"],"nota":"«Overwhelmed» costuma vir graduado: «completely overwhelmed», «totally overwhelmed», «a bit overwhelmed». O verbo é «overwhelm», e o que sobrecarrega é «overwhelming».","v":"cdf6daec"},{"idioma":"en","id":"en-p065","tipo":"palavra","en":"awkward","pt":"constrangedor","aceitas":["constrangedor","sem graca","esquisito","desconfortavel","estranho"],"aceitasEn":["awkward"],"distratores":["apressado","barulhento","demorado","previsível"],"nivel":"B2","tags":["adjetivo","social"],"nota":"«Awkward» é o que não se encaixa: o silêncio que cai na mesa, a pergunta que não devia ter sido feita, a pessoa que não sabe onde pôr as mãos.","v":"d3b8f3d2"},{"idioma":"en","id":"en-u065","tipo":"frase","requer":"en-p065","en":"There was an awkward silence.","pt":"Houve um silêncio constrangedor.","aceitas":["houve um silencio constrangedor","fez-se um silencio constrangedor","rolou um silencio constrangedor","houve um silencio sem graca","deu um silencio constrangedor"],"aceitasEn":["there was an awkward silence"],"distratores":["Houve um silêncio demorado.","Houve um silêncio respeitoso.","Houve um silêncio absoluto.","Houve um silêncio combinado."],"nivel":"B2","tags":["adjetivo","social"],"nota":"«Awkward silence» anda junto, e nenhuma outra palavra ocupa esse lugar. A situação inteira vira «that was awkward», que é o comentário de depois.","v":"5743c55a"},{"idioma":"en","id":"en-p066","tipo":"palavra","en":"the breakthrough","pt":"o avanço decisivo","aceitas":["o avanco decisivo","a grande descoberta","o grande salto","a virada","o avanco"],"aceitasEn":["the breakthrough","breakthrough"],"distratores":["o fracasso retumbante","o começo modesto","o prazo apertado","o resumo final"],"nivel":"C1","tags":["substantivo","tecnologia"],"nota":"«Breakthrough» é o muro que cede: a descoberta que destrava o que estava parado. Anda com «medical», «scientific» e «major», e não serve para qualquer progresso.","v":"01935b7b"},{"idioma":"en","id":"en-u066","tipo":"frase","requer":"en-p066","en":"It was a major breakthrough.","pt":"Foi um avanço decisivo.","aceitas":["foi um avanco decisivo","foi um grande avanco","foi uma grande descoberta","foi uma virada"],"aceitasEn":["it was a major breakthrough"],"distratores":["Foi um fracasso retumbante.","Foi um começo modesto.","Foi um resumo final.","Foi um encontro casual."],"nivel":"C1","tags":["substantivo","tecnologia"],"nota":"«Major» antes de substantivo é o «grande» do que pesa: «a major breakthrough», «a major problem», «a major city». Com pessoa não se usa.","v":"05dc2bf3"},{"idioma":"en","id":"en-p067","tipo":"palavra","en":"homesick","pt":"com saudade de casa","aceitas":["com saudade de casa","com saudades de casa","morrendo de saudade de casa","com saudade da familia"],"aceitasEn":["homesick"],"distratores":["com medo de voar","com pressa de chegar","com raiva do irmão","com vergonha de pedir"],"nivel":"B2","tags":["adjetivo","viagem"],"nota":"O inglês junta casa e doença numa palavra só: quem está «homesick» sente falta de casa a ponto de doer. O mesmo molde dá «seasick», «carsick» e «lovesick».","v":"bb49b28c"},{"idioma":"en","id":"en-u067","tipo":"frase","requer":"en-p067","en":"I felt homesick that night.","pt":"Naquela noite fiquei com saudade de casa.","aceitas":["naquela noite fiquei com saudade de casa","naquela noite eu fiquei com saudade de casa","naquela noite bateu saudade de casa","naquela noite senti saudade de casa"],"aceitasEn":["i felt homesick that night"],"distratores":["Naquela noite fiquei com medo de voar.","Naquela noite fiquei com pressa de chegar.","Naquela noite fiquei com raiva do irmão.","Naquela noite fiquei com vergonha de pedir."],"nivel":"B2","tags":["adjetivo","viagem"],"nota":"«Homesick» se fica: «get homesick», «feel homesick». O substantivo é «homesickness», que é a saudade de casa com nome próprio.","v":"fa8f3980"},{"idioma":"en","id":"en-p068","tipo":"palavra","en":"to cope with","pt":"lidar com","aceitas":["lidar com","dar conta de","aguentar","enfrentar","se virar com"],"aceitasEn":["to cope with","cope with","to cope","cope"],"distratores":["contar com","desistir de","reclamar de","concordar com"],"nivel":"B2","tags":["verbo","saúde"],"nota":"«Cope» é aguentar o que já está acontecendo: a doença, o luto, o excesso de trabalho. Quase nunca vem sozinho — é «cope with» —, e no negativo vira confissão: «I can't cope».","v":"8d2ff08b"},{"idioma":"en","id":"en-u068","tipo":"frase","requer":"en-p068","en":"He can't cope with the pressure.","pt":"Ele não consegue lidar com a pressão.","aceitas":["ele nao consegue lidar com a pressao","nao consegue lidar com a pressao","ele nao aguenta a pressao","ele nao da conta da pressao"],"aceitasEn":["he cant cope with the pressure","he cannot cope with the pressure"],"distratores":["Ele não consegue explicar a pressão.","Ele não consegue medir a pressão.","Ele não consegue entender a pressão.","Ele não consegue esconder a pressão."],"nivel":"B2","tags":["verbo","saúde"],"nota":"«Cope» quase sempre vem com «with»: «cope with stress», «cope with the pressure». Sem objeto, é a confissão seca de quem não aguenta mais: «I can't cope».","v":"12c7c6b1"},{"idioma":"en","id":"en-p069","tipo":"palavra","en":"to bother","pt":"incomodar","aceitas":["incomodar","atrapalhar","chatear","amolar","perturbar"],"aceitasEn":["to bother","bother"],"distratores":["cumprimentar","convencer","emprestar","acompanhar"],"nivel":"B2","tags":["verbo","social"],"nota":"«Bother» é a chateação pequena: o barulho, a pergunta repetida, a mosca. Em «don't bother» muda de lado e vira «não precisa», «nem se dê ao trabalho».","v":"c96a2efb"},{"idioma":"en","id":"en-u069","tipo":"frase","requer":"en-p069","en":"Don't bother, I'll do it myself.","pt":"Não se incomode, eu faço.","aceitas":["nao se incomode eu faco","nao precisa eu faco","deixa que eu faco","nao se incomode que eu faco","nem se de ao trabalho eu faco"],"aceitasEn":["dont bother ill do it myself","do not bother i will do it myself"],"distratores":["Não se atrase, eu faço.","Não se levante, eu faço.","Não se apresse, eu faço.","Não se assuste, eu faço."],"nivel":"B2","tags":["verbo","social"],"nota":"«Don't bother» é a recusa educada de ajuda: quem diz não quer que o outro se mexa. Com verbo depois, pede o «-ing»: «don't bother calling».","v":"ed93a245"},{"idioma":"en","id":"en-p070","tipo":"palavra","en":"to undermine","pt":"minar","aceitas":["minar","solapar","enfraquecer","corroer","abalar"],"aceitasEn":["to undermine","undermine"],"distratores":["sublinhar","subestimar","exagerar","proteger"],"nivel":"C1","tags":["verbo","política"],"nota":"«Undermine» é cavar por baixo: tira o apoio sem atacar de frente. Anda com «authority», «confidence», «trust» e «efforts». Sublinhar é «underline».","v":"1dc37c67"},{"idioma":"en","id":"en-u070","tipo":"frase","requer":"en-p070","en":"That would undermine his authority.","pt":"Isso minaria a autoridade dele.","aceitas":["isso minaria a autoridade dele","isso solaparia a autoridade dele","isso enfraqueceria a autoridade dele","isso abalaria a autoridade dele"],"aceitasEn":["that would undermine his authority"],"distratores":["Isso sublinharia a autoridade dele.","Isso confirmaria a autoridade dele.","Isso exageraria a autoridade dele.","Isso protegeria a autoridade dele."],"nivel":"C1","tags":["verbo","política"],"nota":"«Undermine» pede sempre alguma coisa que se sustenta em pé: autoridade, confiança, esforço, posição. Não se mina uma pessoa — mina-se o que a segura.","v":"8df63896"},{"idioma":"en","id":"en-p071","tipo":"palavra","en":"to overlook","pt":"deixar passar","aceitas":["deixar passar","nao notar","passar batido","ignorar","desconsiderar"],"aceitasEn":["to overlook","overlook"],"distratores":["supervisionar de perto","conferir de novo","insistir no assunto","exagerar no detalhe"],"nivel":"C1","tags":["verbo","trabalho"],"nota":"«Overlook» é o erro que escapa aos olhos, ou a falta que se resolve não ver. Supervisionar é «oversee» — muda uma sílaba e muda tudo.","v":"5a7aa95a"},{"idioma":"en","id":"en-u071","tipo":"frase","requer":"en-p071","en":"We overlooked one detail.","pt":"Deixamos passar um detalhe.","aceitas":["deixamos passar um detalhe","nos deixamos passar um detalhe","nao notamos um detalhe","ignoramos um detalhe"],"aceitasEn":["we overlooked one detail"],"distratores":["Supervisionamos de perto um detalhe.","Conferimos de novo um detalhe.","Insistimos muito num detalhe.","Exageramos bastante num detalhe."],"nivel":"C1","tags":["verbo","trabalho"],"nota":"«Overlook» também é o que a janela faz: «the room overlooks the sea». O mesmo verbo serve para não enxergar um erro e para ter vista para o mar.","v":"3d5d4dbd"},{"idioma":"en","id":"en-p072","tipo":"palavra","en":"thorough","pt":"minucioso","aceitas":["minucioso","meticuloso","detalhado","caprichado","cuidadoso"],"aceitasEn":["thorough"],"distratores":["teimoso","demorado","desconfiado","orgulhoso"],"nivel":"C1","tags":["adjetivo","trabalho"],"nota":"«Thorough» é quem não deixa canto por olhar: «a thorough check», «a thorough cleaning». Não confundir com «through», que é através e se escreve quase igual.","v":"c04bc309"},{"idioma":"en","id":"en-u072","tipo":"frase","requer":"en-p072","en":"He did a thorough job.","pt":"Ele fez um trabalho minucioso.","aceitas":["ele fez um trabalho minucioso","fez um trabalho minucioso","ele fez um trabalho caprichado","ele fez um trabalho meticuloso"],"aceitasEn":["he did a thorough job"],"distratores":["Ele fez um trabalho demorado.","Ele fez um trabalho arriscado.","Ele fez um trabalho voluntário.","Ele fez um trabalho provisório."],"nivel":"C1","tags":["adjetivo","trabalho"],"nota":"«Do a thorough job» é o elogio de quem conferiu tudo. O advérbio «thoroughly» guarda o exagero do inglês: «I thoroughly enjoyed it».","v":"47e86ce7"},{"idioma":"en","id":"en-p073","tipo":"palavra","en":"willing","pt":"disposto","aceitas":["disposto","disposta","de boa vontade","com disposicao"],"aceitasEn":["willing"],"distratores":["obrigado","capaz","grato","curioso"],"nivel":"B2","tags":["adjetivo","trabalho"],"nota":"«Willing» é querer fazer, e «able» é poder fazer: o inglês separa onde o português junta tudo em «poder». «Are you willing to help?» pergunta pela vontade, não pela agenda.","v":"798776e7"},{"idioma":"en","id":"en-u073","tipo":"frase","requer":"en-p073","en":"She's willing to help.","pt":"Ela está disposta a ajudar.","aceitas":["ela esta disposta a ajudar","esta disposta a ajudar","ela topa ajudar","ela esta a fim de ajudar"],"aceitasEn":["shes willing to help","she is willing to help"],"distratores":["Ela está obrigada a ajudar.","Ela está acostumada a ajudar.","Ela está grata por ajudar.","Ela está curiosa para ajudar."],"nivel":"B2","tags":["adjetivo","trabalho"],"nota":"«Willing» pede «to» e o verbo: «willing to help», «willing to pay». Quem não quer é «unwilling», e quem vai a contragosto é «reluctant».","v":"9c152ce6"},{"idioma":"en","id":"en-p074","tipo":"palavra","en":"regardless","pt":"mesmo assim","aceitas":["mesmo assim","de qualquer jeito","de qualquer forma","assim mesmo","ainda assim"],"aceitasEn":["regardless"],"distratores":["pelo contrário","por enquanto","de vez em quando","com certeza"],"nivel":"C1","tags":["formal","gramática"],"nota":"«Regardless» é seguir sem olhar para o que atrapalha. Sozinho, vai no fim da frase: «He went regardless». Com o obstáculo dito, pede «of»: «regardless of the cost».","v":"844ee576"},{"idioma":"en","id":"en-u074","tipo":"frase","requer":"en-p074","en":"He did it regardless.","pt":"Ele fez mesmo assim.","aceitas":["ele fez mesmo assim","fez mesmo assim","ele fez de qualquer jeito","ele fez assim mesmo","ele fez ainda assim"],"aceitasEn":["he did it regardless"],"distratores":["Ele fez de propósito.","Ele fez sem querer.","Ele fez por educação.","Ele fez de novo."],"nivel":"C1","tags":["formal","gramática"],"nota":"No fim da frase «regardless» fica sozinho e quer dizer «mesmo assim». Com o obstáculo dito, entra o «of»: «regardless of the cost», «regardless of what they say».","v":"480f74d2"},{"idioma":"en","id":"en-f081","tipo":"frase","en":"I wish I had known.","pt":"Eu queria ter sabido.","aceitas":["eu queria ter sabido","queria ter sabido","eu gostaria de ter sabido","quem me dera ter sabido"],"aceitasEn":["i wish i had known"],"distratores":["Eu queria saber.","Eu quero saber.","Eu queria ter contado.","Eu sabia disso."],"nivel":"C1","tags":["gramática","subjuntivo"],"nota":"«I wish» com o passado é o arrependimento do presente: «I wish I knew» é eu queria saber agora. «I wish» com «had» e particípio é o arrependimento do passado, do que já não dá para mudar.","v":"9350cb58"},{"idioma":"en","id":"en-f082","tipo":"frase","en":"If I had known, I would have come.","pt":"Se eu soubesse, eu teria vindo.","aceitas":["se eu soubesse eu teria vindo","se eu soubesse teria vindo","se eu tivesse sabido eu teria vindo","se eu soubesse eu tinha vindo"],"aceitasEn":["if i had known i would have come"],"distratores":["Se eu soubesse, eu viria.","Se eu souber, eu venho.","Se eu soubesse, eu teria escrito.","Quando eu soube, eu vim."],"nivel":"B2","tags":["gramática","condicional"],"nota":"A terceira condicional fala do que não aconteceu: «if» com «had» e particípio na primeira metade, «would have» com particípio na segunda. As duas metades no passado, e nenhuma delas com «would» sozinho.","v":"ff5289b3"},{"idioma":"en","id":"en-f083","tipo":"frase","en":"He must have forgotten.","pt":"Ele deve ter esquecido.","aceitas":["ele deve ter esquecido","deve ter esquecido","ele deve ter se esquecido","ele provavelmente esqueceu"],"aceitasEn":["he must have forgotten"],"distratores":["Ele deve ter chegado.","Ele deve ter entendido.","Ele tem que esquecer.","Ele conseguiu esquecer."],"nivel":"B2","tags":["gramática","verbo"],"nota":"«Must» com «have» e particípio é a única conclusão possível sobre o que já passou: não é obrigação, é certeza. O contrário é «can't have»: «he can't have forgotten».","v":"c1f5a23f"},{"idioma":"en","id":"en-f084","tipo":"frase","en":"You needn't have bothered.","pt":"Você não precisava ter se incomodado.","aceitas":["voce nao precisava ter se incomodado","nao precisava ter se incomodado","voce nao precisava se incomodar","nao era preciso ter se incomodado"],"aceitasEn":["you neednt have bothered","you need not have bothered"],"distratores":["Você não podia ter se incomodado.","Você não devia ter se incomodado.","Você não quis se incomodar.","Você não pensou em se incomodar."],"nivel":"C1","tags":["gramática","social"],"nota":"«Needn't have» com particípio diz que a pessoa fez alguma coisa que não era preciso — é o agradecimento com um empurrão. «Didn't need to» diz que não era preciso e por isso não fez.","v":"5a187f40"},{"idioma":"en","id":"en-f085","tipo":"frase","en":"Had I known, I would have called.","pt":"Tivesse eu sabido, teria ligado.","aceitas":["tivesse eu sabido teria ligado","se eu soubesse teria ligado","se eu tivesse sabido teria ligado","tivesse eu sabido eu teria ligado"],"aceitasEn":["had i known i would have called","if i had known i would have called"],"distratores":["Tivesse eu sabido, teria escrito.","Tivesse eu ligado, teria sabido.","Tivesse eu perguntado, teria entendido.","Tivesse eu esperado, teria chegado."],"nivel":"C2","tags":["gramática","formal","condicional"],"nota":"No registro formal o inglês tira o «if» e joga o auxiliar para a frente: «Had I known», «Were I you», «Should you need help». O português faz o mesmo pondo o subjuntivo na frente: «Tivesse eu sabido».","v":"53165164"},{"idioma":"en","id":"en-f086","tipo":"frase","en":"Not only did he lie, he also stole.","pt":"Ele não só mentiu, como também roubou.","aceitas":["ele nao so mentiu como tambem roubou","nao so mentiu como tambem roubou","ele nao so mentiu mas tambem roubou","alem de mentir ele ainda roubou"],"aceitasEn":["not only did he lie he also stole"],"distratores":["Ele não mentiu, mas também roubou.","Ele só mentiu, e não roubou.","Ele não mentiu nem roubou.","Ele mentiu, mas não roubou."],"nivel":"C2","tags":["gramática","formal"],"nota":"Depois de «not only» no começo da frase o inglês inverte, como numa pergunta: «did he lie», «has she won», «was it cold». O mesmo acontece com «never», «rarely» e «no sooner».","v":"d0287271"},{"idioma":"en","id":"en-f087","tipo":"frase","en":"It's high time you left.","pt":"Já está na hora de você ir embora.","aceitas":["ja esta na hora de voce ir embora","ja esta na hora de voce ir","ja passou da hora de voce ir embora","ta na hora de voce ir embora"],"aceitasEn":["its high time you left","it is high time you left"],"distratores":["Já está na hora de você chegar.","Já está na hora de você decidir.","Ainda não está na hora de você ir.","Já está na hora de você almoçar."],"nivel":"C1","tags":["gramática","expressão"],"nota":"«It's high time» pede o verbo no passado, mesmo falando do agora: «it's high time you left», «it's time we went». É o passado da cobrança, e não o do tempo.","v":"35609a5f"},{"idioma":"en","id":"en-f088","tipo":"frase","en":"I'd rather you didn't smoke.","pt":"Eu preferia que você não fumasse.","aceitas":["eu preferia que voce nao fumasse","preferia que voce nao fumasse","eu preferiria que voce nao fumasse","eu prefiro que voce nao fume"],"aceitasEn":["id rather you didnt smoke","i would rather you didnt smoke","i would rather you did not smoke"],"distratores":["Eu preferia não fumar.","Eu prefiro que você fume.","Eu pedi que você não fumasse.","Eu não queria que você fumasse."],"nivel":"C1","tags":["gramática","subjuntivo"],"nota":"«I'd rather» muda de forma conforme quem faz: com o mesmo sujeito pede o verbo nu, «I'd rather not smoke»; com outro sujeito pede o passado, «I'd rather you didn't smoke».","v":"54e6a195"},{"idioma":"en","id":"en-f089","tipo":"frase","en":"No sooner had I arrived than it started raining.","pt":"Mal cheguei, começou a chover.","aceitas":["mal cheguei comecou a chover","assim que cheguei comecou a chover","mal eu cheguei comecou a chover","tinha acabado de chegar e comecou a chover"],"aceitasEn":["no sooner had i arrived than it started raining"],"distratores":["Mal chovia, eu cheguei.","Logo que parou de chover, cheguei.","Cheguei bem antes de começar a chover.","Cheguei porque começou a chover."],"nivel":"C2","tags":["gramática","formal"],"nota":"«No sooner» inverte o auxiliar, «had I arrived», e fecha com «than», nunca com «when». O par mais simples, e muito mais falado, é «as soon as I arrived».","v":"79da1c37"},{"idioma":"en","id":"en-f090","tipo":"frase","en":"She's used to working nights.","pt":"Ela está acostumada a trabalhar à noite.","aceitas":["ela esta acostumada a trabalhar a noite","esta acostumada a trabalhar a noite","ela ja se acostumou a trabalhar a noite","ela tem costume de trabalhar a noite"],"aceitasEn":["shes used to working nights","she is used to working nights"],"distratores":["Ela costumava trabalhar à noite.","Ela vai se acostumar a trabalhar à noite.","Ela odeia trabalhar à noite.","Ela precisa trabalhar à noite."],"nivel":"B2","tags":["gramática","trabalho"],"nota":"«Used to» com o verbo nu é o hábito que acabou: «I used to smoke». «Be used to» com «-ing» é o hábito que se pegou e continua. O «to» do segundo é preposição, e por isso o verbo vira «-ing».","v":"f8d4e7f7"},{"idioma":"en","id":"en-f091","tipo":"frase","en":"I got my hair cut.","pt":"Eu cortei o cabelo.","aceitas":["eu cortei o cabelo","cortei o cabelo","eu fui cortar o cabelo","mandei cortar o cabelo"],"aceitasEn":["i got my hair cut","i had my hair cut"],"distratores":["Eu cortei o cabelo dela.","Eu pintei o cabelo.","Eu lavei o cabelo.","Eu penteei o cabelo."],"nivel":"B2","tags":["gramática","corpo"],"nota":"«Get something done» é mandar fazer, e não fazer: «I got my hair cut» é o cabeleireiro que cortou. Quem cortou o próprio cabelo diz «I cut my own hair».","v":"27f46456"},{"idioma":"en","id":"en-f092","tipo":"frase","en":"The sooner, the better.","pt":"Quanto antes, melhor.","aceitas":["quanto antes melhor","quanto mais cedo melhor","o quanto antes melhor"],"aceitasEn":["the sooner the better"],"distratores":["Quanto depois, melhor.","Quanto mais, pior.","Quanto menos, melhor.","Antes tarde do que nunca."],"nivel":"B2","tags":["gramática","expressão"],"nota":"O molde é «the» com o comparativo, duas vezes: «the sooner, the better», «the more you practice, the easier it gets». Esse «the» não é artigo — é a régua que liga as duas metades.","v":"98219d38"},{"idioma":"en","id":"en-f093","tipo":"frase","en":"Whatever you do, don't tell her.","pt":"Faça o que fizer, não conte para ela.","aceitas":["faca o que fizer nao conte para ela","faca o que voce fizer nao conte para ela","faca o que fizer nao fale para ela","faca o que fizer nao conte a ela"],"aceitasEn":["whatever you do dont tell her","whatever you do do not tell her"],"distratores":["Faça o que quiser, mas conte para ela.","Aconteça o que acontecer, conte para ela.","Diga o que disser, não mostre para ela.","Faça o que ela mandar, e não conte."],"nivel":"B2","tags":["gramática","expressão"],"nota":"«Whatever», «whoever», «wherever» e «however» abrem a metade que não muda nada: «whatever you do». Não são perguntas, e por isso não invertem o verbo.","v":"5e9cac4b"},{"idioma":"en","id":"en-f094","tipo":"frase","en":"He's supposed to be here by now.","pt":"Ele já devia estar aqui.","aceitas":["ele ja devia estar aqui","ja devia estar aqui","ele ja deveria estar aqui","era para ele ja estar aqui"],"aceitasEn":["hes supposed to be here by now","he is supposed to be here by now"],"distratores":["Ele já esteve aqui.","Ele ainda vai estar aqui.","Ele nunca esteve aqui.","Ele quis estar aqui."],"nivel":"B2","tags":["gramática","social"],"nota":"«Be supposed to» é o combinado que não se cumpriu: «he's supposed to be here» quer dizer que ficou de estar e não está. Serve também para o que se diz por aí: «it's supposed to be good».","v":"86257ab3"},{"idioma":"en","id":"en-f095","tipo":"frase","en":"The meeting dragged on.","pt":"A reunião se arrastou.","aceitas":["a reuniao se arrastou","a reuniao arrastou","a reuniao nao acabava mais","a reuniao se estendeu demais"],"aceitasEn":["the meeting dragged on"],"distratores":["A reunião acabou cedo.","A reunião foi adiada.","A reunião começou tarde.","A reunião foi cancelada."],"nivel":"C1","tags":["phrasal verb","trabalho"],"nota":"«Drag on» é o que se arrasta além do que devia: a reunião, a guerra, o processo. Vem sempre com a queixa embutida, e nunca leva objeto.","v":"97884552"},{"idioma":"en","id":"en-f096","tipo":"frase","en":"He backed out at the last minute.","pt":"Ele desistiu na última hora.","aceitas":["ele desistiu na ultima hora","desistiu na ultima hora","ele voltou atras na ultima hora","ele caiu fora na ultima hora"],"aceitasEn":["he backed out at the last minute"],"distratores":["Ele chegou na última hora.","Ele avisou na última hora.","Ele decidiu na última hora.","Ele pagou na última hora."],"nivel":"C1","tags":["phrasal verb","social"],"nota":"«Back out» é sair de um combinado já fechado: o convite aceito, o contrato prometido, a viagem marcada. Com o que se abandona, pede «of»: «he backed out of the deal».","v":"ed5d7f16"},{"idioma":"en","id":"en-f097","tipo":"frase","en":"Things are looking up.","pt":"As coisas estão melhorando.","aceitas":["as coisas estao melhorando","as coisas melhoraram","as coisas estao indo melhor","a situacao esta melhorando"],"aceitasEn":["things are looking up"],"distratores":["As coisas estão piorando.","As coisas estão paradas.","As coisas estão caras.","As coisas estão mudando."],"nivel":"B2","tags":["phrasal verb","expressão"],"nota":"«Look up» com «things» é a virada para melhor, e só existe nesse sentido figurado. Procurar uma palavra no dicionário também é «look up», mas aí leva objeto: «look it up».","v":"ef0dcc4c"},{"idioma":"en","id":"en-f098","tipo":"frase","en":"I can't get over it.","pt":"Eu não consigo superar isso.","aceitas":["eu nao consigo superar isso","nao consigo superar isso","eu nao supero isso","eu nao consigo esquecer isso"],"aceitasEn":["i cant get over it","i cannot get over it"],"distratores":["Eu não consigo entender isso.","Eu não consigo explicar isso.","Eu não consigo aceitar isso.","Eu não consigo lembrar disso."],"nivel":"B2","tags":["phrasal verb","saúde"],"nota":"«Get over» é atravessar e deixar para trás: a gripe, o susto, o fim de um namoro. Serve também para o espanto que não passa: «I can't get over how big he is».","v":"def03dd9"},{"idioma":"en","id":"en-f099","tipo":"frase","en":"She talked me into it.","pt":"Ela me convenceu a fazer isso.","aceitas":["ela me convenceu a fazer isso","me convenceu a fazer isso","ela me convenceu","ela me enrolou pra fazer isso"],"aceitasEn":["she talked me into it"],"distratores":["Ela me proibiu de fazer isso.","Ela me ajudou a fazer isso.","Ela me ensinou a fazer isso.","Ela me obrigou a fazer isso."],"nivel":"B2","tags":["phrasal verb","social"],"nota":"«Talk someone into something» é convencer na conversa. O contrário é «talk someone out of it», que é demover. Os dois pedem o «-ing» quando vem verbo: «talked me into going».","v":"60365acd"},{"idioma":"en","id":"en-f100","tipo":"frase","en":"We ran into each other downtown.","pt":"Nós nos encontramos por acaso no centro.","aceitas":["nos nos encontramos por acaso no centro","nos encontramos por acaso no centro","a gente se esbarrou no centro","nos nos cruzamos no centro"],"aceitasEn":["we ran into each other downtown"],"distratores":["Nós nos encontramos de propósito no centro.","Nós nos perdemos um do outro no centro.","Nós nos falamos por telefone no centro.","Nós nos despedimos com pressa no centro."],"nivel":"B2","tags":["phrasal verb","cidade"],"nota":"«Run into» é o encontro que ninguém marcou. O mesmo verbo serve para bater com o carro, «run into a tree», e para topar com um problema, «run into trouble».","v":"9d14e18e"},{"idioma":"en","id":"en-f101","tipo":"frase","en":"It all boils down to money.","pt":"No fundo, é tudo questão de dinheiro.","aceitas":["no fundo e tudo questao de dinheiro","tudo se resume a dinheiro","no fim e tudo questao de dinheiro","tudo se reduz a dinheiro"],"aceitasEn":["it all boils down to money"],"distratores":["No fundo, é tudo questão de tempo.","No fundo, é tudo questão de sorte.","No fundo, é tudo questão de gosto.","No fundo, é tudo questão de orgulho."],"nivel":"C1","tags":["expressão","economia"],"nota":"«Boil down to» vem da panela: ferve até sobrar só o essencial. É o verbo de quem corta a conversa e vai direto ao que interessa.","v":"1c235d89"},{"idioma":"en","id":"en-f102","tipo":"frase","en":"He owned up to the mistake.","pt":"Ele assumiu o erro.","aceitas":["ele assumiu o erro","assumiu o erro","ele admitiu o erro","ele reconheceu o erro"],"aceitasEn":["he owned up to the mistake"],"distratores":["Ele escondeu o erro.","Ele explicou o erro.","Ele corrigiu o erro.","Ele percebeu o erro."],"nivel":"C1","tags":["phrasal verb","social"],"nota":"«Own up» é confessar o que se fez de errado, e sempre com «to»: «own up to it». É bem mais leve que «confess», que já cheira a delegacia.","v":"6aad8f09"},{"idioma":"en","id":"en-f103","tipo":"frase","en":"It's a piece of cake.","pt":"É moleza.","aceitas":["e moleza","e mole","e facil demais","e sopa","e canja"],"aceitasEn":["its a piece of cake","it is a piece of cake"],"distratores":["É um pedaço de bolo.","É a fatia do bolo.","É uma delícia.","É uma tentação."],"nivel":"B2","tags":["expressão","comida"],"nota":"«A piece of cake» é o que sai sem esforço nenhum. O inglês tem mais dois para a mesma coisa: «as easy as pie» e «a walk in the park». Nenhum deles fala de bolo de verdade.","v":"f14aa606"},{"idioma":"en","id":"en-f104","tipo":"frase","en":"Let's play it by ear.","pt":"Vamos ver na hora.","aceitas":["vamos ver na hora","vamos decidir na hora","a gente ve na hora","vamos deixar rolar","vamos improvisar"],"aceitasEn":["lets play it by ear","let us play it by ear"],"distratores":["Vamos tocar de ouvido.","Vamos escutar com atenção.","Vamos combinar tudo antes.","Vamos deixar para depois."],"nivel":"C1","tags":["expressão","cultura"],"nota":"«Play it by ear» vem do músico que toca sem partitura: decidir na hora, conforme for. Fora da música é onde mais se usa, e quase sempre com «let's».","v":"4928c0a6"},{"idioma":"en","id":"en-f105","tipo":"frase","en":"He's beating around the bush.","pt":"Ele está fazendo rodeios.","aceitas":["ele esta fazendo rodeios","ele esta enrolando","ele nao vai direto ao ponto","ele fica dando voltas"],"aceitasEn":["hes beating around the bush","he is beating around the bush"],"distratores":["Ele está batendo no mato.","Ele está cortando o mato.","Ele está perdendo a paciência.","Ele está mentindo descaradamente."],"nivel":"C1","tags":["expressão","social"],"nota":"«Beat around the bush» vem da caça: batia-se o mato em volta em vez de entrar nele. O oposto é «get to the point», ou «cut to the chase».","v":"eb76f7f7"},{"idioma":"en","id":"en-f106","tipo":"frase","en":"That's the last straw.","pt":"Essa foi a gota d'água.","aceitas":["essa foi a gota d'agua","essa e a gota d'agua","foi a gota d'agua","essa foi a ultima gota"],"aceitasEn":["thats the last straw","that is the last straw"],"distratores":["Essa foi a última palha.","Essa é a palha que faltava.","Essa foi a última chance.","Essa foi a melhor hora."],"nivel":"C1","tags":["expressão","social"],"nota":"«The last straw» vem do camelo: a última palhinha que quebra o lombo já carregado. O inglês diz a palha e o português diz a gota — muda a imagem, não a paciência que acabou.","v":"a6c2c539"},{"idioma":"en","id":"en-f107","tipo":"frase","en":"I'm feeling under the weather.","pt":"Estou meio indisposto.","aceitas":["estou meio indisposto","estou meio indisposta","nao estou me sentindo bem","estou meio adoentado","estou meio mal"],"aceitasEn":["im feeling under the weather","i am feeling under the weather"],"distratores":["Estou debaixo de chuva.","Estou vendo a previsão do tempo.","Estou de mau humor.","Estou com muita pressa."],"nivel":"B2","tags":["expressão","saúde"],"nota":"«Under the weather» é o mal-estar sem nome: nem doente de cama, nem bem. Vem do mar, do passageiro que descia para escapar do tempo ruim no convés.","v":"fa3d9d6b"},{"idioma":"en","id":"en-f108","tipo":"frase","en":"We'll cross that bridge when we come to it.","pt":"Quando chegar a hora, a gente vê.","aceitas":["quando chegar a hora a gente ve","quando chegar a hora nos veremos","depois a gente ve isso","na hora a gente resolve"],"aceitasEn":["well cross that bridge when we come to it","we will cross that bridge when we come to it"],"distratores":["Vamos atravessar a ponte quando chegar lá.","Construímos a ponte antes da hora.","Precisamos resolver tudo isso agora mesmo.","É melhor desistir antes de chegar lá."],"nivel":"C1","tags":["expressão","provérbio"],"nota":"«Cross that bridge when we come to it» é adiar a preocupação que ainda não chegou. Diz-se inteira, e quase sempre com «we'll».","v":"56ba5c6f"},{"idioma":"en","id":"en-f109","tipo":"frase","en":"It cost an arm and a leg.","pt":"Custou os olhos da cara.","aceitas":["custou os olhos da cara","custou uma fortuna","custou caro pra caramba","saiu pelos olhos da cara"],"aceitasEn":["it cost an arm and a leg"],"distratores":["Custou um braço e uma perna.","Machucou o braço e a perna.","Custou o último tostão.","Valeu cada centavo."],"nivel":"B2","tags":["expressão","economia"],"nota":"O inglês paga com braço e perna, o português com os olhos da cara e o espanhol com um olho ou um rim. É a mesma conta, em pedaços diferentes do corpo.","v":"ad80ae7e"},{"idioma":"en","id":"en-f110","tipo":"frase","en":"Don't bite off more than you can chew.","pt":"Não dê passo maior que a perna.","aceitas":["nao de passo maior que a perna","nao de um passo maior que a perna","nao queira abracar o mundo","nao pegue mais do que da conta"],"aceitasEn":["dont bite off more than you can chew","do not bite off more than you can chew"],"distratores":["Não morda mais do que consegue mastigar.","Não coma tão rápido assim.","Não desista antes de tentar.","Não confie em quem promete demais."],"nivel":"C1","tags":["expressão","provérbio"],"nota":"«Bite off more than you can chew» é aceitar mais do que se dá conta. O inglês fala da boca e o português fala da perna, mas os dois avisam antes de a pessoa se meter.","v":"2ccd3bff"},{"idioma":"en","id":"en-f111","tipo":"frase","en":"She let the cat out of the bag.","pt":"Ela deu com a língua nos dentes.","aceitas":["ela deu com a lingua nos dentes","deu com a lingua nos dentes","ela contou o segredo","ela abriu o bico","ela entregou o segredo"],"aceitasEn":["she let the cat out of the bag"],"distratores":["Ela tirou o gato do saco.","Ela comprou gato por lebre.","Ela guardou bem o segredo.","Ela mudou de assunto na hora."],"nivel":"C1","tags":["expressão","animais"],"nota":"«Let the cat out of the bag» é contar o que devia ficar calado, quase sempre sem querer. Vem da feira: vendia-se um leitão dentro do saco e, na hora de abrir, saía um gato.","v":"872f36c8"},{"idioma":"en","id":"en-f112","tipo":"frase","en":"He's got cold feet.","pt":"Ele está perdendo a coragem.","aceitas":["ele esta perdendo a coragem","ele esta amarelando","ele ta com medo de seguir","ele esta recuando"],"aceitasEn":["hes got cold feet","he has got cold feet","he has cold feet"],"distratores":["Ele está com os pés gelados.","Ele está com frio nos pés.","Ele está com pressa de sair.","Ele está com raiva de todos."],"nivel":"C1","tags":["expressão","corpo"],"nota":"«Cold feet» é a coragem que esfria na véspera: o casamento, a entrevista, o salto. Quase sempre com «get» ou «have got», e quase sempre antes da hora.","v":"381718bb"},{"idioma":"en","id":"en-f113","tipo":"frase","en":"Speak of the devil.","pt":"Falando no diabo.","aceitas":["falando no diabo","falando no diabo aparece o rabo","falou no diabo"],"aceitasEn":["speak of the devil"],"distratores":["O diabo que o carregue.","Nem o diabo aguenta isso.","Cada um por si.","Não se fala nisso aqui."],"nivel":"B2","tags":["expressão","social"],"nota":"«Speak of the devil» é o que se diz quando a pessoa comentada aparece na porta. A frase inteira era «speak of the devil and he shall appear», e hoje só sobra a primeira metade.","v":"ed23b2ba"},{"idioma":"en","id":"en-f114","tipo":"frase","en":"Better safe than sorry.","pt":"É melhor prevenir do que remediar.","aceitas":["e melhor prevenir do que remediar","melhor prevenir do que remediar","e melhor garantir","seguranca nunca e demais"],"aceitasEn":["better safe than sorry"],"distratores":["É melhor tarde do que nunca.","É melhor pedir perdão que permissão.","É melhor não arriscar nada.","É melhor deixar como está."],"nivel":"B2","tags":["expressão","provérbio"],"nota":"«Better safe than sorry» é o conselho de quem prefere o trabalho a mais ao arrependimento. O molde «better X than Y» dispensa o verbo, como o «mais vale» do português.","v":"efbeb924"},{"idioma":"en","id":"en-f115","tipo":"frase","en":"It's not rocket science.","pt":"Não é nenhum bicho de sete cabeças.","aceitas":["nao e nenhum bicho de sete cabecas","nao e bicho de sete cabecas","nao e nada de outro mundo","nao tem segredo nenhum"],"aceitasEn":["its not rocket science","it is not rocket science"],"distratores":["Não é nenhuma ciência de foguete.","Não é nenhum assunto de cientista.","Não é nada sério, pode deixar.","Não é bem assim que funciona."],"nivel":"C1","tags":["expressão","tecnologia"],"nota":"«It's not rocket science» é o desdém de quem acha fácil o que o outro complicou. A irmã dela é «it's not brain surgery», e as duas nasceram nos Estados Unidos no século XX.","v":"0c9dee8f"},{"idioma":"en","id":"en-f116","tipo":"frase","en":"He's pulling your leg.","pt":"Ele está te zoando.","aceitas":["ele esta te zoando","ele ta te zoando","ele esta brincando com voce","ele esta tirando uma com a sua cara","ele esta te sacaneando"],"aceitasEn":["hes pulling your leg","he is pulling your leg"],"distratores":["Ele está puxando sua perna.","Ele está segurando sua perna.","Ele está falando sério agora.","Ele está te enganando de verdade."],"nivel":"B2","tags":["expressão","social"],"nota":"«Pull someone's leg» é a brincadeira de contar uma mentira boba para ver se a pessoa acredita. O espanhol puxa o cabelo, «tomar el pelo», e o inglês puxa a perna.","v":"fafd2af6"},{"idioma":"en","id":"en-v047","tipo":"frase","en":"He ran a marathon.","pt":"Ele correu uma maratona.","aceitas":["ele correu uma maratona","correu uma maratona","ele fez uma maratona"],"aceitasEn":["he ran a marathon"],"distratores":["Ele corre uma maratona.","Ele correrá uma maratona.","Ele correria uma maratona.","Ele tinha corrido uma maratona."],"formasEn":{"He runs a marathon":"presente","He will run a marathon":"futuro","He would run a marathon":"condicional","He had run a marathon":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","run","pretérito"],"nota":"«Run», «ran», «run». O particípio volta à forma do infinitivo, e é por isso que «I have run» parece incompleto a quem espera um «-ed». O verbo também serve para administrar: «she runs a company».","v":"179617ae"},{"idioma":"en","id":"en-v048","tipo":"frase","en":"She wore a black dress.","pt":"Ela usou um vestido preto.","aceitas":["ela usou um vestido preto","usou um vestido preto","ela vestiu um vestido preto","ela pos um vestido preto"],"aceitasEn":["she wore a black dress"],"distratores":["Ela usa um vestido preto.","Ela usará um vestido preto.","Ela usaria um vestido preto.","Ela tinha usado um vestido preto."],"formasEn":{"She wears a black dress":"presente","She will wear a black dress":"futuro","She would wear a black dress":"condicional","She had worn a black dress":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","irregular","wear","roupa"],"nota":"«Wear», «wore», «worn». Serve para roupa, óculos, perfume e barba — tudo o que se leva no corpo. Gastar de tanto usar é «wear out».","v":"1b2cd07d"},{"idioma":"en","id":"en-v049","tipo":"frase","en":"He threw the ball.","pt":"Ele jogou a bola.","aceitas":["ele jogou a bola","jogou a bola","ele atirou a bola","ele arremessou a bola"],"aceitasEn":["he threw the ball"],"distratores":["Ele joga a bola.","Ele jogará a bola.","Ele jogaria a bola.","Ele tinha jogado a bola."],"formasEn":{"He throws the ball":"presente","He will throw the ball":"futuro","He would throw the ball":"condicional","He had thrown the ball":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","irregular","throw","pretérito"],"nota":"«Throw», «threw», «thrown». O passado «threw» soa igual a «through», que é através. Jogar fora é «throw away».","v":"acfd3b7c"},{"idioma":"en","id":"en-v050","tipo":"frase","en":"She drew a picture.","pt":"Ela fez um desenho.","aceitas":["ela fez um desenho","fez um desenho","ela desenhou","ela desenhou uma figura"],"aceitasEn":["she drew a picture"],"distratores":["Ela faz um desenho.","Ela fará um desenho.","Ela faria um desenho.","Ela tinha feito um desenho."],"formasEn":{"She draws a picture":"presente","She will draw a picture":"futuro","She would draw a picture":"condicional","She had drawn a picture":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","irregular","draw","pretérito"],"nota":"«Draw», «drew», «drawn». Além de desenhar, é puxar: «draw the curtains», «draw a conclusion». E o empate no futebol também é «a draw».","v":"ee953f37"},{"idioma":"en","id":"en-v051","tipo":"frase","en":"I rode a bike.","pt":"Eu andei de bicicleta.","aceitas":["eu andei de bicicleta","andei de bicicleta","eu fui de bicicleta","eu pedalei"],"aceitasEn":["i rode a bike"],"distratores":["Eu ando de bicicleta.","Eu andarei de bicicleta.","Eu andaria de bicicleta.","Eu tinha andado de bicicleta."],"formasEn":{"I ride a bike":"presente","I will ride a bike":"futuro","I would ride a bike":"condicional","I had ridden a bike":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","irregular","ride","viagem"],"nota":"«Ride», «rode», «ridden». Vale para bicicleta, cavalo, moto e montanha-russa — tudo em que se senta em cima. Ao volante do carro é «drive».","v":"5e5d10ce"},{"idioma":"en","id":"en-v052","tipo":"frase","en":"He shook my hand.","pt":"Ele apertou minha mão.","aceitas":["ele apertou minha mao","apertou minha mao","ele apertou a minha mao","ele me cumprimentou com um aperto de mao"],"aceitasEn":["he shook my hand"],"distratores":["Ele aperta minha mão.","Ele apertará minha mão.","Ele apertaria minha mão.","Ele tinha apertado minha mão."],"formasEn":{"He shakes my hand":"presente","He will shake my hand":"futuro","He would shake my hand":"condicional","He had shaken my hand":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","shake","social"],"nota":"«Shake», «shook», «shaken». O aperto de mão é «shake hands», e balançar a cabeça dizendo não é «shake your head» — o sim é «nod».","v":"da90642f"},{"idioma":"en","id":"en-v053","tipo":"frase","en":"Someone stole my bike.","pt":"Alguém roubou minha bicicleta.","aceitas":["alguem roubou minha bicicleta","roubaram minha bicicleta","alguem levou minha bicicleta","alguem furtou minha bicicleta"],"aceitasEn":["someone stole my bike"],"distratores":["Alguém rouba minha bicicleta.","Alguém roubará minha bicicleta.","Alguém roubaria minha bicicleta.","Alguém tinha roubado minha bicicleta."],"formasEn":{"Someone steals my bike":"presente","Someone will steal my bike":"futuro","Someone would steal my bike":"condicional","Someone had stolen my bike":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","steal","pretérito"],"nota":"«Steal», «stole», «stolen». Rouba-se a coisa, e não a pessoa: «they stole my bike», nunca «they stole me». Assaltar alguém é «rob».","v":"3715ab37"},{"idioma":"en","id":"en-v054","tipo":"frase","en":"She swam in the lake.","pt":"Ela nadou no lago.","aceitas":["ela nadou no lago","nadou no lago","ela foi nadar no lago"],"aceitasEn":["she swam in the lake"],"distratores":["Ela nada no lago.","Ela nadará no lago.","Ela nadaria no lago.","Ela tinha nadado no lago."],"formasEn":{"She swims in the lake":"presente","She will swim in the lake":"futuro","She would swim in the lake":"condicional","She had swum in the lake":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","irregular","swim","pretérito"],"nota":"«Swim», «swam», «swum». O particípio «swum» quase não aparece, mas é ele que entra depois de «have». O maiô é «a swimsuit».","v":"fb820726"},{"idioma":"en","id":"en-v055","tipo":"frase","en":"I tore the paper.","pt":"Eu rasguei o papel.","aceitas":["eu rasguei o papel","rasguei o papel","eu rompi o papel"],"aceitasEn":["i tore the paper"],"distratores":["Eu rasgo o papel.","Eu rasgarei o papel.","Eu rasgaria o papel.","Eu tinha rasgado o papel."],"formasEn":{"I tear the paper":"presente","I will tear the paper":"futuro","I would tear the paper":"condicional","I had torn the paper":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","tear","pretérito"],"nota":"«Tear», «tore», «torn». Escreve-se igual à lágrima, «a tear», mas se pronuncia diferente: o verbo rima com «air» e a lágrima com «ear».","v":"37a49a71"},{"idioma":"en","id":"en-v056","tipo":"frase","en":"He hid the money.","pt":"Ele escondeu o dinheiro.","aceitas":["ele escondeu o dinheiro","escondeu o dinheiro","ele ocultou o dinheiro"],"aceitasEn":["he hid the money"],"distratores":["Ele esconde o dinheiro.","Ele esconderá o dinheiro.","Ele esconderia o dinheiro.","Ele tinha escondido o dinheiro."],"formasEn":{"He hides the money":"presente","He will hide the money":"futuro","He would hide the money":"condicional","He had hidden the money":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","hide","pretérito"],"nota":"«Hide», «hid», «hidden». Serve também para se esconder, e aí dispensa o pronome: «he hid behind the door». A brincadeira é «hide-and-seek».","v":"ca60fc17"},{"idioma":"en","id":"en-v057","tipo":"frase","en":"She meant well.","pt":"A intenção dela era boa.","aceitas":["a intencao dela era boa","ela fez por bem","ela tinha boa intencao","a intencao dela foi boa"],"aceitasEn":["she meant well"],"distratores":["A intenção dela é boa.","A intenção dela será boa.","A intenção dela seria boa.","A intenção dela tinha sido boa."],"formasEn":{"She means well":"presente","She will mean well":"futuro","She would mean well":"condicional","She had meant well":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","mean","pretérito"],"nota":"«Mean», «meant», «meant». O passado guarda o «ea» da escrita e perde o som: pronuncia-se «ment». «Mean well» é ter boa intenção, e «I mean it» é falar sério.","v":"f598e864"},{"idioma":"en","id":"en-v058","tipo":"frase","en":"The phone rang.","pt":"O telefone tocou.","aceitas":["o telefone tocou","tocou o telefone","o telefone chamou"],"aceitasEn":["the phone rang"],"distratores":["O telefone toca.","O telefone tocará.","O telefone tocaria.","O telefone tinha tocado."],"formasEn":{"The phone rings":"presente","The phone will ring":"futuro","The phone would ring":"condicional","The phone had rung":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","irregular","ring","tecnologia"],"nota":"«Ring», «rang», «rung». Vale para telefone, sino e campainha. Ligar para alguém é «ring someone up» no britânico — no americano é «call».","v":"29086e7f"},{"idioma":"en","id":"en-v059","tipo":"frase","en":"She sang beautifully.","pt":"Ela cantou lindamente.","aceitas":["ela cantou lindamente","ela cantou muito bem","cantou lindamente","ela cantou lindo"],"aceitasEn":["she sang beautifully"],"distratores":["Ela canta lindamente.","Ela cantará lindamente.","Ela cantaria lindamente.","Ela tinha cantado lindamente."],"formasEn":{"She sings beautifully":"presente","She will sing beautifully":"futuro","She would sing beautifully":"condicional","She had sung beautifully":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","irregular","sing","cultura"],"nota":"«Sing», «sang», «sung». Segue o mesmo desenho de «ring» e «drink»: a vogal desce de «i» para «a» no passado e vira «u» no particípio.","v":"11dbd73a"},{"idioma":"en","id":"en-v060","tipo":"frase","en":"The dog bit me.","pt":"O cachorro me mordeu.","aceitas":["o cachorro me mordeu","o cao me mordeu","o cachorro deu uma mordida em mim"],"aceitasEn":["the dog bit me"],"distratores":["O cachorro me morde.","O cachorro me morderá.","O cachorro me morderia.","O cachorro tinha me mordido."],"formasEn":{"The dog bites me":"presente","The dog will bite me":"futuro","The dog would bite me":"condicional","The dog had bitten me":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","irregular","bite","animais"],"nota":"«Bite», «bit», «bitten». O passado «bit» é igual ao «bit» de pedacinho. A mordida também é «a bite», e comer alguma coisa rápido é «grab a bite».","v":"3bcb9b66"},{"idioma":"en","id":"en-v061","tipo":"frase","en":"He hung the picture on the wall.","pt":"Ele pendurou o quadro na parede.","aceitas":["ele pendurou o quadro na parede","pendurou o quadro na parede","ele dependurou o quadro na parede"],"aceitasEn":["he hung the picture on the wall"],"distratores":["Ele pendura o quadro na parede.","Ele pendurará o quadro na parede.","Ele penduraria o quadro na parede.","Ele tinha pendurado o quadro na parede."],"formasEn":{"He hangs the picture on the wall":"presente","He will hang the picture on the wall":"futuro","He would hang the picture on the wall":"condicional","He had hung the picture on the wall":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","hang","casa"],"nota":"«Hang», «hung», «hung» para tudo o que se pendura. Existe um segundo passado, «hanged», e ele é só da forca — por isso «he hung up on me» está certo e «he hanged up» não.","v":"4dd4477f"},{"idioma":"en","id":"en-v062","tipo":"frase","en":"They fought for hours.","pt":"Eles brigaram por horas.","aceitas":["eles brigaram por horas","brigaram por horas","eles brigaram durante horas","eles discutiram por horas"],"aceitasEn":["they fought for hours"],"distratores":["Eles brigam por horas.","Eles brigarão por horas.","Eles brigariam por horas.","Eles tinham brigado por horas."],"formasEn":{"They fight for hours":"presente","They will fight for hours":"futuro","They would fight for hours":"condicional","They had fought for hours":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","fight","pretérito"],"nota":"«Fight», «fought», «fought». «Fought» rima com «thought» e «bought», e em nenhum dos três o «gh» se pronuncia. Brigar por alguma coisa é «fight for»; contra, «fight against».","v":"592ee975"},{"idioma":"en","id":"en-v063","tipo":"frase","en":"She flew to Madrid.","pt":"Ela voou para Madri.","aceitas":["ela voou para madri","voou para madri","ela foi de aviao para madri"],"aceitasEn":["she flew to madrid"],"distratores":["Ela voa para Madri.","Ela voará para Madri.","Ela voaria para Madri.","Ela tinha voado para Madri."],"formasEn":{"She flies to Madrid":"presente","She will fly to Madrid":"futuro","She would fly to Madrid":"condicional","She had flown to Madrid":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","irregular","fly","viagem"],"nota":"«Fly», «flew», «flown». O passado «flew» soa igual a «flu», a gripe. No presente da terceira pessoa o «y» vira «ies»: «she flies».","v":"5f810d3f"},{"idioma":"en","id":"en-v064","tipo":"frase","en":"He led the team.","pt":"Ele liderou o time.","aceitas":["ele liderou o time","liderou o time","ele comandou o time","ele chefiou a equipe"],"aceitasEn":["he led the team"],"distratores":["Ele lidera o time.","Ele liderará o time.","Ele lideraria o time.","Ele tinha liderado o time."],"formasEn":{"He leads the team":"presente","He will lead the team":"futuro","He would lead the team":"condicional","He had led the team":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","lead","trabalho"],"nota":"«Lead», «led», «led». O infinitivo rima com «need», e o passado «led» soa como «lead», o chumbo. Tira-se uma letra e a pronúncia troca de lugar.","v":"355d5643"},{"idioma":"en","id":"en-v065","tipo":"frase","en":"She forgave me.","pt":"Ela me perdoou.","aceitas":["ela me perdoou","me perdoou","ela me desculpou"],"aceitasEn":["she forgave me"],"distratores":["Ela me perdoa.","Ela me perdoará.","Ela me perdoaria.","Ela tinha me perdoado."],"formasEn":{"She forgives me":"presente","She will forgive me":"futuro","She would forgive me":"condicional","She had forgiven me":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","forgive","social"],"nota":"«Forgive», «forgave», «forgiven» — é «give» com um prefixo, e conjuga igual a ele. Perdoa-se a pessoa, «forgive me», ou a falta, «forgive the delay».","v":"5c2b4813"},{"idioma":"en","id":"en-v066","tipo":"frase","en":"The lake froze.","pt":"O lago congelou.","aceitas":["o lago congelou","o lago virou gelo","o lago ficou congelado"],"aceitasEn":["the lake froze"],"distratores":["O lago congela.","O lago congelará.","O lago congelaria.","O lago tinha congelado."],"formasEn":{"The lake freezes":"presente","The lake will freeze":"futuro","The lake would freeze":"condicional","The lake had frozen":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","freeze","pretérito"],"nota":"«Freeze», «froze», «frozen». O congelador é «the freezer», e paralisar de susto também é «freeze»: «I froze».","v":"d965a30b"},{"idioma":"en","id":"en-p075","tipo":"palavra","en":"the stranger","pt":"o desconhecido","aceitas":["o desconhecido","desconhecido","o estranho","um estranho","uma pessoa desconhecida"],"aceitasEn":["the stranger","stranger","a stranger"],"distratores":["o intruso","o imigrante","o hóspede","o vizinho"],"nivel":"B1","tags":["substantivo","falso-amigo","social"],"nota":"«Stranger» é quem você não conhece. O sentido de quem vem de fora existe no inglês literário («a stranger in a strange land»), mas na fala de todo dia ele sumiu: quem vem de outro país é «foreigner».\n🇺🇸 stranger → 🇧🇷 desconhecido, estranho\n🇺🇸 foreigner → 🇧🇷 estrangeiro","v":"c2d31560"},{"idioma":"en","id":"en-u075","tipo":"frase","requer":"en-p075","en":"Don't talk to strangers.","pt":"Não fale com desconhecidos.","aceitas":["nao fale com desconhecidos","nao fale com estranhos","nao converse com desconhecidos","nao converse com estranhos","nao fale com quem voce nao conhece","nao fale com pessoas desconhecidas"],"aceitasEn":["dont talk to strangers","do not talk to strangers","dont speak to strangers"],"distratores":["Não fale com estrangeiros.","Não fale com jornalistas.","Não fale com vizinhos.","Não fale com policiais."],"nivel":"B1","tags":["substantivo","falso-amigo","social"],"nota":"A frase que todo pai diz. Repare no plural sem artigo: «strangers», e não «the strangers» — para falar de gente em geral o inglês corta o artigo.","v":"374bbbdb"},{"idioma":"en","id":"en-p076","tipo":"palavra","en":"the notice","pt":"o aviso","aceitas":["o aviso","aviso","o comunicado","o aviso previo"],"aceitasEn":["the notice","notice","a notice"],"distratores":["a notícia","o noticiário","a nota","o recado"],"nivel":"B1","tags":["substantivo","falso-amigo","mídia"],"nota":"«Notice» é o papel pregado na parede ou o aviso dado com antecedência; notícia de jornal é «news», que só existe no plural.\n🇺🇸 notice → 🇧🇷 aviso, comunicado\n🇺🇸 news → 🇧🇷 notícia\nComo verbo, «to notice» é reparar.","v":"ad102e01"},{"idioma":"en","id":"en-u076","tipo":"frase","requer":"en-p076","en":"There's a notice on the door.","pt":"Tem um aviso na porta.","aceitas":["tem um aviso na porta","ha um aviso na porta","tem um aviso pregado na porta","tem um aviso colado na porta","tem um comunicado na porta","tem um cartaz de aviso na porta"],"aceitasEn":["theres a notice on the door","there is a notice on the door"],"distratores":["Tem um recado na porta.","Tem um cadeado na porta.","Tem um adesivo na porta.","Tem um espelho na porta."],"nivel":"B1","tags":["substantivo","falso-amigo","mídia"],"nota":"O aviso fica «on the door», e não «in». Em inglês o que está grudado numa superfície leva «on»: on the wall, on the fridge, on the screen.","v":"81ccd43e"},{"idioma":"en","id":"en-p077","tipo":"palavra","en":"to push","pt":"empurrar","aceitas":["empurrar","dar um empurrao","apertar","pressionar"],"aceitasEn":["to push","push"],"distratores":["puxar","soltar","levantar","arrastar"],"nivel":"A2","tags":["verbo","falso-amigo","cotidiano"],"nota":"A porta que diz PUSH se empurra. «Push» e «puxar» se parecem e dizem o contrário — é o engano mais caro do aeroporto.\n🇺🇸 push → 🇧🇷 empurrar\n🇺🇸 pull → 🇧🇷 puxar","v":"4d545ac6"},{"idioma":"en","id":"en-u077","tipo":"frase","requer":"en-p077","en":"She pushed the door open.","pt":"Ela empurrou a porta.","aceitas":["ela empurrou a porta","empurrou a porta","ela abriu a porta empurrando","ela empurrou a porta e abriu","ela deu um empurrao na porta"],"aceitasEn":["she pushed the door open","she pushed open the door","she pushed the door"],"distratores":["Ela puxou a porta.","Ela trancou a porta.","Ela pintou a porta.","Ela bateu a porta."],"nivel":"A2","tags":["verbo","falso-amigo","cotidiano"],"nota":"«Push something open» junta o empurrão e o resultado numa frase só, e o inglês faz muito isso: push the door open, kick the door open, slam the door shut.","v":"d9973868"},{"idioma":"en","id":"en-p078","tipo":"palavra","en":"terrific","pt":"sensacional","aceitas":["sensacional","otimo","excelente","maravilhoso","fantastico","genial"],"aceitasEn":["terrific"],"distratores":["previsível","exigente","tranquilo","cansativo"],"nivel":"B2","tags":["adjetivo","falso-amigo"],"nota":"«Terrific» hoje é elogio: quer dizer ótimo. O sentido antigo, o de causar terror, sobreviveu em pouca coisa («a terrific storm»), e fora dali quem quer dizer terrível diz «terrible». As duas nasceram do mesmo terror, e o inglês virou uma delas do avesso, como fez com «awesome».\n🇺🇸 terrific → 🇧🇷 sensacional, ótimo\n🇺🇸 terrible → 🇧🇷 terrível","v":"e8dee9c3"},{"idioma":"en","id":"en-u078","tipo":"frase","requer":"en-p078","en":"That's a terrific idea.","pt":"É uma ideia sensacional.","aceitas":["e uma ideia sensacional","e uma ideia otima","e uma otima ideia","que ideia sensacional","e uma ideia excelente","essa ideia e sensacional","e uma ideia genial"],"aceitasEn":["thats a terrific idea","that is a terrific idea","its a terrific idea","what a terrific idea"],"distratores":["É uma ideia terrível.","É uma ideia antiga.","É uma ideia arriscada.","É uma ideia confusa."],"nivel":"B2","tags":["adjetivo","falso-amigo"],"nota":"Elogio de conversa, dito depressa: «That's terrific!» sozinho já é «que ótimo!». Em texto formal fica solto demais — ali se escreve «excellent».","v":"4f4d9b0b"},{"idioma":"en","id":"en-p079","tipo":"palavra","en":"the apology","pt":"a desculpa","aceitas":["a desculpa","desculpa","o pedido de desculpas","as desculpas"],"aceitasEn":["the apology","apology","an apology"],"distratores":["a advertência","a justificativa","a explicação","a homenagem"],"nivel":"B2","tags":["substantivo","falso-amigo","social"],"nota":"«Apology» é o pedido de desculpas, e hoje é só isso. O sentido de defesa sobrevive em título de livro («An Apology for Poetry») e na palavra «apologia», que o inglês guardou à parte; quem quer dizer apologia diz «advocacy» ou «defense».\n🇺🇸 apology → 🇧🇷 desculpa, pedido de desculpas\n🇺🇸 advocacy → 🇧🇷 apologia\nA desculpa esfarrapada, a que serve de pretexto, é «excuse».","v":"d278cb56"},{"idioma":"en","id":"en-u079","tipo":"frase","requer":"en-p079","en":"He owes me an apology.","pt":"Ele me deve uma desculpa.","aceitas":["ele me deve uma desculpa","me deve uma desculpa","ele esta me devendo uma desculpa","ele me deve um pedido de desculpas","ele tem que me pedir desculpa"],"aceitasEn":["he owes me an apology"],"distratores":["Ele me deve uma explicação.","Ele me deve uma resposta.","Ele me deve uma visita.","Ele me deve uma fortuna."],"nivel":"B2","tags":["substantivo","falso-amigo","social"],"nota":"«To owe someone an apology» é a colocação que vale a pena guardar inteira. A desculpa se deve, se aceita («accept an apology») e se pede — mas quem pede usa o verbo: «to apologize».","v":"bcc9456e"},{"idioma":"en","id":"en-p080","tipo":"palavra","en":"the compromise","pt":"o meio-termo","aceitas":["o meio termo","meio termo","a concessao mutua","o acordo com concessoes","o ponto de equilibrio"],"aceitasEn":["the compromise","compromise","a compromise"],"distratores":["o compromisso","a promessa","o desacordo","a teimosia"],"nivel":"C1","tags":["substantivo","falso-amigo","social"],"nota":"«Compromise» é cada lado ceder um pouco para fechar a conta. Compromisso de agenda é «appointment»; compromisso assumido é «commitment».\n🇺🇸 compromise → 🇧🇷 meio-termo, concessão mútua\n🇺🇸 commitment → 🇧🇷 compromisso","v":"77c4f8a4"},{"idioma":"en","id":"en-u080","tipo":"frase","requer":"en-p080","en":"We reached a compromise.","pt":"Chegamos a um meio-termo.","aceitas":["chegamos a um meio termo","a gente chegou a um meio termo","chegamos a um acordo com concessoes","achamos um meio termo","encontramos um meio termo"],"aceitasEn":["we reached a compromise","weve reached a compromise","we have reached a compromise","we came to a compromise"],"distratores":["Chegamos a um impasse.","Chegamos a um veredito.","Chegamos a um limite.","Chegamos a um número."],"nivel":"C1","tags":["substantivo","falso-amigo","social"],"nota":"«Reach a compromise» é o par fixo: o meio-termo se alcança, não se faz. E «to compromise» sozinho, como verbo, muda de assunto: quer dizer comprometer no mau sentido, pôr em risco.","v":"6cf18d9c"},{"idioma":"en","id":"en-p081","tipo":"palavra","en":"fastidious","pt":"meticuloso","aceitas":["meticuloso","minucioso","detalhista","esmerado","criterioso","caprichado no que faz"],"aceitasEn":["fastidious"],"distratores":["fastidioso","apressado","teimoso","distraído"],"nivel":"C1","tags":["adjetivo","falso-amigo"],"nota":"«Fastidious» é quem não deixa passar um detalhe, e quase sempre é elogio. Quem é fastidioso no sentido português — aquele que enche — em inglês é «tedious» ou «annoying».\n🇺🇸 fastidious → 🇧🇷 meticuloso, detalhista\n🇺🇸 tedious → 🇧🇷 fastidioso, enfadonho","v":"c412e6db"},{"idioma":"en","id":"en-u081","tipo":"frase","requer":"en-p081","en":"He's fastidious about his work.","pt":"Ele é meticuloso com o trabalho dele.","aceitas":["ele e meticuloso com o trabalho dele","ele e meticuloso com o trabalho","ele e detalhista com o trabalho dele","ele e minucioso com o trabalho dele","ele e muito caprichado no trabalho"],"aceitasEn":["hes fastidious about his work","he is fastidious about his work"],"distratores":["Ele é orgulhoso com o trabalho dele.","Ele é relaxado com o trabalho dele.","Ele é ansioso com o trabalho dele.","Ele é discreto com o trabalho dele."],"nivel":"C1","tags":["adjetivo","falso-amigo"],"nota":"O adjetivo pede «about»: fastidious about his work, about her appearance, about spelling. E dito de uma pessoa perto da comida vira quase crítica: «a fastidious eater» é o que só come o que gosta.","v":"7db1c539"},{"idioma":"en","id":"en-p082","tipo":"palavra","en":"to struggle","pt":"ter dificuldade","aceitas":["ter dificuldade","penar","batalhar","apanhar para fazer algo","sofrer para conseguir","se esforcar muito","ralar"],"aceitasEn":["to struggle","struggle","to struggle with"],"distratores":["desistir de tudo","relaxar um pouco","reclamar de tudo","hesitar demais"],"nivel":"B2","tags":["verbo","trabalho"],"nota":"«Struggle» é a dificuldade de fazer alguma coisa, e não a briga: «I'm struggling with this exercise» é «estou apanhando neste exercício». Pede «with» na frente do problema e «to» na frente do verbo: struggling to breathe.","v":"be093f3e"},{"idioma":"en","id":"en-u082","tipo":"frase","requer":"en-p082","en":"She struggles with grammar.","pt":"Ela tem dificuldade com gramática.","aceitas":["ela tem dificuldade com gramatica","tem dificuldade com gramatica","ela apanha na gramatica","ela pena com a gramatica","ela tem dificuldade em gramatica","ela sofre com a gramatica","ela tem dificuldade na gramatica"],"aceitasEn":["she struggles with grammar","she is struggling with grammar","shes struggling with grammar"],"distratores":["Ela tem paciência com gramática.","Ela tem facilidade com gramática.","Ela tem implicância com gramática.","Ela tem obsessão com gramática."],"nivel":"B2","tags":["verbo","trabalho","escola"],"nota":"Na escola e no trabalho «struggle» é a palavra neutra para quem não está conseguindo: «a struggling student» não é preguiçoso, é quem está penando. Dizer isso sem ofender é justamente o que ela serve para fazer.","v":"9abb0734"},{"idioma":"en","id":"en-p083","tipo":"palavra","en":"eager","pt":"ansioso","aceitas":["ansioso","animado","louco para","doido para","entusiasmado","avido","empolgado"],"aceitasEn":["eager"],"distratores":["receoso","indeciso","orgulhoso","desconfiado"],"nivel":"B2","tags":["adjetivo","social"],"nota":"«Eager» é a vontade boa de fazer alguma coisa. A ansiedade ruim, a que aperta o peito, é «anxious» — o inglês separa as duas, e o português usa «ansioso» para as duas.\n🇺🇸 eager → 🇧🇷 ansioso no bom sentido, animado\n🇺🇸 anxious → 🇧🇷 ansioso preocupado, aflito\nPede «to» na frente do verbo: eager to learn.","v":"7c7cdf54"},{"idioma":"en","id":"en-u083","tipo":"frase","requer":"en-p083","en":"She's eager to learn.","pt":"Ela está ansiosa para aprender.","aceitas":["ela esta ansiosa para aprender","ela esta animada para aprender","ela esta louca para aprender","ela esta doida para aprender","ela quer muito aprender","ela esta empolgada para aprender","ela esta a fim de aprender"],"aceitasEn":["shes eager to learn","she is eager to learn"],"distratores":["Ela está pronta para aprender.","Ela está nervosa para aprender.","Ela está cansada de aprender.","Ela está insegura para aprender."],"nivel":"B2","tags":["adjetivo","escola"],"nota":"É o elogio que um chefe ou um professor faz de alguém que chegou agora: «she's eager to learn» quer dizer que a pessoa ainda não sabe, mas quer. Dito de um aluno é sempre bom; dito de um adulto experiente soa a inexperiência.","v":"d48377db"},{"idioma":"en","id":"en-p084","tipo":"palavra","en":"the outcome","pt":"o desfecho","aceitas":["o desfecho","desfecho","o resultado","o saldo final","o fim da historia"],"aceitasEn":["the outcome","outcome","an outcome"],"distratores":["o prognóstico","o objetivo","o prazo","o custo"],"nivel":"B2","tags":["substantivo","trabalho"],"nota":"«Outcome» é o que sobrou no fim, depois que tudo aconteceu: de uma eleição, de uma cirurgia, de uma negociação. «Result» serve para o placar e para a prova; «outcome» serve para o processo inteiro, e é a palavra do relatório e da notícia.","v":"64bd8cab"},{"idioma":"en","id":"en-u084","tipo":"frase","requer":"en-p084","en":"Nobody could predict the outcome.","pt":"Ninguém conseguia prever o desfecho.","aceitas":["ninguem conseguia prever o desfecho","ninguem conseguia prever o resultado","ninguem sabia prever o desfecho","ninguem podia prever o desfecho","ninguem conseguia adivinhar o desfecho","ninguem conseguia prever o fim"],"aceitasEn":["nobody could predict the outcome","no one could predict the outcome"],"distratores":["Ninguém conseguia prever o prejuízo.","Ninguém conseguia prever o atraso.","Ninguém conseguia prever o preço.","Ninguém conseguia prever o estrago."],"nivel":"B2","tags":["substantivo","trabalho"],"nota":"«Predict the outcome» é par de jornal e de aposta. Repare que o inglês não põe artigo em «nobody» e já resolve a negação ali: o verbo vem no afirmativo, «could», e não «couldn't».","v":"f0666721"},{"idioma":"en","id":"en-p085","tipo":"palavra","en":"harsh","pt":"duro","aceitas":["duro","severo","aspero","rispido","pesado","rigoroso"],"aceitasEn":["harsh"],"distratores":["injusto","ruidoso","confuso","apressado"],"nivel":"B2","tags":["adjetivo"],"nota":"«Harsh» é o que machuca por ser forte demais, e serve a coisas que em português pedem palavras diferentes: harsh criticism é crítica dura, harsh light é luz forte, harsh winter é inverno rigoroso, harsh soap é sabão que arde. É a força sem delicadeza, em qualquer sentido do corpo.","v":"b13e54f0"},{"idioma":"en","id":"en-u085","tipo":"frase","requer":"en-p085","en":"Don't be so harsh on him.","pt":"Não seja tão duro com ele.","aceitas":["nao seja tao duro com ele","nao seja tao severo com ele","nao pegue tao pesado com ele","nao seja tao rigoroso com ele","pega leve com ele","nao seja tao aspero com ele"],"aceitasEn":["dont be so harsh on him","do not be so harsh on him","dont be so harsh with him"],"distratores":["Não seja tão frio com ele.","Não seja tão irônico com ele.","Não seja tão paciente com ele.","Não seja tão formal com ele."],"nivel":"B2","tags":["adjetivo","social"],"nota":"Aqui a preposição é «on»: ser duro cai em cima da pessoa. «Harsh with» também se ouve, mas «harsh on someone» é a forma que a conversa consagrou — e «be hard on someone» diz a mesma coisa.","v":"79722025"},{"idioma":"en","id":"en-p086","tipo":"palavra","en":"whereas","pt":"ao passo que","aceitas":["ao passo que","enquanto que","enquanto","por outro lado"],"aceitasEn":["whereas"],"distratores":["portanto","desde que","apesar de","a menos que"],"nivel":"B2","tags":["gramática","formal"],"nota":"«Whereas» põe dois fatos lado a lado para mostrar o contraste, e não tem nada de tempo: «He likes tea, whereas she prefers coffee». É palavra de texto escrito — na conversa se diz «but» ou «while». No começo de um contrato ela muda de ofício e vira «considerando que».","v":"0b27aa57"},{"idioma":"en","id":"en-u086","tipo":"frase","requer":"en-p086","en":"She likes tea, whereas he prefers coffee.","pt":"Ela gosta de chá, ao passo que ele prefere café.","aceitas":["ela gosta de cha ao passo que ele prefere cafe","ela gosta de cha enquanto que ele prefere cafe","ela gosta de cha enquanto ele prefere cafe","ela gosta de cha e ele por outro lado prefere cafe","ela gosta de cha mas ele prefere cafe"],"aceitasEn":["she likes tea whereas he prefers coffee"],"distratores":["Ela gosta de chá, por isso ele prefere café.","Ela gosta de chá, embora ele prefira café.","Ela gosta de chá, desde que ele prefira café.","Ela gosta de chá, a não ser que ele prefira café."],"nivel":"B2","tags":["gramática","formal"],"nota":"A vírgula antes de «whereas» é obrigatória, e o que vem depois dela é uma oração inteira, com sujeito e verbo. Este é o uso de comparação — duas pessoas, dois gostos, nenhum juízo sobre qual é melhor.","v":"44692d50"},{"idioma":"en","id":"en-p087","tipo":"palavra","en":"to rely on","pt":"contar com","aceitas":["contar com","depender de","confiar em","se apoiar em"],"aceitasEn":["to rely on","rely on","to rely upon"],"distratores":["desistir de","duvidar de","cuidar de","fugir de"],"nivel":"B2","tags":["verbo","preposição"],"nota":"«Rely on» é contar com alguém ou com alguma coisa para não cair. A preposição é obrigatória: não existe «rely something». E vale conhecer o parente: «reliable» é a pessoa com quem dá para contar, e é o elogio mais comum de carta de recomendação.","v":"79655658"},{"idioma":"en","id":"en-u087","tipo":"frase","requer":"en-p087","en":"You can rely on me.","pt":"Você pode contar comigo.","aceitas":["voce pode contar comigo","pode contar comigo","voce pode confiar em mim","da para contar comigo","voce pode depender de mim"],"aceitasEn":["you can rely on me","you can rely upon me"],"distratores":["Você pode desistir de mim.","Você pode duvidar de mim.","Você pode brigar comigo.","Você pode implicar comigo."],"nivel":"B2","tags":["verbo","preposição","social"],"nota":"Frase de compromisso, dita a um chefe ou a um amigo. O pronome vem depois da preposição, e é por isso que é «on me» e não «on I» — regra sem exceção em inglês.","v":"41b79daa"},{"idioma":"en","id":"en-p088","tipo":"palavra","en":"to skip","pt":"pular","aceitas":["pular","deixar de fazer","passar direto","dispensar","omitir"],"aceitasEn":["to skip","skip"],"distratores":["engolir","adiar","repetir","atrasar"],"nivel":"B2","tags":["verbo","cotidiano"],"nota":"«Skip» é passar por cima de alguma coisa que estava na fila: skip breakfast, skip a chapter, skip class, skip a song. Não é adiar — o que se pula não se faz depois. No inglês de criança ela é pular corda, e é dali que veio a imagem.","v":"0a63e817"},{"idioma":"en","id":"en-u088","tipo":"frase","requer":"en-p088","en":"I skipped breakfast today.","pt":"Pulei o café da manhã hoje.","aceitas":["pulei o cafe da manha hoje","hoje eu pulei o cafe da manha","nao tomei cafe da manha hoje","pulei o cafe hoje","deixei de tomar cafe da manha hoje"],"aceitasEn":["i skipped breakfast today","i skipped breakfast"],"distratores":["Adiei o café da manhã hoje.","Preparei o café da manhã hoje.","Paguei o café da manhã hoje.","Derramei o café da manhã hoje."],"nivel":"B2","tags":["verbo","cotidiano","comida"],"nota":"«Breakfast» não leva artigo aqui: have breakfast, skip breakfast, after breakfast. As três refeições do dia entram assim, secas, quando se fala delas em geral — e o mesmo vale para lunch e dinner.","v":"48698461"},{"idioma":"en","id":"en-p089","tipo":"palavra","en":"blunt","pt":"direto","aceitas":["direto","franco","sem rodeios","seco","direto ao ponto","cru"],"aceitasEn":["blunt"],"distratores":["educado","evasivo","tímido","bajulador"],"nivel":"C1","tags":["adjetivo","social"],"nota":"«Blunt» é dizer a verdade sem embrulhar, e o julgamento vem do tom: pode ser aviso honesto («I'll be blunt with you») ou queixa («don't be so blunt»). A mesma palavra serve à faca sem corte, e a imagem é essa: ponta gasta, que vai direto sem cortar fino.","v":"c76d6f6d"},{"idioma":"en","id":"en-u089","tipo":"frase","requer":"en-p089","en":"Let me be blunt.","pt":"Vou ser direto.","aceitas":["vou ser direto","deixa eu ser direto","vou falar sem rodeios","vou ser franco","deixa eu falar sem rodeios","vou direto ao ponto","deixe me ser franco"],"aceitasEn":["let me be blunt","ill be blunt","let me be blunt with you"],"distratores":["Vou ser breve.","Vou ser discreto.","Vou ser paciente.","Vou ser justo."],"nivel":"C1","tags":["adjetivo","social","formal"],"nota":"É o aviso que vem antes da má notícia, e serve para pedir licença de antemão: quem diz isso sabe que vai magoar e prefere avisar. «Let me be honest» é primo, mas mais macio — «blunt» promete que vai doer.","v":"d5dd76ae"},{"idioma":"en","id":"en-p090","tipo":"palavra","en":"the hassle","pt":"o transtorno","aceitas":["o transtorno","transtorno","a chatice","o trabalho que da","a dor de cabeca","o perrengue"],"aceitasEn":["the hassle","hassle","a hassle"],"distratores":["o descuido","o atraso","o desperdício","o engano"],"nivel":"C1","tags":["substantivo","cotidiano","gíria"],"nota":"«Hassle» é o trabalho chato que uma coisa dá, e não a coisa em si: «renewing the passport is such a hassle». Aparece quase sempre depois de «such a» ou de «too much of a». Como verbo muda de alvo e passa a ser a pessoa: «don't hassle me» é «não me enche».","v":"997ad6db"},{"idioma":"en","id":"en-u090","tipo":"frase","requer":"en-p090","en":"It's not worth the hassle.","pt":"Não vale o transtorno.","aceitas":["nao vale o transtorno","nao compensa o transtorno","nao vale a pena o transtorno","nao vale a dor de cabeca","nao compensa a chatice","nao vale o trabalho que da"],"aceitasEn":["its not worth the hassle","it is not worth the hassle"],"distratores":["Não vale o atraso.","Não vale o risco.","Não vale o dinheiro.","Não vale o prejuízo."],"nivel":"C1","tags":["substantivo","cotidiano","gíria"],"nota":"A frase com que se desiste de alguma coisa que até daria certo, mas dá trabalho demais. «Worth» pede substantivo ou gerúndio depois, nunca infinitivo: worth the hassle, worth trying — e jamais «worth to try».","v":"3166b4d7"},{"idioma":"en","id":"en-p091","tipo":"palavra","en":"to thrive","pt":"prosperar","aceitas":["prosperar","vingar","ir muito bem","florescer","se dar bem","deslanchar"],"aceitasEn":["to thrive","thrive"],"distratores":["sobreviver","resistir","estagnar","definhar"],"nivel":"C1","tags":["verbo","economia"],"nota":"«Thrive» é ir bem muito além do necessário, e vive em par com «survive»: «she doesn't just survive, she thrives». Serve à planta, ao negócio e à pessoa. O passado é regular, «thrived» — a forma antiga «throve» já quase não aparece.","v":"bff0b882"},{"idioma":"en","id":"en-u091","tipo":"frase","requer":"en-p091","en":"Plants thrive in this climate.","pt":"As plantas prosperam neste clima.","aceitas":["as plantas prosperam neste clima","as plantas vao muito bem neste clima","as plantas se dao bem neste clima","as plantas florescem neste clima","as plantas vingam neste clima","planta prospera neste clima"],"aceitasEn":["plants thrive in this climate"],"distratores":["As plantas murcham neste clima.","As plantas apodrecem neste clima.","As plantas resistem neste clima.","As plantas brotam neste clima."],"nivel":"C1","tags":["verbo","economia"],"nota":"«Plants» entra sem artigo porque se fala de plantas em geral, e o inglês corta o artigo nesses casos. E repare na preposição: quem prospera prospera «in» um ambiente — in this climate, in chaos, in a small team.","v":"1856b419"},{"idioma":"en","id":"en-p092","tipo":"palavra","en":"to enforce","pt":"fazer cumprir","aceitas":["fazer cumprir","impor","aplicar a lei","fazer valer","exigir o cumprimento"],"aceitasEn":["to enforce","enforce"],"distratores":["deixar passar","interpretar mal","fazer vista grossa","denunciar o abuso"],"nivel":"C1","tags":["verbo","jurídico"],"nota":"«Enforce» é o lado de quem faz a regra pegar: a polícia, o fiscal, o síndico. É por isso que a polícia americana se chama «law enforcement». Não confunda com «to force», que é forçar alguém — o objeto de «enforce» é sempre a regra, nunca a pessoa.","v":"a1f41421"},{"idioma":"en","id":"en-u092","tipo":"frase","requer":"en-p092","en":"The rule is never enforced.","pt":"A regra nunca é cumprida.","aceitas":["a regra nunca e cumprida","a regra nunca e feita valer","ninguem faz a regra valer","essa regra nunca pega","a regra nunca e aplicada","a regra nunca e exigida"],"aceitasEn":["the rule is never enforced","that rule is never enforced"],"distratores":["A regra nunca é lida.","A regra nunca é escrita.","A regra nunca é discutida.","A regra nunca é votada."],"nivel":"C1","tags":["verbo","jurídico","gramática"],"nota":"A passiva é onde «enforce» mais aparece, porque quase sempre interessa a regra e não quem deveria fazê-la valer. O português troca o ponto de vista para dar conta: o inglês diz que ninguém faz cumprir, e o português diz que ninguém cumpre.","v":"b4b04319"},{"idioma":"en","id":"en-p093","tipo":"palavra","en":"to acknowledge","pt":"reconhecer","aceitas":["reconhecer","admitir","dar-se por ciente","acusar o recebimento","confirmar o recebimento"],"aceitasEn":["to acknowledge","acknowledge"],"distratores":["ignorar","desmentir","elogiar","questionar"],"nivel":"C1","tags":["verbo","formal"],"nota":"«Acknowledge» é dizer em voz alta que se viu, que se recebeu ou que é verdade — e por isso vale para três coisas bem diferentes: admitir um erro, confirmar o recebimento de um e-mail e cumprimentar alguém com a cabeça ao entrar. «Recognize», que parece o par óbvio, é reconhecer de vista.","v":"fedafe60"},{"idioma":"en","id":"en-u093","tipo":"frase","requer":"en-p093","en":"He acknowledged his mistake.","pt":"Ele admitiu o erro dele.","aceitas":["ele admitiu o erro dele","ele reconheceu o erro dele","ele admitiu o erro","ele reconheceu o proprio erro","ele assumiu o erro dele","ele admitiu que errou"],"aceitasEn":["he acknowledged his mistake","he acknowledged the mistake"],"distratores":["Ele escondeu o erro dele.","Ele repetiu o erro dele.","Ele corrigiu o erro dele.","Ele explicou o erro dele."],"nivel":"C1","tags":["verbo","formal","social"],"nota":"É o verbo do pedido de desculpas público, de empresa e de político: admitir sem fazer drama. Num texto acadêmico ele muda de casa e vira gratidão — «acknowledgements» são os agradecimentos do começo do livro.","v":"9e94d101"},{"idioma":"en","id":"en-p094","tipo":"palavra","en":"to overhear","pt":"ouvir sem querer","aceitas":["ouvir sem querer","escutar sem querer","ouvir por acaso","pegar um pedaco da conversa","ouvir de passagem"],"aceitasEn":["to overhear","overhear"],"distratores":["escutar escondido","ouvir de novo","entender mal","ouvir com atenção"],"nivel":"C1","tags":["verbo","social"],"nota":"«Overhear» é ouvir o que não era para você, e sem querer. Quem se esconde para escutar de propósito faz outra coisa: «eavesdrop». O «over-» é o de por cima, como quem passa e pega um pedaço no ar. Irregular, e copia «hear»: overhear, overheard, overheard.","v":"0b649471"},{"idioma":"en","id":"en-u094","tipo":"frase","requer":"en-p094","en":"I overheard your conversation.","pt":"Ouvi sua conversa sem querer.","aceitas":["ouvi sua conversa sem querer","ouvi a conversa de voces sem querer","acabei ouvindo sua conversa","ouvi sem querer o que voces falavam","escutei sua conversa sem querer","ouvi sua conversa por acaso"],"aceitasEn":["i overheard your conversation"],"distratores":["Gravei sua conversa sem querer.","Interrompi sua conversa sem querer.","Contei sua conversa sem querer.","Apaguei sua conversa sem querer."],"nivel":"C1","tags":["verbo","social"],"nota":"A frase serve para confessar e pedir licença ao mesmo tempo, e o «sem querer» está dentro do verbo inglês — por isso a tradução portuguesa precisa de duas palavras a mais para dizer o mesmo.","v":"d9fc3e3d"},{"idioma":"en","id":"en-p095","tipo":"palavra","en":"to entail","pt":"implicar","aceitas":["implicar","acarretar","envolver","exigir","trazer junto"],"aceitasEn":["to entail","entail"],"distratores":["evitar","simplificar","adiar","permitir"],"nivel":"C2","tags":["verbo","formal"],"nota":"«Entail» é o que uma decisão traz junto, querendo ou não: «the job entails a lot of travel». É palavra de relatório e de contrato, e na conversa se diz «involve» ou «mean». No direito inglês antigo ela era outra coisa — prender uma herança a uma linhagem —, e dali veio a ideia de amarrar uma coisa à outra.","v":"cb6cdd2f"},{"idioma":"en","id":"en-u095","tipo":"frase","requer":"en-p095","en":"What does the job entail?","pt":"O que o trabalho envolve?","aceitas":["o que o trabalho envolve","o que o trabalho implica","o que o trabalho acarreta","em que consiste o trabalho","o que a vaga envolve","o que esse trabalho envolve"],"aceitasEn":["what does the job entail"],"distratores":["O que o trabalho rende?","O que o trabalho custa?","O que o trabalho paga?","O que o trabalho ensina?"],"nivel":"C2","tags":["verbo","formal","trabalho"],"nota":"É a pergunta de entrevista de emprego, do lado de quem se candidata. O «does» leva a pergunta inteira nas costas, e por isso o verbo volta ao infinitivo: «entail», e não «entails».","v":"af034030"},{"idioma":"en","id":"en-p096","tipo":"palavra","en":"to outweigh","pt":"pesar mais que","aceitas":["pesar mais que","superar","compensar","valer mais que","contar mais que"],"aceitasEn":["to outweigh","outweigh"],"distratores":["equilibrar os dois","medir os riscos","anular o efeito","adiar a escolha"],"nivel":"C2","tags":["verbo","formal"],"nota":"«Outweigh» é o prato da balança que desce: uma coisa pesa mais do que a outra e por isso decide. O prefixo «out-» faz o mesmo com meio dicionário, sempre no sentido de superar: outnumber, outlast, outrun, outsmart.","v":"155b4a56"},{"idioma":"en","id":"en-u096","tipo":"frase","requer":"en-p096","en":"The benefits outweigh the risks.","pt":"Os benefícios compensam os riscos.","aceitas":["os beneficios compensam os riscos","os beneficios pesam mais que os riscos","os beneficios superam os riscos","os beneficios valem mais que os riscos","o ganho compensa o risco"],"aceitasEn":["the benefits outweigh the risks","the benefit outweighs the risk"],"distratores":["Os benefícios escondem os riscos.","Os benefícios explicam os riscos.","Os benefícios criam os riscos.","Os benefícios dobram os riscos."],"nivel":"C2","tags":["verbo","formal","saúde"],"nota":"A frase inteira é um bloco, e é assim que se fecha uma discussão em inglês formal: num parecer médico, num relatório, numa reunião. O contrário é igualmente fixo — «the risks outweigh the benefits».","v":"3f0ddbe0"},{"idioma":"en","id":"en-f117","tipo":"frase","en":"Little did I know.","pt":"Mal sabia eu.","aceitas":["mal sabia eu","eu mal sabia","mal eu sabia","eu nao fazia ideia","mal sabia eu na epoca"],"aceitasEn":["little did i know","little did i know then"],"distratores":["Eu não queria saber.","Eu fiquei sabendo depois.","Eu já desconfiava.","Eu soube na hora."],"nivel":"C2","tags":["gramática","formal"],"nota":"Inversão: depois de uma palavra negativa ou restritiva no começo da frase, o inglês troca a ordem do sujeito e do auxiliar, como numa pergunta. E a frase sempre olha para trás — quem fala já sabe o que vinha por aí. O mesmo molde vale para «never have I seen» e «rarely does he call».","v":"603b21e7"},{"idioma":"en","id":"en-f118","tipo":"frase","en":"It was John who paid, not me.","pt":"Foi o João que pagou, não eu.","aceitas":["foi o joao que pagou nao eu","foi joao quem pagou nao eu","quem pagou foi o joao nao eu","foi o joao que pagou e nao eu","foi o joao quem pagou nao eu"],"aceitasEn":["it was john who paid not me","it was john that paid not me","it was john who paid not i"],"distratores":["O João pagou por mim.","Foi o João quem me pagou.","O João e eu pagamos.","O João pagou, e eu também."],"nivel":"C1","tags":["gramática"],"nota":"A frase clivada existe para pôr o holofote numa parte só: «It was John who...» avisa que o assunto é quem pagou, e não o que foi pago. O português faz igual, com «foi… que». E repare no fecho: a conversa diz «not me», e não «not I», mesmo que a gramática de cartório prefira a segunda.","v":"d8b4e2ab"},{"idioma":"en","id":"en-f119","tipo":"frase","en":"What I need is a break.","pt":"O que eu preciso é de uma pausa.","aceitas":["o que eu preciso e de uma pausa","o que eu preciso e de um descanso","o que eu preciso e uma pausa","o que eu preciso mesmo e uma folga","o que eu preciso e de uma folga","o que me falta e uma pausa"],"aceitasEn":["what i need is a break","what i need is a break right now"],"distratores":["Preciso saber o que é uma pausa.","O que eu quero é uma pausa.","Não preciso de pausa nenhuma.","O que eu tenho é uma pausa."],"nivel":"B2","tags":["gramática"],"nota":"Esta é a clivada ao contrário: em vez do holofote no sujeito, o holofote vai no que se quer. «What I need is…» é a maneira mais comum de reclamar sem levantar a voz. Repare que o verbo fica no singular, «is», mesmo quando o que vem depois é plural: «what I need is two more days».","v":"8e719fc2"},{"idioma":"en","id":"en-f120","tipo":"frase","en":"He is said to be very rich.","pt":"Dizem que ele é muito rico.","aceitas":["dizem que ele e muito rico","dizem que ele e riquissimo","diz-se que ele e muito rico","consta que ele e muito rico","falam que ele e muito rico"],"aceitasEn":["he is said to be very rich","hes said to be very rich"],"distratores":["Ele disse que é muito rico.","Ele foi chamado de rico.","Mandaram dizer que ele é rico.","Ele diz ser muito rico."],"nivel":"C1","tags":["gramática","formal","mídia"],"nota":"O inglês de jornal usa esta passiva para contar o que se diz sem assinar embaixo: «he is said to», «she is believed to», «they are thought to». O sujeito da frase é a pessoa de quem se fala, e não quem fala — e é justamente isso que o português desfaz, jogando tudo para o «dizem que».","v":"a41d9509"},{"idioma":"en","id":"en-f121","tipo":"frase","en":"The book is worth reading.","pt":"Vale a pena ler o livro.","aceitas":["vale a pena ler o livro","o livro vale a pena","vale a pena ler esse livro","o livro merece ser lido","compensa ler o livro"],"aceitasEn":["the book is worth reading","the book is worth a read"],"distratores":["Vale a pena comprar o livro.","Vale a pena reler o livro.","Não vale a pena ler o livro.","Vale a pena escrever o livro."],"nivel":"B2","tags":["gramática","cultura"],"nota":"Depois de «worth» só entra substantivo ou verbo em -ing: worth reading, worth the trip, worth every penny. «Worth to read» não existe. E repare que o objeto some no fim: o livro já é o sujeito da frase, então não se diz «worth reading it».","v":"5990072f"},{"idioma":"en","id":"en-f122","tipo":"frase","en":"I can't help laughing.","pt":"Não consigo segurar o riso.","aceitas":["nao consigo segurar o riso","nao consigo nao rir","nao da para nao rir","nao tem como nao rir","nao consigo evitar rir","nao consigo deixar de rir","nao consigo conter o riso"],"aceitasEn":["i cant help laughing","i can not help laughing","i cant help but laugh"],"distratores":["Não consigo ajudar rindo.","Não posso ajudar a rir.","Não dá para rir agora.","Não quero rir disso."],"nivel":"B2","tags":["gramática","expressão"],"nota":"«Can't help» não tem nada de ajuda: quer dizer não conseguir evitar. Depois dele o verbo vem sempre em -ing — can't help laughing, can't help wondering. A outra forma, «can't help but laugh», diz o mesmo com infinitivo, e é a única exceção.","v":"5f3e3789"},{"idioma":"en","id":"en-f123","tipo":"frase","en":"She denied taking the money.","pt":"Ela negou ter pegado o dinheiro.","aceitas":["ela negou ter pegado o dinheiro","ela negou que pegou o dinheiro","ela negou ter pego o dinheiro","ela disse que nao pegou o dinheiro","ela negou ter levado o dinheiro"],"aceitasEn":["she denied taking the money","she denied having taken the money"],"distratores":["Ela negou dar o dinheiro.","Ela se recusou a pegar o dinheiro.","Ela negou o dinheiro a ele.","Ela pediu para pegar o dinheiro."],"nivel":"B2","tags":["gramática","jurídico"],"nota":"«Deny» é negar que se fez; «refuse» é recusar-se a fazer. Depois de «deny» vem o verbo em -ing, e a frase olha para trás: «she denied taking». Depois de «refuse» vem infinitivo, e olha para a frente: «she refused to take».","v":"0727a14f"},{"idioma":"en","id":"en-f124","tipo":"frase","en":"I remember locking the door.","pt":"Lembro de ter trancado a porta.","aceitas":["lembro de ter trancado a porta","eu lembro de ter trancado a porta","me lembro de ter trancado a porta","lembro que tranquei a porta","lembro de ter fechado a porta a chave"],"aceitasEn":["i remember locking the door","i remember having locked the door"],"distratores":["Lembrei de trancar a porta.","Preciso lembrar de trancar a porta.","Esqueci de trancar a porta.","Lembro de ter destrancado a porta."],"nivel":"C1","tags":["gramática","casa"],"nota":"A diferença está em qual coisa veio primeiro. «Remember locking» é lembrar de uma coisa que já foi feita; «remember to lock» é lembrar de fazer o que ainda falta. O mesmo vale para «forget», «stop» e «try» — e é o par que mais vira uma frase inteira do avesso.","v":"32687592"},{"idioma":"en","id":"en-f125","tipo":"frase","en":"He stopped to smoke.","pt":"Ele parou para fumar.","aceitas":["ele parou para fumar","parou para fumar","ele parou pra fumar","ele deu uma parada para fumar","ele parou um pouco para fumar"],"aceitasEn":["he stopped to smoke"],"distratores":["Ele parou de fumar.","Ele deixou de fumar.","Ele começou a fumar.","Ele evitou fumar."],"nivel":"C1","tags":["gramática","saúde"],"nota":"Um infinitivo e um gerúndio separam duas notícias muito diferentes: «he stopped to smoke» é que ele parou o que fazia e acendeu um cigarro; «he stopped smoking» é que largou o vício. O que vem depois do verbo é que decide, e aqui a diferença é de vida ou morte.","v":"5393e7f2"},{"idioma":"en","id":"en-f126","tipo":"frase","en":"There's no point in arguing.","pt":"Não adianta discutir.","aceitas":["nao adianta discutir","nao vale a pena discutir","nao tem sentido discutir","nao tem por que discutir","de nada adianta discutir","discutir nao adianta"],"aceitasEn":["theres no point in arguing","there is no point in arguing","theres no point arguing"],"distratores":["Não há ponto de discussão.","Não existe esse argumento.","Não é hora de discutir.","Não sei discutir com ele."],"nivel":"B2","tags":["gramática","expressão"],"nota":"«Point» aqui é propósito, e não ponto: «what's the point?» é «para quê?». A preposição «in» some na conversa — «there's no point arguing» se ouve tanto quanto —, mas o verbo fica sempre em -ing.","v":"a1d89c45"},{"idioma":"en","id":"en-f127","tipo":"frase","en":"I'd better leave now.","pt":"É melhor eu ir embora agora.","aceitas":["e melhor eu ir embora agora","melhor eu ir embora","e melhor eu sair agora","acho melhor eu ir agora","e bom eu ir embora agora","e melhor eu ir indo"],"aceitasEn":["id better leave now","i had better leave now","i better leave now","id better go now"],"distratores":["Eu iria embora agora.","Eu gostaria de ir embora agora.","Eu poderia ir embora agora.","Eu prefiro ir embora agora."],"nivel":"B1","tags":["gramática"],"nota":"«I'd better» não é o condicional de «good»: é «had better», e traz um aviso escondido — se eu não for agora, alguma coisa ruim acontece. «I'd rather», que se parece com ele, é só preferência. Depois de «better» o verbo vem seco, sem «to».","v":"408141e5"},{"idioma":"en","id":"en-f128","tipo":"frase","en":"It's been ages since we spoke.","pt":"Faz séculos que a gente não se fala.","aceitas":["faz seculos que a gente nao se fala","faz seculos que nao nos falamos","faz tempao que a gente nao se fala","ha seculos que nao nos falamos","faz um seculo que a gente nao se fala","faz seculos que a gente nao conversa"],"aceitasEn":["its been ages since we spoke","it has been ages since we spoke","its been ages since we last spoke"],"distratores":["A gente se falou séculos atrás.","Faz séculos que a gente se fala.","A gente vai se falar daqui a um século.","Faz séculos que a gente se conhece."],"nivel":"B2","tags":["gramática","social"],"nota":"A armadilha é a negação: o inglês diz «since we spoke», no afirmativo, e o português precisa do «não» — «que a gente não se fala». O tempo também troca de lugar: o inglês põe o present perfect no começo, e o português resolve tudo com «faz».","v":"7e0a861a"},{"idioma":"en","id":"en-f129","tipo":"frase","en":"He made me do it.","pt":"Ele me obrigou a fazer isso.","aceitas":["ele me obrigou a fazer isso","me obrigou a fazer isso","ele me fez fazer isso","ele me forcou a fazer isso","ele que me obrigou a fazer isso"],"aceitasEn":["he made me do it"],"distratores":["Ele fez isso por mim.","Ele me deixou fazer isso.","Ele me ajudou a fazer isso.","Ele mandou fazer isso."],"nivel":"B1","tags":["gramática"],"nota":"Depois de «make» e de «let» o verbo vem sem «to»: make me do, let me go. Só «force» e «get» pedem a preposição — «he forced me to do it», «he got me to do it». E na passiva a regra se inverte: ali é «I was made to do it».","v":"7dad0e32"},{"idioma":"en","id":"en-f130","tipo":"frase","en":"Much as I like him, I disagree.","pt":"Por mais que eu goste dele, discordo.","aceitas":["por mais que eu goste dele discordo","por mais que eu goste dele eu discordo","embora eu goste dele discordo","por mais que eu goste dele nao concordo","gosto muito dele mas discordo"],"aceitasEn":["much as i like him i disagree"],"distratores":["Por mais que eu goste dele, concordo.","Quanto mais gosto dele, mais discordo.","Gosto muito dele, por isso discordo.","Como gosto dele, não discordo."],"nivel":"C2","tags":["gramática","formal"],"nota":"«Much as» no começo da frase é concessivo, e quer dizer «por mais que». O «much» engana: não é quantidade, é ressalva. O molde é de texto escrito e tem irmãos — «try as I might», «hard as it is», «young as she was».","v":"2f0e309c"},{"idioma":"en","id":"en-f131","tipo":"frase","en":"Don't let me down.","pt":"Não me decepcione.","aceitas":["nao me decepcione","nao me decepciona","nao va me decepcionar","nao me deixe na mao","nao me desaponte","nao me deixa na mao"],"aceitasEn":["dont let me down","do not let me down"],"distratores":["Não me derrube.","Não me deixe descer.","Não me atrapalhe agora.","Não me apresse."],"nivel":"B2","tags":["phrasal verb","social"],"nota":"«Let down» é faltar com o que o outro esperava de você — o que desce ali é a confiança. O substantivo existe e é comum: «what a letdown» é «que decepção». Repare que o objeto entra no meio, sempre: «let me down», e nunca «let down me».","v":"4fc94006"},{"idioma":"en","id":"en-f132","tipo":"frase","en":"She came up with a plan.","pt":"Ela bolou um plano.","aceitas":["ela bolou um plano","ela inventou um plano","ela arquitetou um plano","ela criou um plano","ela apareceu com um plano","ela teve a ideia de um plano"],"aceitasEn":["she came up with a plan"],"distratores":["Ela subiu com um plano.","Ela veio junto com o plano.","Ela concordou com o plano.","Ela desistiu do plano."],"nivel":"B2","tags":["phrasal verb","trabalho"],"nota":"«Come up with» é fazer a ideia aparecer, e a imagem é a de puxar alguma coisa do fundo para a superfície. São três palavras que andam sempre coladas, e o objeto entra só no fim: came up with a plan, with an excuse, with the money.","v":"ae1cc1c0"},{"idioma":"en","id":"en-f133","tipo":"frase","en":"We're running low on gas.","pt":"A gasolina está acabando.","aceitas":["a gasolina esta acabando","estamos ficando sem gasolina","a gasolina ta acabando","o combustivel esta acabando","estamos quase sem gasolina","ta acabando a gasolina"],"aceitasEn":["were running low on gas","we are running low on gas","were running low on fuel"],"distratores":["Estamos correndo com pouca gasolina.","A gasolina está saindo barata.","O carro está gastando muita gasolina.","Ainda temos gasolina de sobra."],"nivel":"B2","tags":["phrasal verb","viagem"],"nota":"«Run low on» é o estoque chegando ao fim, e serve a tudo que se mede: running low on gas, on time, on patience. «Run out of» é o passo seguinte — ali acabou de vez. E «gas» é a palavra americana: no inglês britânico é «petrol».","v":"42362820"},{"idioma":"en","id":"en-f134","tipo":"frase","en":"Stop showing off.","pt":"Para de se exibir.","aceitas":["para de se exibir","pare de se exibir","para de aparecer","chega de se exibir","para de se mostrar","para de dar uma de bom"],"aceitasEn":["stop showing off","stop showing off now"],"distratores":["Para de apagar a luz.","Para de reclamar tanto.","Para de rir de mim.","Para de mostrar tudo."],"nivel":"B2","tags":["phrasal verb","social"],"nota":"«Show off» é mostrar o que se tem para que os outros vejam, e sempre com um tom de crítica. O substantivo vira a pessoa: «he's such a show-off» é «ele é o maior exibido». Pode vir sozinho ou com objeto — «showing off his new car».","v":"142c8124"},{"idioma":"en","id":"en-f135","tipo":"frase","en":"They fell out over money.","pt":"Eles brigaram por causa de dinheiro.","aceitas":["eles brigaram por causa de dinheiro","brigaram por dinheiro","eles se desentenderam por dinheiro","eles romperam por causa de dinheiro","eles se estranharam por causa de dinheiro","eles brigaram por dinheiro"],"aceitasEn":["they fell out over money","they fell out about money"],"distratores":["Eles caíram por causa de dinheiro.","Eles saíram por causa de dinheiro.","Eles ficaram sem dinheiro nenhum.","Eles se juntaram por causa de dinheiro."],"nivel":"C1","tags":["phrasal verb","social"],"nota":"«Fall out» é a amizade que se rompe, e não a queda. A preposição do motivo é «over»: fell out over money, over politics. Serve a amigos, irmãos e sócios, e traz junto a informação de que eram próximos antes.","v":"507d9dab"},{"idioma":"en","id":"en-f136","tipo":"frase","en":"He got away with it.","pt":"Ele se safou.","aceitas":["ele se safou","se safou","ele escapou impune","ele saiu ileso dessa","ele nao pagou por isso","ele escapou sem punicao"],"aceitasEn":["he got away with it"],"distratores":["Ele fugiu de lá.","Ele levou a culpa.","Ele pagou caro por isso.","Ele confessou tudo."],"nivel":"B2","tags":["phrasal verb","jurídico"],"nota":"«Get away with» é escapar sem pagar o preço, e vem quase sempre com gosto de injustiça: «he got away with murder» é o exagero de sempre. As três palavras são coladas, e o «with» aponta para o que a pessoa fez.","v":"76038411"},{"idioma":"en","id":"en-f137","tipo":"frase","en":"I'll make up for it.","pt":"Eu vou compensar.","aceitas":["eu vou compensar","vou compensar","eu compenso depois","vou compensar isso","vou me redimir","vou fazer por merecer"],"aceitasEn":["ill make up for it","i will make up for it"],"distratores":["Eu vou inventar isso.","Eu vou me maquiar para isso.","Eu vou decidir isso.","Eu vou esquecer isso."],"nivel":"B2","tags":["phrasal verb","social"],"nota":"«Make up for» é compensar uma falha: o tempo perdido, a ausência, o erro. Sem o «for» a frase muda de assunto duas vezes — «make up» sozinho é inventar uma história, e «make up with someone» é fazer as pazes.","v":"e2ab3971"},{"idioma":"en","id":"en-f138","tipo":"frase","en":"Cut it out.","pt":"Para com isso.","aceitas":["para com isso","pare com isso","chega disso","corta essa","larga disso","para ja com isso"],"aceitasEn":["cut it out","cut that out"],"distratores":["Recorte isso aí.","Recorte isso agora.","Tire isso daqui.","Deixe isso de lado."],"nivel":"B1","tags":["phrasal verb","gíria"],"nota":"«Cut it out» é «para com isso», dito com impaciência mas sem grosseria — de mãe para filho, de amigo para amigo. O objeto fica obrigatoriamente no meio: nunca «cut out it». Tem um primo mais seco, «knock it off», e um mais educado, «please stop».","v":"a1ddfab4"},{"idioma":"en","id":"en-f139","tipo":"frase","en":"I can't put my finger on it.","pt":"Não consigo dizer o que é.","aceitas":["nao consigo dizer o que e","nao consigo identificar o que e","tem alguma coisa que nao consigo explicar","nao sei dizer o que e","nao consigo apontar o que e","nao consigo botar o dedo no que e"],"aceitasEn":["i cant put my finger on it","i can not put my finger on it"],"distratores":["Não consigo encostar o dedo nisso.","Não consigo pôr o dedo em cima.","Não consigo tirar isso da cabeça.","Não quero me meter nisso."],"nivel":"C1","tags":["expressão"],"nota":"A imagem é a de quem passa o dedo procurando o defeito e não acha: sabe que tem alguma coisa errada, mas não sabe dizer o quê. Vem quase sempre no negativo e depois de «there's something»: «there's something odd about him, but I can't put my finger on it».","v":"1b68db2e"},{"idioma":"en","id":"en-f140","tipo":"frase","en":"It's a blessing in disguise.","pt":"Há males que vêm para bem.","aceitas":["ha males que vem para bem","tem males que vem para bem","e uma bencao disfarcada","no fim das contas foi bom","foi um bem disfarcado"],"aceitasEn":["its a blessing in disguise","it is a blessing in disguise"],"distratores":["Há bens que vêm para mal.","Há males que nunca passam.","Há problemas que não têm solução.","Há sortes que não duram nada."],"nivel":"B2","tags":["expressão","provérbio"],"nota":"«Disguise» é disfarce: a sorte veio vestida de azar e ninguém reconheceu na hora. Diz-se só depois, quando a história já terminou bem — nunca enquanto o problema ainda está de pé.","v":"10180efd"},{"idioma":"en","id":"en-f141","tipo":"frase","en":"Don't count your chickens.","pt":"Não conte com o ovo dentro da galinha.","aceitas":["nao conte com o ovo dentro da galinha","nao conte com o ovo na barriga da galinha","nao cante vitoria antes da hora","nao comemore antes do tempo","nao conte com isso ainda"],"aceitasEn":["dont count your chickens","do not count your chickens","dont count your chickens before they hatch"],"distratores":["Não conte as suas galinhas ainda.","Não venda as galinhas antes da hora.","Não confie em quem promete demais.","Não faça planos com mais ninguém."],"nivel":"C1","tags":["expressão","provérbio"],"nota":"A frase inteira é «don't count your chickens before they hatch» — não conte os pintinhos antes de o ovo chocar —, e na conversa se corta no meio, porque todo mundo sabe o resto. É o aviso para quem já está comemorando cedo demais.","v":"1189d563"},{"idioma":"en","id":"en-f142","tipo":"frase","en":"He's on the fence.","pt":"Ele está em cima do muro.","aceitas":["ele esta em cima do muro","ele ta em cima do muro","ele esta indeciso","ele nao se decide","ele nao toma partido","ele esta na duvida ainda"],"aceitasEn":["hes on the fence","he is on the fence","hes still on the fence"],"distratores":["Ele está sentado na cerca.","Ele está apoiado no muro.","Ele está do nosso lado.","Ele já escolheu um lado."],"nivel":"C1","tags":["expressão","política"],"nota":"A cerca divide dois terrenos, e quem está em cima dela ainda não desceu para nenhum — é a mesma imagem do muro em português. Vive em conversa de eleição e de decisão de grupo, e o verbo que tira a pessoa dali é «get off the fence».","v":"2e25962d"},{"idioma":"en","id":"en-f143","tipo":"frase","en":"It's water under the bridge.","pt":"Isso é água passada.","aceitas":["isso e agua passada","e agua passada","isso ja passou","isso ficou para tras","aguas passadas nao movem moinho"],"aceitasEn":["its water under the bridge","it is water under the bridge"],"distratores":["Tem água embaixo da ponte.","A água passa sob a ponte.","Isso ainda vai dar problema.","Isso está fora do nosso alcance."],"nivel":"C1","tags":["expressão","social"],"nota":"A água que já passou debaixo da ponte não volta, e por isso não vale mais discutir. Diz-se para encerrar uma briga velha, e não para contar o que aconteceu: é um pedido de paz, não um relato.","v":"0a4a42eb"},{"idioma":"en","id":"en-f144","tipo":"frase","en":"She's head over heels for him.","pt":"Ela está caidinha por ele.","aceitas":["ela esta caidinha por ele","ela esta apaixonadissima por ele","ela e louca por ele","ela esta perdidamente apaixonada por ele","ela esta gamada nele","ela ta caidinha por ele"],"aceitasEn":["shes head over heels for him","she is head over heels for him","shes head over heels in love with him"],"distratores":["Ela levou um tombo por causa dele.","Ela está de cabeça para baixo por ele.","Ela está furiosa com ele.","Ela está com pena dele."],"nivel":"C1","tags":["expressão","social"],"nota":"A imagem é a do tombo: a cabeça passando por cima dos calcanhares, o corpo rolando sem controle. A ordem natural seria a inversa, «heels over head», e o inglês trocou as duas faz séculos e nunca mais desfez.","v":"234a0ec4"},{"idioma":"en","id":"en-f145","tipo":"frase","en":"Let's call it a day.","pt":"Vamos parar por hoje.","aceitas":["vamos parar por hoje","vamos encerrar por hoje","por hoje chega","vamos ficar por aqui hoje","chega por hoje","vamos dar o dia por encerrado"],"aceitasEn":["lets call it a day","let us call it a day"],"distratores":["Vamos chamar isso de dia.","Vamos marcar um dia.","Vamos começar cedo amanhã.","Vamos aproveitar o dia."],"nivel":"B2","tags":["expressão","trabalho"],"nota":"É o que se diz para encerrar o expediente quando o trabalho não acabou mas o dia sim. «Call it» aqui é declarar: dar a coisa por terminada. Quem para de vez, na carreira ou numa relação, usa o mesmo molde — «call it quits».","v":"7f914534"},{"idioma":"en","id":"en-f146","tipo":"frase","en":"It slipped my mind.","pt":"Me fugiu da cabeça.","aceitas":["me fugiu da cabeca","fugiu da minha cabeca","me escapou","esqueci completamente","passou batido","nao me lembrei na hora"],"aceitasEn":["it slipped my mind","it completely slipped my mind"],"distratores":["Escorregou na minha mente.","Deslizou pela minha cabeça.","Mudei de ideia na hora.","Perdi a linha de raciocínio."],"nivel":"B2","tags":["expressão","cotidiano"],"nota":"A imagem é a de alguma coisa que escorrega e cai da memória sem ninguém perceber. É a desculpa educada por ter esquecido um compromisso — mais leve que «I forgot», porque tira a culpa de quem fala e põe na lembrança que escapou.","v":"0948ce8d"},{"idioma":"en","id":"en-f147","tipo":"frase","en":"He's burning the candle at both ends.","pt":"Ele está se matando de trabalhar.","aceitas":["ele esta se matando de trabalhar","ele ta se matando de trabalhar","ele esta se acabando de tanto trabalhar","ele nao para nem para dormir","ele esta se esgotando de tanto trabalhar","ele nao para de trabalhar nunca"],"aceitasEn":["hes burning the candle at both ends","he is burning the candle at both ends"],"distratores":["Ele está queimando a vela pelos dois lados.","Ele acendeu a vela nas duas pontas.","Ele está gastando tudo o que tem.","Ele está jogando dos dois lados."],"nivel":"C2","tags":["expressão","trabalho","saúde"],"nota":"A vela acesa nas duas pontas acaba na metade do tempo: é quem dorme tarde e acorda cedo, todo dia. A expressão é do século XVIII, quando vela era dinheiro e o desperdício era literal. Diz-se sempre com preocupação, nunca como elogio.","v":"ba80015d"},{"idioma":"en","id":"en-f148","tipo":"frase","en":"Take it with a grain of salt.","pt":"Leve isso com um pé atrás.","aceitas":["leve isso com um pe atras","ouca isso com reservas","nao leve isso muito a serio","desconfie um pouco disso","pegue isso com desconfianca","leve isso com ressalvas"],"aceitasEn":["take it with a grain of salt","take that with a grain of salt","take it with a pinch of salt"],"distratores":["Coma isso com um pouco de sal.","Ponha um grão de sal nisso.","Aceite isso de bom grado.","Guarde isso para depois."],"nivel":"C1","tags":["expressão"],"nota":"O grão de sal vem de uma receita romana de antídoto contra veneno, que se tomava com um grão de sal para descer melhor: engole-se a história, mas com uma precaução junto. O inglês britânico diz «pinch of salt», uma pitada em vez de um grão.","v":"3a3d6c32"},{"idioma":"en","id":"en-f149","tipo":"frase","en":"It's not my cup of tea.","pt":"Não é muito a minha praia.","aceitas":["nao e muito a minha praia","nao e a minha praia","nao faz o meu genero","nao e bem o meu estilo","nao e a minha cara","nao curto muito isso"],"aceitasEn":["its not my cup of tea","it is not my cup of tea"],"distratores":["Não é a minha xícara de chá.","Não é o chá que eu tomo.","Não é a minha vez ainda.","Não é o meu problema."],"nivel":"B2","tags":["expressão","cultura"],"nota":"Inglês até o osso: o chá de cada um é o gosto de cada um. Serve para recusar sem ofender — um filme, um esporte, um tipo de música — e vem quase sempre no negativo. No afirmativo soa forçado.","v":"2156a5e9"},{"idioma":"en","id":"en-f150","tipo":"frase","en":"Let's agree to disagree.","pt":"Cada um fica com a sua.","aceitas":["cada um fica com a sua","vamos ficar cada um com a sua","cada um com a sua opiniao","vamos concordar em discordar","fica cada um com a sua"],"aceitasEn":["lets agree to disagree","let us agree to disagree"],"distratores":["Vamos concordar para não discutir.","Melhor evitar o assunto por ora.","Deixa isso para mais adiante.","Que outro decida por nós."],"nivel":"C1","tags":["expressão","social"],"nota":"É a frase que encerra uma discussão sem vencedor e sem ninguém ceder: combinamos que não vamos combinar. Soa educada em inglês, e é a saída mais limpa de um assunto que não vai a lugar nenhum.","v":"049d6f4d"},{"idioma":"en","id":"en-f151","tipo":"frase","en":"He threw me under the bus.","pt":"Ele me jogou aos leões.","aceitas":["ele me jogou aos leoes","ele me entregou para se salvar","ele me queimou com o chefe","ele me sacrificou para se salvar","ele me jogou na fogueira","ele me dedurou para se safar"],"aceitasEn":["he threw me under the bus"],"distratores":["Ele me empurrou para debaixo do ônibus.","Ele me deixou esperando o ônibus.","Ele me atrapalhou de propósito.","Ele me culpou por engano."],"nivel":"C1","tags":["expressão","trabalho"],"nota":"Sacrificar alguém para se salvar, quase sempre na frente do chefe ou da imprensa. É expressão americana e recente, dos anos oitenta, e hoje é a que mais se ouve em escritório para descrever uma traição de reunião.","v":"7a65f8b1"},{"idioma":"en","id":"en-f152","tipo":"frase","en":"That's par for the course.","pt":"É o de sempre.","aceitas":["e o de sempre","e o normal por aqui","isso ja era de se esperar","e assim mesmo","nao e novidade nenhuma","era de esperar"],"aceitasEn":["thats par for the course","that is par for the course"],"distratores":["É a média do percurso.","É o par que falta no curso.","É o melhor que se pode fazer.","É uma exceção bem rara."],"nivel":"C2","tags":["expressão"],"nota":"Vem do golfe: o «par» é o número de tacadas previsto para cada buraco, e o «course» é o campo. Fazer o par é fazer o esperado — nem bom nem ruim. Diz-se com resignação, sobre um problema que já se sabia que ia aparecer.","v":"495118c2"},{"idioma":"en","id":"en-v067","tipo":"frase","en":"She drank the whole bottle.","pt":"Ela bebeu a garrafa inteira.","aceitas":["ela bebeu a garrafa inteira","bebeu a garrafa inteira","ela tomou a garrafa inteira","ela bebeu a garrafa toda","ela virou a garrafa inteira"],"aceitasEn":["she drank the whole bottle"],"distratores":["Ela bebe a garrafa inteira.","Ela beberá a garrafa inteira.","Ela beberia a garrafa inteira.","Ela tinha bebido a garrafa inteira."],"formasEn":{"She drinks the whole bottle":"presente","She will drink the whole bottle":"futuro","She would drink the whole bottle":"condicional","She had drunk the whole bottle":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","drink","pretérito"],"nota":"drink, drank, drunk — três vogais em fila, e a do meio é a do passado. O particípio ganhou vida própria como adjetivo: «he's drunk» é «ele está bêbado», e ali não há tempo verbal nenhum.","v":"4864fda4"},{"idioma":"en","id":"en-v068","tipo":"frase","en":"I woke up at six.","pt":"Acordei às seis.","aceitas":["acordei as seis","eu acordei as seis","acordei as seis horas","eu acordei as seis da manha"],"aceitasEn":["i woke up at six","i woke at six"],"distratores":["Acordo às seis.","Acordarei às seis.","Acordaria às seis.","Tinha acordado às seis."],"formasEn":{"I wake up at six":"presente","I will wake up at six":"futuro","I would wake up at six":"condicional","I had woken up at six":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","wake","pretérito","cotidiano"],"nota":"wake, woke, woken. Na prática quase sempre vem com «up»: «wake up» é acordar, e «wake someone up» é acordar alguém. Sem o «up» a palavra soa literária — e «a wake», como substantivo, é o velório.","v":"fb8ce5f8"},{"idioma":"en","id":"en-v069","tipo":"frase","en":"The wind blew all night.","pt":"O vento soprou a noite toda.","aceitas":["o vento soprou a noite toda","o vento soprou a noite inteira","ventou a noite toda","o vento bateu a noite toda"],"aceitasEn":["the wind blew all night"],"distratores":["O vento sopra a noite toda.","O vento soprará a noite toda.","O vento sopraria a noite toda.","O vento tinha soprado a noite toda."],"formasEn":{"The wind blows all night":"presente","The wind will blow all night":"futuro","The wind would blow all night":"condicional","The wind had blown all night":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","blow","pretérito"],"nota":"blow, blew, blown. Repare que «blew» e «blue» soam exatamente igual, e é confusão de escrita das mais comuns. O verbo serve ao vento, à vela de aniversário e ao nariz — «blow your nose» é assoar.","v":"e629b3b3"},{"idioma":"en","id":"en-v070","tipo":"frase","en":"The sun rose at six.","pt":"O sol nasceu às seis.","aceitas":["o sol nasceu as seis","o sol saiu as seis","o sol apareceu as seis","o sol nasceu as seis horas","o sol nasceu as seis da manha"],"aceitasEn":["the sun rose at six"],"distratores":["O sol nasce às seis.","O sol nascerá às seis.","O sol nasceria às seis.","O sol tinha nascido às seis."],"formasEn":{"The sun rises at six":"presente","The sun will rise at six":"futuro","The sun would rise at six":"condicional","The sun had risen at six":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","rise","pretérito"],"nota":"rise, rose, risen — e o verbo não leva objeto: a coisa sobe sozinha. Quem levanta outra coisa usa «raise», que é regular: raise, raised, raised. É o par que mais se troca em inglês escrito.","v":"aae908a0"},{"idioma":"en","id":"en-v071","tipo":"frase","en":"They shot the movie in Brazil.","pt":"Gravaram o filme no Brasil.","aceitas":["gravaram o filme no brasil","eles gravaram o filme no brasil","rodaram o filme no brasil","filmaram no brasil","o filme foi gravado no brasil"],"aceitasEn":["they shot the movie in brazil","they shot the film in brazil"],"distratores":["Gravam o filme no Brasil.","Gravarão o filme no Brasil.","Gravariam o filme no Brasil.","Tinham gravado o filme no Brasil."],"formasEn":{"They shoot the movie in Brazil":"presente","They will shoot the movie in Brazil":"futuro","They would shoot the movie in Brazil":"condicional","They had shot the movie in Brazil":"mais-que-perfeito"},"nivel":"B2","tags":["conjugação","irregular","shoot","pretérito","cultura"],"nota":"shoot, shot, shot — passado e particípio iguais. No cinema e na fotografia o verbo é este: shoot a movie, shoot a photo, e «a shoot» é a sessão de fotos. Fora dali ele é atirar, e o contexto separa os dois sozinho.","v":"c1c52f54"},{"idioma":"en","id":"en-v072","tipo":"frase","en":"The clock struck midnight.","pt":"O relógio bateu meia-noite.","aceitas":["o relogio bateu meia noite","o relogio deu meia noite","bateu meia noite no relogio","o relogio bateu as doze"],"aceitasEn":["the clock struck midnight"],"distratores":["O relógio bate meia-noite.","O relógio baterá meia-noite.","O relógio bateria meia-noite.","O relógio tinha batido meia-noite."],"formasEn":{"The clock strikes midnight":"presente","The clock will strike midnight":"futuro","The clock would strike midnight":"condicional","The clock had struck midnight":"mais-que-perfeito"},"nivel":"B2","tags":["conjugação","irregular","strike","pretérito"],"nota":"strike, struck, struck. O verbo é o de bater com força — o relógio, o raio, a ideia que «strikes you». Como substantivo ele muda de mundo e vira a greve, e o verbo também serve a ela: «the workers went on strike».","v":"08b26023"},{"idioma":"en","id":"en-v073","tipo":"frase","en":"He swore he was innocent.","pt":"Ele jurou que era inocente.","aceitas":["ele jurou que era inocente","jurou que era inocente","ele jurou ser inocente","ele jurou que estava inocente"],"aceitasEn":["he swore he was innocent","he swore that he was innocent"],"distratores":["Ele jura que é inocente.","Ele jurará que é inocente.","Ele juraria que era inocente.","Ele tinha jurado que era inocente."],"formasEn":{"He swears he is innocent":"presente","He will swear he is innocent":"futuro","He would swear he was innocent":"condicional","He had sworn he was innocent":"mais-que-perfeito"},"nivel":"B2","tags":["conjugação","irregular","swear","pretérito","jurídico"],"nota":"swear, swore, sworn. O verbo tem dois ofícios bem distantes: jurar no tribunal e xingar na rua. Quem decide é a preposição — «he swore at me» é «ele me xingou»; sem o «at», é juramento.","v":"a6dd8b3d"},{"idioma":"en","id":"en-v074","tipo":"frase","en":"They dug a hole.","pt":"Cavaram um buraco.","aceitas":["cavaram um buraco","eles cavaram um buraco","abriram um buraco","fizeram um buraco cavando"],"aceitasEn":["they dug a hole"],"distratores":["Cavam um buraco.","Cavarão um buraco.","Cavariam um buraco.","Tinham cavado um buraco."],"formasEn":{"They dig a hole":"presente","They will dig a hole":"futuro","They would dig a hole":"condicional","They had dug a hole":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","dig","pretérito"],"nota":"dig, dug, dug — a vogal muda uma vez só e fica. Na gíria americana o verbo virou gosto: «I dig it» é «eu curto», sobrevivente dos anos sessenta que ainda se ouve.","v":"36fb3680"},{"idioma":"en","id":"en-v075","tipo":"frase","en":"She fed the baby.","pt":"Ela alimentou o bebê.","aceitas":["ela alimentou o bebe","alimentou o bebe","ela deu de comer ao bebe","ela deu comida ao bebe","ela deu de comer para o bebe"],"aceitasEn":["she fed the baby"],"distratores":["Ela alimenta o bebê.","Ela alimentará o bebê.","Ela alimentaria o bebê.","Ela tinha alimentado o bebê."],"formasEn":{"She feeds the baby":"presente","She will feed the baby":"futuro","She would feed the baby":"condicional","She had fed the baby":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","feed","pretérito","família"],"nota":"feed, fed, fed — o «ee» encurta e vira «e», no mesmo molde de «meet/met» e «lead/led». O substantivo que veio dele já mora em português: o «feed» das redes sociais é o que alimenta a tela.","v":"290b5cf4"},{"idioma":"en","id":"en-v076","tipo":"frase","en":"He sought advice.","pt":"Ele buscou conselho.","aceitas":["ele buscou conselho","buscou conselho","ele procurou conselho","ele foi atras de conselho","ele pediu conselho"],"aceitasEn":["he sought advice"],"distratores":["Ele busca conselho.","Ele buscará conselho.","Ele buscaria conselho.","Ele tinha buscado conselho."],"formasEn":{"He seeks advice":"presente","He will seek advice":"futuro","He would seek advice":"condicional","He had sought advice":"mais-que-perfeito"},"nivel":"C1","tags":["conjugação","irregular","seek","pretérito","formal"],"nota":"seek, sought, sought — e a grafia «ought» aparece igual em bought, brought e thought, sempre com o mesmo som. É verbo de registro alto: na conversa se diz «look for». E «advice» não tem plural: nunca «advices».","v":"61e9983d"},{"idioma":"en","id":"en-v077","tipo":"frase","en":"The sun shone all day.","pt":"O sol brilhou o dia todo.","aceitas":["o sol brilhou o dia todo","o sol brilhou o dia inteiro","fez sol o dia todo","o sol brilhou durante todo o dia"],"aceitasEn":["the sun shone all day","the sun shined all day"],"distratores":["O sol brilha o dia todo.","O sol brilhará o dia todo.","O sol brilharia o dia todo.","O sol tinha brilhado o dia todo."],"formasEn":{"The sun shines all day":"presente","The sun will shine all day":"futuro","The sun would shine all day":"condicional","The sun had shone all day":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","shine","pretérito"],"nota":"shine, shone, shone — com um detalhe raro: quando o verbo leva objeto, no sentido de lustrar, ele fica regular. «The sun shone» e «he shined his shoes» convivem, e é o sentido que decide qual forma entra.","v":"100b5e51"},{"idioma":"en","id":"en-v078","tipo":"frase","en":"The boat sank quickly.","pt":"O barco afundou rápido.","aceitas":["o barco afundou rapido","o barco afundou depressa","o barco afundou rapidamente","o barco foi a pique rapido"],"aceitasEn":["the boat sank quickly"],"distratores":["O barco afunda rápido.","O barco afundará rápido.","O barco afundaria rápido.","O barco tinha afundado rápido."],"formasEn":{"The boat sinks quickly":"presente","The boat will sink quickly":"futuro","The boat would sink quickly":"condicional","The boat had sunk quickly":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","sink","pretérito","viagem"],"nota":"sink, sank, sunk — o mesmo desenho de drink e de sing. O substantivo, curiosamente, é a pia da cozinha: o lugar por onde a água desce. E «we're sunk» virou gíria de derrota: «estamos perdidos».","v":"6d89cd03"},{"idioma":"en","id":"en-v079","tipo":"frase","en":"The label stuck to the box.","pt":"A etiqueta grudou na caixa.","aceitas":["a etiqueta grudou na caixa","a etiqueta colou na caixa","a etiqueta ficou grudada na caixa","a etiqueta pegou na caixa"],"aceitasEn":["the label stuck to the box"],"distratores":["A etiqueta gruda na caixa.","A etiqueta grudará na caixa.","A etiqueta grudaria na caixa.","A etiqueta tinha grudado na caixa."],"formasEn":{"The label sticks to the box":"presente","The label will stick to the box":"futuro","The label would stick to the box":"condicional","The label had stuck to the box":"mais-que-perfeito"},"nivel":"B2","tags":["conjugação","irregular","stick","pretérito","objetos"],"nota":"stick, stuck, stuck. O particípio ganhou vida de adjetivo: «I'm stuck» é «estou travado», no trânsito, no elevador ou no exercício. E «a stick» é a vara — o verbo nasceu de espetar, e só depois virou colar.","v":"fe5a2bb4"},{"idioma":"en","id":"en-v080","tipo":"frase","en":"She swept the floor.","pt":"Ela varreu o chão.","aceitas":["ela varreu o chao","varreu o chao","ela deu uma varrida no chao","ela varreu o piso"],"aceitasEn":["she swept the floor"],"distratores":["Ela varre o chão.","Ela varrerá o chão.","Ela varreria o chão.","Ela tinha varrido o chão."],"formasEn":{"She sweeps the floor":"presente","She will sweep the floor":"futuro","She would sweep the floor":"condicional","She had swept the floor":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","sweep","pretérito","casa"],"nota":"sweep, swept, swept — o mesmo molde de keep/kept e sleep/slept. Em eleição e em campeonato o verbo vira vitória larga: «they swept the election» é «ganharam de lavada».","v":"a8400ca3"},{"idioma":"en","id":"en-v081","tipo":"frase","en":"The wheel spun for a while.","pt":"A roda girou um tempo.","aceitas":["a roda girou um tempo","a roda girou um tempinho","a roda rodou um tempo","a roda ficou girando um tempo"],"aceitasEn":["the wheel spun for a while"],"distratores":["A roda gira um tempo.","A roda girará um tempo.","A roda giraria um tempo.","A roda tinha girado um tempo."],"formasEn":{"The wheel spins for a while":"presente","The wheel will spin for a while":"futuro","The wheel would spin for a while":"condicional","The wheel had spun for a while":"mais-que-perfeito"},"nivel":"B2","tags":["conjugação","irregular","spin","pretérito","objetos"],"nota":"spin, spun, spun — a vogal do meio sumiu do passado e nunca mais voltou. O substantivo virou palavra de política: «spin» é o giro que se dá num fato para ele soar melhor, e quem faz isso é o «spin doctor».","v":"857cbb82"},{"idioma":"en","id":"en-v082","tipo":"frase","en":"He withdrew the money.","pt":"Ele sacou o dinheiro.","aceitas":["ele sacou o dinheiro","sacou o dinheiro","ele retirou o dinheiro","ele tirou o dinheiro do banco"],"aceitasEn":["he withdrew the money"],"distratores":["Ele saca o dinheiro.","Ele sacará o dinheiro.","Ele sacaria o dinheiro.","Ele tinha sacado o dinheiro."],"formasEn":{"He withdraws the money":"presente","He will withdraw the money":"futuro","He would withdraw the money":"condicional","He had withdrawn the money":"mais-que-perfeito"},"nivel":"C1","tags":["conjugação","irregular","withdraw","pretérito","economia"],"nota":"withdraw, withdrew, withdrawn — conjuga como «draw», que está dentro dele. No banco é sacar; numa disputa é desistir («he withdrew from the race»); numa conversa é recuar. O caixa eletrônico escreve «withdrawal» na tela.","v":"528d230d"},{"idioma":"en","id":"en-v083","tipo":"frase","en":"She bent the wire.","pt":"Ela entortou o arame.","aceitas":["ela entortou o arame","entortou o arame","ela dobrou o arame","ela torceu o arame"],"aceitasEn":["she bent the wire"],"distratores":["Ela entorta o arame.","Ela entortará o arame.","Ela entortaria o arame.","Ela tinha entortado o arame."],"formasEn":{"She bends the wire":"presente","She will bend the wire":"futuro","She would bend the wire":"condicional","She had bent the wire":"mais-que-perfeito"},"nivel":"B2","tags":["conjugação","irregular","bend","pretérito","objetos"],"nota":"bend, bent, bent — o mesmo molde de send/sent e spend/spent. «Bend the rules» é dobrar a regra sem quebrar de vez, e é assim que se pede um favor grande em inglês de escritório.","v":"fa581f02"},{"idioma":"en","id":"en-v084","tipo":"frase","en":"He dealt with the problem.","pt":"Ele lidou com o problema.","aceitas":["ele lidou com o problema","lidou com o problema","ele cuidou do problema","ele resolveu o problema","ele deu conta do problema","ele tratou do problema"],"aceitasEn":["he dealt with the problem"],"distratores":["Ele lida com o problema.","Ele lidará com o problema.","Ele lidaria com o problema.","Ele tinha lidado com o problema."],"formasEn":{"He deals with the problem":"presente","He will deal with the problem":"futuro","He would deal with the problem":"condicional","He had dealt with the problem":"mais-que-perfeito"},"nivel":"B2","tags":["conjugação","irregular","deal","pretérito","trabalho"],"nota":"deal, dealt, dealt — e o «ea» do passado soa como o «e» de «bed», e não como o «ea» de «deal». O verbo quase não anda sozinho: «deal with» é lidar, «deal in» é negociar, e «a deal» é o acordo.","v":"a412256b"},{"idioma":"en","id":"en-v085","tipo":"frase","en":"She overcame her fear.","pt":"Ela venceu o medo.","aceitas":["ela venceu o medo","venceu o medo","ela superou o medo","ela venceu o proprio medo","ela superou o proprio medo"],"aceitasEn":["she overcame her fear"],"distratores":["Ela vence o medo.","Ela vencerá o medo.","Ela venceria o medo.","Ela tinha vencido o medo."],"formasEn":{"She overcomes her fear":"presente","She will overcome her fear":"futuro","She would overcome her fear":"condicional","She had overcome her fear":"mais-que-perfeito"},"nivel":"C1","tags":["conjugação","irregular","overcome","pretérito","saúde"],"nota":"overcome, overcame, overcome — o particípio volta a ser igual ao infinitivo, e é justamente aí que se erra. Conjuga como «come», que está dentro dele. Na passiva ele muda de sentido: «overcome by smoke» é dominado pela fumaça.","v":"2bb68f1e"},{"idioma":"en","id":"en-v086","tipo":"frase","en":"I mistook him for his brother.","pt":"Confundi ele com o irmão.","aceitas":["confundi ele com o irmao","eu confundi ele com o irmao","confundi ele com o irmao dele","achei que ele era o irmao","eu o confundi com o irmao"],"aceitasEn":["i mistook him for his brother"],"distratores":["Confundo ele com o irmão.","Confundirei ele com o irmão.","Confundiria ele com o irmão.","Eu tinha confundido ele com o irmão."],"formasEn":{"I mistake him for his brother":"presente","I will mistake him for his brother":"futuro","I would mistake him for his brother":"condicional","I had mistaken him for his brother":"mais-que-perfeito"},"nivel":"C1","tags":["conjugação","irregular","mistake","pretérito","social"],"nota":"mistake, mistook, mistaken — conjuga como «take», que está dentro dele. A preposição é «for», e é ela que arma a frase: «mistake A for B» é tomar um pelo outro. E «mistaken» virou adjetivo: «you're mistaken» é «você está enganado».","v":"4b3a900b"},{"idioma":"en","id":"en-p097","tipo":"palavra","en":"the bread","pt":"o pão","aceitas":["o pao","pao","o paozinho"],"aceitasEn":["the bread","bread","some bread"],"distratores":["o bolo","o queijo","a manteiga","o biscoito"],"nivel":"A1","tags":["substantivo","comida"],"nota":"«Bread» não tem plural e não leva artigo quando é comida em geral: «I bought bread», «do you want some bread?». Para contar, o inglês precisa de uma medida: «a loaf of bread» é um pão inteiro, «a slice» é uma fatia.","v":"858095d3"},{"idioma":"en","id":"en-u097","tipo":"frase","requer":"en-p097","en":"I'd like some bread, please.","pt":"Eu queria pão, por favor.","aceitas":["eu queria pao por favor","queria pao por favor","eu gostaria de pao por favor","eu quero pao por favor","me ve um pao por favor"],"aceitasEn":["id like some bread please","i would like some bread please","id like bread please"],"distratores":["Eu queria bolo, por favor.","Eu queria queijo, por favor.","Eu queria água, por favor.","Eu queria sal, por favor."],"nivel":"A1","tags":["substantivo","comida","social"],"nota":"«I'd like» é o pedido educado; «I want» soa a criança mandando, e num restaurante pega mal. E o «some» aqui não é «algum»: é o jeito de pedir uma quantidade sem dizer qual.","v":"d8f9686b"},{"idioma":"en","id":"en-p098","tipo":"palavra","en":"the key","pt":"a chave","aceitas":["a chave","chave","as chaves"],"aceitasEn":["the key","key","a key"],"distratores":["a porta","a fechadura","a carteira","a moeda"],"nivel":"A1","tags":["substantivo","casa","objetos"],"nota":"«Key» é a chave e é também a tecla do teclado — daí «keyboard». E vale no figurado, como em português: «the key to happiness» é a chave da felicidade.","v":"157ecb8e"},{"idioma":"en","id":"en-u098","tipo":"frase","requer":"en-p098","en":"I can't find my keys.","pt":"Não acho minhas chaves.","aceitas":["nao acho minhas chaves","nao estou achando minhas chaves","nao encontro minhas chaves","cade minhas chaves","nao acho as chaves"],"aceitasEn":["i cant find my keys","i can not find my keys","i cant find my keys anywhere"],"distratores":["Não acho meus óculos.","Não acho minha carteira.","Não acho meu celular.","Não acho meu guarda-chuva."],"nivel":"A1","tags":["substantivo","casa","cotidiano"],"nota":"Em inglês a chave vem quase sempre no plural, «keys», porque se pensa no molho inteiro. E «can't find» é o que se diz no meio do aperto; «I lost them» já é a conclusão, e uma notícia bem pior.","v":"56e5e80f"},{"idioma":"en","id":"en-p099","tipo":"palavra","en":"the egg","pt":"o ovo","aceitas":["o ovo","ovo","os ovos"],"aceitasEn":["the egg","egg","an egg"],"distratores":["o feijão","o queijo","a farinha","o arroz"],"nivel":"A1","tags":["substantivo","comida"],"nota":"«Egg» é contável: one egg, two eggs. O frito é «a fried egg», o cozido é «a boiled egg», e os mexidos são «scrambled eggs», sempre no plural — porque mexer junta mais de um.","v":"52d7031c"},{"idioma":"en","id":"en-u099","tipo":"frase","requer":"en-p099","en":"I eat eggs for breakfast.","pt":"Eu como ovo no café da manhã.","aceitas":["eu como ovo no cafe da manha","como ovo no cafe da manha","eu como ovos no cafe da manha","tomo cafe da manha com ovo","eu como ovo de manha"],"aceitasEn":["i eat eggs for breakfast","i have eggs for breakfast"],"distratores":["Eu como fruta no café da manhã.","Eu como queijo no café da manhã.","Eu como bolo no café da manhã.","Eu como aveia no café da manhã."],"nivel":"A1","tags":["substantivo","comida","cotidiano"],"nota":"A refeição leva «for»: for breakfast, for lunch, for dinner. E repare no número: o português gosta do singular genérico («como ovo»), e o inglês põe no plural («eggs») para falar de comida em geral.","v":"8373f090"},{"idioma":"en","id":"en-p100","tipo":"palavra","en":"the chair","pt":"a cadeira","aceitas":["a cadeira","cadeira","as cadeiras"],"aceitasEn":["the chair","chair","a chair"],"distratores":["a mesa","a escada","a estante","a janela"],"nivel":"A1","tags":["substantivo","casa","objetos"],"nota":"«Chair» é a cadeira de encosto reto; a de braços é «armchair», e a de rodinhas do escritório é «office chair». Em reunião a palavra muda de ofício e vira gente: «the chair» é quem preside.","v":"0ce6603b"},{"idioma":"en","id":"en-u100","tipo":"frase","requer":"en-p100","en":"Pull up a chair.","pt":"Puxe uma cadeira.","aceitas":["puxe uma cadeira","puxa uma cadeira","pega uma cadeira","pegue uma cadeira","chega uma cadeira"],"aceitasEn":["pull up a chair","pull up a chair and sit down"],"distratores":["Puxe uma corda.","Puxe uma gaveta.","Puxe uma alavanca.","Puxe uma cortina."],"nivel":"A1","tags":["substantivo","casa","social"],"nota":"Convite de anfitrião: «pull up a chair» é «chega uma cadeira e senta aqui com a gente». O «up» não tem nada de subir — em inglês ele marca que a coisa foi trazida para perto.","v":"bb87afc8"},{"idioma":"en","id":"en-p101","tipo":"palavra","en":"the milk","pt":"o leite","aceitas":["o leite","leite"],"aceitasEn":["the milk","milk","some milk"],"distratores":["a água","o suco","o vinagre","o mel"],"nivel":"A1","tags":["substantivo","comida"],"nota":"«Milk» não tem plural e não leva artigo quando é a bebida em geral: «I drink milk». Para contar, precisa de medida — «a glass of milk», «a carton of milk». E existe como verbo: «to milk a cow» é ordenhar.","v":"14c939b6"},{"idioma":"en","id":"en-u101","tipo":"frase","requer":"en-p101","en":"There's no milk left.","pt":"Não tem mais leite.","aceitas":["nao tem mais leite","acabou o leite","nao sobrou leite","nao ha mais leite","o leite acabou"],"aceitasEn":["theres no milk left","there is no milk left","we have no milk left"],"distratores":["Não tem mais açúcar.","Não tem mais café.","Não tem mais gelo.","Não tem mais sabão."],"nivel":"A1","tags":["substantivo","comida","casa"],"nota":"«Left» no fim da frase quer dizer «que sobrou»: two days left, no money left, nothing left to say. Não tem nada a ver com esquerda — é o particípio de «leave» no sentido de deixar para trás.","v":"8f6a277a"},{"idioma":"en","id":"en-p102","tipo":"palavra","en":"the tree","pt":"a árvore","aceitas":["a arvore","arvore","as arvores"],"aceitasEn":["the tree","tree","a tree"],"distratores":["a flor","a folha","a grama","a pedra"],"nivel":"A1","tags":["substantivo"],"nota":"«Tree» entra em compostos que não se traduzem palavra por palavra: «family tree» é árvore genealógica e «Christmas tree» é a de Natal. A madeira já é outra palavra, «wood», e a árvore de fruta leva o nome do fruto: apple tree, orange tree.","v":"44ce8234"},{"idioma":"en","id":"en-u102","tipo":"frase","requer":"en-p102","en":"There's a bird in the tree.","pt":"Tem um pássaro na árvore.","aceitas":["tem um passaro na arvore","ha um passaro na arvore","tem um passarinho na arvore","tem um passaro em cima da arvore"],"aceitasEn":["theres a bird in the tree","there is a bird in the tree"],"distratores":["Tem um pássaro na janela.","Tem um pássaro no telhado.","Tem um pássaro na gaiola.","Tem um pássaro no muro."],"nivel":"A1","tags":["substantivo","preposição"],"nota":"O pássaro fica «in the tree», e não «on»: o inglês vê a árvore como um espaço fechado, com galhos em volta. «On» fica para superfície plana — on the table, on the roof.","v":"06cc3f33"},{"idioma":"en","id":"en-p103","tipo":"palavra","en":"the towel","pt":"a toalha","aceitas":["a toalha","toalha","as toalhas"],"aceitasEn":["the towel","towel","a towel"],"distratores":["o lençol","o tapete","a cortina","o cobertor"],"nivel":"A2","tags":["substantivo","casa","objetos"],"nota":"«Towel» é a toalha de banho e a de mão; a de mesa é outra palavra, «tablecloth». E o papel toalha é «paper towel» nos Estados Unidos e «kitchen roll» na Inglaterra.","v":"c686ce5a"},{"idioma":"en","id":"en-u103","tipo":"frase","requer":"en-p103","en":"Can I have a clean towel?","pt":"Pode me dar uma toalha limpa?","aceitas":["pode me dar uma toalha limpa","me da uma toalha limpa","voce pode me dar uma toalha limpa","tem uma toalha limpa","pode trazer uma toalha limpa"],"aceitasEn":["can i have a clean towel","could i have a clean towel","may i have a clean towel"],"distratores":["Pode me dar uma colher limpa?","Pode me dar uma xícara limpa?","Pode me dar uma faca limpa?","Pode me dar uma camisa limpa?"],"nivel":"A2","tags":["substantivo","casa","viagem"],"nota":"«Can I have…?» é como se pede qualquer coisa em inglês — num hotel, num bar, numa loja. Ao pé da letra é «posso ter», o que em português soa estranho, e por isso a frase se decora inteira em vez de se traduzir.","v":"74754690"},{"idioma":"en","id":"en-p104","tipo":"palavra","en":"the bill","pt":"a conta","aceitas":["a conta","conta","a fatura","a cedula","a nota de dinheiro"],"aceitasEn":["the bill","bill","the check"],"distratores":["a moeda","o troco","o recibo","o cardápio"],"nivel":"A2","tags":["substantivo","economia","comida"],"nota":"«Bill» é a conta a pagar: do restaurante, da luz, do telefone. Nos Estados Unidos a do restaurante costuma ser «the check», e lá «a bill» é também a cédula — «a ten-dollar bill». No Congresso a palavra muda outra vez e vira projeto de lei.","v":"05dd6640"},{"idioma":"en","id":"en-u104","tipo":"frase","requer":"en-p104","en":"Can we get the bill, please?","pt":"Pode trazer a conta, por favor?","aceitas":["pode trazer a conta por favor","a conta por favor","pode me ver a conta por favor","traz a conta por favor","da para trazer a conta"],"aceitasEn":["can we get the bill please","could we get the bill please","can we have the bill please","can i get the check please"],"distratores":["Pode trazer o cardápio, por favor?","Pode trazer o troco, por favor?","Pode trazer o recibo, por favor?","Pode trazer o guardanapo, por favor?"],"nivel":"A2","tags":["substantivo","economia","comida"],"nota":"Nos Estados Unidos se pede «the check»; na Inglaterra, «the bill». O «get» aqui é só receber — é o verbo coringa do inglês falado, e ele cobre quase tudo que em português pede um verbo específico.","v":"6a4ca4b4"},{"idioma":"en","id":"en-p105","tipo":"palavra","en":"the tip","pt":"a gorjeta","aceitas":["a gorjeta","gorjeta","a caixinha","a dica","a ponta"],"aceitasEn":["the tip","tip","a tip"],"distratores":["a taxa","a entrada","a multa","a comissão"],"nivel":"A2","tags":["substantivo","economia","viagem"],"nota":"Nos Estados Unidos a gorjeta não é opcional: quinze a vinte por cento no restaurante, e o garçom vive disso. A palavra tem outras duas vidas — «the tip of the iceberg» é a ponta, «a useful tip» é uma dica —, e só o contexto separa as três.","v":"7163aba0"},{"idioma":"en","id":"en-u105","tipo":"frase","requer":"en-p105","en":"I left a tip on the table.","pt":"Deixei a gorjeta na mesa.","aceitas":["deixei a gorjeta na mesa","eu deixei a gorjeta na mesa","deixei uma gorjeta na mesa","deixei a caixinha na mesa"],"aceitasEn":["i left a tip on the table","i left the tip on the table"],"distratores":["Deixei a chave na mesa.","Deixei a carteira na mesa.","Deixei a conta na mesa.","Deixei a bolsa na mesa."],"nivel":"A2","tags":["substantivo","economia","viagem"],"nota":"«Leave a tip» é o par fixo: a gorjeta se deixa, e não se dá. O verbo também existe, e leva a pessoa como objeto direto: «I tipped the waiter twenty dollars».","v":"6fe85853"},{"idioma":"en","id":"en-p106","tipo":"palavra","en":"the bucket","pt":"o balde","aceitas":["o balde","balde"],"aceitasEn":["the bucket","bucket","a bucket"],"distratores":["o copo","o cesto","o tanque","o funil"],"nivel":"A2","tags":["substantivo","casa","objetos"],"nota":"«Bucket» é o balde de alça. Na Espanha ele é «el cubo» e na América «el balde» ou «la cubeta», mas em inglês é uma palavra só. E «to kick the bucket» é bater as botas.","v":"f63b1c21"},{"idioma":"en","id":"en-u106","tipo":"frase","requer":"en-p106","en":"Fill the bucket with water.","pt":"Encha o balde de água.","aceitas":["encha o balde de agua","enche o balde de agua","encha o balde com agua","enche o balde com agua","enche o balde ate em cima"],"aceitasEn":["fill the bucket with water","fill up the bucket with water"],"distratores":["Encha o copo de água.","Encha o tanque de água.","Encha o pote de água.","Encha o barril de água."],"nivel":"A2","tags":["substantivo","casa","cotidiano"],"nota":"«Fill something with something» pede «with», e nunca «of»: fill the glass with water. O «of» só aparece quando a palavra vira medida — «a bucket of water», um balde de água.","v":"2aea3baf"},{"idioma":"en","id":"en-p107","tipo":"palavra","en":"the broom","pt":"a vassoura","aceitas":["a vassoura","vassoura"],"aceitasEn":["the broom","broom","a broom"],"distratores":["a pá","a esponja","a escova","a corda"],"nivel":"A2","tags":["substantivo","casa","objetos"],"nota":"«Broom» é a vassoura de cabo comprido; a escova de mão é «brush». O rodo quase não existe na casa americana, e quando existe chama-se «squeegee». A da bruxa é «broomstick».","v":"1ce00b12"},{"idioma":"en","id":"en-u107","tipo":"frase","requer":"en-p107","en":"Where's the broom?","pt":"Cadê a vassoura?","aceitas":["cade a vassoura","onde esta a vassoura","onde ta a vassoura","onde fica a vassoura","onde foi parar a vassoura"],"aceitasEn":["wheres the broom","where is the broom"],"distratores":["Cadê a esponja?","Cadê a chave?","Cadê a toalha?","Cadê a escada?"],"nivel":"A2","tags":["substantivo","casa","cotidiano"],"nota":"«Where's» é a contração de «where is», e na fala ela é quase obrigatória — «where is the broom», separado, soa a livro. O português tem o «cadê», que faz o mesmo serviço e também não aparece em texto formal.","v":"10cfe6e8"},{"idioma":"en","id":"en-p108","tipo":"palavra","en":"the lid","pt":"a tampa","aceitas":["a tampa","tampa"],"aceitasEn":["the lid","lid","a lid"],"distratores":["a alça","a borda","a rolha","a etiqueta"],"nivel":"A2","tags":["substantivo","casa","objetos"],"nota":"«Lid» é a tampa que se encaixa ou rosqueia: da panela, do pote, da caixa. A da garrafa é «cap». E «eyelid» é a pálpebra — a tampa do olho.","v":"e04ee87f"},{"idioma":"en","id":"en-u108","tipo":"frase","requer":"en-p108","en":"Put the lid back on.","pt":"Põe a tampa de volta.","aceitas":["poe a tampa de volta","ponha a tampa de volta","bota a tampa de volta","coloca a tampa de volta","tampa de novo"],"aceitasEn":["put the lid back on","put the lid on again"],"distratores":["Põe a etiqueta de volta.","Põe a corrente de volta.","Põe a rolha de volta.","Põe a fita de volta."],"nivel":"A2","tags":["substantivo","casa","cotidiano"],"nota":"«Back on» é «de volta no lugar», e as duas partes se separam quando entra um pronome: «put it back on». Sem o «back» a frase seria só «põe a tampa»; com ele, fica dito que a tampa já estava ali antes.","v":"bdd88466"},{"idioma":"en","id":"en-p109","tipo":"palavra","en":"the sheet","pt":"o lençol","aceitas":["o lencol","lencol","os lencois","a folha de papel"],"aceitasEn":["the sheet","sheet","a sheet"],"distratores":["o travesseiro","o colchão","o cobertor","o edredom"],"nivel":"A2","tags":["substantivo","casa","objetos"],"nota":"«Sheet» é o lençol e é também a folha — «a sheet of paper». A palavra é a mesma porque a ideia é a de uma superfície fina e larga, e é daí que sai «spreadsheet», a planilha.","v":"a7ac8f1d"},{"idioma":"en","id":"en-u109","tipo":"frase","requer":"en-p109","en":"The sheets need washing.","pt":"Os lençóis precisam ser lavados.","aceitas":["os lencois precisam ser lavados","os lencois precisam de lavagem","tem que lavar os lencois","precisa lavar os lencois","os lencois estao precisando de uma lavada"],"aceitasEn":["the sheets need washing","the sheets need to be washed"],"distratores":["Os lençóis precisam ser dobrados.","Os lençóis precisam ser trocados.","Os lençóis precisam ser guardados.","Os lençóis precisam ser passados."],"nivel":"A2","tags":["substantivo","casa","gramática"],"nota":"«Need + verbo em -ing» é uma passiva disfarçada: «the sheets need washing» quer dizer que alguém tem de lavá-los. A forma completa, «need to be washed», existe e diz o mesmo — a curta é que é a da conversa.","v":"f2d9762a"},{"idioma":"en","id":"en-p110","tipo":"palavra","en":"the fork","pt":"o garfo","aceitas":["o garfo","garfo","os garfos","a bifurcacao"],"aceitasEn":["the fork","fork","a fork"],"distratores":["a faca","o prato","o guardanapo","a bandeja"],"nivel":"A2","tags":["substantivo","comida","objetos"],"nota":"«Fork» é o garfo e é também a bifurcação da estrada — «a fork in the road» —, e é desse sentido que veio o «fork» dos programadores. O garfo de jardim, o de cavar, é «garden fork».","v":"95bb4f18"},{"idioma":"en","id":"en-u110","tipo":"frase","requer":"en-p110","en":"He dropped his fork.","pt":"Ele deixou o garfo cair.","aceitas":["ele deixou o garfo cair","ele derrubou o garfo","ele deixou cair o garfo","o garfo caiu da mao dele"],"aceitasEn":["he dropped his fork","he dropped the fork"],"distratores":["Ele deixou o copo cair.","Ele deixou o prato cair.","Ele deixou o celular cair.","Ele deixou o guardanapo cair."],"nivel":"A2","tags":["substantivo","comida","cotidiano"],"nota":"«Drop» é deixar cair sem querer, num verbo só — o português precisa de três palavras para o mesmo. E repare no possessivo: o inglês diz «his fork» onde o português diz «o garfo», porque para ele o dono precisa aparecer.","v":"dec38dcd"},{"idioma":"en","id":"en-p111","tipo":"palavra","en":"to guess","pt":"adivinhar","aceitas":["adivinhar","chutar","supor","imaginar","dar um palpite"],"aceitasEn":["to guess","guess"],"distratores":["perguntar","responder","lembrar","duvidar"],"nivel":"A2","tags":["verbo"],"nota":"«Guess» é dar um palpite sem ter certeza, e na conversa ele amolece qualquer afirmação: «I guess so» é «acho que sim». O substantivo existe — «take a guess» é dar um chute — e «guess what!» é «adivinha só!».","v":"023f386e"},{"idioma":"en","id":"en-u111","tipo":"frase","requer":"en-p111","en":"Guess how old I am.","pt":"Adivinha quantos anos eu tenho.","aceitas":["adivinha quantos anos eu tenho","adivinhe quantos anos eu tenho","chuta quantos anos eu tenho","adivinha minha idade","tenta adivinhar quantos anos eu tenho"],"aceitasEn":["guess how old i am","guess my age"],"distratores":["Conta quantos anos eu tenho.","Pergunta quantos anos eu tenho.","Lembra quantos anos eu tenho.","Calcula quantos anos eu tenho."],"nivel":"A2","tags":["verbo","gramática"],"nota":"Depois de «guess» a pergunta perde a inversão: é «how old I am», e não «how old am I». Toda pergunta embutida numa frase maior volta à ordem da afirmativa — «I don't know where he lives», e nunca «where does he live».","v":"64afe363"},{"idioma":"en","id":"en-p112","tipo":"palavra","en":"to spill","pt":"derramar","aceitas":["derramar","entornar","virar","deixar cair o liquido"],"aceitasEn":["to spill","spill"],"distratores":["secar","encher","misturar","ferver"],"nivel":"A2","tags":["verbo","cotidiano"],"nota":"«Spill» é o líquido que escapa do copo por acidente. O passado tem duas formas: «spilled» nos Estados Unidos e «spilt» na Inglaterra. E «spill the beans» é abrir o bico, contar o que era segredo.","v":"2ee76ad6"},{"idioma":"en","id":"en-u112","tipo":"frase","requer":"en-p112","en":"I spilled the coffee.","pt":"Derramei o café.","aceitas":["derramei o cafe","eu derramei o cafe","entornei o cafe","virei o cafe","derramei o cafe todo"],"aceitasEn":["i spilled the coffee","i spilt the coffee"],"distratores":["Esquentei o café.","Coei o café.","Adocei o café.","Provei o café."],"nivel":"A2","tags":["verbo","cotidiano","comida"],"nota":"O inglês tem um provérbio inteiro em cima desta frase: «don't cry over spilt milk», não adianta chorar pelo leite derramado. E repare que quem derrama é o sujeito — o espanhol prefere jogar a culpa no acaso, com «se me derramó».","v":"f6bcc393"},{"idioma":"en","id":"en-p113","tipo":"palavra","en":"the ladder","pt":"a escada de mão","aceitas":["a escada de mao","a escada","escada de mao","a escadinha"],"aceitasEn":["the ladder","ladder","a ladder"],"distratores":["a escada rolante","o andaime de obra","o banco alto","a corda de sisal"],"nivel":"B1","tags":["substantivo","objetos","casa"],"nota":"O inglês separa o que o português junta numa palavra só: «ladder» é a que se carrega e se encosta, «stairs» é a de degraus fixos, e «escalator» é a rolante. E «to climb the career ladder» é subir na carreira.","v":"610246d5"},{"idioma":"en","id":"en-u113","tipo":"frase","requer":"en-p113","en":"Hold the ladder for me.","pt":"Segura a escada para mim.","aceitas":["segura a escada para mim","segure a escada para mim","segura a escada pra mim","segura ai a escada","segura a escada um pouco"],"aceitasEn":["hold the ladder for me","hold the ladder"],"distratores":["Segura a porta para mim.","Segura a bolsa para mim.","Segura a corda para mim.","Segura a caixa para mim."],"nivel":"B1","tags":["substantivo","objetos","social"],"nota":"«Hold something for me» é como se pede ajuda de mão em inglês, e o «for me» vai obrigatoriamente no fim. Sem ele a frase vira ordem seca: «hold the ladder».","v":"e4c5142e"},{"idioma":"en","id":"en-p114","tipo":"palavra","en":"the attic","pt":"o sótão","aceitas":["o sotao","sotao","o forro da casa"],"aceitasEn":["the attic","attic","an attic"],"distratores":["o porão","a garagem","o depósito","o corredor"],"nivel":"B1","tags":["substantivo","casa","falso-amigo"],"nota":"«Attic» é o sótão, o espaço embaixo do telhado. Na casa americana ele tem uma escada que desce do teto e é onde mora o que ninguém usa — daí «attic sale», a venda de tranqueira. O de baixo, o porão, é «basement».","v":"af9a7983"},{"idioma":"en","id":"en-u114","tipo":"frase","requer":"en-p114","en":"The old photos are in the attic.","pt":"As fotos antigas estão no sótão.","aceitas":["as fotos antigas estao no sotao","as fotos velhas estao no sotao","as fotos antigas ficam no sotao","as fotos antigas tao no sotao"],"aceitasEn":["the old photos are in the attic","the old pictures are in the attic"],"distratores":["As fotos antigas estão no porão.","As fotos antigas estão na garagem.","As fotos antigas estão no armário.","As fotos antigas estão na gaveta."],"nivel":"B1","tags":["substantivo","casa","família"],"nota":"O sótão é o lugar das caixas que ninguém abre há dez anos, e em inglês ele virou imagem de memória guardada. Repare no «in»: espaço fechado leva «in», e não «on».","v":"eb10bd3d"},{"idioma":"en","id":"en-p115","tipo":"palavra","en":"the basement","pt":"o porão","aceitas":["o porao","porao","o subsolo"],"aceitasEn":["the basement","basement","a basement"],"distratores":["o sótão","o quintal","o alicerce","o galpão"],"nivel":"B1","tags":["substantivo","casa"],"nota":"«Basement» é o porão, o andar abaixo do nível da rua. Na casa americana ele é cômodo de verdade — lavanderia, sala de TV, oficina —, e não o depósito escuro do imaginário brasileiro. O de cima é «attic».","v":"5fc3af9a"},{"idioma":"en","id":"en-u115","tipo":"frase","requer":"en-p115","en":"The washer is in the basement.","pt":"A máquina de lavar fica no porão.","aceitas":["a maquina de lavar fica no porao","a maquina de lavar esta no porao","a lavadora fica no porao","a maquina de lavar roupa fica no porao"],"aceitasEn":["the washer is in the basement","the washing machine is in the basement"],"distratores":["A máquina de lavar fica na cozinha.","A máquina de lavar fica na varanda.","A máquina de lavar fica no quintal.","A máquina de lavar fica no banheiro."],"nivel":"B1","tags":["substantivo","casa","cotidiano"],"nota":"«Washer» é a máquina de lavar roupa nos Estados Unidos; na Inglaterra é «washing machine», por extenso. O par dela é «dryer», a secadora, e na casa americana típica as duas ficam mesmo lá embaixo.","v":"0f73d2cd"},{"idioma":"en","id":"en-p116","tipo":"palavra","en":"the thread","pt":"a linha","aceitas":["a linha","linha","o fio de costura","a linha de costura"],"aceitasEn":["the thread","thread","a thread"],"distratores":["a agulha","o botão","a tesoura","a fita"],"nivel":"B1","tags":["substantivo","objetos"],"nota":"«Thread» é a linha de costura e é também o fio de uma conversa — daí o «thread» das redes sociais, e «to lose the thread» é perder o fio da meada. O fio elétrico já é outra palavra: «wire».","v":"e17f1663"},{"idioma":"en","id":"en-u116","tipo":"frase","requer":"en-p116","en":"I need a needle and thread.","pt":"Preciso de agulha e linha.","aceitas":["preciso de agulha e linha","eu preciso de agulha e linha","preciso de uma agulha e linha","preciso de linha e agulha"],"aceitasEn":["i need a needle and thread","i need needle and thread"],"distratores":["Preciso de agulha e tesoura.","Preciso de agulha e dedal.","Preciso de agulha e cola.","Preciso de agulha e fita."],"nivel":"B1","tags":["substantivo","objetos","cotidiano"],"nota":"«A needle and thread» anda como bloco, com um artigo só para os dois: o inglês trata o par como uma coisa. E não leva «of» — «a needle of thread» não existe.","v":"64918868"},{"idioma":"en","id":"en-p117","tipo":"palavra","en":"sticky","pt":"grudento","aceitas":["grudento","pegajoso","melado","que gruda"],"aceitasEn":["sticky"],"distratores":["áspero","escorregadio","molhado","oleoso"],"nivel":"B1","tags":["adjetivo","objetos"],"nota":"«Sticky» vem de «stick», colar. Serve ao doce nos dedos, ao calor úmido («a sticky day») e ao problema embaraçoso («a sticky situation»). E o post-it é «a sticky note».","v":"3ef88ff7"},{"idioma":"en","id":"en-u117","tipo":"frase","requer":"en-p117","en":"My hands are sticky.","pt":"Minhas mãos estão grudentas.","aceitas":["minhas maos estao grudentas","minhas maos estao pegajosas","estou com as maos grudentas","minhas maos estao meladas","to com a mao grudenta"],"aceitasEn":["my hands are sticky","my hands are all sticky"],"distratores":["Minhas mãos estão geladas.","Minhas mãos estão ásperas.","Minhas mãos estão molhadas.","Minhas mãos estão inchadas."],"nivel":"B1","tags":["adjetivo","corpo"],"nota":"O inglês diz «my hands are sticky», com possessivo e verbo «to be»; o português gosta mais de «estou com as mãos grudentas», jogando o estado para o verbo. As duas construções existem nas duas línguas, mas cada uma tem a sua preferida.","v":"1f6a545c"},{"idioma":"en","id":"en-p118","tipo":"palavra","en":"to squeeze","pt":"espremer","aceitas":["espremer","apertar","torcer","apertar com forca"],"aceitasEn":["to squeeze","squeeze"],"distratores":["esticar","dobrar","cortar","raspar"],"nivel":"B1","tags":["verbo","cotidiano"],"nota":"«Squeeze» é apertar até sair alguma coisa: o limão, a esponja, a mão de alguém. Rende duas frases muito usadas — «squeeze in» é encaixar mais um na agenda, e «a tight squeeze» é o aperto de quem não cabe.","v":"54f9630f"},{"idioma":"en","id":"en-u118","tipo":"frase","requer":"en-p118","en":"Squeeze the lemon.","pt":"Esprema o limão.","aceitas":["esprema o limao","espreme o limao","aperta o limao","espreme o limao ai","esprema o limao todo"],"aceitasEn":["squeeze the lemon","squeeze the lemon in"],"distratores":["Descasque o limão.","Corte o limão.","Rale o limão.","Lave o limão."],"nivel":"B1","tags":["verbo","comida","cotidiano"],"nota":"O espremedor é «a lemon squeezer», e o suco espremido na hora é «freshly squeezed» — expressão que se lê em caixa de suco no mundo inteiro. O verbo pede objeto direto, sem preposição nenhuma.","v":"bbbaaa2a"},{"idioma":"en","id":"en-f153","tipo":"frase","en":"Were it not for you, I'd have failed.","pt":"Se não fosse por você, eu teria reprovado.","aceitas":["se nao fosse por voce eu teria reprovado","se nao fosse voce eu teria reprovado","sem voce eu teria reprovado","nao fosse voce eu teria reprovado","se nao fosse voce eu tinha reprovado"],"aceitasEn":["were it not for you id have failed","were it not for you i would have failed"],"distratores":["Se fosse por você, eu teria reprovado.","Como não foi por você, eu reprovei.","Por sua causa eu reprovei.","Mesmo com você eu reprovei."],"nivel":"C2","tags":["gramática","formal","escola"],"nota":"«Were it not for» é a inversão de «if it were not for»: o «if» some e o verbo vai para a frente. É o registro mais alto que o inglês tem para agradecer — o dia a dia diz «if it weren't for you». E o verbo fica no plural com sujeito singular: é o subjuntivo antigo, o mesmo de «if I were you».","v":"2a6a2a5a"},{"idioma":"en","id":"en-f154","tipo":"frase","en":"Suffice it to say, it didn't go well.","pt":"Basta dizer que não foi bem.","aceitas":["basta dizer que nao foi bem","basta dizer que nao deu certo","e so dizer que nao foi bem","digamos apenas que nao foi bem","basta saber que nao foi bem"],"aceitasEn":["suffice it to say it didnt go well","suffice it to say it did not go well"],"distratores":["Chega de dizer que não foi bem.","Não basta dizer que não foi bem.","Só dizem que não foi bem.","Dizer isso já não basta."],"nivel":"C2","tags":["gramática","formal"],"nota":"Fórmula congelada: «suffice it to say» é «basta dizer», e o «it» encravado no meio é resto de um subjuntivo que o inglês não usa mais em lugar nenhum. Serve para cortar caminho, e sempre avisa que o detalhe cortado é ruim.","v":"d5c01d0f"},{"idioma":"en","id":"en-f155","tipo":"frase","en":"For all his talent, he never made it.","pt":"Apesar de todo o talento, ele nunca chegou lá.","aceitas":["apesar de todo o talento ele nunca chegou la","com todo o talento dele ele nunca chegou la","por mais talento que tivesse ele nunca chegou la","apesar do talento ele nunca vingou"],"aceitasEn":["for all his talent he never made it"],"distratores":["Por causa do talento, ele nunca chegou lá.","Com todo o talento, ele chegou bem longe.","Só com talento ele chegou lá.","Faltou talento para ele chegar lá."],"nivel":"C2","tags":["gramática","formal"],"nota":"«For all» no começo da frase é concessivo, e quer dizer «apesar de». O «for» engana quem lê depressa, porque ali ele não indica causa nenhuma — indica o contrário. E «to make it» é chegar lá, vencer, sem precisar dizer onde.","v":"087ca916"},{"idioma":"en","id":"en-f156","tipo":"frase","en":"She's nothing if not thorough.","pt":"Ela é meticulosa, isso não se discute.","aceitas":["ela e meticulosa isso nao se discute","ela e meticulosa isso ninguem tira dela","meticulosa ela e sem duvida","ela e tudo menos desleixada","ela e meticulosa como ninguem"],"aceitasEn":["shes nothing if not thorough","she is nothing if not thorough"],"distratores":["Ela não é nada além de meticulosa.","Ela não é meticulosa de jeito nenhum.","Ela é meticulosa, mas nada além disso.","Ela não seria meticulosa se pudesse."],"nivel":"C2","tags":["gramática","formal"],"nota":"«Nothing if not X» é a maneira mais enfática que o inglês tem de dizer que alguém é X: são dois negativos que se anulam e deixam a qualidade de pé. Ao pé da letra daria «nada, se não for X», e é por isso que a fórmula se decora inteira — traduzida palavra por palavra, ela sai ao contrário.","v":"60a02411"},{"idioma":"en","id":"en-f157","tipo":"frase","en":"It's not for me to say.","pt":"Não cabe a mim dizer.","aceitas":["nao cabe a mim dizer","nao sou eu quem deve dizer","quem tem que dizer nao sou eu","nao me compete dizer","nao e a mim que cabe dizer"],"aceitasEn":["its not for me to say","it is not for me to say"],"distratores":["Não é para eu dizer isso.","Isso não foi dito para mim.","Não tenho nada a dizer.","Não quero dizer isso."],"nivel":"C2","tags":["gramática","formal","social"],"nota":"«It's not for me to» é recusar-se a opinar por não ter a autoridade — de um funcionário sobre a decisão do chefe, de um médico sobre a escolha do paciente. O molde serve a qualquer verbo: «it's not for us to judge».","v":"873f5bfe"},{"idioma":"en","id":"en-f158","tipo":"frase","en":"Be that as it may, we have to decide.","pt":"Seja como for, temos que decidir.","aceitas":["seja como for temos que decidir","de qualquer forma temos que decidir","ainda assim temos que decidir","seja como for a gente tem que decidir","mesmo assim temos que decidir"],"aceitasEn":["be that as it may we have to decide"],"distratores":["Já que é assim, temos que decidir.","Se for assim, temos que decidir.","Como não é assim, temos que decidir.","Nesse caso, temos que decidir."],"nivel":"C2","tags":["gramática","formal"],"nota":"Fórmula inteira, de registro alto: concede o ponto do outro e segue em frente assim mesmo. O «be» do começo é subjuntivo antigo, o mesmo de «so be it» e «be it known» — o inglês guardou três ou quatro fósseis desses e não fabrica mais nenhum.","v":"50874ce8"},{"idioma":"en","id":"en-f159","tipo":"frase","en":"He was none the wiser.","pt":"Ele ficou sem entender nada.","aceitas":["ele ficou sem entender nada","ele continuou sem saber de nada","ele nao ficou sabendo de nada","ele saiu de la sem entender nada","ele ficou na mesma"],"aceitasEn":["he was none the wiser"],"distratores":["Ele ficou bem mais sábio.","Ele não era o mais sábio.","Ele ficou um pouco mais esperto.","Ele voltou para casa sabendo tudo."],"nivel":"C2","tags":["gramática","formal"],"nota":"«None the wiser» é «nem um pouco mais sabido», e esse «none the» é um comparativo negativo que só sobrevive nesta família: none the worse, none the better. Serve a duas cenas — quem não entendeu a explicação, e quem nunca descobriu que foi enganado.","v":"062a7c7f"},{"idioma":"en","id":"en-f160","tipo":"frase","en":"That's neither here nor there.","pt":"Isso não vem ao caso.","aceitas":["isso nao vem ao caso","isso nao tem nada a ver","isso e irrelevante","isso nao importa agora","nao e disso que se trata"],"aceitasEn":["thats neither here nor there","that is neither here nor there"],"distratores":["Isso não está nem aqui nem ali.","Isso não fica em lugar nenhum.","Isso está em toda parte.","Isso é indecisão pura."],"nivel":"C2","tags":["expressão","formal"],"nota":"O que não está nem de um lado nem do outro não entra na conta: é o jeito inglês de dizer que o argumento do outro, verdadeiro ou não, não muda nada. Diz-se para cortar uma digressão sem chamar ninguém de errado.","v":"62e0b337"},{"idioma":"en","id":"en-f161","tipo":"frase","en":"Far be it from me to complain.","pt":"Longe de mim reclamar.","aceitas":["longe de mim reclamar","longe de mim ficar reclamando","nao que eu queira reclamar","nem me passaria pela cabeca reclamar","longe de mim vir reclamar"],"aceitasEn":["far be it from me to complain"],"distratores":["Estou longe de reclamar disso.","Isso está longe de ser uma reclamação.","Já reclamei demais disso.","Vim de longe para reclamar."],"nivel":"C2","tags":["expressão","formal"],"nota":"Outro subjuntivo fóssil, com o «be» na frente: «far be it from me» é «longe de mim». E quase sempre é mentira educada — quem abre a frase com ela está prestes a reclamar, e o português faz exatamente a mesma coisa com as mesmas palavras.","v":"0afe20e9"},{"idioma":"en","id":"en-f162","tipo":"frase","en":"He would sooner quit than apologize.","pt":"Ele prefere se demitir a pedir desculpa.","aceitas":["ele prefere se demitir a pedir desculpa","ele prefere pedir demissao a pedir desculpa","antes ele se demite do que pede desculpa","ele largaria o emprego antes de pedir desculpa"],"aceitasEn":["he would sooner quit than apologize","hed sooner quit than apologize"],"distratores":["Ele vai se demitir logo depois de pedir desculpa.","Ele se demitiu antes de pedir desculpa.","Ele pediu desculpa mais cedo do que se demitiu.","Ele se demite assim que pedir desculpa."],"nivel":"C2","tags":["gramática","formal","trabalho"],"nota":"«Would sooner X than Y» não tem nada de tempo: é preferência forte, «prefiro X a Y». O «sooner» aqui é o «antes» do português em «antes morrer que passar por isso». É primo de «would rather», com um grau a mais de teimosia.","v":"a30a88c7"},{"idioma":"en","id":"en-f163","tipo":"frase","en":"By and large, it worked.","pt":"De modo geral, funcionou.","aceitas":["de modo geral funcionou","no geral funcionou","de maneira geral funcionou","na maior parte funcionou","em linhas gerais funcionou"],"aceitasEn":["by and large it worked"],"distratores":["Aos poucos, funcionou.","Por pouco, funcionou.","De longe, foi o que funcionou.","Com folga, funcionou."],"nivel":"C2","tags":["expressão","formal"],"nota":"«By and large» é «de modo geral», e veio da navegação: eram dois jeitos de pegar o vento, e juntos cobriam todas as direções. Hoje só sobrou a ideia do conjunto. Vem sempre no começo da frase, com vírgula.","v":"da9a89f4"},{"idioma":"en","id":"en-f164","tipo":"frase","en":"To say the least, I was surprised.","pt":"Para dizer o mínimo, fiquei surpreso.","aceitas":["para dizer o minimo fiquei surpreso","no minimo fiquei surpreso","fiquei surpreso para dizer o minimo","e pouco dizer que fiquei surpreso","dizer que fiquei surpreso e pouco"],"aceitasEn":["to say the least i was surprised"],"distratores":["Para dizer o máximo, fiquei surpreso.","Sem dizer nada, fiquei surpreso.","Para não dizer nada, fiquei surpreso.","Depois de dizer tudo, fiquei surpreso."],"nivel":"C2","tags":["expressão","formal"],"nota":"«To say the least» vai quase sempre no fim e é ironia educada: quem a usa está dizendo muito menos do que sente. «I was surprised, to say the least» quer dizer que a pessoa ficou passada.","v":"4f2e5131"},{"idioma":"en","id":"en-f165","tipo":"frase","en":"He insisted that she be present.","pt":"Ele insistiu que ela estivesse presente.","aceitas":["ele insistiu que ela estivesse presente","ele fez questao que ela estivesse presente","ele insistiu para que ela estivesse presente","ele exigiu que ela estivesse presente"],"aceitasEn":["he insisted that she be present","he insisted she be present"],"distratores":["Ele insistiu que ela estava presente.","Ele insistiu em estar presente com ela.","Ele reparou que ela estava presente.","Ele avisou que ela estaria presente."],"nivel":"C2","tags":["gramática","formal"],"nota":"Depois de verbos de ordem e de pedido — insist, demand, suggest, require, recommend — o inglês americano usa o infinitivo sem «to»: «that she be», «that he go», «that it stop». É o subjuntivo que sobreviveu, e ele não muda com a pessoa. O britânico prefere «should be».","v":"b4ce01ff"},{"idioma":"en","id":"en-f166","tipo":"frase","en":"Should you need anything, just call.","pt":"Se precisar de alguma coisa, é só ligar.","aceitas":["se precisar de alguma coisa e so ligar","qualquer coisa e so ligar","se precisar de algo e so ligar","caso precise de alguma coisa e so ligar","precisando de alguma coisa e so ligar"],"aceitasEn":["should you need anything just call","should you need anything just call me"],"distratores":["Você deveria ligar se precisar de alguma coisa.","Se for para ligar, precise de alguma coisa.","Deve ligar mesmo sem precisar de nada.","Precisando ou não, é para ligar."],"nivel":"C2","tags":["gramática","formal","social"],"nota":"Inversão outra vez: «should you need» é «if you should need», com o «if» cortado e o auxiliar à frente. É a fórmula do e-mail formal e do hotel, e o «should» ali não é dever nenhum — ele só marca que a hipótese é remota.","v":"30a24c0d"},{"idioma":"en","id":"en-f167","tipo":"frase","en":"I take it you've heard.","pt":"Imagino que você já saiba.","aceitas":["imagino que voce ja saiba","suponho que voce ja saiba","presumo que voce ja saiba","imagino que voce ja tenha ficado sabendo","pelo visto voce ja sabe"],"aceitasEn":["i take it youve heard","i take it you have heard"],"distratores":["Eu levo isso que você ouviu.","Vou aceitar o que você ouviu.","Entendi o que você quis dizer.","Me conta o que aconteceu."],"nivel":"C1","tags":["expressão","social"],"nota":"«I take it» é «pelo que eu entendo», e abre uma pergunta disfarçada de afirmação: quem diz isso quer confirmação sem ter de perguntar. O «take» não tem nada de pegar — é o mesmo de «take it easy», onde ele também só amarra o resto da frase.","v":"5fbf37ab"},{"idioma":"en","id":"en-f168","tipo":"frase","en":"It goes without saying.","pt":"Nem precisa dizer.","aceitas":["nem precisa dizer","isso nem precisa ser dito","e obvio","nao precisa nem falar","isso se subentende"],"aceitasEn":["it goes without saying","that goes without saying"],"distratores":["Isso vai sem avisar.","Ele foi embora sem dizer nada.","Isso não se diz de jeito nenhum.","Ninguém disse isso ainda."],"nivel":"C1","tags":["expressão"],"nota":"A coisa é tão óbvia que anda sozinha, sem precisar ser dita. O francês tem a frase inteira — «ça va sans dire» —, e o inglês copiou dele no século XIX, palavra por palavra.","v":"1d259e20"},{"idioma":"en","id":"en-f169","tipo":"frase","en":"Come to think of it, he was right.","pt":"Agora que eu penso, ele tinha razão.","aceitas":["agora que eu penso ele tinha razao","pensando bem ele tinha razao","agora que voce falou ele tinha razao","refletindo bem ele tinha razao","bem pensado ele tinha razao"],"aceitasEn":["come to think of it he was right"],"distratores":["Venha pensar nisso, ele tinha razão.","Vim pensando nisso, ele tinha razão.","Depois de muito pensar, ele tinha razão.","Antes de pensar, ele tinha razão."],"nivel":"C1","tags":["expressão"],"nota":"«Come to think of it» é o «pensando bem» do português, e marca a ideia que chegou agora, no meio da conversa. O «come» é imperativo só na forma — ninguém está mandando ninguém vir a lugar nenhum.","v":"b8c2969d"},{"idioma":"en","id":"en-f170","tipo":"frase","en":"He's out of his depth.","pt":"Ele não dá conta do recado.","aceitas":["ele nao da conta do recado","ele nao da conta","isso e grande demais para ele","ele esta perdido nesse assunto","ele nao tem cacife para isso"],"aceitasEn":["hes out of his depth","he is out of his depth"],"distratores":["Ele está fora da piscina.","Ele não alcança o fundo.","Ele é raso demais.","Ele saiu por cima."],"nivel":"C1","tags":["expressão","trabalho"],"nota":"A imagem é a de quem entrou na parte funda da piscina e não toca mais o chão. Diz-se de quem assumiu tarefa grande demais, e é crítica com pena junto: não acusa de má-fé, só de não dar conta.","v":"86d10e7c"},{"idioma":"en","id":"en-f171","tipo":"frase","en":"Let's touch base next week.","pt":"Vamos nos falar semana que vem.","aceitas":["vamos nos falar semana que vem","vamos conversar semana que vem","a gente se fala semana que vem","vamos alinhar semana que vem","vamos trocar uma ideia semana que vem"],"aceitasEn":["lets touch base next week","lets touch base again next week"],"distratores":["Vamos tocar na base semana que vem.","Vamos visitar a base semana que vem.","Vamos decidir tudo semana que vem.","Vamos começar do zero semana que vem."],"nivel":"C1","tags":["expressão","trabalho"],"nota":"Vem do beisebol: o corredor tem de encostar em cada base para a corrida valer. No escritório virou «dar um alô para ver como está», sem pauta e sem decisão — e é das expressões que mais aparecem em e-mail de trabalho americano.","v":"f6c4b12b"},{"idioma":"en","id":"en-f172","tipo":"frase","en":"I'll take a rain check.","pt":"Fica para a próxima.","aceitas":["fica para a proxima","hoje nao mas fica para a proxima","vamos deixar para outra vez","fica para outro dia","deixa para a proxima"],"aceitasEn":["ill take a rain check","i will take a rain check","can i take a rain check"],"distratores":["Vou ver como fica o tempo.","Vou pegar o guarda-chuva.","Deixa eu pensar e te aviso.","Não conta comigo mais."],"nivel":"C1","tags":["expressão","social"],"nota":"O «rain check» era o bilhete que o estádio americano dava quando a chuva adiava o jogo: valia para a partida remarcada. Recusar um convite com ele é dizer «hoje não, mas guarde o convite» — recusa educada que não fecha a porta.","v":"5c2da5e8"},{"idioma":"en","id":"en-f173","tipo":"frase","en":"She rubbed me the wrong way.","pt":"Não fui com a cara dela.","aceitas":["nao fui com a cara dela","ela nao me desceu bem","ela me deu uma ma impressao","ela me irritou de cara","ela nao me caiu bem"],"aceitasEn":["she rubbed me the wrong way"],"distratores":["Ela me esfregou do lado errado.","Ela passou a mão em mim errado.","Ela me enganou direitinho.","Ela me tratou muito bem."],"nivel":"C1","tags":["expressão","social"],"nota":"A imagem é a de passar a mão no gato contra o pelo. Diz-se da antipatia que se sente sem saber explicar por quê, e por isso não acusa a pessoa de nada: o incômodo fica sendo de quem fala.","v":"48245a09"},{"idioma":"en","id":"en-f174","tipo":"frase","en":"He talked me out of it.","pt":"Ele me convenceu a desistir.","aceitas":["ele me convenceu a desistir","ele me fez desistir","ele me dissuadiu","ele me tirou a ideia da cabeca","ele me convenceu a nao fazer"],"aceitasEn":["he talked me out of it"],"distratores":["Ele falou de mim lá fora.","Ele me tirou dali conversando.","Ele me convenceu a fazer.","Ele falou mal de mim."],"nivel":"C1","tags":["phrasal verb","social"],"nota":"«Talk someone out of something» é convencer a não fazer; «talk into» é o contrário, convencer a fazer. As preposições guardam a direção — «out» tira a pessoa da ideia, «into» a põe dentro —, e a pessoa vai obrigatoriamente no meio.","v":"13210651"},{"idioma":"en","id":"en-f175","tipo":"frase","en":"Don't back down now.","pt":"Não recue agora.","aceitas":["nao recue agora","nao volte atras agora","nao amarele agora","nao desista agora","nao se acovarde agora"],"aceitasEn":["dont back down now","do not back down now"],"distratores":["Não desça agora.","Não volte por aí agora.","Não corra agora.","Não grite agora."],"nivel":"B2","tags":["phrasal verb","social"],"nota":"«Back down» é recuar de uma posição que já foi defendida em público — numa discussão, numa greve, numa aposta. Não é desistir de qualquer coisa: é ceder depois de ter dito que não cederia.","v":"c1ff5b9a"},{"idioma":"en","id":"en-f176","tipo":"frase","en":"We're running behind schedule.","pt":"Estamos atrasados no cronograma.","aceitas":["estamos atrasados no cronograma","estamos atrasados","o cronograma esta atrasado","estamos fora do prazo","estamos atrasados com o cronograma"],"aceitasEn":["were running behind schedule","we are running behind schedule","were behind schedule"],"distratores":["Estamos correndo atrás do ônibus.","Estamos correndo pelo cronograma.","Estamos adiantados no cronograma.","Estamos refazendo o cronograma."],"nivel":"B2","tags":["expressão","trabalho"],"nota":"«Run behind» é ficar para trás do combinado, e o «run» aqui não é correr — é o mesmo de «the trains run on time». O contrário é «ahead of schedule», adiantado, e «on schedule» é em cima da hora marcada.","v":"feda1314"},{"idioma":"en","id":"en-f177","tipo":"frase","en":"I'm not up to it today.","pt":"Hoje eu não estou em condições.","aceitas":["hoje eu nao estou em condicoes","hoje nao estou a fim","hoje eu nao dou conta","hoje nao estou com cabeca para isso","hoje eu nao estou bem para isso"],"aceitasEn":["im not up to it today","i am not up to it today"],"distratores":["Hoje eu não subo lá.","Hoje não estou por cima.","Hoje eu não escolho.","Hoje eu não vou lá."],"nivel":"B2","tags":["expressão","saúde"],"nota":"«Be up to something» é ter condição ou energia para a coisa — de saúde, de ânimo, de capacidade. Cuidado com as outras vidas da mesma frase: «what are you up to?» é «o que você está aprontando?», e «it's up to you» é «você decide».","v":"4b2c1d64"},{"idioma":"en","id":"en-f178","tipo":"frase","en":"It's up in the air.","pt":"Ainda está indefinido.","aceitas":["ainda esta indefinido","ainda nao esta decidido","ainda esta no ar","ainda nao se sabe","ainda esta em aberto"],"aceitasEn":["its up in the air","it is up in the air","its still up in the air"],"distratores":["Está lá em cima no ar.","Subiu e ficou no ar.","Já está tudo resolvido.","Não tem mais volta."],"nivel":"B2","tags":["expressão"],"nota":"O que está no ar ainda não caiu de nenhum lado: é o plano que não foi confirmado nem cancelado. Serve a viagem, a reunião e a contratação, e quem responde assim está dizendo que a decisão não é dele.","v":"fd8ef0ba"},{"idioma":"en","id":"en-f179","tipo":"frase","en":"Keep me posted.","pt":"Me mantenha informado.","aceitas":["me mantenha informado","me mantem informado","me avisa de qualquer novidade","vai me contando","me mantenha a par"],"aceitasEn":["keep me posted","keep me posted on it"],"distratores":["Me manda pelo correio.","Deixa isso no quadro de avisos.","Me chama quando acabar.","Me manda tudo por escrito."],"nivel":"B2","tags":["expressão","trabalho"],"nota":"«Post» aqui é o verbo antigo de despachar a mala do correio, o mesmo que virou «postar» nas redes. «Keep me posted» é «vai me mandando notícia» — pedido de fim de conversa, sem hora marcada e sem cobrança.","v":"92d701b1"},{"idioma":"en","id":"en-f180","tipo":"frase","en":"That's a long shot.","pt":"É tiro no escuro.","aceitas":["e tiro no escuro","e um tiro no escuro","e muito improvavel","e dificil dar certo","as chances sao minimas"],"aceitasEn":["thats a long shot","that is a long shot","its a long shot"],"distratores":["É um tiro de longe.","É uma foto de longe.","É certeza absoluta.","É coisa rápida."],"nivel":"B2","tags":["expressão"],"nota":"O tiro dado de muito longe quase não acerta, mas ainda vale a pena tentar — e é essa a diferença para «impossible». «A long shot» é a chance pequena que alguém vai correr mesmo assim.","v":"af92594c"},{"idioma":"en","id":"en-f181","tipo":"frase","en":"Let's get this over with.","pt":"Vamos acabar logo com isso.","aceitas":["vamos acabar logo com isso","vamos terminar logo com isso","vamos despachar isso logo","vamos resolver isso de uma vez","vamos logo com isso"],"aceitasEn":["lets get this over with","let us get this over with"],"distratores":["Vamos pegar isso de novo.","Vamos passar por cima disso.","Vamos começar isso agora.","Vamos deixar isso para depois."],"nivel":"B2","tags":["expressão","trabalho"],"nota":"«Get something over with» é despachar o que não se quer fazer: a consulta, a prova, a conversa difícil. O «with» no fim parece sobrar e é obrigatório — sem ele a frase muda de sentido e passa a ser superar.","v":"f4f4b9ce"},{"idioma":"en","id":"en-f182","tipo":"frase","en":"He caught on quickly.","pt":"Ele pegou rápido.","aceitas":["ele pegou rapido","ele sacou rapido","ele entendeu rapido","ele pegou a coisa rapido","ele aprendeu rapido"],"aceitasEn":["he caught on quickly","he caught on fast"],"distratores":["Ele pegou o ônibus rápido.","Ele foi pego rápido.","Ele desistiu rápido.","Ele se cansou rápido."],"nivel":"B2","tags":["phrasal verb","escola"],"nota":"«Catch on» é a ficha caindo: entender como a coisa funciona depois de um tempo olhando. E tem um segundo ofício, sobre moda e costume — «the word caught on» é «a palavra pegou».","v":"daef48a2"},{"idioma":"en","id":"en-f183","tipo":"frase","en":"Can you give me a hand?","pt":"Pode me dar uma mão?","aceitas":["pode me dar uma mao","voce pode me dar uma mao","me da uma mao","me ajuda aqui","pode me ajudar"],"aceitasEn":["can you give me a hand","could you give me a hand","can you lend me a hand"],"distratores":["Pode me dar um tempo?","Pode me dar um exemplo?","Pode me dar uma carona?","Pode me dar um conselho?"],"nivel":"B1","tags":["expressão","social"],"nota":"«Give someone a hand» é ajudar, e «lend a hand», emprestar a mão, diz o mesmo. Cuidado com o primo de fora: «give someone a big hand» é aplaudir, e não ajudar muito.","v":"401d3c34"},{"idioma":"en","id":"en-f184","tipo":"frase","en":"What's it like?","pt":"Como é que é?","aceitas":["como e que e","como e","como e la","como que e","como e por la"],"aceitasEn":["whats it like","what is it like"],"distratores":["Do que ele gosta?","O que ele quer?","Ele gosta disso?","Quando é que é?"],"nivel":"B1","tags":["gramática","viagem"],"nota":"O «like» de «what's it like» não é gostar: é o «como» de comparação. A pergunta pede descrição — «what's London like?» é «como é Londres?» —, e quem quer saber a aparência pergunta «what does it look like?».","v":"6d83bb60"},{"idioma":"en","id":"en-f185","tipo":"frase","en":"I have no idea.","pt":"Não faço ideia.","aceitas":["nao faco ideia","nao tenho a menor ideia","nao faco a menor ideia","sei la","nao tenho ideia"],"aceitasEn":["i have no idea","i have no clue","i havent got a clue"],"distratores":["Não tenho essa ideia.","Não gostei da ideia.","Tenho outra ideia.","A ideia não foi minha."],"nivel":"B1","tags":["expressão"],"nota":"«No idea» é mais forte que «I don't know»: quem diz isso não tem nem por onde começar. E repare onde cai a negação — o inglês nega o substantivo, «I have no idea», e não o verbo, que daria «I don't have idea», que não existe.","v":"79ba23f3"},{"idioma":"en","id":"en-f186","tipo":"frase","en":"Help yourself.","pt":"Pode se servir.","aceitas":["pode se servir","se sirva","sirva-se","fica a vontade para pegar","pode pegar a vontade"],"aceitasEn":["help yourself","help yourselves"],"distratores":["Se ajude sozinho.","Faça você mesmo.","Peça ajuda a alguém.","Vire-se como puder."],"nivel":"B1","tags":["expressão","comida","social"],"nota":"À mesa, «help yourself» é «pode se servir», e não tem nada de se virar sozinho. O anfitrião diz isso apontando a comida, e para mais de um convidado o pronome muda: «help yourselves».","v":"a7031fdf"},{"idioma":"en","id":"en-f187","tipo":"frase","en":"It's my turn.","pt":"É a minha vez.","aceitas":["e a minha vez","agora e a minha vez","e minha vez","chegou a minha vez","e a minha vez agora"],"aceitasEn":["its my turn","it is my turn","its my turn now"],"distratores":["É a minha volta.","É o meu turno de trabalho.","É a minha parte.","É o meu lugar."],"nivel":"B1","tags":["expressão","cotidiano"],"nota":"«Turn» aqui é a vez, na fila ou no jogo. O turno de trabalho é outra palavra, «shift». E a pergunta que sempre acompanha é «whose turn is it?», de quem é a vez.","v":"1e36f197"},{"idioma":"en","id":"en-f188","tipo":"frase","en":"Suit yourself.","pt":"Então faça do seu jeito.","aceitas":["entao faca do seu jeito","voce que sabe","faca como quiser","como voce quiser","problema seu","a escolha e sua"],"aceitasEn":["suit yourself"],"distratores":["Vista-se você mesmo.","O terno é seu.","Eu é que sei.","Faça o que eu mandar."],"nivel":"B1","tags":["expressão","social"],"nota":"«Suit» é servir, cair bem — daí «it suits you», fica bem em você. «Suit yourself» é «faça o que lhe convier», e quase sempre sai com um dar de ombros: quem diz isso tinha sugerido outra coisa.","v":"cd6245d0"},{"idioma":"en","id":"en-v087","tipo":"frase","en":"She lit the candle.","pt":"Ela acendeu a vela.","aceitas":["ela acendeu a vela","acendeu a vela","ela acendeu a velinha"],"aceitasEn":["she lit the candle"],"distratores":["Ela acende a vela.","Ela acenderá a vela.","Ela acenderia a vela.","Ela tinha acendido a vela."],"formasEn":{"She lights the candle":"presente","She will light the candle":"futuro","She would light the candle":"condicional","She had lit the candle":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","light","pretérito","casa"],"nota":"light, lit, lit. A forma regular «lighted» existe e quase sumiu — hoje só sobrevive como adjetivo, em «a lighted match». O verbo serve à vela, ao cigarro e ao cômodo inteiro: «light the room».","v":"04a89bfb"},{"idioma":"en","id":"en-v088","tipo":"frase","en":"The book slid off the table.","pt":"O livro escorregou da mesa.","aceitas":["o livro escorregou da mesa","o livro deslizou da mesa","o livro escorregou e caiu da mesa","o livro escorregou para fora da mesa"],"aceitasEn":["the book slid off the table"],"distratores":["O livro escorrega da mesa.","O livro escorregará da mesa.","O livro escorregaria da mesa.","O livro tinha escorregado da mesa."],"formasEn":{"The book slides off the table":"presente","The book will slide off the table":"futuro","The book would slide off the table":"condicional","The book had slid off the table":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","slide","pretérito","objetos"],"nota":"slide, slid, slid — e o particípio antigo «slidden» morreu sem deixar saudade. O substantivo é o escorregador do parquinho e também o slide da apresentação, que veio do projetor, onde a imagem deslizava para dentro.","v":"11312ccd"},{"idioma":"en","id":"en-v089","tipo":"frase","en":"His nose bled a lot.","pt":"O nariz dele sangrou muito.","aceitas":["o nariz dele sangrou muito","ele sangrou muito pelo nariz","o nariz dele sangrou bastante","sangrou muito o nariz dele"],"aceitasEn":["his nose bled a lot"],"distratores":["O nariz dele sangra muito.","O nariz dele sangrará muito.","O nariz dele sangraria muito.","O nariz dele tinha sangrado muito."],"formasEn":{"His nose bleeds a lot":"presente","His nose will bleed a lot":"futuro","His nose would bleed a lot":"condicional","His nose had bled a lot":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","bleed","pretérito","saúde"],"nota":"bleed, bled, bled — mesmo molde de feed/fed e lead/led, com o «ee» encurtando. O sangramento de nariz tem nome próprio em inglês, «a nosebleed», e a frase mais ouvida é «my nose is bleeding».","v":"938f2a95"},{"idioma":"en","id":"en-v090","tipo":"frase","en":"A bee stung him.","pt":"Uma abelha picou ele.","aceitas":["uma abelha picou ele","uma abelha o picou","ele foi picado por uma abelha","uma abelha ferroou ele"],"aceitasEn":["a bee stung him"],"distratores":["Uma abelha pica ele.","Uma abelha picará ele.","Uma abelha picaria ele.","Uma abelha tinha picado ele."],"formasEn":{"A bee stings him":"presente","A bee will sting him":"futuro","A bee would sting him":"condicional","A bee had stung him":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","sting","pretérito","animais"],"nota":"sting, stung, stung. Serve ao inseto, à planta que arde e ao comentário que dói — «a stinging remark». O ferrão é «the sting», e é a mesma palavra do golpe bem armado dos filmes de assalto.","v":"cc8de070"},{"idioma":"en","id":"en-v091","tipo":"frase","en":"The kids swung on the gate.","pt":"As crianças se balançaram no portão.","aceitas":["as criancas se balancaram no portao","as criancas ficaram se balancando no portao","as criancas balancaram no portao","as criancas se penduraram no portao balancando"],"aceitasEn":["the kids swung on the gate"],"distratores":["As crianças se balançam no portão.","As crianças se balançarão no portão.","As crianças se balançariam no portão.","As crianças tinham se balançado no portão."],"formasEn":{"The kids swing on the gate":"presente","The kids will swing on the gate":"futuro","The kids would swing on the gate":"condicional","The kids had swung on the gate":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","swing","pretérito"],"nota":"swing, swung, swung. O balanço do parquinho é «a swing», e foi daí que o ritmo ganhou nome. O verbo também é o de virar de opinião em bloco: «swing voters» são os eleitores que decidem a eleição.","v":"93ebd0e5"},{"idioma":"en","id":"en-v092","tipo":"frase","en":"My shirt shrank in the wash.","pt":"Minha camisa encolheu na lavagem.","aceitas":["minha camisa encolheu na lavagem","minha camisa encolheu na maquina","a camisa encolheu quando lavei","minha camisa encolheu depois de lavar"],"aceitasEn":["my shirt shrank in the wash","my shirt shrunk in the wash"],"distratores":["Minha camisa encolhe na lavagem.","Minha camisa encolherá na lavagem.","Minha camisa encolheria na lavagem.","Minha camisa tinha encolhido na lavagem."],"formasEn":{"My shirt shrinks in the wash":"presente","My shirt will shrink in the wash":"futuro","My shirt would shrink in the wash":"condicional","My shirt had shrunk in the wash":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","shrink","pretérito","roupa"],"nota":"shrink, shrank, shrunk — mesmo desenho de drink e de sing. O particípio virou título de filme, «Honey, I Shrunk the Kids», e na gíria americana «a shrink» é o psicanalista, encurtado de «headshrinker».","v":"7603e55c"},{"idioma":"en","id":"en-v093","tipo":"frase","en":"The toast burned.","pt":"A torrada queimou.","aceitas":["a torrada queimou","o pao queimou","a torrada ficou queimada","a torrada torrou demais"],"aceitasEn":["the toast burned"],"distratores":["A torrada queima.","A torrada queimará.","A torrada queimaria.","A torrada tinha queimado."],"formasEn":{"The toast burns":"presente","The toast will burn":"futuro","The toast would burn":"condicional","The toast had burned":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","burn","pretérito","comida"],"nota":"burn, burned, burned nos Estados Unidos; burn, burnt, burnt na Inglaterra. As duas estão certas, e o americano guarda o «burnt» só como adjetivo: «burnt toast». O mesmo acontece com learn, spell, smell, spill e dream.","regionaisEn":{"the toast burnt":"na Inglaterra"},"v":"721192ad"},{"idioma":"en","id":"en-v094","tipo":"frase","en":"The kitchen smelled strange.","pt":"A cozinha cheirava estranho.","aceitas":["a cozinha cheirava estranho","a cozinha estava com cheiro estranho","a cozinha cheirou estranho","tinha um cheiro estranho na cozinha","a cozinha tava com um cheiro esquisito"],"aceitasEn":["the kitchen smelled strange"],"distratores":["A cozinha cheira estranho.","A cozinha cheirará estranho.","A cozinha cheiraria estranho.","A cozinha tinha cheirado estranho."],"formasEn":{"The kitchen smells strange":"presente","The kitchen will smell strange":"futuro","The kitchen would smell strange":"condicional","The kitchen had smelled strange":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","smell","imperfeito","casa"],"nota":"smell, smelled, smelled nos Estados Unidos; smelt na Inglaterra. E repare que depois de «smell» vem adjetivo, e não advérbio: «it smells strange», nunca «strangely» — regra que vale para todos os verbos de sentido.","regionaisEn":{"the kitchen smelt strange":"na Inglaterra"},"v":"97d2af67"},{"idioma":"en","id":"en-v095","tipo":"frase","en":"She spelled her name for me.","pt":"Ela soletrou o nome para mim.","aceitas":["ela soletrou o nome para mim","ela soletrou o nome dela para mim","ela me soletrou o nome","ela soletrou o nome pra mim"],"aceitasEn":["she spelled her name for me"],"distratores":["Ela soletra o nome para mim.","Ela soletrará o nome para mim.","Ela soletraria o nome para mim.","Ela tinha soletrado o nome para mim."],"formasEn":{"She spells her name for me":"presente","She will spell her name for me":"futuro","She would spell her name for me":"condicional","She had spelled her name for me":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","spell","pretérito","social"],"nota":"spell, spelled, spelled nos Estados Unidos; spelt na Inglaterra. «How do you spell it?» é a pergunta que todo estrangeiro ouve, e soletrar em inglês é obrigação prática: nome, e-mail, endereço.","regionaisEn":{"she spelt her name for me":"na Inglaterra"},"v":"43d72443"},{"idioma":"en","id":"en-v096","tipo":"frase","en":"He lay on the sofa all afternoon.","pt":"Ele ficou deitado no sofá a tarde toda.","aceitas":["ele ficou deitado no sofa a tarde toda","ele passou a tarde toda deitado no sofa","ele ficou deitado no sofa a tarde inteira","ele deitou no sofa a tarde toda"],"aceitasEn":["he lay on the sofa all afternoon"],"distratores":["Ele fica deitado no sofá a tarde toda.","Ele ficará deitado no sofá a tarde toda.","Ele ficaria deitado no sofá a tarde toda.","Ele tinha ficado deitado no sofá a tarde toda."],"formasEn":{"He lies on the sofa all afternoon":"presente","He will lie on the sofa all afternoon":"futuro","He would lie on the sofa all afternoon":"condicional","He had lain on the sofa all afternoon":"mais-que-perfeito"},"nivel":"B2","tags":["conjugação","irregular","lie","pretérito","casa"],"nota":"lie, lay, lain — deitar-se, sem objeto. E aqui mora a confusão mais famosa do inglês: «lay», que é o passado deste verbo, é também o presente de outro, «to lay», que é deitar outra coisa e leva objeto. O terceiro «lie», o de mentir, é regular: lied.","v":"1266811b"},{"idioma":"en","id":"en-v097","tipo":"frase","en":"She laid the baby down.","pt":"Ela deitou o bebê.","aceitas":["ela deitou o bebe","ela pos o bebe deitado","ela colocou o bebe deitado","ela botou o bebe deitado"],"aceitasEn":["she laid the baby down"],"distratores":["Ela deita o bebê.","Ela deitará o bebê.","Ela deitaria o bebê.","Ela tinha deitado o bebê."],"formasEn":{"She lays the baby down":"presente","She will lay the baby down":"futuro","She would lay the baby down":"condicional","She had laid the baby down":"mais-que-perfeito"},"nivel":"B2","tags":["conjugação","irregular","lay","pretérito","família"],"nota":"lay, laid, laid — deitar alguma coisa, sempre com objeto. O par com «lie» é o erro mais comum até entre quem fala inglês desde criança: quem se deita usa «lie», quem deita outra coisa usa «lay». A galinha «lays eggs», e nunca «lies eggs».","v":"625f3fb9"},{"idioma":"en","id":"en-v098","tipo":"frase","en":"A cat crept into the room.","pt":"Um gato entrou de mansinho na sala.","aceitas":["um gato entrou de mansinho na sala","um gato entrou na sala sem fazer barulho","um gato se esgueirou para dentro da sala","um gato entrou na sala de fininho"],"aceitasEn":["a cat crept into the room"],"distratores":["Um gato entra de mansinho na sala.","Um gato entrará de mansinho na sala.","Um gato entraria de mansinho na sala.","Um gato tinha entrado de mansinho na sala."],"formasEn":{"A cat creeps into the room":"presente","A cat will creep into the room":"futuro","A cat would creep into the room":"condicional","A cat had crept into the room":"mais-que-perfeito"},"nivel":"B2","tags":["conjugação","irregular","creep","pretérito","animais"],"nota":"creep, crept, crept — mesmo molde de keep/kept e sleep/slept. É andar devagar para não ser notado, e daí saiu «creepy», o que dá arrepio. Como substantivo, «a creep» é o sujeito esquisito de quem se quer distância.","v":"ce1f9c70"},{"idioma":"en","id":"en-v099","tipo":"frase","en":"She knelt beside the bed.","pt":"Ela se ajoelhou ao lado da cama.","aceitas":["ela se ajoelhou ao lado da cama","ela ajoelhou ao lado da cama","ela se ajoelhou do lado da cama","ela se pos de joelhos ao lado da cama"],"aceitasEn":["she knelt beside the bed","she kneeled beside the bed"],"distratores":["Ela se ajoelha ao lado da cama.","Ela se ajoelhará ao lado da cama.","Ela se ajoelharia ao lado da cama.","Ela tinha se ajoelhado ao lado da cama."],"formasEn":{"She kneels beside the bed":"presente","She will kneel beside the bed":"futuro","She would kneel beside the bed":"condicional","She had knelt beside the bed":"mais-que-perfeito"},"nivel":"B2","tags":["conjugação","irregular","kneel","pretérito","corpo"],"nota":"kneel, knelt, knelt — e «kneeled» também vale, sobretudo nos Estados Unidos. O «k» do começo é mudo, como em knife, knee e know. E o joelho, «the knee», está ali dentro do verbo.","v":"20377e99"},{"idioma":"en","id":"en-v100","tipo":"frase","en":"He ground the coffee.","pt":"Ele moeu o café.","aceitas":["ele moeu o cafe","moeu o cafe","ele triturou o cafe","ele moeu os graos de cafe"],"aceitasEn":["he ground the coffee"],"distratores":["Ele mói o café.","Ele moerá o café.","Ele moeria o café.","Ele tinha moído o café."],"formasEn":{"He grinds the coffee":"presente","He will grind the coffee":"futuro","He would grind the coffee":"condicional","He had ground the coffee":"mais-que-perfeito"},"nivel":"B2","tags":["conjugação","irregular","grind","pretérito","comida"],"nota":"grind, ground, ground — e cuidado com a coincidência: «ground» é também o chão, palavra sem parentesco nenhum com este verbo. O café moído é «ground coffee», e «the daily grind» é a rotina que desgasta.","v":"00c21b63"},{"idioma":"en","id":"en-v101","tipo":"frase","en":"They fled the country.","pt":"Eles fugiram do país.","aceitas":["eles fugiram do pais","fugiram do pais","eles escaparam do pais","eles deixaram o pais fugindo"],"aceitasEn":["they fled the country"],"distratores":["Eles fogem do país.","Eles fugirão do país.","Eles fugiriam do país.","Eles tinham fugido do país."],"formasEn":{"They flee the country":"presente","They will flee the country":"futuro","They would flee the country":"condicional","They had fled the country":"mais-que-perfeito"},"nivel":"B2","tags":["conjugação","irregular","flee","pretérito","política"],"nota":"flee, fled, fled. É verbo de notícia e de guerra, e não leva preposição quando o objeto é o lugar de onde se foge: «flee the country», e não «flee from the country». Na conversa se diz «run away».","v":"2bfe451d"},{"idioma":"en","id":"en-v102","tipo":"frase","en":"The child clung to her mother.","pt":"A criança se agarrou à mãe.","aceitas":["a crianca se agarrou a mae","a crianca se agarrou na mae","a crianca ficou agarrada na mae","a crianca se grudou na mae"],"aceitasEn":["the child clung to her mother"],"distratores":["A criança se agarra à mãe.","A criança se agarrará à mãe.","A criança se agarraria à mãe.","A criança tinha se agarrado à mãe."],"formasEn":{"The child clings to her mother":"presente","The child will cling to her mother":"futuro","The child would cling to her mother":"condicional","The child had clung to her mother":"mais-que-perfeito"},"nivel":"B2","tags":["conjugação","irregular","cling","pretérito","família"],"nota":"cling, clung, clung — mesmo desenho de sting/stung. Pede «to» obrigatoriamente: cling to someone, cling to hope. E o plástico-filme da cozinha é «cling film» na Inglaterra, porque gruda sem cola nenhuma.","v":"9c60ac64"},{"idioma":"en","id":"en-v103","tipo":"frase","en":"She wove a rug.","pt":"Ela teceu um tapete.","aceitas":["ela teceu um tapete","teceu um tapete","ela fez um tapete tecido","ela teceu um tapete no tear"],"aceitasEn":["she wove a rug"],"distratores":["Ela tece um tapete.","Ela tecerá um tapete.","Ela teceria um tapete.","Ela tinha tecido um tapete."],"formasEn":{"She weaves a rug":"presente","She will weave a rug":"futuro","She would weave a rug":"condicional","She had woven a rug":"mais-que-perfeito"},"nivel":"B2","tags":["conjugação","irregular","weave","pretérito","objetos"],"nota":"weave, wove, woven. Quando o sentido é costurar entre os carros no trânsito, o verbo fica regular: «he weaved through traffic». E «the web», a teia e a rede, vem da mesma raiz antiga.","v":"73bf7f19"},{"idioma":"en","id":"en-v104","tipo":"frase","en":"She wept for hours.","pt":"Ela chorou por horas.","aceitas":["ela chorou por horas","ela chorou durante horas","ela passou horas chorando","ela chorou horas a fio"],"aceitasEn":["she wept for hours"],"distratores":["Ela chora por horas.","Ela chorará por horas.","Ela choraria por horas.","Ela tinha chorado por horas."],"formasEn":{"She weeps for hours":"presente","She will weep for hours":"futuro","She would weep for hours":"condicional","She had wept for hours":"mais-que-perfeito"},"nivel":"C1","tags":["conjugação","irregular","weep","pretérito"],"nota":"weep, wept, wept. É o chorar da literatura e da notícia grave; na conversa se diz «cry». O salgueiro-chorão é «a weeping willow», e a distância entre os dois verbos é a mesma que separa «pranto» de «choro».","v":"9a332c9f"},{"idioma":"en","id":"en-v105","tipo":"frase","en":"A problem arose.","pt":"Surgiu um problema.","aceitas":["surgiu um problema","apareceu um problema","deu um problema","um problema surgiu"],"aceitasEn":["a problem arose"],"distratores":["Surge um problema.","Surgirá um problema.","Surgiria um problema.","Tinha surgido um problema."],"formasEn":{"A problem arises":"presente","A problem will arise":"futuro","A problem would arise":"condicional","A problem had arisen":"mais-que-perfeito"},"nivel":"C1","tags":["conjugação","irregular","arise","pretérito","formal"],"nota":"arise, arose, arisen — conjuga como «rise», que está dentro dele. É verbo de coisa abstrata: surgem problemas, dúvidas e oportunidades, e não pessoas. Para gente levantando da cama o verbo é «get up».","v":"f4104e59"},{"idioma":"en","id":"en-v106","tipo":"frase","en":"He underwent surgery.","pt":"Ele passou por uma cirurgia.","aceitas":["ele passou por uma cirurgia","ele fez uma cirurgia","ele foi operado","ele passou por uma operacao"],"aceitasEn":["he underwent surgery"],"distratores":["Ele passa por uma cirurgia.","Ele passará por uma cirurgia.","Ele passaria por uma cirurgia.","Ele tinha passado por uma cirurgia."],"formasEn":{"He undergoes surgery":"presente","He will undergo surgery":"futuro","He would undergo surgery":"condicional","He had undergone surgery":"mais-que-perfeito"},"nivel":"C1","tags":["conjugação","irregular","undergo","pretérito","saúde"],"nota":"undergo, underwent, undergone — conjuga como «go», que está dentro dele. O sujeito não escolhe: quem «undergoes» passa por alguma coisa que é feita nele — cirurgia, tratamento, exame, mudança. É palavra de prontuário e de relatório de empresa.","v":"37f1c873"},{"idioma":"en","id":"en-p119","tipo":"palavra","en":"the water","pt":"a água","aceitas":["a agua","agua"],"aceitasEn":["the water","water","some water"],"distratores":["o leite","o suco","o gelo","o sal"],"nivel":"A1","tags":["substantivo","comida"],"nota":"«Water» não tem plural nem artigo quando é a substância: «I drink water». Com artigo, «the water» é a água daquele lugar — a do copo, a da piscina. E o verbo existe: «to water the plants» é regar.","v":"7cbdfb90"},{"idioma":"en","id":"en-u119","tipo":"frase","requer":"en-p119","en":"The water is cold.","pt":"A água está fria.","aceitas":["a agua esta fria","a agua ta fria","a agua esta gelada","a agua esta geladinha"],"aceitasEn":["the water is cold","the waters cold"],"distratores":["A comida está fria.","A sopa está fria.","A sala está fria.","A cama está fria."],"nivel":"A1","tags":["substantivo","casa","cotidiano"],"nota":"«The water», com artigo, é a água daquele lugar — a do chuveiro, a do mar. Sem artigo seria a substância em geral. E repare no verbo: «the water is», sempre no singular.","v":"91189d88"},{"idioma":"en","id":"en-p120","tipo":"palavra","en":"the book","pt":"o livro","aceitas":["o livro","livro","os livros"],"aceitasEn":["the book","book","a book"],"distratores":["o caderno","a revista","o jornal","a página"],"nivel":"A1","tags":["substantivo","objetos","cultura"],"nota":"«Book» é o livro, e como verbo é reservar — «book a table», «book a flight». O caderno é «notebook», e cuidado com o par: «library» é a biblioteca, e a livraria onde se compra é «bookstore».","v":"f91a97a6"},{"idioma":"en","id":"en-u120","tipo":"frase","requer":"en-p120","en":"I'm reading a good book.","pt":"Estou lendo um livro bom.","aceitas":["estou lendo um livro bom","estou lendo um bom livro","to lendo um livro bom","estou lendo um livro legal"],"aceitasEn":["im reading a good book","i am reading a good book"],"distratores":["Estou lendo um jornal bom.","Estou lendo um artigo bom.","Estou lendo um roteiro bom.","Estou lendo um poema bom."],"nivel":"A1","tags":["substantivo","cultura","gramática"],"nota":"O presente contínuo, «I'm reading», é para o que está acontecendo agora ou nestes dias. «I read a good book» seria outra coisa: um hábito, ou um livro que já acabou.","v":"7887c528"},{"idioma":"en","id":"en-p121","tipo":"palavra","en":"the window","pt":"a janela","aceitas":["a janela","janela","as janelas"],"aceitasEn":["the window","window","a window"],"distratores":["a porta","a parede","a cortina","a varanda"],"nivel":"A1","tags":["substantivo","casa","objetos"],"nota":"«Window» é a janela da casa e a da tela — o Windows do computador veio daí. A vitrine da loja é «shop window», e o assento da janela do avião é «window seat».","v":"1c68ebef"},{"idioma":"en","id":"en-u121","tipo":"frase","requer":"en-p121","en":"Close the window, please.","pt":"Feche a janela, por favor.","aceitas":["feche a janela por favor","fecha a janela por favor","pode fechar a janela por favor","fecha a janela ai por favor"],"aceitasEn":["close the window please","shut the window please","could you close the window please"],"distratores":["Feche a porta, por favor.","Feche a gaveta, por favor.","Feche a torneira, por favor.","Feche a mala, por favor."],"nivel":"A1","tags":["substantivo","casa","social"],"nota":"«Close» e «shut» valem os dois para janela e porta; «shut» é mais seco, e «shut up!» é «cala a boca». O «please» no fim não é enfeite: sem ele, o imperativo inglês soa a ordem militar.","v":"40fad81d"},{"idioma":"en","id":"en-p122","tipo":"palavra","en":"the cheese","pt":"o queijo","aceitas":["o queijo","queijo"],"aceitasEn":["the cheese","cheese","some cheese"],"distratores":["a manteiga","o presunto","o iogurte","a farinha"],"nivel":"A1","tags":["substantivo","comida"],"nota":"«Cheese» não tem plural quando é comida: «I like cheese». E é a palavra que se diz na hora da foto — «say cheese!» — porque a boca fica em posição de sorriso, pelo mesmo motivo do «xis» em português.","v":"4fd586b7"},{"idioma":"en","id":"en-u122","tipo":"frase","requer":"en-p122","en":"There's cheese in the fridge.","pt":"Tem queijo na geladeira.","aceitas":["tem queijo na geladeira","ha queijo na geladeira","tem queijo dentro da geladeira","tem queijo la na geladeira"],"aceitasEn":["theres cheese in the fridge","there is cheese in the fridge"],"distratores":["Tem manteiga na geladeira.","Tem presunto na geladeira.","Tem iogurte na geladeira.","Tem suco na geladeira."],"nivel":"A1","tags":["substantivo","comida","casa"],"nota":"«Fridge» é o encurtamento de «refrigerator», e é o que se diz em casa; a palavra inteira só aparece em manual. Repare que «cheese» entra sem artigo nenhum: é comida em geral, e o inglês corta o artigo nesses casos.","v":"cf4c640a"},{"idioma":"en","id":"en-p123","tipo":"palavra","en":"the shoe","pt":"o sapato","aceitas":["o sapato","sapato","os sapatos"],"aceitasEn":["the shoe","shoe","a shoe"],"distratores":["a meia","o cinto","a bota","o chinelo"],"nivel":"A1","tags":["substantivo","roupa"],"nota":"«Shoe» quase sempre vem no plural, «shoes», porque são dois. O cadarço é «shoelace», e «to be in someone's shoes» é estar na pele do outro — a mesma imagem, com outra peça de roupa.","v":"d602eee5"},{"idioma":"en","id":"en-u123","tipo":"frase","requer":"en-p123","en":"My shoes are too tight.","pt":"Meus sapatos estão apertados.","aceitas":["meus sapatos estao apertados","meus sapatos estao muito apertados","meu sapato esta apertado","os sapatos estao apertados demais"],"aceitasEn":["my shoes are too tight","my shoes are very tight"],"distratores":["Meus sapatos estão molhados.","Meus sapatos estão sujos.","Meus sapatos estão gastos.","Meus sapatos estão novos."],"nivel":"A1","tags":["substantivo","roupa","cotidiano"],"nota":"«Too» não é «muito»: é «demais», e sempre traz um problema junto. «My shoes are very tight» é um comentário; «too tight» quer dizer que não dá para usar.","v":"17dde4f2"},{"idioma":"en","id":"en-p124","tipo":"palavra","en":"the wall","pt":"a parede","aceitas":["a parede","parede","as paredes","o muro"],"aceitasEn":["the wall","wall","a wall"],"distratores":["o teto","o chão","a porta","a cerca"],"nivel":"A1","tags":["substantivo","casa"],"nota":"«Wall» é a parede de dentro e o muro de fora: o inglês usa uma palavra só para as duas coisas. E ela entra em expressão — «off the wall» é maluco, e «the writing on the wall» é o sinal de que a coisa vai acabar mal.","v":"b372eb0b"},{"idioma":"en","id":"en-u124","tipo":"frase","requer":"en-p124","en":"There's a picture on the wall.","pt":"Tem um quadro na parede.","aceitas":["tem um quadro na parede","ha um quadro na parede","tem uma foto na parede","tem um quadro pendurado na parede"],"aceitasEn":["theres a picture on the wall","there is a picture on the wall"],"distratores":["Tem um relógio na parede.","Tem um espelho na parede.","Tem um buraco na parede.","Tem um interruptor na parede."],"nivel":"A1","tags":["substantivo","casa","objetos"],"nota":"Na parede é «on the wall», porque é superfície. «In the wall» existe e diz outra coisa: dentro dela, como um cofre ou um cano. E «picture» serve ao quadro e à foto.","v":"e83533f0"},{"idioma":"en","id":"en-p125","tipo":"palavra","en":"the belt","pt":"o cinto","aceitas":["o cinto","cinto","os cintos"],"aceitasEn":["the belt","belt","a belt"],"distratores":["o cadarço","o tirante","o colarinho","o bolso"],"nivel":"A2","tags":["substantivo","roupa"],"nota":"«Belt» é o cinto da calça e o de segurança — «seat belt». Vira região no mapa americano: «the Bible Belt» é a faixa religiosa do sul. E «below the belt» é golpe baixo, a mesma imagem do boxe.","v":"0388abc8"},{"idioma":"en","id":"en-u125","tipo":"frase","requer":"en-p125","en":"Fasten your seat belt.","pt":"Aperte o cinto de segurança.","aceitas":["aperte o cinto de seguranca","aperta o cinto de seguranca","poe o cinto de seguranca","coloque o cinto de seguranca","aperte o cinto"],"aceitasEn":["fasten your seat belt","fasten your seatbelt","put your seat belt on"],"distratores":["Aperte o nó da gravata.","Aperte o fecho do casaco.","Aperte a pulseira do relógio.","Aperte a fivela do sapato."],"nivel":"A2","tags":["substantivo","viagem","roupa"],"nota":"«Fasten» é prender, e é a palavra do aviso luminoso do avião. Na conversa se diz «buckle up» ou «put your seat belt on». E «seat belt» se escreve junto ou separado, tanto faz.","v":"bee7e600"},{"idioma":"en","id":"en-p126","tipo":"palavra","en":"the pocket","pt":"o bolso","aceitas":["o bolso","bolso","os bolsos"],"aceitasEn":["the pocket","pocket","a pocket"],"distratores":["a bolsa","a manga","o forro","a gola"],"nivel":"A2","tags":["substantivo","roupa"],"nota":"«Pocket» é o bolso da roupa. A bolsa de mão é «purse» nos Estados Unidos e «handbag» na Inglaterra, e a mochila é «backpack». E «out of pocket» é do próprio bolso.","v":"22a71aac"},{"idioma":"en","id":"en-u126","tipo":"frase","requer":"en-p126","en":"I keep my phone in my pocket.","pt":"Eu guardo o celular no bolso.","aceitas":["eu guardo o celular no bolso","guardo o celular no bolso","eu ando com o celular no bolso","eu deixo o celular no bolso"],"aceitasEn":["i keep my phone in my pocket"],"distratores":["Eu guardo o celular na bolsa.","Eu guardo o celular na gaveta.","Eu guardo o celular na mochila.","Eu guardo o celular no carro."],"nivel":"A2","tags":["substantivo","roupa","cotidiano"],"nota":"«Keep» aqui não é guardar para sempre: é onde a coisa costuma ficar. E repare nos dois possessivos — «my phone in my pocket» —, que o português dispensa sem perder nada.","v":"56c55ae1"},{"idioma":"en","id":"en-p127","tipo":"palavra","en":"the wheel","pt":"a roda","aceitas":["a roda","roda","as rodas","o volante"],"aceitasEn":["the wheel","wheel","a wheel"],"distratores":["o pneu","o freio","o eixo","a corrente"],"nivel":"A2","tags":["substantivo","objetos","viagem"],"nota":"«Wheel» é a roda e também o volante — «behind the wheel» é ao volante. O pneu é outra palavra: «tire» nos Estados Unidos e «tyre» na Inglaterra. E «to reinvent the wheel» é reinventar a roda, igualzinho.","v":"79ab4b9c"},{"idioma":"en","id":"en-u127","tipo":"frase","requer":"en-p127","en":"The front wheel is loose.","pt":"A roda da frente está solta.","aceitas":["a roda da frente esta solta","a roda dianteira esta solta","a roda de frente esta solta","a roda da frente ta solta"],"aceitasEn":["the front wheel is loose"],"distratores":["A porta da frente está solta.","A luz da frente está solta.","A placa da frente está solta.","A grade da frente está solta."],"nivel":"A2","tags":["substantivo","viagem","objetos"],"nota":"«Front» e «back» viram adjetivo sem mudar de forma: front wheel, back door, front seat. O português precisa de «da frente» ou de «dianteiro», e o inglês só encosta uma palavra na outra.","v":"d968eff8"},{"idioma":"en","id":"en-p128","tipo":"palavra","en":"the mirror","pt":"o espelho","aceitas":["o espelho","espelho","os espelhos"],"aceitasEn":["the mirror","mirror","a mirror"],"distratores":["o quadro","a vidraça","a moldura","a lente"],"nivel":"A2","tags":["substantivo","casa","objetos"],"nota":"«Mirror» é o espelho, e como verbo é espelhar: «the report mirrors the data». O retrovisor do carro é «rearview mirror», e o de fora é «side mirror».","v":"80d6ea35"},{"idioma":"en","id":"en-u128","tipo":"frase","requer":"en-p128","en":"Look at yourself in the mirror.","pt":"Se olha no espelho.","aceitas":["se olha no espelho","olhe-se no espelho","olha no espelho","se olhe no espelho","va se olhar no espelho"],"aceitasEn":["look at yourself in the mirror","look in the mirror"],"distratores":["Se olha na foto.","Se olha na câmera.","Se olha na tela.","Se olha na vitrine."],"nivel":"A2","tags":["substantivo","casa","corpo"],"nota":"O inglês precisa do «at» e do reflexivo: «look at yourself». Sem o «at» o verbo muda de ofício — «look for» é procurar, «look after» é cuidar, «look up» é consultar. Em «look», quem manda é a preposição.","v":"9a2e1b1b"},{"idioma":"en","id":"en-p129","tipo":"palavra","en":"the soap","pt":"o sabão","aceitas":["o sabao","sabao","o sabonete"],"aceitasEn":["the soap","soap","some soap"],"distratores":["a espuma","o xampu","a toalha","a esponja"],"nivel":"A2","tags":["substantivo","casa","objetos"],"nota":"«Soap» não tem plural: o sabonete em barra é «a bar of soap». E «soap opera» é a novela — o nome veio de as primeiras serem patrocinadas por fábricas de sabão, nos anos trinta.","v":"011344b9"},{"idioma":"en","id":"en-u129","tipo":"frase","requer":"en-p129","en":"Wash your hands with soap.","pt":"Lave as mãos com sabão.","aceitas":["lave as maos com sabao","lava as maos com sabao","lave as maos com sabonete","lave bem as maos com sabao"],"aceitasEn":["wash your hands with soap","wash your hands with soap and water"],"distratores":["Lave as mãos com álcool.","Lave as mãos com vinagre.","Lave as mãos com xampu.","Lave as mãos com areia."],"nivel":"A2","tags":["substantivo","saúde","corpo"],"nota":"«Wash your hands» leva possessivo obrigatório: o inglês não diz «wash the hands». Vale para tudo que é parte do corpo — brush your teeth, comb your hair, wash your face.","v":"c3cd4db4"},{"idioma":"en","id":"en-p130","tipo":"palavra","en":"the razor","pt":"o barbeador","aceitas":["o barbeador","barbeador","o aparelho de barbear","a gilete"],"aceitasEn":["the razor","razor","a razor"],"distratores":["a tesoura","o pente","a escova","a pinça"],"nivel":"A2","tags":["substantivo","objetos","corpo"],"nota":"«Razor» é o aparelho de barbear, e a lâmina dele é «razor blade». O elétrico é «electric shaver». E «razor-sharp» é afiadíssimo, dito tanto de faca quanto de raciocínio.","v":"1a9329e6"},{"idioma":"en","id":"en-u130","tipo":"frase","requer":"en-p130","en":"I need a new razor.","pt":"Preciso de um barbeador novo.","aceitas":["preciso de um barbeador novo","eu preciso de um barbeador novo","preciso de uma gilete nova","preciso comprar um barbeador novo"],"aceitasEn":["i need a new razor"],"distratores":["Preciso de um pente novo.","Preciso de um travesseiro novo.","Preciso de um casaco novo.","Preciso de um relógio novo."],"nivel":"A2","tags":["substantivo","objetos","cotidiano"],"nota":"O adjetivo vem antes do substantivo em inglês, sempre: «a new razor», e nunca «a razor new». É a ordem inversa da portuguesa, e é o que mais trava quem está começando a montar frase.","v":"3c2e7a98"},{"idioma":"en","id":"en-p131","tipo":"palavra","en":"the comb","pt":"o pente","aceitas":["o pente","pente","os pentes"],"aceitasEn":["the comb","comb","a comb"],"distratores":["a escova","o secador","o grampo","a tesoura"],"nivel":"A2","tags":["substantivo","objetos","corpo"],"nota":"«Comb» tem o «b» mudo, como em thumb, climb e lamb. Como verbo é pentear — «comb your hair» — e também vasculhar: «they combed the area» é «vasculharam a área».","v":"84e2fae1"},{"idioma":"en","id":"en-u131","tipo":"frase","requer":"en-p131","en":"This comb is missing a tooth.","pt":"Falta um dente neste pente.","aceitas":["falta um dente neste pente","esta faltando um dente no pente","o pente esta com um dente faltando","falta um dente nesse pente"],"aceitasEn":["this comb is missing a tooth","this comb has a tooth missing"],"distratores":["Falta um dente neste garfo.","Falta um dente nesta engrenagem.","Falta um dente nesta serra.","Falta um dente neste rastelo."],"nivel":"A2","tags":["substantivo","objetos"],"nota":"O dente do pente é «a tooth», a mesma palavra do dente da boca, com o mesmo plural irregular: «teeth». Serve ao garfo, à serra e à engrenagem — o inglês vê dente em tudo que tem ponta em fila.","v":"578a9755"},{"idioma":"en","id":"en-p132","tipo":"palavra","en":"to wrap","pt":"embrulhar","aceitas":["embrulhar","enrolar","empacotar","envolver"],"aceitasEn":["to wrap","wrap"],"distratores":["desamarrar","costurar","rasgar","pendurar"],"nivel":"A2","tags":["verbo","cotidiano"],"nota":"«Wrap» é envolver com papel ou com pano: o presente, o sanduíche, o cachecol no pescoço. O papel de presente é «wrapping paper», e «wrap up» tem duas vidas — agasalhar-se e encerrar a reunião.","v":"f804bfa9"},{"idioma":"en","id":"en-u132","tipo":"frase","requer":"en-p132","en":"Can you wrap it as a gift?","pt":"Pode embrulhar para presente?","aceitas":["pode embrulhar para presente","pode embrulhar pra presente","da para embrulhar para presente","voce pode embrulhar para presente","embrulha para presente por favor"],"aceitasEn":["can you wrap it as a gift","can you gift wrap it","could you wrap it as a gift"],"distratores":["Pode guardar para presente?","Pode separar para presente?","Pode etiquetar para presente?","Pode reservar para presente?"],"nivel":"A2","tags":["verbo","cotidiano","social"],"nota":"«Gift wrap» é o par fixo da loja, e funciona como verbo inteiro: «can you gift wrap it?». A frase se decora — traduzida ao pé da letra, o «para presente» do português não tem preposição correspondente.","v":"3f9f0f30"},{"idioma":"en","id":"en-p133","tipo":"palavra","en":"to fold","pt":"dobrar","aceitas":["dobrar","vincar","dobrar ao meio"],"aceitasEn":["to fold","fold"],"distratores":["esticar","amassar","cortar","enrolar"],"nivel":"A2","tags":["verbo","casa"],"nota":"«Fold» é dobrar papel, roupa e cadeira. O português usa «dobrar» também para virar a esquina e para duplicar, e o inglês não: ali são «turn» e «double». No pôquer, «to fold» é desistir da mão.","v":"219e4787"},{"idioma":"en","id":"en-u133","tipo":"frase","requer":"en-p133","en":"Fold the towel in half.","pt":"Dobre a toalha ao meio.","aceitas":["dobre a toalha ao meio","dobra a toalha ao meio","dobre a toalha no meio","dobra a toalha na metade"],"aceitasEn":["fold the towel in half","fold the towel in two"],"distratores":["Estique a toalha toda.","Corte a toalha ao meio.","Rasgue a toalha ao meio.","Enrole a toalha inteira."],"nivel":"A2","tags":["verbo","casa","cotidiano"],"nota":"«In half» é «ao meio», e o «in» é obrigatório: nunca «at half». A outra forma, «in two», diz o mesmo. E dobrar de novo é «fold it again» — «refold» existe no dicionário e ninguém usa.","v":"51a55794"},{"idioma":"en","id":"en-p134","tipo":"palavra","en":"to lock","pt":"trancar","aceitas":["trancar","trancar a chave","fechar a chave","chavear"],"aceitasEn":["to lock","lock"],"distratores":["empurrar","emperrar","pintar","abrir"],"nivel":"A2","tags":["verbo","casa"],"nota":"«Lock» é trancar com chave num verbo só, onde o português precisa de duas ou três palavras. O cadeado é «padlock», e «lock someone out» é deixar alguém do lado de fora sem chave.","v":"6139d79c"},{"idioma":"en","id":"en-u134","tipo":"frase","requer":"en-p134","en":"Did you lock the car?","pt":"Você trancou o carro?","aceitas":["voce trancou o carro","trancou o carro","voce fechou o carro a chave","voce travou o carro"],"aceitasEn":["did you lock the car","did you lock the car up"],"distratores":["Você lavou o carro?","Você estacionou o carro?","Você abasteceu o carro?","Você vendeu o carro?"],"nivel":"A2","tags":["verbo","viagem","gramática"],"nota":"A pergunta no passado leva «did» na frente e o verbo volta ao infinitivo: «did you lock», e nunca «did you locked». É a regra que mais escapa quando se fala depressa.","v":"efe57df3"},{"idioma":"en","id":"en-p135","tipo":"palavra","en":"to taste","pt":"provar","aceitas":["provar","experimentar","ter gosto de","degustar"],"aceitasEn":["to taste","taste"],"distratores":["cheirar","mastigar","engolir","cozinhar"],"nivel":"A2","tags":["verbo","comida"],"nota":"«Taste» tem dois ofícios: provar («taste this») e ter gosto («it tastes salty»). No segundo vem adjetivo depois, e não advérbio. E o substantivo é o gosto, inclusive o figurado — «good taste in music».","v":"8525e1d2"},{"idioma":"en","id":"en-u135","tipo":"frase","requer":"en-p135","en":"It tastes like chicken.","pt":"Tem gosto de frango.","aceitas":["tem gosto de frango","o gosto e de frango","parece frango no gosto","tem sabor de frango"],"aceitasEn":["it tastes like chicken"],"distratores":["Tem cheiro de frango.","Tem cara de frango.","Tem cor de frango.","Tem jeito de frango."],"nivel":"A2","tags":["verbo","comida","expressão"],"nota":"«Taste like» é «ter gosto de», e o «like» aqui é comparação, não gosto. A frase virou piada pronta em inglês: tudo que é exótico, dizem, «tastes like chicken».","v":"77717d86"},{"idioma":"en","id":"en-p136","tipo":"palavra","en":"the nail","pt":"o prego","aceitas":["o prego","prego","a unha"],"aceitasEn":["the nail","nail","a nail"],"distratores":["o parafuso","o martelo","a tachinha","o alicate"],"nivel":"B1","tags":["substantivo","objetos"],"nota":"«Nail» é o prego e é também a unha: a mesma palavra para as duas coisas, e quem separa é o contexto. O esmalte é «nail polish», e «to hit the nail on the head» é acertar na mosca.","v":"3cb534ed"},{"idioma":"en","id":"en-u136","tipo":"frase","requer":"en-p136","en":"I stepped on a nail.","pt":"Pisei num prego.","aceitas":["pisei num prego","eu pisei num prego","pisei em um prego","pisei num prego sem querer"],"aceitasEn":["i stepped on a nail"],"distratores":["Pisei numa pedra.","Pisei num caco.","Pisei numa poça.","Pisei numa formiga."],"nivel":"B1","tags":["substantivo","objetos","saúde"],"nota":"«Step on» pede o «on»: em inglês o pé cai em cima de alguma coisa, e o verbo sozinho não basta. O português já carrega a preposição dentro de «pisar em», e o espanhol dispensa as duas.","v":"8ab1625e"},{"idioma":"en","id":"en-p137","tipo":"palavra","en":"the screw","pt":"o parafuso","aceitas":["o parafuso","parafuso","os parafusos"],"aceitasEn":["the screw","screw","a screw"],"distratores":["a porca","a arruela","o prego","a dobradiça"],"nivel":"B1","tags":["substantivo","objetos"],"nota":"«Screw» é o parafuso, e a chave de fenda é «screwdriver» — ao pé da letra, «o que dirige o parafuso». Como verbo ele tem uso vulgar; o seguro é usar com preposição, em «screw in» (atarraxar) e «screw up» (estragar tudo).","v":"947a852e"},{"idioma":"en","id":"en-u137","tipo":"frase","requer":"en-p137","en":"Tighten the screw.","pt":"Aperte o parafuso.","aceitas":["aperte o parafuso","aperta o parafuso","aperte bem o parafuso","rosqueie o parafuso"],"aceitasEn":["tighten the screw","tighten the screw up"],"distratores":["Aperte a porca.","Aperte a dobradiça.","Aperte a corda.","Aperte a tampa."],"nivel":"B1","tags":["substantivo","objetos","gramática"],"nota":"«Tighten» vem de «tight», apertado, e o sufixo «-en» faz adjetivo virar verbo: widen, shorten, darken, soften, weaken. O contrário aqui é «loosen», afrouxar, feito do mesmo jeito.","v":"b54958b0"},{"idioma":"en","id":"en-p138","tipo":"palavra","en":"to melt","pt":"derreter","aceitas":["derreter","desmanchar","derreter-se"],"aceitasEn":["to melt","melt"],"distratores":["ferver","congelar","secar","queimar"],"nivel":"B1","tags":["verbo","comida"],"nota":"«Melt» é o sólido que vira líquido no calor: o gelo, a manteiga, o chocolate. O metal na fundição é «to smelt», com «s» na frente. E «my heart melted» é o coração derretendo, imagem igual à portuguesa.","v":"79cb54e3"},{"idioma":"en","id":"en-u138","tipo":"frase","requer":"en-p138","en":"The ice melted quickly.","pt":"O gelo derreteu rápido.","aceitas":["o gelo derreteu rapido","o gelo derreteu depressa","o gelo se derreteu rapido","o gelo derreteu rapidinho"],"aceitasEn":["the ice melted quickly","the ice melted fast"],"distratores":["O gelo rachou rápido.","O gelo endureceu rápido.","O gelo escorregou rápido.","O gelo esfriou rápido."],"nivel":"B1","tags":["verbo","comida","cotidiano"],"nota":"«Melt» não é reflexivo em inglês: o gelo «melts», sem pronome nenhum. O português e o espanhol põem o «se», e o inglês guarda essa construção só para os verbos que precisam mesmo de objeto.","v":"5c418c20"},{"idioma":"en","id":"en-p139","tipo":"palavra","en":"to pour","pt":"despejar","aceitas":["despejar","servir","verter","virar o liquido"],"aceitasEn":["to pour","pour"],"distratores":["ferver","mexer","coar","provar"],"nivel":"B1","tags":["verbo","comida"],"nota":"«Pour» é virar o líquido de um recipiente para outro, e sempre de propósito — quem faz sem querer usa «spill». E «it's pouring» é chover forte: a chuva caindo como quem despeja um balde.","v":"1d09145d"},{"idioma":"en","id":"en-u139","tipo":"frase","requer":"en-p139","en":"Pour me a glass of water.","pt":"Me serve um copo de água.","aceitas":["me serve um copo de agua","serve um copo de agua para mim","despeje um copo de agua para mim","me poe um copo de agua","me serve agua num copo"],"aceitasEn":["pour me a glass of water","pour me some water"],"distratores":["Me traz um copo de água.","Me guarda um copo de água.","Me esquenta um copo de água.","Me paga um copo de água."],"nivel":"B1","tags":["verbo","comida","social"],"nota":"O inglês põe a pessoa logo depois do verbo, sem preposição nenhuma: «pour me a glass». É a mesma construção de «give me», «buy me» e «tell me», e é por isso que «pour a glass to me» soa errado.","v":"19a1753f"},{"idioma":"en","id":"en-p140","tipo":"palavra","en":"loose","pt":"solto","aceitas":["solto","frouxo","folgado","bambo"],"aceitasEn":["loose"],"distratores":["apertado","preso","firme","reto"],"nivel":"B1","tags":["adjetivo","objetos"],"nota":"«Loose» é solto, com dois oo e som de «s». Cuidado com «lose», de um o só e som de «z», que é perder: é o par que mais se erra na escrita, inclusive por quem fala inglês desde criança.","v":"a55e7f49"},{"idioma":"en","id":"en-u140","tipo":"frase","requer":"en-p140","en":"My tooth is loose.","pt":"Meu dente está mole.","aceitas":["meu dente esta mole","meu dente esta bambo","tenho um dente mole","meu dente esta solto","meu dente ta mole"],"aceitasEn":["my tooth is loose","i have a loose tooth"],"distratores":["Meu dente está quebrado.","Meu dente está doendo.","Meu dente está manchado.","Meu dente está torto."],"nivel":"B1","tags":["adjetivo","corpo","saúde"],"nota":"O dente de leite que está para cair é «a loose tooth», e é o que a criança anuncia à mesa. Para parafuso e para botão vale a mesma palavra. E o plural de «tooth» é «teeth», irregular desde o inglês antigo.","v":"5f25cbdb"},{"idioma":"en","id":"en-f189","tipo":"frase","en":"What time is it?","pt":"Que horas são?","aceitas":["que horas sao","que hora e","que horas voce tem","tem horas ai"],"aceitasEn":["what time is it","whats the time","do you have the time"],"distratores":["Que dia é hoje?","Quanto tempo falta?","A que horas começa?","Quanto tempo demora?"],"nivel":"A2","tags":["gramática","cotidiano"],"nota":"«What time is it?» é a pergunta padrão. «Do you have the time?» é mais educada e diz a mesma coisa — cuidado só para não cortar o «the», porque «do you have time?» é «você tem um tempinho?».","v":"1d06f37f"},{"idioma":"en","id":"en-f190","tipo":"frase","en":"I don't understand.","pt":"Não entendi.","aceitas":["nao entendi","nao entendo","nao estou entendendo","nao peguei","nao compreendi"],"aceitasEn":["i dont understand","i do not understand"],"distratores":["Não ouvi.","Não concordo.","Não sei.","Não acredito."],"nivel":"A2","tags":["gramática","social"],"nota":"O inglês diz no presente, «I don't understand», onde o português quase sempre põe no passado: «não entendi». As duas dizem a mesma coisa, e esta é a frase mais útil de todas para quem está começando.","v":"212ea6c6"},{"idioma":"en","id":"en-f191","tipo":"frase","en":"Can you repeat that?","pt":"Pode repetir?","aceitas":["pode repetir","voce pode repetir","repete por favor","pode falar de novo","da para repetir"],"aceitasEn":["can you repeat that","could you repeat that","can you say that again"],"distratores":["Pode traduzir?","Pode explicar?","Pode escrever?","Pode soletrar?"],"nivel":"A2","tags":["gramática","social"],"nota":"«Can you repeat that?» é o pedido completo; na conversa se ouve mais «sorry?» ou «come again?», que fazem o mesmo serviço numa palavra. «What?» sozinho soa grosseiro.","v":"19079cda"},{"idioma":"en","id":"en-f192","tipo":"frase","en":"Where's the bathroom?","pt":"Onde fica o banheiro?","aceitas":["onde fica o banheiro","onde esta o banheiro","cade o banheiro","onde e o banheiro"],"aceitasEn":["wheres the bathroom","where is the bathroom","wheres the restroom"],"distratores":["Onde fica a cozinha?","Onde fica a saída?","Onde fica o elevador?","Onde fica a recepção?"],"nivel":"A2","tags":["viagem","cotidiano"],"nota":"Nos Estados Unidos se pergunta por «the bathroom» mesmo num restaurante, onde banho não tem; «restroom» é o mais formal. Na Inglaterra é «the toilet» ou «the loo». O «WC» está escrito na porta e ninguém fala.","v":"8dbc2e66"},{"idioma":"en","id":"en-f193","tipo":"frase","en":"How do you say this in English?","pt":"Como se diz isso em inglês?","aceitas":["como se diz isso em ingles","como e que se diz isso em ingles","como se fala isso em ingles","qual e a palavra em ingles para isso"],"aceitasEn":["how do you say this in english","how do you say that in english"],"distratores":["Como se escreve isso em inglês?","Como se soletra isso em inglês?","O que significa isso em inglês?","Como se lê isso em inglês?"],"nivel":"A2","tags":["gramática","escola"],"nota":"«How do you say» usa o «you» impessoal — não é «você» em particular, é «a gente». O inglês não tem o «se» do português e resolve tudo com esse «you» genérico: «you never know», «you can't win».","v":"1a80152d"},{"idioma":"en","id":"en-f194","tipo":"frase","en":"I'm sorry I'm late.","pt":"Desculpa o atraso.","aceitas":["desculpa o atraso","desculpe o atraso","me desculpe pelo atraso","desculpa a demora","perdao pelo atraso"],"aceitasEn":["im sorry im late","i am sorry i am late","sorry im late"],"distratores":["Desculpa o incômodo.","Desculpa a bagunça.","Desculpa o barulho.","Desculpa a confusão."],"nivel":"A2","tags":["social","cotidiano"],"nota":"O inglês repete o «I'm»: «I'm sorry I'm late». Na conversa o primeiro cai e sobra «sorry I'm late», que é o que se diz de verdade ao entrar na sala atrasado.","v":"fab80ccc"},{"idioma":"en","id":"en-f195","tipo":"frase","en":"See you tomorrow.","pt":"Até amanhã.","aceitas":["ate amanha","a gente se ve amanha","nos vemos amanha","te vejo amanha"],"aceitasEn":["see you tomorrow","see ya tomorrow"],"distratores":["Até segunda.","Até logo.","Até mais tarde.","Até a próxima."],"nivel":"A2","tags":["social","cotidiano"],"nota":"«See you» é a despedida coringa, e o que vem depois marca o prazo: see you tomorrow, see you later, see you soon, see you around. Sozinho vira «see ya», e por escrito, «cya».","v":"5d636961"},{"idioma":"en","id":"en-f196","tipo":"frase","en":"It doesn't matter.","pt":"Tanto faz.","aceitas":["tanto faz","nao faz diferenca","nao importa","pode ser qualquer um","para mim da na mesma"],"aceitasEn":["it doesnt matter","it does not matter"],"distratores":["Não interessa a ninguém.","Não é da minha conta.","Não vale nada.","Não faz sentido."],"nivel":"A2","tags":["expressão","social"],"nota":"«It doesn't matter» serve a duas coisas: dizer que tanto faz, e dizer que não houve problema depois de um pedido de desculpa. Quem separa é o tom, e o português faz a mesma economia com «não tem problema».","v":"e01408b3"},{"idioma":"en","id":"en-f197","tipo":"frase","en":"What do you do for a living?","pt":"Você trabalha com o quê?","aceitas":["voce trabalha com o que","o que voce faz da vida","qual e a sua profissao","voce faz o que da vida","em que voce trabalha"],"aceitasEn":["what do you do for a living","what do you do"],"distratores":["Você mora onde?","Você estuda o quê?","Você ganha quanto?","Você trabalha quantas horas?"],"nivel":"B1","tags":["trabalho","social"],"nota":"«For a living» é «para viver», e o inglês põe isso porque «what do you do?» sozinho seria vago demais. Na conversa o «for a living» cai e todo mundo entende — mas na primeira vez que se pergunta, ele ajuda.","v":"790f9960"},{"idioma":"en","id":"en-f198","tipo":"frase","en":"I'll think about it.","pt":"Vou pensar.","aceitas":["vou pensar","eu vou pensar","vou pensar no assunto","deixa eu pensar","vou pensar e te falo"],"aceitasEn":["ill think about it","i will think about it"],"distratores":["Vou lembrar disso.","Vou perguntar sobre isso.","Vou esquecer isso.","Vou escrever sobre isso."],"nivel":"B1","tags":["expressão","social"],"nota":"«Think about» é refletir sobre alguma coisa; «think of» é ter em mente ou lembrar. E «I'll think about it» é, nas três línguas, a recusa educada que ninguém confessa ser recusa.","v":"592a3939"},{"idioma":"en","id":"en-f199","tipo":"frase","en":"Do you mind if I sit here?","pt":"Posso sentar aqui?","aceitas":["posso sentar aqui","voce se importa se eu sentar aqui","da para eu sentar aqui","tem problema eu sentar aqui","incomoda se eu sentar aqui"],"aceitasEn":["do you mind if i sit here","would you mind if i sat here"],"distratores":["Posso ficar aqui?","Posso esperar aqui?","Posso entrar aqui?","Posso guardar isso aqui?"],"nivel":"B1","tags":["social","gramática"],"nota":"Cuidado com a resposta: «do you mind?» pergunta se incomoda, então «no» é o sim. Quem quer autorizar responde «no, go ahead» — e é a armadilha que mais confunde quem está aprendendo.","v":"4d0ce63f"},{"idioma":"en","id":"en-f200","tipo":"frase","en":"I'd rather stay home.","pt":"Prefiro ficar em casa.","aceitas":["prefiro ficar em casa","eu prefiro ficar em casa","acho melhor ficar em casa","prefiro ficar por aqui mesmo"],"aceitasEn":["id rather stay home","i would rather stay home","id rather stay at home"],"distratores":["Deveria ficar em casa.","Poderia ficar em casa.","Vou ficar em casa.","Consigo ficar em casa."],"nivel":"B1","tags":["gramática","casa"],"nota":"Depois de «would rather» o verbo vem sem «to»: «I'd rather stay». E o americano diz «stay home», sem preposição, enquanto o britânico prefere «stay at home» — as duas estão certas.","v":"d6c36daa"},{"idioma":"en","id":"en-f201","tipo":"frase","en":"It's worth a try.","pt":"Vale a tentativa.","aceitas":["vale a tentativa","vale a pena tentar","nao custa tentar","vale tentar"],"aceitasEn":["its worth a try","it is worth a try","its worth trying"],"distratores":["Vale o preço.","Vale a pena esperar.","Vale a espera.","Vale a viagem."],"nivel":"B1","tags":["expressão"],"nota":"É o que se diz antes de arriscar, quando a chance é pequena mas o custo também. Repare que o inglês usa o substantivo «a try» onde o português prefere o verbo, «vale a pena tentar».","v":"8e63eb4c"},{"idioma":"en","id":"en-f202","tipo":"frase","en":"That makes sense.","pt":"Faz sentido.","aceitas":["faz sentido","isso faz sentido","agora faz sentido","e logico"],"aceitasEn":["that makes sense","it makes sense"],"distratores":["Isso tem graça.","Isso tem valor.","Isso dá trabalho.","Isso tem jeito."],"nivel":"B1","tags":["expressão"],"nota":"Em inglês o sentido se faz: «make sense». O português diz que ele se faz também, e o espanhol que se tem. E «make sense of something» é conseguir entender: «I can't make sense of this».","v":"c2601e50"},{"idioma":"en","id":"en-f203","tipo":"frase","en":"I'm in a hurry.","pt":"Estou com pressa.","aceitas":["estou com pressa","to com pressa","estou apressado","estou sem tempo agora"],"aceitasEn":["im in a hurry","i am in a hurry"],"distratores":["Estou com fome.","Estou com sono.","Estou com medo.","Estou com frio."],"nivel":"B1","tags":["expressão","cotidiano"],"nota":"O inglês usa «to be» para estados que o português constrói com «estar com»: I'm hungry, I'm cold, I'm afraid, I'm in a hurry. Na direção contrária o erro é automático — «I have hunger» não existe.","v":"5821a43b"},{"idioma":"en","id":"en-f204","tipo":"frase","en":"Don't worry about it.","pt":"Não esquenta a cabeça.","aceitas":["nao esquenta a cabeca","nao esquenta","nao se preocupe","deixa isso pra la","nao precisa se preocupar"],"aceitasEn":["dont worry about it","do not worry about it","dont worry"],"distratores":["Não pense nisso agora.","Não fale disso agora.","Não mexa nisso.","Não pergunte isso."],"nivel":"B1","tags":["expressão","social"],"nota":"«Worry about» pede o «about» quando há objeto; sem objeto, «don't worry» sozinho vale e é o que mais se ouve. E «no worries» é a resposta australiana que virou mundial para «de nada».","v":"d99196ef"},{"idioma":"en","id":"en-f205","tipo":"frase","en":"It happens all the time.","pt":"Acontece toda hora.","aceitas":["acontece toda hora","isso acontece toda hora","acontece o tempo todo","acontece direto","isso acontece sempre"],"aceitasEn":["it happens all the time","that happens all the time"],"distratores":["Acontece de vez em quando.","Acontece uma vez por ano.","Aconteceu naquela hora.","Acontece na hora certa."],"nivel":"B1","tags":["expressão","gramática"],"nota":"Repare no artigo: é «all the time», com «the». Sem ele seria «all time», que quer dizer outra coisa — «de todos os tempos», como em «the best of all time».","v":"271db838"},{"idioma":"en","id":"en-f206","tipo":"frase","en":"I can't stand him.","pt":"Não suporto ele.","aceitas":["nao suporto ele","eu nao suporto ele","nao aguento ele","nao o suporto","nao aguento mais ele"],"aceitasEn":["i cant stand him","i can not stand him"],"distratores":["Não fico de pé perto dele.","Não consigo ficar em pé.","Não entendo ele.","Não confio nele."],"nivel":"B1","tags":["expressão","social"],"nota":"«Stand» aqui não é ficar de pé: é aguentar, e a imagem é a de quem não se mantém mais em pé diante daquilo. Vale para pessoa, comida e barulho — e sempre no negativo: «I can stand him» quase não se diz.","v":"27f7202e"},{"idioma":"en","id":"en-f207","tipo":"frase","en":"What's going on?","pt":"O que está acontecendo?","aceitas":["o que esta acontecendo","o que ta acontecendo","o que houve","o que foi","que que ta rolando"],"aceitasEn":["whats going on","what is going on"],"distratores":["Para onde está indo?","O que está funcionando?","Quando vai acontecer?","O que está por vir?"],"nivel":"B1","tags":["expressão","social"],"nota":"«Go on» é acontecer, e não seguir em frente — embora a ideia venha dali. Serve para perguntar o que houve numa sala agitada, e também para mandar alguém continuar: «go on, tell me».","v":"76b0b1fd"},{"idioma":"en","id":"en-f208","tipo":"frase","en":"Take care.","pt":"Se cuida.","aceitas":["se cuida","se cuide","cuide-se","fica bem","se cuida ai"],"aceitasEn":["take care","take care of yourself"],"distratores":["Toma cuidado com isso.","Cuida disso para mim.","Presta atenção.","Fica esperto."],"nivel":"B1","tags":["expressão","social"],"nota":"«Take care» sozinho é despedida carinhosa. Com objeto muda de ofício — «take care of the dog» é cuidar do cachorro —, e o aviso de perigo é outro: «be careful».","v":"c398c85c"},{"idioma":"en","id":"en-f209","tipo":"frase","en":"I'm having second thoughts.","pt":"Estou repensando.","aceitas":["estou repensando","comecei a duvidar","estou em duvida agora","estou pensando melhor","estou reconsiderando"],"aceitasEn":["im having second thoughts","i am having second thoughts"],"distratores":["Estou pensando duas vezes.","Tive duas ideias.","Estou pensando em outra coisa.","Mudei de ideia."],"nivel":"B2","tags":["expressão"],"nota":"«Second thoughts» são as dúvidas que chegam depois de a decisão já estar tomada. Não é mudar de ideia — é começar a duvidar da que já se tinha. E «on second thought», no singular, é «pensando bem».","v":"5d91c31a"},{"idioma":"en","id":"en-f210","tipo":"frase","en":"He's got a point.","pt":"Ele tem razão nisso.","aceitas":["ele tem razao nisso","ele tem um ponto","ele nao esta errado nisso","ate que ele tem razao","o argumento dele e bom"],"aceitasEn":["hes got a point","he has a point","he does have a point"],"distratores":["Ele marcou um ponto.","Ele apontou para lá.","Ele tem um objetivo.","Ele fez uma pergunta."],"nivel":"B2","tags":["expressão","social"],"nota":"«A point» aqui é o argumento, e «he's got a point» é conceder que o outro acertou numa coisa sem dar o braço a torcer no resto. O contrário é «that's beside the point»: isso não vem ao caso.","v":"6079acae"},{"idioma":"en","id":"en-f211","tipo":"frase","en":"I'll keep that in mind.","pt":"Vou ter isso em mente.","aceitas":["vou ter isso em mente","vou guardar isso","vou levar isso em conta","fico com isso na cabeca","vou lembrar disso"],"aceitasEn":["ill keep that in mind","i will keep that in mind","ill bear that in mind"],"distratores":["Vou manter a calma.","Vou guardar segredo.","Vou mudar de ideia.","Vou anotar no papel."],"nivel":"B2","tags":["expressão","social"],"nota":"«Keep in mind» é guardar a informação para usar depois, e é a resposta educada a um conselho que não se vai seguir agora. O britânico diz «bear in mind», com o mesmo sentido.","v":"19f12cda"},{"idioma":"en","id":"en-f212","tipo":"frase","en":"It's a done deal.","pt":"Já está fechado.","aceitas":["ja esta fechado","ja esta acertado","ja e coisa fechada","ja foi decidido","esta tudo acertado"],"aceitasEn":["its a done deal","it is a done deal"],"distratores":["É um bom negócio.","É um acordo caro.","Ainda está sendo negociado.","É um negócio arriscado."],"nivel":"B2","tags":["expressão","trabalho","economia"],"nota":"«A done deal» é o acordo já fechado, que não se discute mais. Diz-se de contrato, de contratação e de casamento — e quase sempre para encerrar a conversa de quem ainda queria opinar.","v":"fedca6e9"},{"idioma":"en","id":"en-f213","tipo":"frase","en":"We see eye to eye.","pt":"A gente concorda em tudo.","aceitas":["a gente concorda em tudo","nos concordamos","a gente se entende","estamos de acordo","a gente pensa igual"],"aceitasEn":["we see eye to eye","we see eye to eye on this"],"distratores":["A gente se olha nos olhos.","A gente fica cara a cara.","A gente se evita.","A gente briga sempre."],"nivel":"B2","tags":["expressão","social"],"nota":"Duas pessoas que veem na mesma altura veem a mesma coisa: é a imagem do acordo. Aparece muito no negativo — «we don't see eye to eye» é o jeito educado de dizer que os dois não se bicam.","v":"5bb46b85"},{"idioma":"en","id":"en-f214","tipo":"frase","en":"She pulls her weight.","pt":"Ela faz a parte dela.","aceitas":["ela faz a parte dela","ela da conta da parte dela","ela nao fica devendo nada","ela cumpre a parte dela"],"aceitasEn":["she pulls her weight","she pulls her own weight"],"distratores":["Ela puxa o peso sozinha.","Ela levanta o próprio peso.","Ela pesa mais do que parece.","Ela carrega todo mundo."],"nivel":"B2","tags":["expressão","trabalho"],"nota":"Vem do barco a remo: cada um puxa a parte do peso que lhe cabe. No trabalho é fazer a sua parte sem sobrecarregar os outros, e aparece muito no negativo — «he's not pulling his weight».","v":"1fefc20a"},{"idioma":"en","id":"en-f215","tipo":"frase","en":"He's a tough nut to crack.","pt":"Ele é osso duro de roer.","aceitas":["ele e osso duro de roer","ele e um osso duro de roer","ele e dificil de convencer","com ele nao e facil","ele e casca grossa"],"aceitasEn":["hes a tough nut to crack","he is a tough nut to crack"],"distratores":["Ele é uma noz difícil de abrir.","Ele quebra qualquer noz.","Ele é frágil por dentro.","Ele cede fácil demais."],"nivel":"C1","tags":["expressão","social"],"nota":"O inglês usa a noz onde o português usa o osso, e a imagem é a mesma: casca dura que resiste. Serve à pessoa teimosa e ao problema difícil, sem trocar de palavra.","v":"9fc1eb76"},{"idioma":"en","id":"en-f216","tipo":"frase","en":"That ship has sailed.","pt":"Esse trem já passou.","aceitas":["esse trem ja passou","o trem ja passou","essa oportunidade ja foi","ja perdeu a hora disso","agora e tarde para isso"],"aceitasEn":["that ship has sailed","that ships sailed"],"distratores":["O navio já zarpou do porto.","O navio ainda está atracado.","A viagem foi cancelada.","O plano ainda pode dar certo."],"nivel":"C1","tags":["expressão"],"nota":"O navio que já partiu não volta ao cais: é a chance que passou. O português e o espanhol usam o trem para dizer o mesmo, e o inglês fica com o barco — mesma ideia, outro meio de transporte.","v":"ec34043c"},{"idioma":"en","id":"en-f217","tipo":"frase","en":"Don't shoot the messenger.","pt":"Não é culpa de quem avisou.","aceitas":["nao e culpa de quem avisou","nao desconte em quem trouxe a noticia","eu so trouxe a noticia","nao mate o mensageiro","nao brigue com quem trouxe o recado"],"aceitasEn":["dont shoot the messenger","do not shoot the messenger"],"distratores":["Não atire no carteiro.","Não machuque o entregador.","Não acredite no que ele diz.","Não conte para ninguém."],"nivel":"C1","tags":["expressão","social"],"nota":"Vem da guerra antiga, quando o mensageiro que trazia a derrota podia pagar por ela. Hoje é o que se diz antes ou depois de dar uma notícia ruim que não se causou.","v":"1535b295"},{"idioma":"en","id":"en-f218","tipo":"frase","en":"Such was his anger that he left.","pt":"Tal era a raiva dele que foi embora.","aceitas":["tal era a raiva dele que foi embora","de tanta raiva ele foi embora","a raiva era tanta que ele foi embora","tamanha era a raiva dele que foi embora"],"aceitasEn":["such was his anger that he left"],"distratores":["A raiva dele foi embora.","Ele ficou com raiva e voltou.","A raiva veio depois que ele saiu.","Ele foi embora sem raiva nenhuma."],"nivel":"C2","tags":["gramática","formal"],"nota":"Inversão com «such»: o normal seria «his anger was such that…», e o registro formal joga o «such» para a frente e vira o verbo. Serve a qualquer substantivo — «such was the noise», «such is life», que é «assim é a vida».","v":"da016be0"},{"idioma":"en","id":"en-f219","tipo":"frase","en":"Only after he left did I understand.","pt":"Só entendi depois que ele saiu.","aceitas":["so entendi depois que ele saiu","so depois que ele saiu e que eu entendi","foi so depois que ele saiu que eu entendi","eu so fui entender depois que ele saiu"],"aceitasEn":["only after he left did i understand"],"distratores":["Só entendi antes de ele sair.","Ele saiu só depois que eu entendi.","Entendi na hora em que ele saiu.","Ele entendeu só depois que eu saí."],"nivel":"C2","tags":["gramática","formal"],"nota":"Depois de «only» no começo da frase, o inglês inverte o sujeito e o auxiliar: «did I understand». É a mesma regra de «never have I seen» e de «little did I know», e o gatilho é sempre uma palavra restritiva à frente.","v":"19eb7420"},{"idioma":"en","id":"en-f220","tipo":"frase","en":"What with the rain and the traffic, we were late.","pt":"Entre a chuva e o trânsito, atrasamos.","aceitas":["entre a chuva e o transito atrasamos","entre a chuva e o transito a gente atrasou","com a chuva e o transito a gente atrasou","por causa da chuva e do transito atrasamos"],"aceitasEn":["what with the rain and the traffic we were late"],"distratores":["Apesar da chuva e do trânsito, atrasamos.","Sem a chuva e o trânsito, atrasamos.","Depois da chuva e do trânsito, atrasamos.","Antes da chuva e do trânsito, atrasamos."],"nivel":"C2","tags":["gramática","formal"],"nota":"«What with» é fórmula fixa que apresenta causas acumuladas, quase sempre para explicar um atraso ou um cansaço. O «what» não pergunta nada, e o molde não aceita verbo depois — só substantivos em lista.","v":"2cbd9466"},{"idioma":"en","id":"en-f221","tipo":"frase","en":"He is not one to complain.","pt":"Ele não é de reclamar.","aceitas":["ele nao e de reclamar","ele nao e do tipo que reclama","ele nao costuma reclamar","reclamar nao e do feitio dele"],"aceitasEn":["he is not one to complain","hes not one to complain"],"distratores":["Ele não é o único que reclama.","Ele não é o primeiro a reclamar.","Ele não reclamou dessa vez.","Ele não é ninguém para reclamar."],"nivel":"C2","tags":["gramática","formal","social"],"nota":"«Not one to» descreve feitio, e não um episódio: é «não é de fazer isso». O «one» ali não é número nem indefinido comum — é «o tipo de pessoa que». E o positivo existe: «she's one to talk» é «olha quem fala».","v":"9cb7896e"},{"idioma":"en","id":"en-f222","tipo":"frase","en":"If anything, it got worse.","pt":"Se é que mudou, foi para pior.","aceitas":["se e que mudou foi para pior","se mudou foi para pior","se alguma coisa mudou foi para pior","na verdade ate piorou","se e que teve mudanca foi para pior"],"aceitasEn":["if anything it got worse"],"distratores":["Se acontecer qualquer coisa, piora.","Se algo piorou, foi por pouco.","Não piorou coisa nenhuma.","Tudo piorou, sem exceção."],"nivel":"C2","tags":["gramática","formal"],"nota":"«If anything» corrige o que o outro disse e aponta para o lado contrário: quem usa isso está negando a melhora e sugerindo a piora. Vai no começo da frase, com vírgula, e não aceita verbo depois.","v":"eb57fb12"},{"idioma":"en","id":"en-f223","tipo":"frase","en":"He was taken aback.","pt":"Ele ficou sem reação.","aceitas":["ele ficou sem reacao","ele ficou desconcertado","ele ficou pasmo","ele ficou sem saber o que dizer","ele ficou sem chao"],"aceitasEn":["he was taken aback","he was taken aback by it"],"distratores":["Ele foi levado para trás.","Ele foi carregado de volta.","Ele reagiu na hora.","Ele já esperava por isso."],"nivel":"C2","tags":["expressão","formal"],"nota":"«Aback» só existe nesta expressão, e veio da navegação: o vento batia de frente e jogava a vela para trás, parando o navio. É a surpresa que trava a pessoa, e vem quase sempre na passiva — «I was taken aback».","v":"f543d9bb"},{"idioma":"en","id":"en-f224","tipo":"frase","en":"Granted, it wasn't perfect.","pt":"É verdade que não foi perfeito.","aceitas":["e verdade que nao foi perfeito","reconheco que nao foi perfeito","admito que nao foi perfeito","concordo que nao foi perfeito","la isso e verdade nao foi perfeito"],"aceitasEn":["granted it wasnt perfect","granted it was not perfect"],"distratores":["Garantiram que não foi perfeito.","Foi concedido que não fosse perfeito.","Deram de presente, e não foi perfeito.","Negaram que não foi perfeito."],"nivel":"C2","tags":["gramática","formal"],"nota":"«Granted» sozinho, no começo da frase, é conceder o ponto do outro antes de discordar: «granted, it wasn't perfect, but…». É o particípio de «grant», conceder, que sobreviveu solto — e quase sempre vem com um «but» logo atrás.","v":"6d55c9b7"},{"idioma":"en","id":"en-v107","tipo":"frase","en":"I was tired.","pt":"Eu estava cansado.","aceitas":["eu estava cansado","estava cansado","eu tava cansado","eu estava exausto"],"aceitasEn":["i was tired"],"distratores":["Eu estou cansado.","Eu estarei cansado.","Eu estaria cansado.","Eu tinha ficado cansado."],"formasEn":{"I am tired":"presente","I will be tired":"futuro","I would be tired":"condicional","I had been tired":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","irregular","be","imperfeito"],"nota":"be, was/were, been — o verbo mais irregular do inglês, e o único que muda de forma no passado conforme a pessoa: «I was», «we were». Aqui ele traduz o «estar» do português; para «ser» é o mesmo verbo, e quem separa os dois é o contexto.","v":"1a793e58"},{"idioma":"en","id":"en-v108","tipo":"frase","en":"We had a good time.","pt":"A gente se divertiu.","aceitas":["a gente se divertiu","nos nos divertimos","a gente se divertiu muito","foi divertido","a gente curtiu"],"aceitasEn":["we had a good time"],"distratores":["A gente se diverte.","A gente vai se divertir.","A gente se divertiria.","A gente tinha se divertido."],"formasEn":{"We have a good time":"presente","We will have a good time":"futuro","We would have a good time":"condicional","We have had a good time":"pretérito perfeito"},"nivel":"A2","tags":["conjugação","irregular","have","pretérito","social"],"nota":"have, had, had. Além de possuir, «have» monta dezenas de expressões em que o português usa outros verbos: have a good time (divertir-se), have breakfast (tomar café), have a shower (tomar banho), have a baby (dar à luz).","v":"95389d74"},{"idioma":"en","id":"en-v109","tipo":"frase","en":"I did my homework.","pt":"Fiz a lição de casa.","aceitas":["fiz a licao de casa","eu fiz a licao de casa","fiz o dever de casa","fiz a tarefa de casa"],"aceitasEn":["i did my homework"],"distratores":["Faço a lição de casa.","Farei a lição de casa.","Faria a lição de casa.","Tinha feito a lição de casa."],"formasEn":{"I do my homework":"presente","I will do my homework":"futuro","I would do my homework":"condicional","I had done my homework":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","irregular","do","pretérito","escola"],"nota":"do, did, done. O verbo trabalha dobrado em inglês: é «fazer» e é também o auxiliar das perguntas e das negativas — «do you know?», «I don't know». E «homework» não tem plural: nunca «homeworks».","v":"6aef4b57"},{"idioma":"en","id":"en-v110","tipo":"frase","en":"She said nothing.","pt":"Ela não disse nada.","aceitas":["ela nao disse nada","nao disse nada","ela ficou calada","ela nao falou nada"],"aceitasEn":["she said nothing","she didnt say anything"],"distratores":["Ela não diz nada.","Ela não dirá nada.","Ela não diria nada.","Ela não tinha dito nada."],"formasEn":{"She says nothing":"presente","She will say nothing":"futuro","She would say nothing":"condicional","She had said nothing":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","irregular","say","pretérito"],"nota":"say, said, said — e o passado se pronuncia «sed», e não «seid». Repare na negação: o inglês nega uma vez só, dentro de «nothing», e o verbo fica no afirmativo. «She didn't say nothing» é erro de gramática, embora se ouça na fala.","v":"b19988f0"},{"idioma":"en","id":"en-v111","tipo":"frase","en":"I learned it fast.","pt":"Aprendi rápido.","aceitas":["aprendi rapido","eu aprendi rapido","aprendi depressa","peguei rapido"],"aceitasEn":["i learned it fast"],"distratores":["Aprendo rápido.","Aprenderei rápido.","Aprenderia rápido.","Tinha aprendido rápido."],"formasEn":{"I learn it fast":"presente","I will learn it fast":"futuro","I would learn it fast":"condicional","I had learned it fast":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","irregular","learn","pretérito","escola"],"nota":"learn, learned, learned nos Estados Unidos; learnt na Inglaterra. É o mesmo par de burn, spell, smell, spill e dream — seis verbos que o americano regularizou e o britânico guardou com «t».","regionaisEn":{"i learnt it fast":"na Inglaterra"},"v":"3bf0f56c"},{"idioma":"en","id":"en-v112","tipo":"frase","en":"The garbage stank.","pt":"O lixo fedia.","aceitas":["o lixo fedia","o lixo estava fedendo","o lixo cheirava mal","o lixo tava fedido"],"aceitasEn":["the garbage stank","the garbage stunk"],"distratores":["O lixo fede.","O lixo vai feder.","O lixo federia.","O lixo tinha fedido."],"formasEn":{"The garbage stinks":"presente","The garbage will stink":"futuro","The garbage would stink":"condicional","The garbage had stunk":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","stink","imperfeito","casa"],"nota":"stink, stank, stunk — mesmo desenho de drink e de sink. É bem mais forte que «smell bad», e serve ao figurado: «this whole thing stinks» é «essa história toda está mal contada».","v":"67335b24"},{"idioma":"en","id":"en-v113","tipo":"frase","en":"I dreamed about you.","pt":"Sonhei com você.","aceitas":["sonhei com voce","eu sonhei com voce","sonhei contigo","eu sonhei contigo"],"aceitasEn":["i dreamed about you","i dreamed of you"],"distratores":["Sonho com você.","Sonharei com você.","Sonharia com você.","Tinha sonhado com você."],"formasEn":{"I dream about you":"presente","I will dream about you":"futuro","I would dream about you":"condicional","I had dreamed about you":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","dream","pretérito"],"nota":"dream, dreamed, dreamed nos Estados Unidos; dreamt na Inglaterra. E a preposição muda o tom: «dream about» é o sonho da noite, e «dream of» é o sonho de vida — «I dream of being a pilot».","regionaisEn":{"i dreamt about you":"na Inglaterra"},"v":"20399efe"},{"idioma":"en","id":"en-v114","tipo":"frase","en":"I overslept this morning.","pt":"Perdi a hora hoje de manhã.","aceitas":["perdi a hora hoje de manha","eu perdi a hora hoje de manha","dormi demais hoje de manha","acordei tarde hoje de manha","perdi a hora de manha"],"aceitasEn":["i overslept this morning","i overslept"],"distratores":["Perco a hora toda manhã.","Vou perder a hora de manhã.","Perderia a hora de manhã.","Tinha perdido a hora de manhã."],"formasEn":{"I oversleep every morning":"presente","I will oversleep tomorrow":"futuro","I would oversleep in the morning":"condicional","I had overslept that morning":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","oversleep","pretérito","cotidiano"],"nota":"oversleep, overslept, overslept — conjuga como «sleep», que está dentro dele. O prefixo «over-» é o de passar da conta, o mesmo de overeat, overpay e overdo. Um verbo só para o que o português resolve com três palavras.","v":"4af1fb07"},{"idioma":"en","id":"en-v115","tipo":"frase","en":"She misunderstood the question.","pt":"Ela entendeu a pergunta errado.","aceitas":["ela entendeu a pergunta errado","ela entendeu errado a pergunta","ela nao entendeu bem a pergunta","ela interpretou mal a pergunta"],"aceitasEn":["she misunderstood the question"],"distratores":["Ela entende a pergunta errado.","Ela entenderá a pergunta errado.","Ela entenderia a pergunta errado.","Ela tinha entendido a pergunta errado."],"formasEn":{"She misunderstands the question":"presente","She will misunderstand the question":"futuro","She would misunderstand the question":"condicional","She had misunderstood the question":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","misunderstand","pretérito","gramática"],"nota":"misunderstand, misunderstood, misunderstood — conjuga como «stand», que está lá dentro. O prefixo «mis-» é o do erro e rende muito: misread, misspell, mishear, misplace, mistake. Um prefixo só onde o português precisa de «mal» ou de «errado».","v":"b67ae577"},{"idioma":"en","id":"en-v116","tipo":"frase","en":"My ankle swelled up.","pt":"Meu tornozelo inchou.","aceitas":["meu tornozelo inchou","meu tornozelo ficou inchado","inchou meu tornozelo","o tornozelo inchou"],"aceitasEn":["my ankle swelled up","my ankle swelled"],"distratores":["Meu tornozelo incha.","Meu tornozelo vai inchar.","Meu tornozelo incharia.","Meu tornozelo tinha inchado."],"formasEn":{"My ankle swells up":"presente","My ankle will swell up":"futuro","My ankle would swell up":"condicional","My ankle had swollen up":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","swell","pretérito","saúde","corpo"],"nota":"swell, swelled, swollen — o passado é regular e o particípio não, e é o particípio que virou adjetivo: «a swollen ankle». Na gíria americana antiga «swell» queria dizer ótimo, e ainda aparece em filme velho.","v":"619f4886"},{"idioma":"en","id":"en-v117","tipo":"frase","en":"He leaned against the wall.","pt":"Ele se encostou na parede.","aceitas":["ele se encostou na parede","ele encostou na parede","ele se apoiou na parede","ele ficou encostado na parede"],"aceitasEn":["he leaned against the wall"],"distratores":["Ele se encosta na parede.","Ele vai se encostar na parede.","Ele se encostaria na parede.","Ele tinha se encostado na parede."],"formasEn":{"He leans against the wall":"presente","He will lean against the wall":"futuro","He would lean against the wall":"condicional","He had leaned against the wall":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","lean","pretérito","corpo"],"nota":"lean, leaned, leaned nos Estados Unidos; leant na Inglaterra. A preposição é «against» quando há apoio físico, e «on» quando se depende de alguém: «lean on me» é «conte comigo».","regionaisEn":{"he leant against the wall":"na Inglaterra"},"v":"b6a9d476"},{"idioma":"en","id":"en-v118","tipo":"frase","en":"She sewed a button on.","pt":"Ela pregou um botão.","aceitas":["ela pregou um botao","ela costurou um botao","pregou um botao","ela costurou um botao na roupa"],"aceitasEn":["she sewed a button on","she sewed on a button"],"distratores":["Ela prega um botão.","Ela vai pregar um botão.","Ela pregaria um botão.","Ela tinha pregado um botão."],"formasEn":{"She sews a button on":"presente","She will sew a button on":"futuro","She would sew a button on":"condicional","She had sewn a button on":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","sew","pretérito","roupa"],"nota":"sew, sewed, sewn — e o «ew» soa como o «o» de «so», e não como em «new». A máquina de costura é «sewing machine». Cuidado com o par de escrita: «sow», semear, é outro verbo e soa exatamente igual.","v":"dd8d613c"},{"idioma":"en","id":"en-v119","tipo":"frase","en":"He lent me his car.","pt":"Ele me emprestou o carro.","aceitas":["ele me emprestou o carro","me emprestou o carro","ele emprestou o carro dele para mim","ele me emprestou o carro dele"],"aceitasEn":["he lent me his car"],"distratores":["Ele me empresta o carro.","Ele vai me emprestar o carro.","Ele me emprestaria o carro.","Ele tinha me emprestado o carro."],"formasEn":{"He lends me his car":"presente","He will lend me his car":"futuro","He would lend me his car":"condicional","He had lent me his car":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","lend","pretérito","viagem"],"nota":"lend, lent, lent — mesmo molde de send/sent e spend/spent. Quem dá usa «lend» e quem pega usa «borrow»: são duas palavras diferentes para as duas pontas do mesmo empréstimo.","v":"623ed1ea"},{"idioma":"en","id":"en-v120","tipo":"frase","en":"I've never been to Japan.","pt":"Nunca fui ao Japão.","aceitas":["nunca fui ao japao","eu nunca fui ao japao","nunca estive no japao","nunca fui para o japao"],"aceitasEn":["ive never been to japan","i have never been to japan"],"distratores":["Nunca vou ao Japão.","Nunca irei ao Japão.","Nunca iria ao Japão.","Nunca tinha ido ao Japão."],"formasEn":{"I never go to Japan":"presente","I will never go to Japan":"futuro","I would never go to Japan":"condicional","I had never been to Japan":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","be","present perfect","viagem"],"nota":"«Have been to» é ter ido e voltado; «have gone to» é ter ido e ainda estar lá. O present perfect serve à experiência de vida, sem data marcada — e é por isso que combina tão bem com «never» e «ever».","v":"4a2805c9"},{"idioma":"en","id":"en-v121","tipo":"frase","en":"I was watching TV when he called.","pt":"Eu estava vendo TV quando ele ligou.","aceitas":["eu estava vendo tv quando ele ligou","estava vendo tv quando ele ligou","eu tava vendo televisao quando ele ligou","eu estava assistindo tv quando ele ligou"],"aceitasEn":["i was watching tv when he called"],"distratores":["Eu vejo TV quando ele liga.","Eu verei TV quando ele ligar.","Eu veria TV se ele ligasse.","Eu tinha visto TV quando ele ligou."],"formasEn":{"I watch TV when he calls":"presente","I will watch TV when he calls":"futuro","I would watch TV if he called":"condicional","I had watched TV when he called":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","regular","watch","imperfeito","cotidiano"],"nota":"O passado contínuo é o pano de fundo e o passado simples é o que corta: «I was watching» dura, «he called» acontece num ponto. É o par com que o inglês conta qualquer história, e o português resolve com imperfeito e pretérito.","v":"06941f2c"},{"idioma":"en","id":"en-v122","tipo":"frase","en":"The cat leapt onto the table.","pt":"O gato pulou na mesa.","aceitas":["o gato pulou na mesa","o gato saltou na mesa","o gato pulou em cima da mesa","o gato deu um pulo na mesa"],"aceitasEn":["the cat leapt onto the table","the cat leaped onto the table"],"distratores":["O gato pula na mesa.","O gato vai pular na mesa.","O gato pularia na mesa.","O gato tinha pulado na mesa."],"formasEn":{"The cat leaps onto the table":"presente","The cat will leap onto the table":"futuro","The cat would leap onto the table":"condicional","The cat had leapt onto the table":"mais-que-perfeito"},"nivel":"B2","tags":["conjugação","irregular","leap","pretérito","animais"],"nota":"leap, leapt, leapt — e «leaped» também vale. É o pulo largo e decidido, mais forte que «jump», e aparece no ano bissexto: «leap year», o ano que dá um salto de um dia.","v":"d9b8d1d6"},{"idioma":"en","id":"en-v123","tipo":"frase","en":"The road wound through the hills.","pt":"A estrada serpenteava entre os morros.","aceitas":["a estrada serpenteava entre os morros","a estrada fazia curvas entre os morros","a estrada ia sinuosa entre os morros","a estrada subia fazendo curvas pelos morros"],"aceitasEn":["the road wound through the hills"],"distratores":["A estrada serpenteia entre os morros.","A estrada serpenteará entre os morros.","A estrada serpentearia entre os morros.","A estrada tinha serpenteado entre os morros."],"formasEn":{"The road winds through the hills":"presente","The road will wind through the hills":"futuro","The road would wind through the hills":"condicional","The road had wound through the hills":"mais-que-perfeito"},"nivel":"B2","tags":["conjugação","irregular","wind","imperfeito","viagem"],"nota":"wind, wound, wound — e este «wind» rima com «find», e não com o vento «wind», que é outra palavra e soa diferente. O passado «wound» se escreve igual à ferida, e também não tem parentesco nenhum com ela.","v":"db02dfda"},{"idioma":"en","id":"en-v124","tipo":"frase","en":"They forbade him to leave.","pt":"Proibiram que ele saísse.","aceitas":["proibiram que ele saisse","proibiram ele de sair","nao deixaram ele sair","proibiram a saida dele"],"aceitasEn":["they forbade him to leave","they forbade him from leaving"],"distratores":["Proíbem que ele saia.","Proibirão que ele saia.","Proibiriam que ele saísse.","Tinham proibido que ele saísse."],"formasEn":{"They forbid him to leave":"presente","They will forbid him to leave":"futuro","They would forbid him to leave":"condicional","They had forbidden him to leave":"mais-que-perfeito"},"nivel":"B2","tags":["conjugação","irregular","forbid","pretérito","jurídico"],"nota":"forbid, forbade, forbidden — e o passado se pronuncia «for-BAD». O particípio virou adjetivo famoso: «forbidden fruit», o fruto proibido. Na conversa se prefere a volta mais longa, «they wouldn't let him leave».","v":"637f6f69"},{"idioma":"en","id":"en-v125","tipo":"frase","en":"The ad misled the public.","pt":"O anúncio enganou o público.","aceitas":["o anuncio enganou o publico","a propaganda enganou o publico","o anuncio induziu o publico ao erro","o anuncio levou o publico a erro"],"aceitasEn":["the ad misled the public"],"distratores":["O anúncio engana o público.","O anúncio enganará o público.","O anúncio enganaria o público.","O anúncio tinha enganado o público."],"formasEn":{"The ad misleads the public":"presente","The ad will mislead the public":"futuro","The ad would mislead the public":"condicional","The ad had misled the public":"mais-que-perfeito"},"nivel":"B2","tags":["conjugação","irregular","mislead","pretérito","mídia"],"nota":"mislead, misled, misled — conjuga como «lead», que está dentro dele, e o passado se escreve com um «e» só. É o engano por informação torta, e não a mentira direta; o adjetivo «misleading» é a palavra do processo contra propaganda enganosa.","v":"97a63058"},{"idioma":"en","id":"en-v126","tipo":"frase","en":"The car sped past us.","pt":"O carro passou voando por nós.","aceitas":["o carro passou voando por nos","o carro passou em alta velocidade por nos","o carro passou disparado por nos","o carro passou zunindo por nos"],"aceitasEn":["the car sped past us"],"distratores":["O carro passa voando por nós.","O carro passará voando por nós.","O carro passaria voando por nós.","O carro tinha passado voando por nós."],"formasEn":{"The car speeds past us":"presente","The car will speed past us":"futuro","The car would speed past us":"condicional","The car had sped past us":"mais-que-perfeito"},"nivel":"B2","tags":["conjugação","irregular","speed","pretérito","viagem"],"nota":"speed, sped, sped — mas quando o sentido é acelerar de propósito, o verbo fica regular: «the process was speeded up». E «speeding» é a infração de excesso de velocidade, a multa mais comum dos Estados Unidos.","v":"ae1fd2a0"},{"idioma":"en","id":"en-p141","tipo":"palavra","en":"the door","pt":"a porta","aceitas":["a porta","porta","as portas"],"aceitasEn":["the door","door","a door"],"distratores":["o portão","a parede","a entrada","a escada"],"nivel":"A1","tags":["substantivo","casa"],"nota":"«Door» é a porta de casa e a do carro; o portão da rua é «gate». E a palavra entra em conta de endereço: «two doors down» é «duas casas adiante», e «next door» é o vizinho de parede.","v":"dea7e586"},{"idioma":"en","id":"en-u141","tipo":"frase","requer":"en-p141","en":"Someone's at the door.","pt":"Tem alguém na porta.","aceitas":["tem alguem na porta","ha alguem na porta","tem gente na porta","tem alguem batendo na porta","tem alguem la na porta"],"aceitasEn":["someones at the door","someone is at the door"],"distratores":["Tem alguém na janela.","Tem alguém na garagem.","Tem alguém no telefone.","Tem alguém na calçada."],"nivel":"A1","tags":["substantivo","casa","cotidiano"],"nota":"A preposição é «at», e não «in»: quem está «at the door» está do lado de fora, esperando. «In the door» seria dentro do vão da porta, entalado — e é o que ninguém quer dizer.","v":"33918f80"},{"idioma":"en","id":"en-p142","tipo":"palavra","en":"the hand","pt":"a mão","aceitas":["a mao","mao","as maos"],"aceitasEn":["the hand","hand","a hand"],"distratores":["o braço","o dedo","o punho","o cotovelo"],"nivel":"A1","tags":["substantivo","corpo"],"nota":"«Hand» é só a mão; o braço é «arm», e o inglês separa os dois com rigor onde o português às vezes junta. O ponteiro do relógio também é «hand», e daí «the hour hand», o ponteiro das horas.","v":"dae18a28"},{"idioma":"en","id":"en-u142","tipo":"frase","requer":"en-p142","en":"He raised his hand.","pt":"Ele levantou a mão.","aceitas":["ele levantou a mao","levantou a mao","ele ergueu a mao","ele pos a mao para cima"],"aceitasEn":["he raised his hand","he put his hand up"],"distratores":["Ele levantou o braço.","Ele levantou a cabeça.","Ele levantou o copo.","Ele levantou a voz."],"nivel":"A1","tags":["substantivo","corpo","escola"],"nota":"O inglês põe o possessivo onde o português põe o artigo: «his hand», e não «the hand». Vale para todo o corpo — he broke his leg, she washed her face —, e soar estranho ao ouvido português é o preço.","v":"fec4da07"},{"idioma":"en","id":"en-p143","tipo":"palavra","en":"the street","pt":"a rua","aceitas":["a rua","rua","as ruas"],"aceitasEn":["the street","street","a street"],"distratores":["a esquina","a praça","a estrada","a ponte"],"nivel":"A1","tags":["substantivo","cidade"],"nota":"«Street» é a rua da cidade; a estrada entre cidades é «road», e a avenida larga é «avenue». No endereço americano a palavra vira abreviatura: «Main St.». E «on the street» é na rua, sem teto.","v":"ac6c855c"},{"idioma":"en","id":"en-u143","tipo":"frase","requer":"en-p143","en":"I live on this street.","pt":"Eu moro nesta rua.","aceitas":["eu moro nesta rua","moro nesta rua","eu moro nessa rua","eu moro aqui nesta rua"],"aceitasEn":["i live on this street","i live in this street"],"distratores":["Eu moro nesta praça.","Eu moro nesta esquina.","Eu moro neste prédio.","Eu moro neste bairro."],"nivel":"A1","tags":["substantivo","cidade","cotidiano"],"nota":"O americano diz «on this street» e o britânico, «in this street» — as duas estão certas, cada uma do seu lado do mar. E o verbo «live» é «morar»: «where do you live?» é a pergunta, não «where do you inhabit».","v":"4bf78831"},{"idioma":"en","id":"en-p144","tipo":"palavra","en":"the rain","pt":"a chuva","aceitas":["a chuva","chuva"],"aceitasEn":["the rain","rain","some rain"],"distratores":["o vento","a neve","a nuvem","o trovão"],"nivel":"A1","tags":["substantivo"],"nota":"«Rain» é substantivo e é verbo: «it rains» é chove, e o sujeito «it» é obrigatório mesmo sem querer dizer nada. A capa de chuva é «raincoat», e o arco-íris é «rainbow» — o arco da chuva.","v":"6a4851cc"},{"idioma":"en","id":"en-u144","tipo":"frase","requer":"en-p144","en":"The rain stopped.","pt":"A chuva parou.","aceitas":["a chuva parou","parou de chover","a chuva ja parou","a chuva deu uma parada"],"aceitasEn":["the rain stopped","the rain has stopped"],"distratores":["A chuva aumentou.","A chuva voltou.","A chuva molhou tudo.","A chuva atrapalhou o jogo."],"nivel":"A1","tags":["substantivo","cotidiano"],"nota":"Aqui «rain» é o sujeito e leva artigo: «the rain stopped», a chuva que estava caindo. Sem artigo seria chuva em geral, como em «rain is good for the garden».","v":"434c86f3"},{"idioma":"en","id":"en-p145","tipo":"palavra","en":"the name","pt":"o nome","aceitas":["o nome","nome","os nomes"],"aceitasEn":["the name","name","a name"],"distratores":["o apelido","a assinatura","o título","o endereço"],"nivel":"A1","tags":["substantivo","social"],"nota":"«Name» é o nome, e o inglês reparte o nosso «nome completo» em três: «first name» é o de batismo, «last name» ou «surname» é o de família, e «middle name» é o do meio, que quase todo americano tem.","v":"821b665d"},{"idioma":"en","id":"en-u145","tipo":"frase","requer":"en-p145","en":"What's your last name?","pt":"Qual é o seu sobrenome?","aceitas":["qual e o seu sobrenome","qual e seu sobrenome","qual o seu sobrenome","como e o seu sobrenome"],"aceitasEn":["whats your last name","what is your last name","whats your surname"],"distratores":["Qual é o seu apelido?","Qual é o seu endereço?","Qual é o seu telefone?","Qual é o seu cargo?"],"nivel":"A1","tags":["substantivo","social","viagem"],"nota":"«Last name» é o sobrenome, e é o que se pede em formulário e em balcão de hotel. Cuidado com a pergunta: é «what», e não «which» — «which is your name» soaria como escolher entre uma lista.","v":"73641ead"},{"idioma":"en","id":"en-p146","tipo":"palavra","en":"the head","pt":"a cabeça","aceitas":["a cabeca","cabeca","as cabecas"],"aceitasEn":["the head","head","a head"],"distratores":["o pescoço","o rosto","a testa","o ombro"],"nivel":"A1","tags":["substantivo","corpo"],"nota":"«Head» é a cabeça e é também quem chefia: «the head of the department». Como verbo é ir em direção a alguma coisa — «we're heading home» —, e daí «heading», o título que encabeça o texto.","v":"aceeafa2"},{"idioma":"en","id":"en-u146","tipo":"frase","requer":"en-p146","en":"My head hurts.","pt":"Minha cabeça está doendo.","aceitas":["minha cabeca esta doendo","minha cabeca doi","estou com dor de cabeca","ta doendo minha cabeca","minha cabeca ta doendo"],"aceitasEn":["my head hurts","i have a headache"],"distratores":["Minha garganta está doendo.","Minha barriga está doendo.","Minha perna está doendo.","Minha mão está doendo."],"nivel":"A1","tags":["substantivo","corpo","saúde"],"nota":"O inglês faz a parte do corpo ser o sujeito: «my head hurts», a cabeça é que dói. O português faz igual, e o espanhol vira a frase ao contrário com o «me duele». E «a headache» resolve tudo numa palavra só.","v":"634d4917"},{"idioma":"en","id":"en-p147","tipo":"palavra","en":"the knee","pt":"o joelho","aceitas":["o joelho","joelho","os joelhos"],"aceitasEn":["the knee","knee","a knee"],"distratores":["o cotovelo","a coxa","a canela","o tornozelo"],"nivel":"A2","tags":["substantivo","corpo"],"nota":"«Knee» tem o «k» mudo, como em knife, knock e know. O verbo derivado é «kneel», ajoelhar-se, e «on your knees» é de joelhos. A rótula é «kneecap» — a tampa do joelho.","v":"1858c50d"},{"idioma":"en","id":"en-u147","tipo":"frase","requer":"en-p147","en":"I hurt my knee.","pt":"Machuquei o joelho.","aceitas":["machuquei o joelho","eu machuquei o joelho","machuquei meu joelho","ralei o joelho"],"aceitasEn":["i hurt my knee","i hurt my knee badly"],"distratores":["Machuquei o pé.","Machuquei o braço.","Machuquei o dedo.","Machuquei as costas."],"nivel":"A2","tags":["substantivo","corpo","saúde"],"nota":"«Hurt» é o verbo que não muda: hurt, hurt, hurt. E serve aos dois lados — «I hurt my knee» é eu machuquei, e «my knee hurts» é ele dói. O sujeito decide qual dos dois.","v":"023ca4ae"},{"idioma":"en","id":"en-p148","tipo":"palavra","en":"the shoulder","pt":"o ombro","aceitas":["o ombro","ombro","os ombros"],"aceitasEn":["the shoulder","shoulder","a shoulder"],"distratores":["o cotovelo","o pescoço","o peito","o quadril"],"nivel":"A2","tags":["substantivo","corpo"],"nota":"«Shoulder» é o ombro, e é também o acostamento da estrada: «pull over onto the shoulder». E «a shoulder to cry on» é o ombro amigo, com a mesma imagem do português.","v":"04cc3744"},{"idioma":"en","id":"en-u148","tipo":"frase","requer":"en-p148","en":"He shrugged his shoulders.","pt":"Ele deu de ombros.","aceitas":["ele deu de ombros","deu de ombros","ele levantou os ombros","ele fez que nao sabia com os ombros"],"aceitasEn":["he shrugged his shoulders","he shrugged"],"distratores":["Ele cruzou os braços.","Ele balançou a cabeça.","Ele bateu o pé.","Ele estalou os dedos."],"nivel":"A2","tags":["substantivo","corpo","social"],"nota":"«Shrug» já traz os ombros dentro, e por isso «he shrugged», sozinho, basta. O gesto quer dizer «não sei» ou «tanto faz», e o emoji dele virou palavra escrita no inglês da internet.","v":"c61e2934"},{"idioma":"en","id":"en-p149","tipo":"palavra","en":"the ankle","pt":"o tornozelo","aceitas":["o tornozelo","tornozelo","os tornozelos"],"aceitasEn":["the ankle","ankle","an ankle"],"distratores":["o pulso","o calcanhar","a panturrilha","o joelho"],"nivel":"A2","tags":["substantivo","corpo"],"nota":"«Ankle» é o tornozelo. A calça que para ali é «ankle-length», e a tornozeleira eletrônica é «ankle monitor». O calcanhar, logo abaixo, é «heel» — a mesma palavra do salto do sapato.","v":"93925bd7"},{"idioma":"en","id":"en-u149","tipo":"frase","requer":"en-p149","en":"I twisted my ankle.","pt":"Torci o tornozelo.","aceitas":["torci o tornozelo","eu torci o tornozelo","torci meu tornozelo","dei uma torcida no tornozelo"],"aceitasEn":["i twisted my ankle","i sprained my ankle"],"distratores":["Torci o pescoço.","Torci o pulso.","Torci o joelho.","Torci o dedo."],"nivel":"A2","tags":["substantivo","corpo","saúde"],"nota":"«Twist» é torcer de leve e «sprain» é a torção com lesão, que precisa de gelo. Na conversa se usam quase como sinônimos, e no pronto-socorro não: ali a diferença muda o diagnóstico.","v":"532d382f"},{"idioma":"en","id":"en-p150","tipo":"palavra","en":"the wrist","pt":"o pulso","aceitas":["o pulso","pulso","os pulsos"],"aceitasEn":["the wrist","wrist","a wrist"],"distratores":["o cotovelo","a palma","o antebraço","o nó do dedo"],"nivel":"A2","tags":["substantivo","corpo"],"nota":"«Wrist» é o pulso do braço; a pulsação que o médico conta é «pulse», outra palavra. O relógio é «wristwatch», e o «w» do começo é mudo, como em write e wrong.","v":"9f43f65c"},{"idioma":"en","id":"en-u150","tipo":"frase","requer":"en-p150","en":"He broke his wrist.","pt":"Ele quebrou o pulso.","aceitas":["ele quebrou o pulso","quebrou o pulso","ele fraturou o pulso","ele quebrou o pulso dele"],"aceitasEn":["he broke his wrist"],"distratores":["Ele quebrou o braço.","Ele quebrou a perna.","Ele quebrou o dedo.","Ele quebrou o nariz."],"nivel":"A2","tags":["substantivo","corpo","saúde"],"nota":"O inglês diz «broke his wrist», com possessivo, e não «broke the wrist». É a mesma regra de toda parte do corpo, e ela vale inclusive quando o dono é óbvio.","v":"4767289c"},{"idioma":"en","id":"en-p151","tipo":"palavra","en":"the thumb","pt":"o polegar","aceitas":["o polegar","polegar","o dedao","o dedo polegar"],"aceitasEn":["the thumb","thumb","a thumb"],"distratores":["o indicador","o mindinho","a unha","a palma"],"nivel":"A2","tags":["substantivo","corpo"],"nota":"«Thumb» é só o polegar, e o inglês não o conta como «finger»: são quatro fingers e um thumb. O «b» é mudo, como em comb e climb. E «thumbs up» é o joinha.","v":"9fe5a867"},{"idioma":"en","id":"en-u151","tipo":"frase","requer":"en-p151","en":"He gave me a thumbs up.","pt":"Ele me fez um joinha.","aceitas":["ele me fez um joinha","ele fez um joinha para mim","ele me deu um joinha","ele levantou o polegar para mim"],"aceitasEn":["he gave me a thumbs up","he gave me the thumbs up"],"distratores":["Ele me fez um aceno.","Ele me fez uma careta.","Ele me fez um sinal de pare.","Ele me fez uma reverência."],"nivel":"A2","tags":["substantivo","corpo","social"],"nota":"«A thumbs up» anda no plural mesmo com um polegar só, e leva artigo no singular — é uma dessas expressões que o inglês congelou torta e ninguém conserta.","v":"8f892cc6"},{"idioma":"en","id":"en-p152","tipo":"palavra","en":"the chin","pt":"o queixo","aceitas":["o queixo","queixo","o mento"],"aceitasEn":["the chin","chin","a chin"],"distratores":["a testa","a bochecha","o pescoço","o lábio"],"nivel":"A2","tags":["substantivo","corpo"],"nota":"«Chin» é o queixo, e o «ch» soa como em «church». A papada é «double chin», e a barba que cobre só o queixo é «goatee». Não confunda com «cheek», que é a bochecha.","v":"ca96e260"},{"idioma":"en","id":"en-u152","tipo":"frase","requer":"en-p152","en":"Keep your chin up.","pt":"Cabeça erguida.","aceitas":["cabeca erguida","mantenha a cabeca erguida","nao desanime","levanta essa cabeca","cabeca em pe"],"aceitasEn":["keep your chin up","chin up"],"distratores":["Cabeça baixa.","Braços cruzados.","Peito estufado.","Olhos abertos."],"nivel":"A2","tags":["substantivo","corpo","social"],"nota":"O inglês levanta o queixo onde o português levanta a cabeça — o gesto é o mesmo e a parte do corpo muda. Diz-se para consolar alguém que está para baixo, e vale sozinho: «chin up!».","v":"45d2f8d8"},{"idioma":"en","id":"en-p153","tipo":"palavra","en":"the stove","pt":"o fogão","aceitas":["o fogao","fogao","a boca do fogao"],"aceitasEn":["the stove","stove","a stove"],"distratores":["a geladeira","a pia","o forno","a chaleira"],"nivel":"A2","tags":["substantivo","casa","comida"],"nota":"«Stove» é o fogão de boca, e o forno é «oven» — duas palavras onde o português tem uma só para o móvel inteiro. E «on the stove» é na boca do fogão, com a panela em cima.","v":"c8f68eaa"},{"idioma":"en","id":"en-u153","tipo":"frase","requer":"en-p153","en":"The pot is on the stove.","pt":"A panela está no fogão.","aceitas":["a panela esta no fogao","a panela ta no fogao","a panela esta em cima do fogao","a panela esta no fogo"],"aceitasEn":["the pot is on the stove"],"distratores":["A panela está na pia.","A panela está no forno.","A panela está na mesa.","A panela está no armário."],"nivel":"A2","tags":["substantivo","casa","comida"],"nota":"A panela fica «on the stove», em cima, e nunca «in». Dentro do forno é que se diz «in the oven» — e é a mesma lógica de «on the table» contra «in the drawer».","v":"4fc81d95"},{"idioma":"en","id":"en-p154","tipo":"palavra","en":"to whisper","pt":"sussurrar","aceitas":["sussurrar","cochichar","falar baixinho","falar no pe do ouvido"],"aceitasEn":["to whisper","whisper"],"distratores":["gritar","bocejar","assobiar","gaguejar"],"nivel":"A2","tags":["verbo","social"],"nota":"«Whisper» é falar sem voz, só com o ar. No inglês americano o «wh» soa como um «w» simples. E a palavra serve ao boato: «there are whispers about a merger» é «corre um boato».","v":"d849be2a"},{"idioma":"en","id":"en-u154","tipo":"frase","requer":"en-p154","en":"Stop whispering.","pt":"Para de sussurrar.","aceitas":["para de sussurrar","pare de sussurrar","para de cochichar","chega de cochicho","para de falar baixinho"],"aceitasEn":["stop whispering","stop whispering please"],"distratores":["Para de gritar.","Para de assobiar.","Para de bocejar.","Para de resmungar."],"nivel":"A2","tags":["verbo","social","escola"],"nota":"Depois de «stop» vem o verbo em -ing quando se manda parar a ação: «stop whispering». Com infinitivo a frase muda de sentido e passa a ser «parou para sussurrar» — o mesmo par de «stop smoking».","v":"fe8f9ba8"},{"idioma":"en","id":"en-p155","tipo":"palavra","en":"to swallow","pt":"engolir","aceitas":["engolir","tragar","deglutir","engolir em seco"],"aceitasEn":["to swallow","swallow"],"distratores":["mastigar","cuspir","morder","lamber"],"nivel":"A2","tags":["verbo","comida","corpo"],"nota":"«Swallow» é engolir, e é também a andorinha — mesma palavra, sem parentesco nenhum. «Hard to swallow» é difícil de aceitar, igual ao português, e «swallow your pride» é engolir o orgulho.","v":"3ced1f79"},{"idioma":"en","id":"en-u155","tipo":"frase","requer":"en-p155","en":"It's hard to swallow.","pt":"É difícil de engolir.","aceitas":["e dificil de engolir","e dificil engolir","custa engolir","nao desce facil"],"aceitasEn":["its hard to swallow","it is hard to swallow"],"distratores":["É difícil de mastigar.","É difícil de cortar.","É difícil de achar.","É difícil de carregar."],"nivel":"A2","tags":["verbo","comida","expressão"],"nota":"Vale para o comprimido e vale para a notícia: as duas línguas usam a mesma imagem, e por isso esta é das poucas expressões que se traduzem ao pé da letra sem errar.","v":"43703aeb"},{"idioma":"en","id":"en-p156","tipo":"palavra","en":"to breathe","pt":"respirar","aceitas":["respirar","tomar folego","puxar o ar"],"aceitasEn":["to breathe","breathe"],"distratores":["soprar","tossir","suspirar","bocejar"],"nivel":"A2","tags":["verbo","corpo","saúde"],"nota":"«Breathe» é o verbo, com «e» no fim; «breath» é o substantivo, sem o «e» e com som diferente — «take a deep breath» é respirar fundo. Os dois se confundem na escrita até entre quem fala inglês de nascença.","v":"f28d803e"},{"idioma":"en","id":"en-u156","tipo":"frase","requer":"en-p156","en":"Breathe through your nose.","pt":"Respire pelo nariz.","aceitas":["respire pelo nariz","respira pelo nariz","puxe o ar pelo nariz","respire so pelo nariz"],"aceitasEn":["breathe through your nose","breathe in through your nose"],"distratores":["Respire pela boca.","Assopre pelo nariz.","Fale pelo nariz.","Cheire pelo nariz."],"nivel":"A2","tags":["verbo","corpo","saúde"],"nota":"«Through» é «por dentro de», e é a preposição do ar que atravessa. O inglês põe o possessivo até aqui — «your nose» —, onde o português se contenta com o artigo.","v":"d987ec0d"},{"idioma":"en","id":"en-p157","tipo":"palavra","en":"to blink","pt":"piscar","aceitas":["piscar","piscar os olhos","pestanejar"],"aceitasEn":["to blink","blink"],"distratores":["espiar","bocejar","encarar","sorrir"],"nivel":"A2","tags":["verbo","corpo"],"nota":"«Blink» é piscar os dois olhos sem querer; piscar um olho de propósito é «wink», outra palavra. A luz que pisca também «blinks», e «in the blink of an eye» é num piscar de olhos.","v":"4a091acc"},{"idioma":"en","id":"en-u157","tipo":"frase","requer":"en-p157","en":"Don't blink.","pt":"Não pisque.","aceitas":["nao pisque","nao pisca","nem pisque","nao pisque os olhos","nao pestaneje"],"aceitasEn":["dont blink","do not blink"],"distratores":["Não olhe.","Não respire.","Não se mexa.","Não fale."],"nivel":"A2","tags":["verbo","corpo"],"nota":"«Don't blink» é o aviso de quem vai mostrar uma coisa rápida, e também a ameaça do filme de terror. O imperativo negativo em inglês é sempre «don't» mais o verbo seco, sem conjugação nenhuma.","v":"852acd74"},{"idioma":"en","id":"en-p158","tipo":"palavra","en":"to sneeze","pt":"espirrar","aceitas":["espirrar","dar um espirro","soltar um espirro"],"aceitasEn":["to sneeze","sneeze"],"distratores":["tossir","soluçar","fungar","bocejar"],"nivel":"B1","tags":["verbo","saúde","corpo"],"nota":"«Sneeze» é espirrar. Quando alguém espirra, o inglês responde «bless you», que ao pé da letra é «Deus te abençoe» e é obrigatório em qualquer sala. E «nothing to sneeze at» é «não é pouca coisa».","v":"71a806d7"},{"idioma":"en","id":"en-u158","tipo":"frase","requer":"en-p158","en":"I can't stop sneezing.","pt":"Não paro de espirrar.","aceitas":["nao paro de espirrar","nao consigo parar de espirrar","estou espirrando sem parar","nao para de espirro"],"aceitasEn":["i cant stop sneezing","i can not stop sneezing"],"distratores":["Não paro de tossir.","Não paro de bocejar.","Não paro de rir.","Não paro de tremer."],"nivel":"B1","tags":["verbo","saúde"],"nota":"Depois de «stop» vem sempre o verbo em -ing quando se fala da ação que não cessa. E «can't stop» é mais forte que «don't stop»: quer dizer que a pessoa tentou e não conseguiu.","v":"6af9da3c"},{"idioma":"en","id":"en-p159","tipo":"palavra","en":"the bruise","pt":"o roxo","aceitas":["o roxo","roxo","a mancha roxa","o hematoma"],"aceitasEn":["the bruise","bruise","a bruise"],"distratores":["o corte","o curativo","o arranhão","o calombo"],"nivel":"B1","tags":["substantivo","saúde","corpo"],"nota":"«Bruise» é a marca roxa do machucado que não abriu a pele. O verbo existe: «I bruise easily» é «eu marco fácil». E serve à fruta batida — «bruised bananas» são as que ficaram com a parte escura.","v":"15d4ecfa"},{"idioma":"en","id":"en-u159","tipo":"frase","requer":"en-p159","en":"She has a bruise on her arm.","pt":"Ela está com um roxo no braço.","aceitas":["ela esta com um roxo no braco","ela tem um roxo no braco","ela esta com uma mancha roxa no braco","ela esta com um hematoma no braco"],"aceitasEn":["she has a bruise on her arm","shes got a bruise on her arm"],"distratores":["Ela está com um corte no braço.","Ela está com um curativo no braço.","Ela está com um arranhão no braço.","Ela está com um calombo no braço."],"nivel":"B1","tags":["substantivo","saúde","corpo"],"nota":"O inglês diz «has a bruise», com o verbo ter, onde o português prefere «está com». E o possessivo volta a aparecer no corpo: «her arm», e não «the arm».","v":"14ef0ba5"},{"idioma":"en","id":"en-p160","tipo":"palavra","en":"to limp","pt":"mancar","aceitas":["mancar","claudicar","andar mancando","puxar a perna"],"aceitasEn":["to limp","limp"],"distratores":["tropeçar","escorregar","correr","pular"],"nivel":"B1","tags":["verbo","corpo","saúde"],"nota":"«Limp» é andar mancando, e como adjetivo é mole, sem firmeza: «a limp handshake» é um aperto de mão frouxo. São a mesma palavra e dois sentidos que nunca se cruzam.","v":"b9d2e352"},{"idioma":"en","id":"en-u160","tipo":"frase","requer":"en-p160","en":"He walked with a limp.","pt":"Ele andava mancando.","aceitas":["ele andava mancando","ele mancava","ele andava puxando a perna","ele caminhava mancando"],"aceitasEn":["he walked with a limp","he had a limp"],"distratores":["Ele andava depressa.","Ele andava encurvado.","Ele andava de muletas.","Ele andava descalço."],"nivel":"B1","tags":["verbo","corpo","saúde"],"nota":"«Walk with a limp» usa o substantivo onde o português usa o gerúndio: «andava mancando». O inglês gosta de transformar a maneira em coisa — walk with a limp, speak with an accent, look with envy.","v":"3e1942a1"},{"idioma":"en","id":"en-p161","tipo":"palavra","en":"to blush","pt":"corar","aceitas":["corar","ficar vermelho","enrubescer","ficar corado"],"aceitasEn":["to blush","blush"],"distratores":["empalidecer","tremer","suar","gaguejar"],"nivel":"B1","tags":["verbo","corpo","social"],"nota":"«Blush» é o vermelho que sobe ao rosto de vergonha, e é também o blush da maquiagem — a mesma palavra, com a mesma ideia. E «at first blush» é «à primeira vista», num sentido antigo que já perdeu o rosto.","v":"0a1500bf"},{"idioma":"en","id":"en-u161","tipo":"frase","requer":"en-p161","en":"She blushed when he said it.","pt":"Ela corou quando ele falou.","aceitas":["ela corou quando ele falou","ela ficou vermelha quando ele falou","ela corou quando ele disse isso","ela ficou corada quando ele falou"],"aceitasEn":["she blushed when he said it"],"distratores":["Ela chorou quando ele falou.","Ela riu quando ele falou.","Ela saiu quando ele falou.","Ela gritou quando ele falou."],"nivel":"B1","tags":["verbo","corpo","social"],"nota":"«Blush» não é reflexivo em inglês: «she blushed», sem pronome nenhum, onde o espanhol precisa do «se». O inglês guarda o reflexivo só para quando a pessoa faz alguma coisa a si mesma de propósito.","v":"4e89e30b"},{"idioma":"en","id":"en-p162","tipo":"palavra","en":"to itch","pt":"coçar","aceitas":["cocar","dar coceira","estar cocando","pinicar"],"aceitasEn":["to itch","itch"],"distratores":["arranhar","queimar","inchar","descascar"],"nivel":"B1","tags":["verbo","corpo","saúde"],"nota":"O inglês separa o que o português junta num verbo só: «itch» é a coceira que se sente, e «scratch» é a unha que se passa. «My arm itches» é o braço coçando; «I scratched my arm» é eu coçando o braço.","v":"377a4a22"},{"idioma":"en","id":"en-u162","tipo":"frase","requer":"en-p162","en":"My back itches.","pt":"Minhas costas estão coçando.","aceitas":["minhas costas estao cocando","ta cocando minhas costas","minhas costas cocam","estou com coceira nas costas"],"aceitasEn":["my back itches","my back is itchy"],"distratores":["Minhas costas estão doendo.","Minhas costas estão travadas.","Minhas costas estão queimadas.","Minhas costas estão suadas."],"nivel":"B1","tags":["verbo","corpo","saúde"],"nota":"«Back» é as costas, e em inglês é singular: «my back itches», com o verbo no singular. O português põe no plural, «minhas costas», e é uma das poucas palavras em que as duas línguas contam diferente.","v":"f0843d69"},{"idioma":"en","id":"en-f225","tipo":"frase","en":"How are you doing?","pt":"Como você está?","aceitas":["como voce esta","como vai voce","tudo bem com voce","como voce ta","e ai tudo bem"],"aceitasEn":["how are you doing","how you doing","hows it going"],"distratores":["O que você está fazendo?","Como você fez isso?","Onde você está?","Para onde você vai?"],"nivel":"A2","tags":["social","cotidiano"],"nota":"Cuidado com a semelhança: «how are you doing?» é «como vai?», e «what are you doing?» é «o que você está fazendo?». Uma palavra separa as duas, e a resposta esperada da primeira é só «good, thanks».","v":"26241207"},{"idioma":"en","id":"en-f226","tipo":"frase","en":"Nice to meet you.","pt":"Prazer em conhecer.","aceitas":["prazer em conhecer","muito prazer","prazer em te conhecer","e um prazer conhecer voce","prazer"],"aceitasEn":["nice to meet you","nice meeting you","pleased to meet you"],"distratores":["Bom te ver de novo.","Foi bom conversar.","Obrigado por vir.","Até a próxima."],"nivel":"A2","tags":["social"],"nota":"«Nice to meet you» é só para a primeira vez; do segundo encontro em diante é «nice to see you». Trocar as duas é o deslize mais comum de quem está aprendendo, e quem ouve repara.","v":"d8067fa6"},{"idioma":"en","id":"en-f227","tipo":"frase","en":"Excuse me.","pt":"Com licença.","aceitas":["com licenca","da licenca","por favor com licenca","licenca"],"aceitasEn":["excuse me","excuse me please"],"distratores":["Me desculpe pelo erro.","Obrigado pela ajuda.","Por favor, espere.","Tenha um bom dia."],"nivel":"A2","tags":["social","cotidiano"],"nota":"«Excuse me» é para pedir passagem, chamar atenção de alguém ou interromper. «Sorry» é para o que já foi feito de errado. O inglês separa as duas com rigor, e o português usa «desculpa» para as duas.","v":"76a65c2d"},{"idioma":"en","id":"en-f228","tipo":"frase","en":"I'm just looking.","pt":"Só estou olhando.","aceitas":["so estou olhando","estou so olhando","to so olhando","so dando uma olhada","estou so dando uma olhada"],"aceitasEn":["im just looking","i am just looking","just looking thanks"],"distratores":["Só estou esperando.","Só estou passando.","Só estou perguntando.","Só estou conferindo."],"nivel":"A2","tags":["social","viagem"],"nota":"É a resposta padrão ao vendedor que pergunta «can I help you?». Dita com um «thanks» no fim, ela encerra a conversa sem grosseria — e é a frase mais útil de quem entra numa loja só para ver.","v":"2a39f1e1"},{"idioma":"en","id":"en-f229","tipo":"frase","en":"Can I pay by card?","pt":"Posso pagar com cartão?","aceitas":["posso pagar com cartao","da para pagar com cartao","voces aceitam cartao","posso pagar no cartao"],"aceitasEn":["can i pay by card","can i pay with a card","do you take cards"],"distratores":["Posso pagar em dinheiro?","Posso pagar depois?","Posso pagar em parcelas?","Posso pagar adiantado?"],"nivel":"A2","tags":["economia","viagem"],"nota":"A preposição é «by» quando se fala do meio de pagamento: pay by card, pay by check. Com dinheiro vivo muda: «pay in cash», com «in». São duas preposições que não se trocam.","v":"3d5b2801"},{"idioma":"en","id":"en-f230","tipo":"frase","en":"I don't speak English well.","pt":"Eu não falo inglês bem.","aceitas":["eu nao falo ingles bem","nao falo ingles bem","meu ingles nao e bom","eu falo pouco ingles","nao falo ingles direito"],"aceitasEn":["i dont speak english well","i do not speak english well"],"distratores":["Eu não entendo inglês bem.","Eu não escrevo inglês bem.","Eu não leio inglês bem.","Eu não estudo inglês direito."],"nivel":"A2","tags":["social","escola"],"nota":"O advérbio vem no fim: «I speak English well». Pôr «well» antes do verbo é o erro mais comum de quem traduz do português, onde «falo bem inglês» é a ordem natural.","v":"18fa87bb"},{"idioma":"en","id":"en-f231","tipo":"frase","en":"Where are you from?","pt":"De onde você é?","aceitas":["de onde voce e","voce e de onde","de onde voce vem","qual e a sua terra"],"aceitasEn":["where are you from","whereabouts are you from"],"distratores":["Onde você está?","Para onde você vai?","Onde você mora?","Por onde você passou?"],"nivel":"A2","tags":["social","viagem"],"nota":"O «from» vai no fim da pergunta, longe do «where» — o inglês deixa preposição solta no fim o tempo todo, e é o que mais estranha o ouvido português. «From where are you?» existe no papel e ninguém fala.","v":"c12595cb"},{"idioma":"en","id":"en-f232","tipo":"frase","en":"Have a good trip.","pt":"Boa viagem.","aceitas":["boa viagem","tenha uma boa viagem","faca boa viagem","otima viagem"],"aceitasEn":["have a good trip","have a nice trip","have a safe trip"],"distratores":["Bom descanso.","Bom proveito.","Boa sorte.","Boa noite."],"nivel":"A2","tags":["social","viagem"],"nota":"O inglês monta todos os votos com «have a»: have a good trip, have a nice day, have a good one. O português corta o verbo e deixa só o adjetivo e o substantivo — e por isso a fórmula inglesa se decora inteira.","v":"6e69ad13"},{"idioma":"en","id":"en-f233","tipo":"frase","en":"I'm getting used to it.","pt":"Estou me acostumando.","aceitas":["estou me acostumando","to me acostumando","ja estou me acostumando","estou me habituando","estou pegando o jeito"],"aceitasEn":["im getting used to it","i am getting used to it"],"distratores":["Estou desistindo disso.","Estou enjoando disso.","Estou aprendendo isso.","Estou evitando isso."],"nivel":"B1","tags":["gramática","social"],"nota":"«Get used to» é o processo, e «be used to» é o estado já alcançado: «I'm getting used to it» ainda está no meio do caminho. Depois do «to» vem substantivo ou verbo em -ing, e nunca infinitivo.","v":"45508b94"},{"idioma":"en","id":"en-f234","tipo":"frase","en":"It's not that simple.","pt":"Não é tão simples assim.","aceitas":["nao e tao simples assim","nao e tao simples","a coisa nao e tao simples","nao e bem assim"],"aceitasEn":["its not that simple","it is not that simple"],"distratores":["Não é simples de explicar.","Não é o mais simples.","Não é simples assim de fazer.","Não é simples nem complicado."],"nivel":"B1","tags":["gramática","social"],"nota":"O «that» aqui não é «aquele»: é «tão», e mede o grau. «It's not that far» é «não é tão longe assim». É uso de conversa, e no lugar dele o texto escrito põe «so».","v":"eed78fd5"},{"idioma":"en","id":"en-f235","tipo":"frase","en":"Let's split the bill.","pt":"Vamos dividir a conta.","aceitas":["vamos dividir a conta","vamos rachar a conta","a gente divide a conta","vamos pagar a conta dividida"],"aceitasEn":["lets split the bill","lets split it","lets go dutch"],"distratores":["Vamos pedir a conta.","Vamos conferir a conta.","Vamos contestar a conta.","Vamos arredondar a conta."],"nivel":"B1","tags":["economia","social"],"nota":"«Split» é partir ao meio, e serve à conta, à lenha e ao grupo. Há uma variante antiga, «go Dutch», que ainda se ouve e que os holandeses não acham graça nenhuma.","v":"bbd69d02"},{"idioma":"en","id":"en-f236","tipo":"frase","en":"I owe you one.","pt":"Fico te devendo uma.","aceitas":["fico te devendo uma","te devo uma","fiquei te devendo uma","devo essa a voce"],"aceitasEn":["i owe you one","i owe you"],"distratores":["Você me deve uma.","Já te paguei essa.","Estamos quites agora.","Fico te devendo tudo."],"nivel":"B1","tags":["social","expressão"],"nota":"O «one» no fim não se traduz por «um»: é «uma» no sentido de um favor. A frase fecha o agradecimento com a promessa de retribuir, e o par dela é «we're even», estamos quites.","v":"4cbdf60d"},{"idioma":"en","id":"en-f237","tipo":"frase","en":"I couldn't agree more.","pt":"Concordo plenamente.","aceitas":["concordo plenamente","concordo totalmente","nao poderia concordar mais","concordo em genero numero e grau","estou totalmente de acordo"],"aceitasEn":["i couldnt agree more","i could not agree more"],"distratores":["Concordo um pouco mais.","Não concordo nada.","Concordaria se pudesse.","Discordo totalmente."],"nivel":"B1","tags":["gramática","social"],"nota":"A frase parece negativa e é o elogio máximo: «não daria para concordar mais do que já concordo». É o molde de «I couldn't be happier» e de «it couldn't be better» — e traduzida ao pé da letra sai ao contrário.","v":"2b7bc2f3"},{"idioma":"en","id":"en-f238","tipo":"frase","en":"Fair enough.","pt":"Tudo bem, entendi.","aceitas":["tudo bem entendi","faz sentido entao","tudo bem entao","ta certo entao","entendi o seu ponto"],"aceitasEn":["fair enough","thats fair enough"],"distratores":["Justo o suficiente.","Bastante justo mesmo.","Nem um pouco justo.","Foi uma feira boa."],"nivel":"B1","tags":["expressão","social"],"nota":"«Fair enough» é aceitar o argumento do outro sem concordar de todo: «tudo bem, entendi o seu ponto». É das expressões mais britânicas que existem, e o americano usa menos. Repare no «fair», que aqui é justo, e não feira.","v":"86163bd6"},{"idioma":"en","id":"en-f239","tipo":"frase","en":"It's on me.","pt":"É por minha conta.","aceitas":["e por minha conta","fica por minha conta","eu pago","deixa que eu pago","a conta e minha"],"aceitasEn":["its on me","this ones on me"],"distratores":["Está em cima de mim.","Depende de mim.","A culpa é minha.","É a minha vez."],"nivel":"B1","tags":["economia","social"],"nota":"«On me» é «por minha conta», e a preposição é a mesma de «the drinks are on the house». Cuidado com a vizinha «it's up to me», que é «depende de mim» — um «up» separa as duas.","v":"76db5da7"},{"idioma":"en","id":"en-f240","tipo":"frase","en":"Are you serious?","pt":"Você está falando sério?","aceitas":["voce esta falando serio","ta falando serio","e serio isso","voce ta falando serio mesmo","serio mesmo"],"aceitasEn":["are you serious","are you being serious","seriously"],"distratores":["Você está falando sozinho?","Você está falando comigo?","Você está falando baixo?","Você está falando demais?"],"nivel":"B1","tags":["social","expressão"],"nota":"Serve para a surpresa boa e para a indignação, e quem decide é o tom. O inglês usa o adjetivo — «are you serious» — onde o português usa o advérbio, «falando sério».","v":"b626ed67"},{"idioma":"en","id":"en-f241","tipo":"frase","en":"I lost track of time.","pt":"Perdi a noção do tempo.","aceitas":["perdi a nocao do tempo","eu perdi a nocao do tempo","perdi a hora sem ver","nem vi o tempo passar"],"aceitasEn":["i lost track of time","i completely lost track of time"],"distratores":["Perdi a hora do trem.","Perdi o fio da meada.","Perdi a paciência de vez.","Perdi o interesse na hora."],"nivel":"B1","tags":["expressão","cotidiano"],"nota":"«Lose track of» é perder a conta de alguma coisa que vinha sendo seguida — o tempo, as pessoas, os gastos. Com pessoa vira despedida triste: «we lost track of each other».","v":"3bdcd115"},{"idioma":"en","id":"en-f242","tipo":"frase","en":"Better late than never.","pt":"Antes tarde do que nunca.","aceitas":["antes tarde do que nunca","melhor tarde do que nunca","antes tarde que nunca"],"aceitasEn":["better late than never"],"distratores":["Antes nunca do que tarde.","Antes cedo do que tarde.","Antes tarde do que cedo.","Antes agora do que nunca."],"nivel":"B1","tags":["expressão","provérbio"],"nota":"O provérbio é o mesmo nas três línguas, palavra por palavra, e isso é raro. Serve para desculpar o próprio atraso e para aceitar o do outro — e no segundo caso costuma vir com ironia.","v":"a243d871"},{"idioma":"en","id":"en-f243","tipo":"frase","en":"I'm all ears.","pt":"Sou todo ouvidos.","aceitas":["sou todo ouvidos","estou todo ouvidos","pode falar que eu escuto","estou te escutando"],"aceitasEn":["im all ears","i am all ears"],"distratores":["Estou com o ouvido cheio.","Tenho as duas orelhas boas.","Não quero saber de nada.","Estou surdo hoje."],"nivel":"B1","tags":["expressão","social"],"nota":"A imagem é a mesma nas três línguas: a pessoa vira ouvido inteiro. Diz-se para pedir que o outro conte logo, e o tom costuma ser de curiosidade, não de paciência.","v":"27a0b8a8"},{"idioma":"en","id":"en-f244","tipo":"frase","en":"Sleep on it.","pt":"Pense com calma até amanhã.","aceitas":["pense com calma ate amanha","deixa para decidir amanha","decide amanha com a cabeca fria","dorme e pensa amanha","consulte o travesseiro"],"aceitasEn":["sleep on it","why dont you sleep on it"],"distratores":["Durma em cima disso.","Deite-se em cima disso.","Esqueça o assunto.","Decida agora mesmo."],"nivel":"B1","tags":["expressão","social"],"nota":"«Sleep on it» é adiar a decisão até o dia seguinte, para decidir com a cabeça descansada. O espanhol tem a mesma ideia com outro móvel, a almofada, e o português a diz por extenso.","v":"14ab1807"},{"idioma":"en","id":"en-f245","tipo":"frase","en":"Don't take it personally.","pt":"Não leve para o lado pessoal.","aceitas":["nao leve para o lado pessoal","nao leva para o lado pessoal","nao e nada pessoal","nao leve a mal","nao leve para o pessoal"],"aceitasEn":["dont take it personally","do not take it personally"],"distratores":["Não leve isso com você.","Não pegue isso pessoalmente.","Não fale disso em público.","Não guarde isso para você."],"nivel":"B2","tags":["expressão","social"],"nota":"«Take» aqui é receber, interpretar: «don't take it the wrong way» é primo desta. A frase vem sempre depois de uma crítica, e quase sempre tarde demais.","v":"fcfb7bcd"},{"idioma":"en","id":"en-f246","tipo":"frase","en":"Let's cut to the chase.","pt":"Vamos direto ao ponto.","aceitas":["vamos direto ao ponto","vamos ao ponto","vamos parar de enrolar","vamos ao que interessa","vamos ao assunto logo"],"aceitasEn":["lets cut to the chase","let us cut to the chase"],"distratores":["Vamos cortar a perseguição.","Vamos correr atrás disso.","Vamos deixar para depois.","Vamos com calma agora."],"nivel":"B2","tags":["expressão","trabalho"],"nota":"Vem do cinema mudo: a cena de perseguição era a boa, e «cut to the chase» era a ordem do diretor para pular o resto. Hoje é o pedido de quem não quer mais introdução.","v":"c4ab69c0"},{"idioma":"en","id":"en-f247","tipo":"frase","en":"He's hard to please.","pt":"Ele é difícil de agradar.","aceitas":["ele e dificil de agradar","ele e dificil de contentar","nada agrada ele","ele nunca esta satisfeito","e dificil agradar ele"],"aceitasEn":["hes hard to please","he is hard to please"],"distratores":["Ele é difícil de encontrar.","Ele é difícil de entender.","Ele é difícil de convencer.","Ele é difícil de acompanhar."],"nivel":"B2","tags":["expressão","social"],"nota":"O molde «hard to + verbo» dispensa o objeto: «he's hard to please», e não «hard to please him». O inglês entende que o objeto é o próprio sujeito da frase, e repetir soa errado.","v":"19964099"},{"idioma":"en","id":"en-f248","tipo":"frase","en":"It's only a matter of time.","pt":"É só questão de tempo.","aceitas":["e so questao de tempo","e questao de tempo","e so uma questao de tempo","mais cedo ou mais tarde acontece"],"aceitasEn":["its only a matter of time","it is only a matter of time"],"distratores":["É só uma questão de sorte.","É só uma questão de dinheiro.","É só uma perda de tempo.","É só um problema de agenda."],"nivel":"B2","tags":["expressão"],"nota":"«A matter of» é «uma questão de», e o inglês usa «matter» onde o português usa «questão»: a matter of taste, a matter of opinion, a matter of life and death. Como verbo, «matter» é importar.","v":"242fa2ce"},{"idioma":"en","id":"en-f249","tipo":"frase","en":"I wouldn't count on it.","pt":"Eu não contaria com isso.","aceitas":["eu nao contaria com isso","nao contaria com isso","nao conte muito com isso","duvido que aconteca","nao espere muito por isso"],"aceitasEn":["i wouldnt count on it","i would not count on it"],"distratores":["Eu não contaria isso a ninguém.","Eu não somaria isso agora.","Eu não pagaria por isso.","Eu não apostaria nisso tudo."],"nivel":"B2","tags":["expressão","social"],"nota":"«Count on» é contar com, e o «on» é obrigatório — sem ele, «count» vira contar números. O condicional «wouldn't» suaviza o aviso: quem fala não está dizendo que é impossível, só que não apostaria.","v":"45974efe"},{"idioma":"en","id":"en-f250","tipo":"frase","en":"She stood her ground.","pt":"Ela não recuou.","aceitas":["ela nao recuou","ela se manteve firme","ela bateu o pe","ela nao cedeu","ela segurou a posicao dela"],"aceitasEn":["she stood her ground","she held her ground"],"distratores":["Ela ficou de pé.","Ela comprou terreno.","Ela mudou de ideia.","Ela saiu de perto."],"nivel":"B2","tags":["expressão","social"],"nota":"A imagem vem da batalha: manter o pedaço de chão em que se está, sem recuar um passo. Hoje é discussão, negociação e reunião — e sempre com admiração de quem conta.","v":"0be218e2"},{"idioma":"en","id":"en-f251","tipo":"frase","en":"That crossed my mind.","pt":"Isso me passou pela cabeça.","aceitas":["isso me passou pela cabeca","passou pela minha cabeca","ja pensei nisso","isso ja me ocorreu","cheguei a pensar nisso"],"aceitasEn":["that crossed my mind","it crossed my mind"],"distratores":["Isso saiu da minha cabeça.","Isso ficou na minha cabeça.","Isso cruzou o meu caminho.","Isso mudou a minha cabeça."],"nivel":"B2","tags":["expressão"],"nota":"A ideia atravessa a cabeça e some: foi pensada, mas não ficou. A imagem é igual à portuguesa, com «cruzar» em vez de «passar», e o negativo é comum — «it never crossed my mind».","v":"dbdd1b80"},{"idioma":"en","id":"en-f252","tipo":"frase","en":"It slipped through the cracks.","pt":"Isso acabou passando batido.","aceitas":["isso acabou passando batido","isso passou batido","isso escapou sem ninguem ver","isso ficou esquecido no meio","isso passou despercebido"],"aceitasEn":["it slipped through the cracks","it fell through the cracks"],"distratores":["Isso escorregou na rachadura.","Isso caiu por uma fresta.","Isso foi feito às pressas.","Isso foi escondido de propósito."],"nivel":"B2","tags":["expressão","trabalho"],"nota":"A coisa some pela fresta entre duas tábuas: ninguém a jogou fora, ela caiu sozinha. Serve para o processo esquecido e para a pessoa que o sistema não atendeu, e é a desculpa favorita de qualquer burocracia.","v":"3fd66672"},{"idioma":"en","id":"en-f253","tipo":"frase","en":"He jumped the gun.","pt":"Ele se precipitou.","aceitas":["ele se precipitou","ele agiu cedo demais","ele saiu na frente antes da hora","ele foi rapido demais","ele queimou a largada"],"aceitasEn":["he jumped the gun","he really jumped the gun"],"distratores":["Ele pulou a arma.","Ele saltou o revólver.","Ele chegou atrasado.","Ele desistiu no fim."],"nivel":"C1","tags":["expressão","trabalho"],"nota":"Vem do atletismo: o corredor que parte antes do tiro de largada. A imagem portuguesa é a mesma, «queimar a largada», e o sentido também — agir antes da hora e estragar o que vinha bem.","v":"d4f1b399"},{"idioma":"en","id":"en-f254","tipo":"frase","en":"Let's not get ahead of ourselves.","pt":"Vamos com calma.","aceitas":["vamos com calma","vamos devagar","nao vamos nos adiantar","calma que ainda e cedo","um passo de cada vez"],"aceitasEn":["lets not get ahead of ourselves","let us not get ahead of ourselves"],"distratores":["Vamos passar na frente deles.","Vamos sair daqui antes.","Vamos deixar isso de lado.","Vamos decidir tudo agora."],"nivel":"C1","tags":["expressão","trabalho"],"nota":"«Get ahead of ourselves» é passar na frente da própria história: celebrar antes de ganhar, planejar antes de confirmar. O reflexivo é obrigatório e muda com a pessoa — «don't get ahead of yourself».","v":"70229a72"},{"idioma":"en","id":"en-f255","tipo":"frase","en":"It's a grey area.","pt":"Isso é uma zona cinzenta.","aceitas":["isso e uma zona cinzenta","e uma zona cinzenta","isso nao e nem uma coisa nem outra","isso fica numa area indefinida","e um meio do caminho duvidoso"],"aceitasEn":["its a grey area","its a gray area","it is a grey area"],"distratores":["É uma área bem escura.","É um bairro cinzento.","É uma regra bem clara.","É um assunto proibido."],"nivel":"C1","tags":["expressão","jurídico"],"nota":"Entre o branco e o preto fica o cinza: o caso que a regra não previu e que ninguém sabe julgar. É palavra de advogado e de comitê de ética. E repare na grafia — «grey» é britânica, «gray» é americana.","v":"5aa7b69f"},{"idioma":"en","id":"en-f256","tipo":"frase","en":"Much to my surprise, he agreed.","pt":"Para minha surpresa, ele aceitou.","aceitas":["para minha surpresa ele aceitou","para grande surpresa minha ele aceitou","ele aceitou para minha surpresa","surpreendentemente ele aceitou"],"aceitasEn":["much to my surprise he agreed"],"distratores":["Com muita surpresa, ele recusou.","Sem nenhuma surpresa, ele aceitou.","Depois da surpresa, ele aceitou.","Apesar da surpresa, ele recusou."],"nivel":"C2","tags":["gramática","formal"],"nota":"«Much to my» é fórmula fixa de registro alto, e o «much» mede a surpresa, não a quantidade. O molde aceita outros substantivos de reação — much to my relief, much to her dismay, much to everyone's delight.","v":"717f8962"},{"idioma":"en","id":"en-f257","tipo":"frase","en":"Rarely does he admit a mistake.","pt":"Raramente ele admite um erro.","aceitas":["raramente ele admite um erro","ele raramente admite um erro","quase nunca ele admite um erro","e raro ele admitir um erro"],"aceitasEn":["rarely does he admit a mistake"],"distratores":["Ele admite um erro raro.","Ele admite raramente que erra.","Ele nunca comete um erro raro.","Ele sempre admite um erro."],"nivel":"C2","tags":["gramática","formal"],"nota":"Mais uma inversão: depois de «rarely», «seldom» e «hardly ever» no começo da frase, o auxiliar passa à frente do sujeito, como numa pergunta. Sem inversão a frase existe, mas cai de registro.","v":"ac8771a6"},{"idioma":"en","id":"en-f258","tipo":"frase","en":"In no uncertain terms, she refused.","pt":"Ela recusou sem deixar dúvida.","aceitas":["ela recusou sem deixar duvida","ela recusou de forma categorica","ela recusou sem meias palavras","ela disse nao com todas as letras"],"aceitasEn":["in no uncertain terms she refused"],"distratores":["Ela recusou com alguma dúvida.","Ela recusou em termos vagos.","Ela recusou sem dizer por quê.","Ela recusou de um jeito educado."],"nivel":"C2","tags":["gramática","formal"],"nota":"Dois negativos que se anulam: «no uncertain» é «bem certo». A fórmula descreve a recusa que não deixou margem nenhuma, e traduzida ao pé da letra ela sai exatamente ao contrário do que diz.","v":"7ea06165"},{"idioma":"en","id":"en-f259","tipo":"frase","en":"Therein lies the problem.","pt":"É aí que está o problema.","aceitas":["e ai que esta o problema","o problema esta justamente ai","ai e que mora o problema","e exatamente ai o problema"],"aceitasEn":["therein lies the problem"],"distratores":["O problema foi embora daí.","O problema mente sobre isso.","O problema está resolvido.","O problema vem de outro lugar."],"nivel":"C2","tags":["gramática","formal"],"nota":"«Therein» é «nisso», e é um daqueles advérbios antigos que o inglês só usa em contrato e em ensaio — como therefore, thereby e hereby. E «lies» aqui é o verbo de estar deitado, não o de mentir.","v":"2885af6a"},{"idioma":"en","id":"en-f260","tipo":"frase","en":"All things considered, it was fine.","pt":"No fim das contas, foi bom.","aceitas":["no fim das contas foi bom","pesando tudo foi bom","considerando tudo foi bom","levando tudo em conta foi bom","no geral foi bom"],"aceitasEn":["all things considered it was fine"],"distratores":["Todas as coisas foram boas.","Nada foi considerado bom.","Depois de tudo, foi ruim.","Antes de tudo, foi bom."],"nivel":"C2","tags":["gramática","formal"],"nota":"É particípio absoluto: «all things considered» é uma oração inteira sem verbo conjugado, e vale por «depois de pesar tudo». O molde é produtivo — weather permitting, that said, all being well.","v":"e4db27db"},{"idioma":"en","id":"en-v127","tipo":"frase","en":"He doesn't like coffee.","pt":"Ele não gosta de café.","aceitas":["ele nao gosta de cafe","nao gosta de cafe","ele nao curte cafe","ele nao toma cafe por nao gostar"],"aceitasEn":["he doesnt like coffee","he does not like coffee"],"distratores":["Ele não gostou de café.","Ele não vai gostar de café.","Ele não gostaria de café.","Ele não tinha gostado de café."],"formasEn":{"He liked coffee":"pretérito","He will like coffee":"futuro","He would like coffee":"condicional","He had liked coffee":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","regular","do","presente","comida"],"nota":"Na negativa o «-s» da terceira pessoa migra para o auxiliar: é «he doesn't like», e nunca «he doesn't likes». O verbo principal volta ao infinitivo seco, e essa é a regra que mais escapa no inglês falado depressa.","v":"20d0a3b5"},{"idioma":"en","id":"en-v128","tipo":"frase","en":"Do you have a pen?","pt":"Você tem uma caneta?","aceitas":["voce tem uma caneta","tem uma caneta ai","voce tem caneta","tem caneta"],"aceitasEn":["do you have a pen","have you got a pen"],"distratores":["Você tinha uma caneta?","Você vai ter uma caneta?","Você teria uma caneta?","Você tem tido uma caneta?"],"formasEn":{"Did you have a pen":"pretérito","Will you have a pen":"futuro","Would you have a pen":"condicional","Had you had a pen":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","irregular","have","presente","escola"],"nota":"A pergunta no presente pede «do» na frente, mesmo com o verbo «have». A forma britânica «have you got a pen?» dispensa o auxiliar e diz o mesmo — as duas convivem, e a americana é a primeira.","v":"ec28fc6f"},{"idioma":"en","id":"en-v129","tipo":"frase","en":"They're going to travel.","pt":"Eles vão viajar.","aceitas":["eles vao viajar","vao viajar","eles estao de viagem marcada","eles pretendem viajar"],"aceitasEn":["theyre going to travel","they are going to travel"],"distratores":["Eles viajam sempre.","Eles viajaram ontem.","Eles viajariam se pudessem.","Eles tinham viajado antes."],"formasEn":{"They travel a lot":"presente","They travelled yesterday":"pretérito","They would travel if they could":"condicional","They had travelled before":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","regular","travel","futuro","viagem"],"nota":"«Going to» é o futuro de quem já decidiu ou já vê o sinal chegando; «will» é o de quem decide na hora. O português usa «vão viajar» para os dois, e por isso a diferença precisa ser decorada.","v":"a077c96e"},{"idioma":"en","id":"en-v130","tipo":"frase","en":"I'll call you later.","pt":"Eu te ligo mais tarde.","aceitas":["eu te ligo mais tarde","te ligo mais tarde","vou te ligar mais tarde","eu ligo para voce mais tarde"],"aceitasEn":["ill call you later","i will call you later"],"distratores":["Eu te liguei mais tarde.","Eu te ligo sempre mais tarde.","Eu te ligaria mais tarde.","Eu tinha te ligado mais tarde."],"formasEn":{"I call you later":"presente","I called you later":"pretérito","I would call you later":"condicional","I had called you later":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","regular","call","futuro","social"],"nota":"«Will» é a promessa feita na hora, e na fala ele quase some: «I'll» é o que se ouve. O português resolve com o presente — «eu te ligo» —, e o inglês não pode: «I call you later» soaria a hábito.","v":"11f02cb8"},{"idioma":"en","id":"en-v131","tipo":"frase","en":"She's eating right now.","pt":"Ela está comendo agora.","aceitas":["ela esta comendo agora","ela ta comendo agora","ela esta almocando agora","ela esta comendo neste momento"],"aceitasEn":["shes eating right now","she is eating right now"],"distratores":["Ela come todo dia.","Ela comeu bem cedo.","Ela comeria agora.","Ela tinha comido antes."],"formasEn":{"She eats every day":"presente","She ate early":"pretérito","She would eat now":"condicional","She had eaten before":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","irregular","eat","presente","comida"],"nota":"O presente contínuo é para o que está acontecendo neste instante, e o inglês o usa muito mais que o português. «She eats» seria hábito; «she's eating» é agora, com a comida na frente.","v":"8b87024d"},{"idioma":"en","id":"en-v132","tipo":"frase","en":"He rewrote the whole letter.","pt":"Ele reescreveu a carta inteira.","aceitas":["ele reescreveu a carta inteira","reescreveu a carta inteira","ele escreveu a carta de novo","ele refez a carta inteira"],"aceitasEn":["he rewrote the whole letter"],"distratores":["Ele reescreve a carta inteira.","Ele reescreverá a carta inteira.","Ele reescreveria a carta inteira.","Ele tinha reescrito a carta inteira."],"formasEn":{"He rewrites the whole letter":"presente","He will rewrite the whole letter":"futuro","He would rewrite the whole letter":"condicional","He had rewritten the whole letter":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","rewrite","pretérito","trabalho"],"nota":"rewrite, rewrote, rewritten — conjuga como «write», que está dentro dele. O prefixo «re-» é o de fazer outra vez, e ele se cola em quase tudo: redo, reread, rebuild, rethink.","v":"c0c2d79e"},{"idioma":"en","id":"en-v133","tipo":"frase","en":"She awoke at dawn.","pt":"Ela despertou ao amanhecer.","aceitas":["ela despertou ao amanhecer","ela acordou ao amanhecer","ela despertou de madrugada","ela acordou com o dia clareando"],"aceitasEn":["she awoke at dawn","she awakened at dawn"],"distratores":["Ela desperta ao amanhecer.","Ela despertará ao amanhecer.","Ela despertaria ao amanhecer.","Ela tinha despertado ao amanhecer."],"formasEn":{"She awakes at dawn":"presente","She will awake at dawn":"futuro","She would awake at dawn":"condicional","She had awoken at dawn":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","awake","pretérito"],"nota":"awake, awoke, awoken — e é o primo literário de «wake up», que é o de todo dia. «Awake» também é adjetivo: «are you awake?» é «você está acordado?», e ali ele não se conjuga.","v":"6d738ccb"},{"idioma":"en","id":"en-v134","tipo":"frase","en":"The baby spat out the food.","pt":"O bebê cuspiu a comida.","aceitas":["o bebe cuspiu a comida","o bebe cuspiu tudo","o bebe botou a comida para fora","o bebe cuspiu a comida fora"],"aceitasEn":["the baby spat out the food"],"distratores":["O bebê cospe a comida.","O bebê cuspirá a comida.","O bebê cuspiria a comida.","O bebê tinha cuspido a comida."],"formasEn":{"The baby spits out the food":"presente","The baby will spit out the food":"futuro","The baby would spit out the food":"condicional","The baby had spat out the food":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","spit","pretérito","família"],"nota":"spit, spat, spat na Inglaterra; nos Estados Unidos o passado costuma ser «spit», igual ao presente. E «spit it out!» é «desembucha!» — mandar alguém falar logo o que está engasgado.","v":"0f19c06c"},{"idioma":"en","id":"en-v135","tipo":"frase","en":"A truck overtook us.","pt":"Um caminhão nos ultrapassou.","aceitas":["um caminhao nos ultrapassou","um caminhao passou a gente","um caminhao ultrapassou a gente","um caminhao nos passou"],"aceitasEn":["a truck overtook us"],"distratores":["Um caminhão nos ultrapassa.","Um caminhão nos ultrapassará.","Um caminhão nos ultrapassaria.","Um caminhão tinha nos ultrapassado."],"formasEn":{"A truck overtakes us":"presente","A truck will overtake us":"futuro","A truck would overtake us":"condicional","A truck had overtaken us":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","overtake","pretérito","viagem"],"nota":"overtake, overtook, overtaken — conjuga como «take», que está dentro dele. Na estrada é ultrapassar, e na economia é passar à frente: «China overtook Japan». O americano prefere «pass» para o carro.","v":"d0998980"},{"idioma":"en","id":"en-v136","tipo":"frase","en":"He outgrew his shoes.","pt":"Ele cresceu e não coube mais nos sapatos.","aceitas":["ele cresceu e nao coube mais nos sapatos","os sapatos ficaram pequenos para ele","ele cresceu e os sapatos apertaram","os sapatos dele ficaram pequenos"],"aceitasEn":["he outgrew his shoes"],"distratores":["Ele cresce e não cabe nos sapatos.","Ele crescerá e não caberá nos sapatos.","Ele cresceria e não caberia nos sapatos.","Ele tinha crescido e não cabia nos sapatos."],"formasEn":{"He outgrows his shoes":"presente","He will outgrow his shoes":"futuro","He would outgrow his shoes":"condicional","He had outgrown his shoes":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","outgrow","pretérito","roupa"],"nota":"outgrow, outgrew, outgrown — conjuga como «grow». Um verbo só para o que o português precisa de uma frase inteira: crescer além do tamanho de alguma coisa. Serve à roupa, ao hobby e à amizade de infância.","v":"401f2cbc"},{"idioma":"en","id":"en-v137","tipo":"frase","en":"I have lived here for ten years.","pt":"Moro aqui há dez anos.","aceitas":["moro aqui ha dez anos","eu moro aqui ha dez anos","faz dez anos que moro aqui","estou morando aqui ha dez anos"],"aceitasEn":["i have lived here for ten years","ive lived here for ten years"],"distratores":["Morei aqui por dez anos.","Vou morar aqui por dez anos.","Moraria aqui por dez anos.","Tinha morado aqui por dez anos."],"formasEn":{"I lived here for ten years":"pretérito","I will live here for ten years":"futuro","I would live here for ten years":"condicional","I had lived here for ten years":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","regular","live","present perfect","cotidiano"],"nota":"O present perfect liga o passado ao agora: «I have lived here» quer dizer que ainda moro. Com o passado simples, «I lived here», já saí. O português resolve os dois com o presente e um «há», e é por isso que a diferença escapa.","v":"6528be4f"},{"idioma":"en","id":"en-v138","tipo":"frase","en":"She had already left.","pt":"Ela já tinha ido embora.","aceitas":["ela ja tinha ido embora","ela ja havia ido embora","ela ja tinha saido","ela ja tinha partido"],"aceitasEn":["she had already left","shed already left"],"distratores":["Ela já foi embora.","Ela já vai embora.","Ela já iria embora.","Ela já estava indo embora."],"formasEn":{"She has already left":"pretérito perfeito","She already leaves":"presente","She will already have left":"futuro perfeito","She would already have left":"condicional composto"},"nivel":"B1","tags":["conjugação","irregular","leave","mais-que-perfeito","social"],"nota":"O mais-que-perfeito marca o passado anterior a outro passado: quando eu cheguei, ela já tinha saído. Em inglês é «had» mais o particípio, e a forma não muda com a pessoa — «I had», «she had», «they had».","v":"4341a26b"},{"idioma":"en","id":"en-v139","tipo":"frase","en":"We were going to leave.","pt":"A gente ia sair.","aceitas":["a gente ia sair","nos iamos sair","estavamos para sair","a gente estava de saida"],"aceitasEn":["we were going to leave","we were about to leave"],"distratores":["A gente vai sair.","A gente saiu mesmo.","A gente sairia hoje.","A gente tinha saído."],"formasEn":{"We are going to leave":"presente","We left":"pretérito","We would leave":"condicional","We had left":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","leave","imperfeito","social"],"nota":"«Was going to» é o futuro que não aconteceu: a intenção que ficou no meio do caminho. Quase sempre vem com um «but» logo atrás — «we were going to leave, but it started raining».","v":"7c10ee9b"},{"idioma":"en","id":"en-v140","tipo":"frase","en":"These shoes are made in Brazil.","pt":"Estes sapatos são feitos no Brasil.","aceitas":["estes sapatos sao feitos no brasil","esses sapatos sao feitos no brasil","estes sapatos sao fabricados no brasil","esses sapatos vem do brasil"],"aceitasEn":["these shoes are made in brazil"],"distratores":["Estes sapatos foram feitos no Brasil.","Estes sapatos serão feitos no Brasil.","Estes sapatos seriam feitos no Brasil.","Estes sapatos tinham sido feitos no Brasil."],"formasEn":{"These shoes were made in Brazil":"pretérito","These shoes will be made in Brazil":"futuro","These shoes would be made in Brazil":"condicional","These shoes had been made in Brazil":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","make","presente","economia"],"nota":"A passiva é «to be» mais o particípio, e o inglês a usa muito mais que o português — é a forma padrão do rótulo, da bula e do relatório. Quem fez não aparece, e é exatamente esse o ponto.","v":"e5584e62"},{"idioma":"en","id":"en-v141","tipo":"frase","en":"The house was sold last year.","pt":"A casa foi vendida ano passado.","aceitas":["a casa foi vendida ano passado","a casa foi vendida no ano passado","venderam a casa ano passado","a casa acabou vendida ano passado"],"aceitasEn":["the house was sold last year"],"distratores":["A casa é vendida todo ano.","A casa será vendida ano que vem.","A casa seria vendida ano que vem.","A casa tinha sido vendida antes."],"formasEn":{"The house is sold every year":"presente","The house will be sold next year":"futuro","The house would be sold next year":"condicional","The house had been sold before":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","sell","pretérito","economia"],"nota":"Na passiva do passado o «to be» é que vai para o passado, e o particípio não muda: «was sold», «were sold». Para dizer quem vendeu, entra «by» no fim — «the house was sold by an agency».","v":"25a0ce2a"},{"idioma":"en","id":"en-v142","tipo":"frase","en":"They bred horses for years.","pt":"Eles criaram cavalos por anos.","aceitas":["eles criaram cavalos por anos","criaram cavalos por anos","eles criaram cavalos durante anos","eles foram criadores de cavalos por anos"],"aceitasEn":["they bred horses for years"],"distratores":["Eles criam cavalos por anos.","Eles criarão cavalos por anos.","Eles criariam cavalos por anos.","Eles tinham criado cavalos por anos."],"formasEn":{"They breed horses":"presente","They will breed horses":"futuro","They would breed horses":"condicional","They had bred horses":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","breed","pretérito","animais"],"nota":"breed, bred, bred — o «ee» encurta, no mesmo molde de feed/fed e bleed/bled. O substantivo é a raça do animal: «what breed is your dog?». E «well-bred» é bem-educado, dito de gente.","v":"cac71b10"},{"idioma":"en","id":"en-v143","tipo":"frase","en":"She oversaw the whole project.","pt":"Ela supervisionou o projeto inteiro.","aceitas":["ela supervisionou o projeto inteiro","ela supervisionou todo o projeto","ela coordenou o projeto inteiro","ela tocou o projeto inteiro"],"aceitasEn":["she oversaw the whole project"],"distratores":["Ela supervisiona o projeto inteiro.","Ela supervisionará o projeto inteiro.","Ela supervisionaria o projeto inteiro.","Ela tinha supervisionado o projeto inteiro."],"formasEn":{"She oversees the whole project":"presente","She will oversee the whole project":"futuro","She would oversee the whole project":"condicional","She had overseen the whole project":"mais-que-perfeito"},"nivel":"B2","tags":["conjugação","irregular","oversee","pretérito","trabalho"],"nota":"oversee, oversaw, overseen — conjuga como «see». Cuidado com o falso parente: «overlook» é deixar passar sem ver, e «oversee» é justamente o contrário, olhar de cima e cuidar de tudo.","v":"9553a8d3"},{"idioma":"en","id":"en-v144","tipo":"frase","en":"The bridge withstood the storm.","pt":"A ponte resistiu à tempestade.","aceitas":["a ponte resistiu a tempestade","a ponte aguentou a tempestade","a ponte suportou a tempestade","a ponte nao cedeu na tempestade"],"aceitasEn":["the bridge withstood the storm"],"distratores":["A ponte resiste à tempestade.","A ponte resistirá à tempestade.","A ponte resistiria à tempestade.","A ponte tinha resistido à tempestade."],"formasEn":{"The bridge withstands the storm":"presente","The bridge will withstand the storm":"futuro","The bridge would withstand the storm":"condicional","The bridge had withstood the storm":"mais-que-perfeito"},"nivel":"B2","tags":["conjugação","irregular","withstand","pretérito"],"nota":"withstand, withstood, withstood — conjuga como «stand», e o «with-» aqui é o de «contra», sentido antigo que sobrevive só nesta família: withstand, withhold, withdraw. É resistir sem ceder.","v":"1c319f42"},{"idioma":"en","id":"en-v145","tipo":"frase","en":"He undertook the task alone.","pt":"Ele assumiu a tarefa sozinho.","aceitas":["ele assumiu a tarefa sozinho","ele encarou a tarefa sozinho","ele tomou a tarefa para si","ele se encarregou da tarefa sozinho"],"aceitasEn":["he undertook the task alone"],"distratores":["Ele assume a tarefa sozinho.","Ele assumirá a tarefa sozinho.","Ele assumiria a tarefa sozinho.","Ele tinha assumido a tarefa sozinho."],"formasEn":{"He undertakes the task alone":"presente","He will undertake the task alone":"futuro","He would undertake the task alone":"condicional","He had undertaken the task alone":"mais-que-perfeito"},"nivel":"B2","tags":["conjugação","irregular","undertake","pretérito","trabalho"],"nota":"undertake, undertook, undertaken — conjuga como «take». É palavra de relatório: assumir uma tarefa grande e responder por ela. E o substantivo «undertaker» mudou de ramo — hoje é o agente funerário.","v":"4b5bdc06"},{"idioma":"en","id":"en-v146","tipo":"frase","en":"He is being interviewed right now.","pt":"Ele está sendo entrevistado agora.","aceitas":["ele esta sendo entrevistado agora","ele ta sendo entrevistado agora","estao entrevistando ele agora","ele esta em entrevista agora"],"aceitasEn":["he is being interviewed right now","hes being interviewed right now"],"distratores":["Ele é entrevistado toda semana.","Ele foi entrevistado ontem.","Ele será entrevistado amanhã.","Ele tinha sido entrevistado antes."],"formasEn":{"He is interviewed every week":"presente","He was interviewed yesterday":"pretérito","He will be interviewed tomorrow":"futuro","He had been interviewed before":"mais-que-perfeito"},"nivel":"B2","tags":["conjugação","regular","interview","presente","mídia"],"nota":"A passiva contínua empilha três peças: «is» mais «being» mais o particípio. É a forma do que está sendo feito neste instante, e o espanhol quase sempre a desfaz com «lo están» — porque em espanhol ela soa pesada.","v":"bcbfac97"},{"idioma":"en","id":"en-p163","tipo":"palavra","en":"the bed","pt":"a cama","aceitas":["a cama","cama","as camas"],"aceitasEn":["the bed","bed","a bed"],"distratores":["o sofá","o travesseiro","o colchão","o berço"],"nivel":"A1","tags":["substantivo","casa","objetos"],"nota":"«Bed» é a cama, e some o artigo em muita expressão: go to bed, in bed, before bed. Nessas horas o inglês trata a cama como lugar, e não como móvel.","v":"5b33df67"},{"idioma":"en","id":"en-u163","tipo":"frase","requer":"en-p163","en":"I'm going to bed.","pt":"Vou dormir.","aceitas":["vou dormir","vou para a cama","estou indo dormir","vou me deitar","vou deitar"],"aceitasEn":["im going to bed","i am going to bed"],"distratores":["Vou ao banheiro.","Vou à cozinha.","Vou ao mercado.","Vou ao trabalho."],"nivel":"A1","tags":["substantivo","casa","cotidiano"],"nota":"«Go to bed» não leva artigo: é a cama como destino, não como objeto. Com artigo, «go to the bed», seria caminhar até o móvel. A mesma economia vale para go to school, go to work, go to church.","v":"665bce14"},{"idioma":"en","id":"en-p164","tipo":"palavra","en":"the table","pt":"a mesa","aceitas":["a mesa","mesa","as mesas"],"aceitasEn":["the table","table","a table"],"distratores":["a cadeira","a estante","a bancada","a escrivaninha"],"nivel":"A1","tags":["substantivo","casa","objetos"],"nota":"«Table» é a mesa de comer e a tabela de números — a mesma palavra para as duas, e é daí que vem «timetable», a tabela de horários. A mesa de escritório, com gavetas, é «desk».","v":"84108695"},{"idioma":"en","id":"en-u164","tipo":"frase","requer":"en-p164","en":"Set the table, please.","pt":"Põe a mesa, por favor.","aceitas":["poe a mesa por favor","ponha a mesa por favor","bota a mesa por favor","arruma a mesa por favor"],"aceitasEn":["set the table please","please set the table"],"distratores":["Limpa a mesa, por favor.","Tira a mesa, por favor.","Arrasta a mesa, por favor.","Reserva a mesa, por favor."],"nivel":"A1","tags":["substantivo","casa","comida"],"nota":"«Set the table» é pôr a mesa, com «set» no lugar de «put». É o verbo de arrumar as coisas no lugar certo — o mesmo de set the alarm, set a date, set a price.","v":"0a5e3a46"},{"idioma":"en","id":"en-p165","tipo":"palavra","en":"the money","pt":"o dinheiro","aceitas":["o dinheiro","dinheiro","a grana"],"aceitasEn":["the money","money","some money"],"distratores":["a moeda","a conta","o cartão","o troco"],"nivel":"A1","tags":["substantivo","economia"],"nota":"«Money» não tem plural e leva verbo no singular: «the money is gone». O que se conta são «bills» e «coins», as notas e as moedas, e «cash» é o dinheiro vivo.","v":"bf45e9e1"},{"idioma":"en","id":"en-u165","tipo":"frase","requer":"en-p165","en":"I don't have any money.","pt":"Não tenho dinheiro.","aceitas":["nao tenho dinheiro","eu nao tenho dinheiro","estou sem dinheiro","nao tenho nenhum dinheiro"],"aceitasEn":["i dont have any money","i do not have any money","i havent got any money"],"distratores":["Não tenho tempo.","Não tenho troco.","Não tenho fome.","Não tenho pressa."],"nivel":"A1","tags":["substantivo","economia","cotidiano"],"nota":"«Any» aparece na negativa e na pergunta, e não se traduz: «I don't have any money» é só «não tenho dinheiro». Na afirmativa ele troca de forma e vira «some» — «I have some money».","v":"ccb91e9f"},{"idioma":"en","id":"en-p166","tipo":"palavra","en":"the child","pt":"a criança","aceitas":["a crianca","crianca","as criancas"],"aceitasEn":["the child","child","a child"],"distratores":["o adulto","o bebê","o jovem","o neto"],"nivel":"A1","tags":["substantivo","família"],"nota":"«Child» não diz o sexo, e o plural é irregular: «children». É palavra de formulário e de notícia; em casa se diz «kid» — «how many kids do you have?».","v":"7f7a78c2"},{"idioma":"en","id":"en-u166","tipo":"frase","requer":"en-p166","en":"She has three children.","pt":"Ela tem três filhos.","aceitas":["ela tem tres filhos","tem tres filhos","ela tem tres criancas","ela e mae de tres"],"aceitasEn":["she has three children","shes got three children"],"distratores":["Ela tem três irmãos.","Ela tem três netos.","Ela tem três sobrinhos.","Ela tem três gatos."],"nivel":"A1","tags":["substantivo","família"],"nota":"«Children» é o plural irregular de «child», e serve a dois sentidos: as crianças em geral e os filhos de alguém. Aqui é filhos, e a frase não diz a idade de ninguém — «children» de trinta anos continuam «children» da mãe.","v":"013cd30b"},{"idioma":"en","id":"en-p167","tipo":"palavra","en":"the eye","pt":"o olho","aceitas":["o olho","olho","os olhos"],"aceitasEn":["the eye","eye","an eye"],"distratores":["a orelha","o nariz","a boca","a sobrancelha"],"nivel":"A1","tags":["substantivo","corpo"],"nota":"«Eye» é o olho, com plural regular. A palavra entra em muita expressão: «keep an eye on» é ficar de olho, «an eye for detail» é olho clínico, e «see eye to eye» é concordar.","v":"2ec4dbc2"},{"idioma":"en","id":"en-u167","tipo":"frase","requer":"en-p167","en":"Close your eyes.","pt":"Fecha os olhos.","aceitas":["fecha os olhos","feche os olhos","fecha o olho","cerra os olhos"],"aceitasEn":["close your eyes","shut your eyes"],"distratores":["Fecha a boca.","Fecha as mãos.","Fecha a porta.","Fecha o livro."],"nivel":"A1","tags":["substantivo","corpo"],"nota":"O possessivo é obrigatório: «close your eyes», e nunca «close the eyes». E o plural também — são dois, e «close your eye» seria fechar um só, de propósito.","v":"3a29f934"},{"idioma":"en","id":"en-p168","tipo":"palavra","en":"the car","pt":"o carro","aceitas":["o carro","carro","os carros","o automovel"],"aceitasEn":["the car","car","a car"],"distratores":["o ônibus","a moto","o caminhão","a bicicleta"],"nivel":"A1","tags":["substantivo","viagem","objetos"],"nota":"«Car» é o carro, e é também o vagão do trem — «the dining car». O carrinho do mercado é «cart», e o de bebê é «stroller»: três coisas que o português chama quase igual e o inglês separa.","v":"3eae053d"},{"idioma":"en","id":"en-u168","tipo":"frase","requer":"en-p168","en":"My car won't start.","pt":"Meu carro não pega.","aceitas":["meu carro nao pega","meu carro nao liga","meu carro nao esta pegando","o carro nao quer pegar"],"aceitasEn":["my car wont start","my car will not start"],"distratores":["Meu carro não anda.","Meu carro não freia.","Meu carro não tem gasolina.","Meu carro não sai da garagem."],"nivel":"A1","tags":["substantivo","viagem","cotidiano"],"nota":"«Won't» aqui não é futuro: é recusa. «My car won't start» é «meu carro não quer pegar», com a mesma personificação do português — e é por isso que «doesn't start» soa mais frio, de laudo de mecânico.","v":"a1c2cee5"},{"idioma":"en","id":"en-p169","tipo":"palavra","en":"the elevator","pt":"o elevador","aceitas":["o elevador","elevador","os elevadores"],"aceitasEn":["the elevator","elevator","an elevator"],"regionaisEn":{"the lift":"na Inglaterra","lift":"na Inglaterra"},"distratores":["a escada","a rampa","o corredor","a portaria"],"nivel":"A2","tags":["substantivo","cidade","objetos"],"nota":"«Elevator» é o elevador nos Estados Unidos; na Inglaterra é «lift». A escada rolante é «escalator» nos dois lados do mar, e é fácil trocar as duas.","v":"14ef79ce"},{"idioma":"en","id":"en-u169","tipo":"frase","requer":"en-p169","en":"The elevator is broken.","pt":"O elevador está quebrado.","aceitas":["o elevador esta quebrado","o elevador quebrou","o elevador nao esta funcionando","o elevador esta com defeito"],"aceitasEn":["the elevator is broken","the elevators broken"],"regionaisEn":{"the lift is broken":"na Inglaterra"},"distratores":["O chuveiro está quebrado.","O portão está quebrado.","O ventilador está quebrado.","O interfone está quebrado."],"nivel":"A2","tags":["substantivo","cidade","cotidiano"],"nota":"«Broken» serve ao que se partiu e ao que parou de funcionar: o elevador, o braço, a promessa. Na placa do prédio americano se lê «out of order», que é o mesmo recado por escrito.","v":"f324bb1a"},{"idioma":"en","id":"en-p170","tipo":"palavra","en":"the apartment","pt":"o apartamento","aceitas":["o apartamento","apartamento","o ap"],"aceitasEn":["the apartment","apartment","an apartment"],"regionaisEn":{"the flat":"na Inglaterra","flat":"na Inglaterra"},"distratores":["a casa","o quarto","o prédio","o terreno"],"nivel":"A2","tags":["substantivo","casa","cidade"],"nota":"«Apartment» é o apartamento nos Estados Unidos; na Inglaterra é «flat», e lá «apartment» soa a aluguel de luxo. O prédio inteiro é «apartment building».","v":"c1e7de6e"},{"idioma":"en","id":"en-u170","tipo":"frase","requer":"en-p170","en":"They live in a small apartment.","pt":"Eles moram num apartamento pequeno.","aceitas":["eles moram num apartamento pequeno","eles moram em um apartamento pequeno","eles moram num ap pequeno","moram num apartamento pequeno"],"aceitasEn":["they live in a small apartment"],"regionaisEn":{"they live in a small flat":"na Inglaterra"},"distratores":["Eles moram num quarto pequeno.","Eles moram num sítio pequeno.","Eles moram num hotel pequeno.","Eles moram num barco pequeno."],"nivel":"A2","tags":["substantivo","casa","cidade"],"nota":"O adjetivo vem antes do substantivo: «a small apartment». E repare no artigo «a», que o inglês exige e o português dispensa quando diz só «moram em apartamento pequeno».","v":"3fce79a9"},{"idioma":"en","id":"en-p171","tipo":"palavra","en":"the garbage","pt":"o lixo","aceitas":["o lixo","lixo"],"aceitasEn":["the garbage","garbage","the trash","trash"],"regionaisEn":{"the rubbish":"na Inglaterra","rubbish":"na Inglaterra"},"distratores":["a poeira","a sujeira","o entulho","a reciclagem"],"nivel":"A2","tags":["substantivo","casa","cidade"],"nota":"«Garbage» e «trash» valem as duas nos Estados Unidos; na Inglaterra é «rubbish», que lá também é adjetivo de desprezo — «the film was rubbish» é «o filme foi uma porcaria».","v":"0a70aa9d"},{"idioma":"en","id":"en-u171","tipo":"frase","requer":"en-p171","en":"Take out the garbage.","pt":"Leva o lixo para fora.","aceitas":["leva o lixo para fora","leve o lixo para fora","poe o lixo na rua","desce o lixo","leva o lixo"],"aceitasEn":["take out the garbage","take the garbage out","take out the trash"],"regionaisEn":{"take out the rubbish":"na Inglaterra"},"distratores":["Leva o cachorro para fora.","Leva a bicicleta para fora.","Leva as plantas para fora.","Leva as cadeiras para fora."],"nivel":"A2","tags":["substantivo","casa","cotidiano"],"nota":"«Take out» se separa quando entra um pronome: «take it out». É a tarefa doméstica que mais aparece em série americana, e o lixo vai «out» porque na casa de lá a lixeira fica na calçada.","v":"ac62e757"},{"idioma":"en","id":"en-p172","tipo":"palavra","en":"the cookie","pt":"o biscoito","aceitas":["o biscoito","biscoito","a bolacha"],"aceitasEn":["the cookie","cookie","a cookie"],"regionaisEn":{"the biscuit":"na Inglaterra","biscuit":"na Inglaterra"},"distratores":["o bolo","o pão","a bala","o sorvete"],"nivel":"A2","tags":["substantivo","comida"],"nota":"«Cookie» é o biscoito doce nos Estados Unidos; na Inglaterra é «biscuit», e lá «cookie» só serve ao grandão de gotas de chocolate. Cuidado com o falso parente: «biscuit» nos Estados Unidos é um pãozinho salgado que se come com molho.","v":"503f4f20"},{"idioma":"en","id":"en-u172","tipo":"frase","requer":"en-p172","en":"Do you want a cookie?","pt":"Quer um biscoito?","aceitas":["quer um biscoito","voce quer um biscoito","quer uma bolacha","aceita um biscoito"],"aceitasEn":["do you want a cookie","would you like a cookie"],"regionaisEn":{"do you want a biscuit":"na Inglaterra"},"distratores":["Quer um pedaço de bolo?","Quer um pão?","Quer uma bala?","Quer um sorvete?"],"nivel":"A2","tags":["substantivo","comida","social"],"nota":"O biscoito é contável, então leva «a»: «a cookie». E para oferecer, o dia a dia usa «do you want» e a boa educação usa «would you like» — a segunda é a do garçom.","v":"94c0ab7c"},{"idioma":"en","id":"en-p173","tipo":"palavra","en":"the line","pt":"a fila","aceitas":["a fila","fila","a linha","a fileira"],"aceitasEn":["the line","line","a line"],"regionaisEn":{"the queue":"na Inglaterra","queue":"na Inglaterra"},"distratores":["a porta","a entrada","a bilheteria","a saída"],"nivel":"A2","tags":["substantivo","cidade","cotidiano"],"nota":"«Line» é a fila nos Estados Unidos; na Inglaterra é «queue», que se escreve com cinco letras e se pronuncia como a letra Q. A palavra também é a linha e o verso de poema, e o contexto separa os três.","v":"ec7182a9"},{"idioma":"en","id":"en-u173","tipo":"frase","requer":"en-p173","en":"There's a long line.","pt":"Tem uma fila grande.","aceitas":["tem uma fila grande","tem uma fila enorme","a fila esta grande","tem fila grande","ta uma fila enorme"],"aceitasEn":["theres a long line","there is a long line"],"regionaisEn":{"theres a long queue":"na Inglaterra"},"distratores":["Tem uma escada grande.","Tem uma festa grande.","Tem uma sala grande.","Tem uma placa grande."],"nivel":"A2","tags":["substantivo","cidade","cotidiano"],"nota":"Em inglês a fila é «long», comprida, e nunca «big»: o tamanho que conta é o comprimento. E «stand in line» é ficar na fila, com «in» — «on line» só se diz em Nova York.","v":"ea2b2b42"},{"idioma":"en","id":"en-p174","tipo":"palavra","en":"the vacation","pt":"as férias","aceitas":["as ferias","ferias","o periodo de ferias"],"aceitasEn":["the vacation","vacation","a vacation"],"regionaisEn":{"the holiday":"na Inglaterra","holiday":"na Inglaterra"},"distratores":["o feriado","a folga","a viagem","o recesso"],"nivel":"A2","tags":["substantivo","viagem","trabalho"],"nota":"«Vacation» é singular em inglês onde o português põe no plural: «a two-week vacation». Na Inglaterra se diz «holiday», que nos Estados Unidos quer dizer feriado — «Thanksgiving is a holiday».","v":"e2bf7410"},{"idioma":"en","id":"en-u174","tipo":"frase","requer":"en-p174","en":"We're on vacation.","pt":"Estamos de férias.","aceitas":["estamos de ferias","a gente esta de ferias","estamos em ferias","to de ferias"],"aceitasEn":["were on vacation","we are on vacation"],"regionaisEn":{"were on holiday":"na Inglaterra"},"distratores":["Estamos de folga.","Estamos de mudança.","Estamos de passagem.","Estamos de luto."],"nivel":"A2","tags":["substantivo","viagem","trabalho"],"nota":"«On vacation» leva «on» e não leva artigo nenhum. É a construção de «on holiday», «on a trip», «on duty» — o inglês põe a pessoa em cima da situação em que ela está.","v":"0c9041c4"},{"idioma":"en","id":"en-p175","tipo":"palavra","en":"the oven","pt":"o forno","aceitas":["o forno","forno","os fornos"],"aceitasEn":["the oven","oven","an oven"],"distratores":["a geladeira","o fogão","a pia","o micro-ondas"],"nivel":"A2","tags":["substantivo","casa","comida"],"nota":"«Oven» é o forno fechado, e o fogão de boca é «stove»: duas palavras para o que o português chama com uma. A luva de forno é «oven mitt» nos Estados Unidos e «oven glove» na Inglaterra.","v":"9d2b73c7"},{"idioma":"en","id":"en-u175","tipo":"frase","requer":"en-p175","en":"Put it in the oven.","pt":"Põe no forno.","aceitas":["poe no forno","ponha no forno","bota no forno","coloca no forno","leva ao forno"],"aceitasEn":["put it in the oven","put that in the oven"],"distratores":["Põe na geladeira.","Põe na pia.","Põe no armário.","Põe na janela."],"nivel":"A2","tags":["substantivo","casa","comida"],"nota":"No forno é «in the oven», porque é espaço fechado; em cima do fogão é «on the stove». As duas preposições ficam a um palmo de distância na cozinha e não se trocam.","v":"4d9ba764"},{"idioma":"en","id":"en-p176","tipo":"palavra","en":"the tray","pt":"a bandeja","aceitas":["a bandeja","bandeja","as bandejas"],"aceitasEn":["the tray","tray","a tray"],"distratores":["o prato","a tigela","a travessa","a tábua"],"nivel":"A2","tags":["substantivo","comida","objetos"],"nota":"«Tray» é a bandeja de carregar, e também a gaveta rasa da impressora. No restaurante de self-service ela é obrigatória, e a esteira de devolver é o «tray return».","v":"f7c588e4"},{"idioma":"en","id":"en-u176","tipo":"frase","requer":"en-p176","en":"She carried the tray carefully.","pt":"Ela carregou a bandeja com cuidado.","aceitas":["ela carregou a bandeja com cuidado","ela levou a bandeja com cuidado","ela segurou a bandeja com cuidado","ela carregou a bandeja devagar"],"aceitasEn":["she carried the tray carefully"],"distratores":["Ela carregou a caixa com cuidado.","Ela carregou o vaso com cuidado.","Ela carregou o bolo com cuidado.","Ela carregou a mala com cuidado."],"nivel":"A2","tags":["substantivo","objetos","cotidiano"],"nota":"«Carry» é levar carregando no corpo, e «take» é levar sem dizer como. O advérbio em «-ly» fica no fim: «carefully». E «careful!» sozinho, sem o «-ly», é o grito de aviso.","v":"d073d337"},{"idioma":"en","id":"en-p177","tipo":"palavra","en":"the jar","pt":"o pote","aceitas":["o pote","pote","o vidro","o pote de vidro"],"aceitasEn":["the jar","jar","a jar"],"distratores":["a lata","a garrafa","a caixa","o saco"],"nivel":"A2","tags":["substantivo","casa","comida"],"nota":"«Jar» é o pote de vidro de boca larga, o da geleia e o do azeite. A lata é «can», a garrafa é «bottle», e o de plástico com tampa é «container». Como verbo, «jar» é sacudir com força.","v":"3e43f2e0"},{"idioma":"en","id":"en-u177","tipo":"frase","requer":"en-p177","en":"Open the jar for me.","pt":"Abre o pote para mim.","aceitas":["abre o pote para mim","abra o pote para mim","abre o pote pra mim","abre esse pote para mim"],"aceitasEn":["open the jar for me","can you open the jar for me"],"distratores":["Abre a lata para mim.","Abre a garrafa para mim.","Abre a porta para mim.","Abre a caixa para mim."],"nivel":"A2","tags":["substantivo","comida","social"],"nota":"«For me» vai no fim, e é o que transforma a ordem em pedido. Sem ele, «open the jar» é instrução seca de receita. O espanhol resolve com o pronome colado no verbo, e o inglês não tem essa saída.","v":"d2933d15"},{"idioma":"en","id":"en-p178","tipo":"palavra","en":"the rug","pt":"o tapete","aceitas":["o tapete","tapete","os tapetes"],"aceitasEn":["the rug","rug","a rug"],"distratores":["a cortina","o lençol","a toalha","a almofada"],"nivel":"A2","tags":["substantivo","casa","objetos"],"nota":"«Rug» é o tapete solto, de um pedaço do chão; o que cobre o piso todo é «carpet». E «to pull the rug out from under someone» é tirar o tapete de alguém, com a mesma imagem do português.","v":"cdca9aa0"},{"idioma":"en","id":"en-u178","tipo":"frase","requer":"en-p178","en":"There's a rug by the door.","pt":"Tem um tapete na porta.","aceitas":["tem um tapete na porta","ha um tapete na porta","tem um tapete perto da porta","tem um capacho na porta"],"aceitasEn":["theres a rug by the door","there is a rug by the door"],"distratores":["Tem um banco na porta.","Tem um vaso na porta.","Tem um guarda-chuva na porta.","Tem um cabide na porta."],"nivel":"A2","tags":["substantivo","casa","preposição"],"nota":"«By» é «ao lado de», e é a forma curta de «next to», que diz o mesmo. O capacho de limpar os pés tem nome próprio em inglês: «doormat».","v":"61b1ef0f"},{"idioma":"en","id":"en-p179","tipo":"palavra","en":"the kettle","pt":"a chaleira","aceitas":["a chaleira","chaleira","as chaleiras"],"aceitasEn":["the kettle","kettle","a kettle"],"distratores":["a panela","a frigideira","a jarra","a caneca"],"nivel":"A2","tags":["substantivo","casa","comida"],"nota":"«Kettle» é a chaleira de ferver água. Na Inglaterra ela é elétrica e está em toda cozinha, e «put the kettle on» quer dizer «vou fazer um chá». Nos Estados Unidos é menos comum, e a de fogão chama-se «teakettle».","v":"812571f4"},{"idioma":"en","id":"en-u179","tipo":"frase","requer":"en-p179","en":"The kettle is boiling.","pt":"A chaleira está fervendo.","aceitas":["a chaleira esta fervendo","a agua da chaleira esta fervendo","a chaleira ferveu","a chaleira esta apitando"],"aceitasEn":["the kettle is boiling","the kettles boiling"],"distratores":["A panela está fervendo.","A sopa está fervendo.","O leite está fervendo.","O óleo está fervendo."],"nivel":"A2","tags":["substantivo","casa","comida"],"nota":"Quem ferve é a água, e o inglês diz que é a chaleira: a mesma figura de pôr o recipiente no lugar do conteúdo que o português usa em «o copo caiu». E «put the kettle on» é o convite inglês para conversar.","v":"60081c98"},{"idioma":"en","id":"en-p180","tipo":"palavra","en":"the flashlight","pt":"a lanterna","aceitas":["a lanterna","lanterna","as lanternas"],"aceitasEn":["the flashlight","flashlight","a flashlight"],"regionaisEn":{"the torch":"na Inglaterra","torch":"na Inglaterra"},"distratores":["a vela","o abajur","o farol","a tocha"],"nivel":"B1","tags":["substantivo","objetos"],"nota":"«Flashlight» é a lanterna de mão nos Estados Unidos; na Inglaterra é «torch», que do lado americano quer dizer tocha de fogo. A do celular é «the flashlight» nos dois lados, porque o nome veio do aplicativo.","v":"a1e26b05"},{"idioma":"en","id":"en-u180","tipo":"frase","requer":"en-p180","en":"Bring a flashlight.","pt":"Traz uma lanterna.","aceitas":["traz uma lanterna","traga uma lanterna","leve uma lanterna","traz lanterna"],"aceitasEn":["bring a flashlight","bring a flashlight with you"],"regionaisEn":{"bring a torch":"na Inglaterra"},"distratores":["Traz uma vela.","Traz um cobertor.","Traz uma corda.","Traz um mapa."],"nivel":"B1","tags":["substantivo","objetos","viagem"],"nota":"«Bring» é trazer para onde quem fala está, e «take» é levar para outro lugar. O português divide igual, com «trazer» e «levar», e é por isso que o erro aqui é raro — mas é o mais comum entre quem vem do espanhol, que usa «llevar» para os dois.","v":"66a85ab1"},{"idioma":"en","id":"en-p181","tipo":"palavra","en":"the trunk","pt":"o porta-malas","aceitas":["o porta malas","porta malas","o bagageiro"],"aceitasEn":["the trunk","trunk","a trunk"],"regionaisEn":{"the boot":"na Inglaterra","boot":"na Inglaterra"},"distratores":["o capô","o painel","o para-choque","o tanque"],"nivel":"B1","tags":["substantivo","viagem","objetos"],"nota":"«Trunk» é o porta-malas nos Estados Unidos; na Inglaterra é «boot», que do outro lado é a bota. A palavra serve também ao tronco da árvore e ao baú de viagem — três coisas ligadas pela ideia de caixa grande.","v":"0dcaf238"},{"idioma":"en","id":"en-u181","tipo":"frase","requer":"en-p181","en":"Put the bags in the trunk.","pt":"Põe as malas no porta-malas.","aceitas":["poe as malas no porta malas","ponha as malas no porta malas","bota as malas no porta malas","coloca as malas no porta malas"],"aceitasEn":["put the bags in the trunk","put the bags in the trunk please"],"regionaisEn":{"put the bags in the boot":"na Inglaterra"},"distratores":["Põe as malas no banco de trás.","Põe as malas no chão.","Põe as malas na esteira.","Põe as malas no carrinho."],"nivel":"B1","tags":["substantivo","viagem","cotidiano"],"nota":"«Bags» serve à mala, à sacola e à bolsa: o inglês usa a palavra larga e deixa o contexto apertar. Quando é preciso ser exato, a mala de viagem tem nome próprio — «suitcase».","v":"2cd08c6a"},{"idioma":"en","id":"en-p182","tipo":"palavra","en":"the hood","pt":"o capô","aceitas":["o capo","capo","o capuz"],"aceitasEn":["the hood","hood","a hood"],"regionaisEn":{"the bonnet":"na Inglaterra","bonnet":"na Inglaterra"},"distratores":["o porta-malas","o teto","a porta","o para-brisa"],"nivel":"B1","tags":["substantivo","viagem","objetos"],"nota":"«Hood» é o capô nos Estados Unidos; na Inglaterra é «bonnet», que também é um gorro de bebê. E «hood» é o capuz do moletom — daí «hoodie», que já entrou no português.","v":"dc4da918"},{"idioma":"en","id":"en-u182","tipo":"frase","requer":"en-p182","en":"He opened the hood.","pt":"Ele abriu o capô.","aceitas":["ele abriu o capo","abriu o capo","ele levantou o capo","ele abriu o capo do carro"],"aceitasEn":["he opened the hood"],"regionaisEn":{"he opened the bonnet":"na Inglaterra"},"distratores":["Ele abriu o porta-malas.","Ele abriu a porta.","Ele abriu a janela.","Ele abriu o tanque."],"nivel":"B1","tags":["substantivo","viagem"],"nota":"O gesto é o de quem vai olhar o motor, e em inglês se diz «look under the hood» — que virou expressão para «ver como a coisa funciona por dentro», inclusive de programa de computador.","v":"60d12ad6"},{"idioma":"en","id":"en-p183","tipo":"palavra","en":"the stroller","pt":"o carrinho de bebê","aceitas":["o carrinho de bebe","carrinho de bebe","o carrinho"],"aceitasEn":["the stroller","stroller","a stroller"],"regionaisEn":{"the pram":"na Inglaterra","pram":"na Inglaterra","the pushchair":"na Inglaterra"},"distratores":["o berço","o cercadinho","a cadeirinha","o bebê conforto"],"nivel":"B1","tags":["substantivo","família","objetos"],"nota":"«Stroller» é o carrinho de bebê nos Estados Unidos. Na Inglaterra são dois: «pram» é o deitado, de recém-nascido, e «pushchair» é o sentado. A cadeirinha do carro é «car seat», e não se confunde com nenhum dos dois.","v":"30dfb415"},{"idioma":"en","id":"en-u183","tipo":"frase","requer":"en-p183","en":"The stroller doesn't fit.","pt":"O carrinho não cabe.","aceitas":["o carrinho nao cabe","o carrinho de bebe nao cabe","o carrinho nao entra","nao cabe o carrinho"],"aceitasEn":["the stroller doesnt fit","the stroller does not fit"],"regionaisEn":{"the pram doesnt fit":"na Inglaterra"},"distratores":["O berço não cabe.","A mala não cabe.","A bicicleta não cabe.","A cadeira não cabe."],"nivel":"B1","tags":["substantivo","família","viagem"],"nota":"«Fit» é caber, e dispensa preposição quando o lugar está implícito: «it doesn't fit». Com o lugar dito, entra «in» — «it doesn't fit in the trunk». E «fit» de roupa é servir: «these shoes don't fit».","v":"d81cb200"},{"idioma":"en","id":"en-p184","tipo":"palavra","en":"the band-aid","pt":"o curativo","aceitas":["o curativo","curativo","o band aid","o adesivo de ferimento"],"aceitasEn":["the band aid","band aid","a band aid"],"regionaisEn":{"the plaster":"na Inglaterra","plaster":"na Inglaterra"},"distratores":["o antisséptico","o algodão","o remédio","o termômetro"],"nivel":"B1","tags":["substantivo","saúde","objetos"],"nota":"«Band-Aid» era marca de fábrica e virou nome comum nos Estados Unidos, como «gilete» em português. Na Inglaterra se diz «plaster», que lá também é o gesso da parede. E «a band-aid solution» é o remendo, a solução que só tapa.","v":"c905cbc8"},{"idioma":"en","id":"en-u184","tipo":"frase","requer":"en-p184","en":"I need a band-aid.","pt":"Preciso de um curativo.","aceitas":["preciso de um curativo","eu preciso de um curativo","preciso de um band aid","me ve um curativo"],"aceitasEn":["i need a band aid","i need a bandaid"],"regionaisEn":{"i need a plaster":"na Inglaterra"},"distratores":["Preciso de um antisséptico.","Preciso de um algodão.","Preciso de um remédio.","Preciso de um termômetro."],"nivel":"B1","tags":["substantivo","saúde","cotidiano"],"nota":"É a frase do armário de banheiro e da farmácia. Repare no artigo «a»: o curativo é contável, e sem ele a frase soaria a pedido de gaze a metro.","v":"5b3b40de"},{"idioma":"en","id":"en-f261","tipo":"frase","en":"Is this seat taken?","pt":"Esse lugar está ocupado?","aceitas":["esse lugar esta ocupado","este lugar esta ocupado","esse assento esta ocupado","alguem esta sentado aqui","esta ocupado esse lugar"],"aceitasEn":["is this seat taken","is this seat free","is anyone sitting here"],"distratores":["Esse lugar está reservado?","Esse lugar está confortável?","Esse lugar está sujo?","Esse lugar está longe?"],"nivel":"A2","tags":["social","viagem"],"nota":"«Taken» é o particípio de «take», e aqui quer dizer «já pegado por alguém». A pergunta pelo contrário também vale e é mais simpática: «is this seat free?».","v":"93a5975a"},{"idioma":"en","id":"en-f262","tipo":"frase","en":"I'll take this one.","pt":"Vou ficar com este.","aceitas":["vou ficar com este","vou ficar com esse","eu fico com este","vou levar este","quero este"],"aceitasEn":["ill take this one","i will take this one","ill take this"],"distratores":["Vou pensar neste.","Vou devolver este.","Vou trocar este.","Vou deixar este."],"nivel":"A2","tags":["social","economia"],"nota":"«Take» na loja é levar comprado, e «I'll take it» é como se fecha a compra em inglês. O «one» no fim substitui o substantivo já dito — «this one» é «este aqui», sem repetir a coisa.","v":"58aca97a"},{"idioma":"en","id":"en-f263","tipo":"frase","en":"What's your phone number?","pt":"Qual é o seu telefone?","aceitas":["qual e o seu telefone","qual e seu telefone","qual e o seu numero","me passa o seu telefone","qual o seu telefone"],"aceitasEn":["whats your phone number","what is your phone number","whats your number"],"distratores":["Qual é o seu endereço?","Qual é o seu e-mail?","Qual é o seu sobrenome?","Qual é a sua idade?"],"nivel":"A2","tags":["social","cotidiano"],"nota":"Em inglês o número é lido dígito por dígito, e o zero se diz «oh» na fala: «five-oh-two». E repare na pergunta — é «what», e não «which», porque não há lista para escolher.","v":"c4886007"},{"idioma":"en","id":"en-f264","tipo":"frase","en":"Could you help me, please?","pt":"Você poderia me ajudar, por favor?","aceitas":["voce poderia me ajudar por favor","poderia me ajudar por favor","voce pode me ajudar por favor","sera que voce pode me ajudar"],"aceitasEn":["could you help me please","can you help me please","would you help me please"],"distratores":["Você poderia me esperar, por favor?","Você poderia me avisar, por favor?","Você poderia me acompanhar, por favor?","Você poderia me responder, por favor?"],"nivel":"A2","tags":["social","cotidiano"],"nota":"«Could» é mais educado que «can», e é o que se usa com estranho. O pronome vem logo depois do verbo, sem preposição: «help me», e nunca «help to me».","v":"e89e25da"},{"idioma":"en","id":"en-f265","tipo":"frase","en":"I'm looking for the station.","pt":"Estou procurando a estação.","aceitas":["estou procurando a estacao","to procurando a estacao","estou tentando achar a estacao","onde fica a estacao"],"aceitasEn":["im looking for the station","i am looking for the station"],"distratores":["Estou procurando o hotel.","Estou procurando o banheiro.","Estou procurando a saída.","Estou procurando o ônibus."],"nivel":"A2","tags":["viagem","cidade"],"nota":"«Look for» é procurar, e o «for» é obrigatório: sem ele, «look» é só olhar. É a frase com que se para um estranho na rua, e vale mais que apontar o mapa.","v":"b366ab3d"},{"idioma":"en","id":"en-f266","tipo":"frase","en":"Do you have a smaller size?","pt":"Tem um número menor?","aceitas":["tem um numero menor","voce tem um numero menor","tem um tamanho menor","tem menor","tem no numero menor"],"aceitasEn":["do you have a smaller size","do you have this in a smaller size"],"distratores":["Tem um número maior?","Tem outra cor?","Tem outro modelo?","Tem mais barato?"],"nivel":"A2","tags":["roupa","economia"],"nota":"«Size» serve ao número do sapato e ao tamanho da roupa — uma palavra onde o português usa duas. O comparativo curto leva «-er»: small, smaller; big, bigger. Só os longos pedem «more».","v":"6a7dee77"},{"idioma":"en","id":"en-f267","tipo":"frase","en":"Have a nice day.","pt":"Tenha um bom dia.","aceitas":["tenha um bom dia","tenha um otimo dia","bom dia para voce","um bom dia para voce","tenha um dia bom"],"aceitasEn":["have a nice day","have a good day","have a great day"],"distratores":["Tenha uma boa viagem.","Tenha uma boa noite.","Tenha um bom descanso.","Tenha um bom fim de semana."],"nivel":"A2","tags":["social","cotidiano"],"nota":"É a despedida padrão do caixa, do garçom e do motorista nos Estados Unidos, dita cem vezes por dia. Não espera resposta elaborada: «you too» basta, e é o que se responde.","v":"04c8017d"},{"idioma":"en","id":"en-f268","tipo":"frase","en":"Sorry, I'm lost.","pt":"Desculpa, estou perdido.","aceitas":["desculpa estou perdido","desculpe estou perdido","desculpa eu me perdi","desculpa to perdido","perdao estou perdido"],"aceitasEn":["sorry im lost","sorry i am lost","excuse me im lost"],"distratores":["Desculpa, estou atrasado.","Desculpa, estou com pressa.","Desculpa, estou cansado.","Desculpa, estou sem dinheiro."],"nivel":"A2","tags":["viagem","social"],"nota":"«Lost» é o particípio de «lose» usado como adjetivo: quem está perdido «is lost», e não «has lost». E vale para a cabeça também — «I'm lost» no meio de uma explicação é «não estou entendendo nada».","v":"7a0a4a2d"},{"idioma":"en","id":"en-f269","tipo":"frase","en":"Could you speak more slowly?","pt":"Você pode falar mais devagar?","aceitas":["voce pode falar mais devagar","pode falar mais devagar","da para falar mais devagar","fala mais devagar por favor"],"aceitasEn":["could you speak more slowly","can you speak more slowly","could you speak slower"],"distratores":["Você pode falar mais alto?","Você pode falar mais baixo?","Você pode falar em inglês?","Você pode falar depois?"],"nivel":"B1","tags":["social","escola"],"nota":"«Slowly» é o advérbio correto, com «-ly». «Slower» também se ouve e passa, mas «more slowly» é o que se escreve. E este é o pedido mais útil de todos para quem está começando — mais que qualquer palavra nova.","v":"0ea3abf6"},{"idioma":"en","id":"en-f270","tipo":"frase","en":"I'd like to make a reservation.","pt":"Gostaria de fazer uma reserva.","aceitas":["gostaria de fazer uma reserva","queria fazer uma reserva","eu gostaria de reservar","queria reservar uma mesa"],"aceitasEn":["id like to make a reservation","i would like to make a reservation","id like to book a table"],"distratores":["Gostaria de cancelar uma reserva.","Gostaria de confirmar uma reserva.","Gostaria de mudar uma reserva.","Gostaria de pagar a reserva."],"nivel":"B1","tags":["viagem","social"],"nota":"«Make a reservation» é o par fixo: a reserva se faz, e não se pede. Na Inglaterra se usa muito o verbo «book» — «I'd like to book a table» —, que nos Estados Unidos soa mais a passagem de avião.","v":"fe263172"},{"idioma":"en","id":"en-f271","tipo":"frase","en":"What do you recommend?","pt":"O que você recomenda?","aceitas":["o que voce recomenda","o que voce indica","o que voce sugere","qual voce recomenda","o que e bom aqui"],"aceitasEn":["what do you recommend","what would you recommend"],"distratores":["O que você prefere?","O que você pediu?","O que você acha disso?","O que você vai querer?"],"nivel":"B1","tags":["comida","social"],"nota":"«Recommend» não leva preposição antes do objeto: «recommend the fish», e nunca «recommend to the fish». Com pessoa, entra o objeto duplo — «I recommend you the fish» é erro; o certo é «I recommend the fish to you».","v":"3c892825"},{"idioma":"en","id":"en-f272","tipo":"frase","en":"Is breakfast included?","pt":"O café da manhã está incluído?","aceitas":["o cafe da manha esta incluido","o cafe esta incluido","inclui o cafe da manha","o cafe da manha ta incluso","esta incluido o cafe da manha"],"aceitasEn":["is breakfast included","does it include breakfast"],"distratores":["O café da manhã está pronto?","O café da manhã está servido?","O café da manhã está caro?","O café da manhã está quente?"],"nivel":"B1","tags":["viagem","comida"],"nota":"«Breakfast» entra sem artigo: é a refeição em geral, não um café da manhã específico. É a pergunta de balcão de hotel, e a resposta curta é «yes, it is» — repetindo o verbo, como o inglês sempre faz.","v":"caf4720d"},{"idioma":"en","id":"en-f273","tipo":"frase","en":"Can I try it on?","pt":"Posso experimentar?","aceitas":["posso experimentar","posso provar","da para experimentar","posso experimentar isso","posso vestir para ver"],"aceitasEn":["can i try it on","could i try it on","can i try this on"],"distratores":["Posso levar?","Posso devolver?","Posso reservar?","Posso pagar depois?"],"nivel":"B1","tags":["roupa","social"],"nota":"«Try on» é experimentar roupa, e o «on» é obrigatório: «try it» sozinho é provar comida ou tentar fazer. O pronome fica no meio — «try it on», e nunca «try on it».","v":"9612b68b"},{"idioma":"en","id":"en-f274","tipo":"frase","en":"Does this bus go downtown?","pt":"Esse ônibus vai para o centro?","aceitas":["esse onibus vai para o centro","este onibus vai para o centro","esse onibus vai ao centro","esse onibus passa no centro"],"aceitasEn":["does this bus go downtown","does this bus go to downtown"],"distratores":["Esse ônibus vai para o aeroporto?","Esse ônibus vai para a praia?","Esse ônibus vai para a rodoviária?","Esse ônibus vai para o hospital?"],"nivel":"B1","tags":["viagem","cidade"],"nota":"«Downtown» é o centro da cidade, e vai sem preposição e sem artigo: «go downtown», «live downtown». É palavra americana — na Inglaterra se diz «the city centre», com artigo e tudo.","v":"ecd6737a"},{"idioma":"en","id":"en-f275","tipo":"frase","en":"I'm allergic to nuts.","pt":"Sou alérgico a castanhas.","aceitas":["sou alergico a castanhas","eu sou alergico a castanhas","tenho alergia a castanhas","sou alergico a nozes"],"aceitasEn":["im allergic to nuts","i am allergic to nuts"],"distratores":["Sou alérgico à poeira.","Sou alérgico a camarão.","Sou alérgico a gato.","Sou alérgico a remédio."],"nivel":"B1","tags":["saúde","comida"],"nota":"A preposição é «to», sempre: allergic to nuts, allergic to cats. E «nuts» cobre castanha, noz, amêndoa e amendoim de uma vez — num restaurante americano a palavra vale como aviso para todas.","v":"b4966a35"},{"idioma":"en","id":"en-f276","tipo":"frase","en":"Keep the change.","pt":"Fica com o troco.","aceitas":["fica com o troco","fique com o troco","pode ficar com o troco","o troco e seu","deixa o troco"],"aceitasEn":["keep the change","you can keep the change"],"distratores":["Traz o troco.","Confere o troco.","Guarda a nota.","Conta o dinheiro."],"nivel":"B1","tags":["economia","social"],"nota":"«Change» é o troco e é também a mudança — a mesma palavra para as duas, e o contexto separa. E «keep» aqui é ficar com, no sentido de não devolver: é como se deixa gorjeta de táxi.","v":"88eed69f"},{"idioma":"en","id":"en-f277","tipo":"frase","en":"It's within walking distance.","pt":"Dá para ir andando.","aceitas":["da para ir andando","da para ir a pe","e perto o suficiente para ir andando","fica a pe daqui","e pertinho da para andar"],"aceitasEn":["its within walking distance","it is within walking distance"],"distratores":["Dá para ir de ônibus.","Dá para ir de bicicleta.","Dá para ir de carro.","Dá para ir de metrô."],"nivel":"B1","tags":["viagem","cidade"],"nota":"«Within walking distance» é fórmula de anúncio de imóvel e de hotel, e significa «perto o bastante para ir a pé». O «within» é «dentro de», e aqui mede a distância sem dizer quanto.","v":"9a462c8f"},{"idioma":"en","id":"en-f278","tipo":"frase","en":"Let me check.","pt":"Deixa eu ver.","aceitas":["deixa eu ver","deixe me ver","vou verificar","vou conferir","deixa eu conferir"],"aceitasEn":["let me check","let me check that","ill check"],"distratores":["Deixa eu pensar.","Deixa eu tentar.","Deixa eu explicar.","Deixa eu terminar."],"nivel":"B1","tags":["social","trabalho"],"nota":"«Check» é conferir, e é a palavra do atendente que vai olhar no sistema. Depois de «let me» o verbo vem sem «to» — «let me check», e nunca «let me to check».","v":"423c3c85"},{"idioma":"en","id":"en-f279","tipo":"frase","en":"I'll be right back.","pt":"Já volto.","aceitas":["ja volto","volto ja","eu ja volto","volto num instante","volto rapidinho"],"aceitasEn":["ill be right back","i will be right back","ill be back in a second"],"distratores":["Já vou.","Já acabei.","Já cheguei.","Já saí."],"nivel":"B1","tags":["social","cotidiano"],"nota":"«Right» aqui não é direita nem correto: é «já», intensificando o tempo. Serve em «right now», «right away», «right here» — e é o mesmo «já» que o português põe antes do verbo.","v":"45da5b4b"},{"idioma":"en","id":"en-f280","tipo":"frase","en":"That's all for now.","pt":"Por enquanto é só isso.","aceitas":["por enquanto e so isso","por enquanto e so","e so isso por agora","por ora e isso","so isso por enquanto"],"aceitasEn":["thats all for now","that is all for now"],"distratores":["Por enquanto é cedo.","Por enquanto está bom.","Por enquanto é difícil.","Por enquanto é segredo."],"nivel":"B1","tags":["social","trabalho"],"nota":"«For now» é «por enquanto», e marca que a lista pode crescer depois. É o jeito educado de encerrar um pedido sem fechar a porta, e serve em reunião, em consulta e em balcão.","v":"3bcf974f"},{"idioma":"en","id":"en-f281","tipo":"frase","en":"I'd appreciate it if you could help.","pt":"Eu agradeceria se você pudesse ajudar.","aceitas":["eu agradeceria se voce pudesse ajudar","agradeceria se voce pudesse ajudar","ficaria grato se voce pudesse ajudar","eu agradeceria muito a sua ajuda"],"aceitasEn":["id appreciate it if you could help","i would appreciate it if you could help"],"distratores":["Eu agradeço a ajuda de ontem.","Eu agradeceria uma explicação.","Eu aceitaria ajuda se precisasse.","Eu pediria ajuda se fosse grave."],"nivel":"B2","tags":["gramática","formal","trabalho"],"nota":"O «it» no meio parece sobrar e é obrigatório: «I'd appreciate it if…», nunca «I'd appreciate if». É o pronome que segura o lugar da oração que vem depois, e esquecê-lo é o deslize mais comum em e-mail de trabalho.","v":"1795bf16"},{"idioma":"en","id":"en-f282","tipo":"frase","en":"We're short-staffed today.","pt":"Estamos com pouca gente hoje.","aceitas":["estamos com pouca gente hoje","hoje estamos com pouca gente","estamos com a equipe reduzida hoje","falta gente hoje","estamos desfalcados hoje"],"aceitasEn":["were short staffed today","we are short staffed today"],"distratores":["Estamos com pouco tempo hoje.","Estamos com pouco espaço hoje.","Estamos com pouca luz hoje.","Estamos com pouca paciência hoje."],"nivel":"B2","tags":["trabalho","expressão"],"nota":"«Short» com hífen e um substantivo atrás vira adjetivo de falta: short-staffed, short-handed, short-sighted. É a desculpa padrão de restaurante e de loja em dia de fila, e o cliente americano entende na hora.","v":"1f40921d"},{"idioma":"en","id":"en-f283","tipo":"frase","en":"It's on back order.","pt":"Está em falta, com entrega marcada.","aceitas":["esta em falta com entrega marcada","esta em falta e ja foi encomendado","esta sem estoque mas ja foi pedido","o pedido esta na fila do fornecedor"],"aceitasEn":["its on back order","it is on back order","its on backorder"],"distratores":["Está em falta e sem previsão.","Está disponível para entrega.","Está reservado para outro cliente.","Está esgotado e fora de linha."],"nivel":"B2","tags":["economia","trabalho"],"nota":"«Back order» é o pedido que já foi feito ao fornecedor e espera chegada: não é «esgotado», que seria «out of stock» sem mais. A diferença importa na loja, porque uma tem data e a outra não.","v":"507e4534"},{"idioma":"en","id":"en-f284","tipo":"frase","en":"Let's circle back to that.","pt":"Vamos voltar a esse ponto depois.","aceitas":["vamos voltar a esse ponto depois","vamos retomar isso depois","depois a gente volta nesse ponto","guarda esse ponto para depois","vamos deixar esse ponto para depois"],"aceitasEn":["lets circle back to that","let us circle back to that"],"distratores":["Vamos dar uma volta agora.","Vamos rodear o assunto.","Vamos encerrar esse ponto.","Vamos decidir isso agora."],"nivel":"B2","tags":["expressão","trabalho"],"nota":"«Circle back» é dar a volta e voltar ao ponto: o inglês de reunião o usa para adiar sem recusar. É das expressões de escritório que mais se ouve em videoconferência americana, junto de «touch base» e «align».","v":"8ca7ab13"},{"idioma":"en","id":"en-f285","tipo":"frase","en":"That's a hard no.","pt":"Isso é um não definitivo.","aceitas":["isso e um nao definitivo","e um nao definitivo","e nao e ponto final","isso e um nao redondo","e um nao sem discussao"],"aceitasEn":["thats a hard no","that is a hard no"],"distratores":["Isso é um não difícil de dar.","Isso é um não por enquanto.","Isso é um talvez.","Isso é um não meio sim."],"nivel":"B2","tags":["expressão","trabalho"],"nota":"«Hard» aqui não é difícil: é firme, sem margem. O par dela é «a soft no», que é o não que ainda se pode negociar. As duas são recentes e vêm do inglês de negócio.","v":"1872f757"},{"idioma":"en","id":"en-f286","tipo":"frase","en":"I'm swamped.","pt":"Estou atolado de trabalho.","aceitas":["estou atolado de trabalho","estou atolado","to atolado de trabalho","estou enterrado de trabalho","estou cheio de trabalho ate o pescoco"],"aceitasEn":["im swamped","i am swamped","im swamped at work"],"distratores":["Estou atrasado no trabalho.","Estou cansado do trabalho.","Estou sem trabalho agora.","Estou folgado esta semana."],"nivel":"B2","tags":["expressão","trabalho"],"nota":"«Swamp» é o pântano, e «swamped» é estar afundado nele até o peito. A imagem portuguesa é a mesma, com «atolado». E «snowed under» diz o mesmo com neve em vez de lama.","v":"387f2ce2"},{"idioma":"en","id":"en-f287","tipo":"frase","en":"He's got his work cut out for him.","pt":"Ele vai ter trabalho.","aceitas":["ele vai ter trabalho","ele vai ter muito trabalho","a tarefa dele nao vai ser facil","ele arrumou trabalho para si","vai dar trabalho para ele"],"aceitasEn":["hes got his work cut out for him","he has his work cut out for him"],"distratores":["Ele já deixou o trabalho pronto.","Ele cortou o trabalho ao meio.","Ele foi demitido do trabalho.","Ele dividiu o trabalho com alguém."],"nivel":"C1","tags":["expressão","trabalho"],"nota":"Vem da costura: o tecido já está cortado e só falta montar — mas é tanto que vai dar trabalho. O «cut out» engana quem lê rápido, porque parece recortar e dispensar, e é o contrário.","v":"e1863f89"},{"idioma":"en","id":"en-f288","tipo":"frase","en":"It's a blessing and a curse.","pt":"Tem um lado bom e um ruim.","aceitas":["tem um lado bom e um ruim","tem um lado bom e um lado ruim","e bom e ruim ao mesmo tempo","e uma faca de dois legumes","e bencao e maldicao"],"aceitasEn":["its a blessing and a curse","it is a blessing and a curse"],"distratores":["Tem um lado bom e nenhum ruim.","Tem um lado ruim e nenhum bom.","Tem um lado bom e nada mais.","Não tem lado bom nem lado ruim."],"nivel":"C1","tags":["expressão"],"nota":"Diz-se do dom que cobra um preço: a memória boa, o filho genial, o cargo alto. Não se confunde com «a blessing in disguise», que é o azar que acabou bem — aqui os dois lados são permanentes.","v":"4365f41f"},{"idioma":"en","id":"en-f289","tipo":"frase","en":"He threw in the towel.","pt":"Ele jogou a toalha.","aceitas":["ele jogou a toalha","jogou a toalha","ele desistiu de vez","ele entregou os pontos","ele largou tudo"],"aceitasEn":["he threw in the towel","he has thrown in the towel"],"distratores":["Ele jogou a toalha no chão.","Ele pendurou a toalha.","Ele ganhou a luta no fim.","Ele voltou para o segundo round."],"nivel":"C1","tags":["expressão","social"],"nota":"Vem do boxe: o treinador joga a toalha no ringue para encerrar a luta. As três línguas usam a mesma imagem, mas o inglês põe o «in» — «throw in the towel» —, e sem ele a frase vira o gesto literal.","v":"088e45d0"},{"idioma":"en","id":"en-f290","tipo":"frase","en":"Needless to say, we declined.","pt":"Nem preciso dizer que recusamos.","aceitas":["nem preciso dizer que recusamos","nao preciso dizer que recusamos","obviamente recusamos","claro que recusamos","evidentemente recusamos"],"aceitasEn":["needless to say we declined"],"distratores":["Sem precisar falar, recusamos.","Sem dizer nada, recusamos.","Por falta do que dizer, recusamos.","Dizendo o necessário, recusamos."],"nivel":"C2","tags":["gramática","formal"],"nota":"«Needless» é «desnecessário», e a fórmula inteira quer dizer que o que vem depois era previsível. Vai no começo, com vírgula, e é parente de «it goes without saying» — esta mais seca, de texto escrito.","v":"17765622"},{"idioma":"en","id":"en-f291","tipo":"frase","en":"Scarcely had we sat down when it began.","pt":"Mal nos sentamos, começou.","aceitas":["mal nos sentamos comecou","mal a gente se sentou comecou","nem bem nos sentamos e comecou","assim que nos sentamos comecou"],"aceitasEn":["scarcely had we sat down when it began"],"distratores":["Nos sentamos depois que começou.","Começou pouco antes de nos sentarmos.","Nos sentamos e não começou.","Faltou pouco para começar antes de nos sentarmos."],"nivel":"C2","tags":["gramática","formal"],"nota":"Inversão depois de «scarcely», como depois de «hardly» e de «no sooner»: o auxiliar passa à frente do sujeito. E repare no par — «scarcely… when», e não «scarcely… than», que é o de «no sooner».","v":"ecd11ffc"},{"idioma":"en","id":"en-f292","tipo":"frase","en":"He is nothing short of brilliant.","pt":"Ele é brilhante, sem exagero.","aceitas":["ele e brilhante sem exagero","ele e simplesmente brilhante","ele e nada menos que brilhante","ele e brilhante e nao e exagero"],"aceitasEn":["he is nothing short of brilliant","hes nothing short of brilliant"],"distratores":["Ele é quase brilhante.","Ele está longe de ser brilhante.","Ele é brilhante só às vezes.","Ele é brilhante, mas falta pouco."],"nivel":"C2","tags":["gramática","formal"],"nota":"«Nothing short of» é «nada menos que», e é elogio no grau máximo: a qualidade não fica nem um palmo abaixo do que se disse. O «short» engana, porque sozinho ele é «curto» — aqui o «nothing» o vira do avesso.","v":"5ca9a2d2"},{"idioma":"en","id":"en-f293","tipo":"frase","en":"On no account should you sign it.","pt":"Em nenhuma hipótese assine isso.","aceitas":["em nenhuma hipotese assine isso","de jeito nenhum assine isso","nao assine isso de maneira nenhuma","em hipotese alguma assine isso"],"aceitasEn":["on no account should you sign it"],"distratores":["Só assine isso em último caso.","Assine isso por conta própria.","Assine isso em nome da conta.","Não assine isso sem ler."],"nivel":"C2","tags":["gramática","formal","jurídico"],"nota":"«On no account» é «em nenhuma hipótese», e por começar com negativa puxa a inversão: «should you sign», e não «you should sign». O «account» aqui é razão, motivo — nada a ver com conta bancária.","v":"5516c7be"},{"idioma":"en","id":"en-f294","tipo":"frase","en":"It bears repeating.","pt":"Vale repetir.","aceitas":["vale repetir","vale a pena repetir","convem repetir","merece ser repetido","e bom repetir"],"aceitasEn":["it bears repeating","this bears repeating"],"distratores":["Aguenta ser repetido.","Suporta a repetição.","Não precisa repetir.","Chega de repetir isso."],"nivel":"C2","tags":["gramática","formal"],"nota":"«Bear» aqui não é carregar nem suportar: é «merecer», num uso que só sobrevive neste molde — «it bears repeating», «it bears mentioning», «it bears noting». Depois dele vem sempre verbo em -ing.","v":"1efdaa2f"},{"idioma":"en","id":"en-f295","tipo":"frase","en":"For want of a better word, it's odd.","pt":"Na falta de palavra melhor, é estranho.","aceitas":["na falta de palavra melhor e estranho","por falta de palavra melhor e estranho","na falta de uma palavra melhor e estranho","sem achar palavra melhor e estranho"],"aceitasEn":["for want of a better word its odd"],"distratores":["Por querer uma palavra melhor, é estranho.","Com uma palavra melhor, seria estranho.","Faltando a palavra, ficou estranho.","Querendo dizer melhor, é estranho."],"nivel":"C2","tags":["gramática","formal"],"nota":"«For want of» é «na falta de», e o «want» aqui é falta, não vontade — sentido antigo que sobrevive neste molde e no provérbio «for want of a nail». Serve para pedir desculpa pela palavra que se vai usar.","v":"a411ea72"},{"idioma":"en","id":"en-f296","tipo":"frase","en":"As it stands, we can't proceed.","pt":"Como está, não podemos seguir.","aceitas":["como esta nao podemos seguir","do jeito que esta nao podemos seguir","assim como esta nao podemos seguir","nas condicoes atuais nao podemos seguir"],"aceitasEn":["as it stands we cant proceed","as it stands we can not proceed"],"distratores":["Enquanto ele estiver aí, não podemos seguir.","Como ele quer, não podemos seguir.","Depois que parar, não podemos seguir.","Mesmo assim, não podemos seguir."],"nivel":"C2","tags":["gramática","formal","trabalho"],"nota":"«Stand» aqui é «estar», no estado em que a coisa se encontra — não tem nada de ficar de pé. «As it stands» é o retrato do momento, e o molde tem irmãos: «as things stand», «where matters stand».","v":"51160e2c"},{"idioma":"en","id":"en-v147","tipo":"frase","en":"I can swim.","pt":"Eu sei nadar.","aceitas":["eu sei nadar","sei nadar","eu consigo nadar","eu nado"],"aceitasEn":["i can swim"],"distratores":["Eu sabia nadar.","Eu vou saber nadar.","Eu saberia nadar.","Eu tinha sabido nadar."],"formasEn":{"I could swim":"imperfeito","I will be able to swim":"futuro","I would be able to swim":"condicional","I had been able to swim":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","irregular","swim","presente"],"nota":"«Can» de habilidade aprendida é o «saber» do português, e não o «poder»: «I can swim» é «sei nadar». E «can» não tem infinitivo nem futuro — para isso o inglês empresta «be able to».","v":"2dcf833f"},{"idioma":"en","id":"en-v148","tipo":"frase","en":"He isn't here.","pt":"Ele não está aqui.","aceitas":["ele nao esta aqui","nao esta aqui","ele nao ta aqui","ele nao se encontra aqui"],"aceitasEn":["he isnt here","he is not here","hes not here"],"distratores":["Ele não estava aqui.","Ele não estará aqui.","Ele não estaria aqui.","Ele não tinha estado aqui."],"formasEn":{"He wasn't here":"pretérito","He won't be here":"futuro","He wouldn't be here":"condicional","He hadn't been here":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","irregular","be","presente"],"nota":"«Be» é o único verbo que nega sozinho, sem «do»: «he isn't», e nunca «he doesn't be». As duas contrações valem — «he isn't» e «he's not» —, e a segunda é a mais ouvida na fala.","v":"58e0f0a7"},{"idioma":"en","id":"en-v149","tipo":"frase","en":"Did you see the movie?","pt":"Você viu o filme?","aceitas":["voce viu o filme","viu o filme","voce assistiu o filme","voce chegou a ver o filme"],"aceitasEn":["did you see the movie","did you see the film"],"distratores":["Você vê o filme?","Você verá o filme?","Você veria o filme?","Você tinha visto o filme?"],"formasEn":{"Do you see the movie":"presente","Will you see the movie":"futuro","Would you see the movie":"condicional","Had you seen the movie":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","irregular","see","pretérito","cultura"],"nota":"Na pergunta de passado o «did» carrega o tempo e o verbo volta ao infinitivo: «did you see», e nunca «did you saw». E «movie» é americano; na Inglaterra se diz «film», que vale como resposta.","v":"b2a45177"},{"idioma":"en","id":"en-v150","tipo":"frase","en":"There are two beds.","pt":"Tem duas camas.","aceitas":["tem duas camas","ha duas camas","existem duas camas","sao duas camas"],"aceitasEn":["there are two beds"],"distratores":["Tinha duas camas.","Vai ter duas camas.","Teria duas camas.","Tinha havido duas camas."],"formasEn":{"There were two beds":"pretérito","There will be two beds":"futuro","There would be two beds":"condicional","There had been two beds":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","irregular","be","presente","viagem"],"nota":"«There is» e «there are» concordam com o que vem depois: uma cama pede «is», duas pedem «are». O português e o espanhol não concordam nada — «tem» e «hay» servem para qualquer número —, e é daí que vem o erro.","v":"1d18a4c2"},{"idioma":"en","id":"en-v151","tipo":"frase","en":"She has to work tomorrow.","pt":"Ela tem que trabalhar amanhã.","aceitas":["ela tem que trabalhar amanha","ela precisa trabalhar amanha","ela tem de trabalhar amanha","amanha ela trabalha obrigada"],"aceitasEn":["she has to work tomorrow"],"distratores":["Ela tinha que trabalhar ontem.","Ela terá que trabalhar amanhã.","Ela teria que trabalhar amanhã.","Ela tinha tido que trabalhar."],"formasEn":{"She had to work yesterday":"pretérito","She will have to work tomorrow":"futuro","She would have to work tomorrow":"condicional","She had had to work before":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","irregular","work","presente","trabalho"],"nota":"«Have to» é a obrigação que vem de fora — do chefe, da lei, do horário. «Must» é a que vem de dentro, de quem fala. E «have to» conjuga normalmente, com «has» na terceira pessoa, enquanto «must» não muda nunca.","v":"b68baeb7"},{"idioma":"en","id":"en-v152","tipo":"frase","en":"You should see a doctor.","pt":"Você deveria ir ao médico.","aceitas":["voce deveria ir ao medico","voce devia ir ao medico","e melhor voce ir ao medico","voce precisa ver um medico","voce tinha que ir ao medico"],"aceitasEn":["you should see a doctor","you ought to see a doctor"],"distratores":["Você foi ao médico.","Você vai ao médico.","Você irá ao médico.","Você tinha ido ao médico."],"formasEn":{"You saw a doctor":"pretérito","You will see a doctor":"futuro","You should have seen a doctor":"condicional composto","You had seen a doctor":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","see","condicional","saúde"],"nota":"«Should» é o conselho, e não muda com a pessoa: I should, she should, they should. E «see a doctor» é a colocação — o médico se vê, não se visita: «visit a doctor» soa a casa de amigo.","v":"58a906c4"},{"idioma":"en","id":"en-v153","tipo":"frase","en":"It might rain later.","pt":"Pode chover mais tarde.","aceitas":["pode chover mais tarde","talvez chova mais tarde","e possivel que chova mais tarde","pode ser que chova mais tarde"],"aceitasEn":["it might rain later","it may rain later"],"distratores":["Choveu mais tarde.","Vai chover mais tarde.","Choveria mais tarde.","Tinha chovido mais tarde."],"formasEn":{"It rained later":"pretérito","It will rain later":"futuro","It would rain later":"condicional","It had rained later":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","regular","rain","futuro"],"nota":"«Might» é a possibilidade fraca, e «may» é a mesma coisa um grau mais provável — na conversa os dois se misturam. Nenhum dos dois leva «to» depois, e nenhum muda com a pessoa.","v":"fd3361e8"},{"idioma":"en","id":"en-v154","tipo":"frase","en":"I've been waiting for an hour.","pt":"Estou esperando há uma hora.","aceitas":["estou esperando ha uma hora","faz uma hora que estou esperando","estou esperando faz uma hora","ja espero ha uma hora"],"aceitasEn":["ive been waiting for an hour","i have been waiting for an hour"],"distratores":["Esperei por uma hora.","Vou esperar por uma hora.","Esperaria por uma hora.","Tinha esperado por uma hora."],"formasEn":{"I waited for an hour":"pretérito","I will wait for an hour":"futuro","I would wait for an hour":"condicional","I had waited for an hour":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","regular","wait","present perfect"],"nota":"O present perfect contínuo é a ação que começou atrás e continua agora, e é por isso que o português responde com o presente: «estou esperando há uma hora». Com o passado simples, «I waited», a espera já acabou.","v":"c029397e"},{"idioma":"en","id":"en-v155","tipo":"frase","en":"He said he would come.","pt":"Ele disse que vinha.","aceitas":["ele disse que vinha","ele disse que viria","ele falou que vinha","ele disse que ia vir"],"aceitasEn":["he said he would come","he said hed come"],"distratores":["Ele disse que não vem.","Ele disse que veio.","Ele diz que virá.","Ele tinha dito que viria."],"formasEn":{"He says he will come":"presente","He said he came":"pretérito","He will say he is coming":"futuro","He had said he would come":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","come","condicional","social"],"nota":"Quando o verbo de dizer vai para o passado, o que vem depois recua um tempo também: «he will come» vira «he would come». É a regra do discurso indireto, e o português faz igual com «vinha» ou «viria».","v":"96b36e7f"},{"idioma":"en","id":"en-v156","tipo":"frase","en":"If I were you, I'd ask.","pt":"Se eu fosse você, eu perguntaria.","aceitas":["se eu fosse voce eu perguntaria","se eu fosse voce perguntaria","no seu lugar eu perguntaria","eu perguntaria se fosse voce"],"aceitasEn":["if i were you id ask","if i were you i would ask"],"distratores":["Se eu for você, eu pergunto.","Se eu era você, eu perguntava.","Quando eu for você, eu pergunto.","Como eu sou você, eu pergunto."],"formasEn":{"If I am you I ask":"presente","If I was you I asked":"pretérito","If I had been you I would have asked":"condicional composto","If I will be you I will ask":"futuro"},"nivel":"B1","tags":["conjugação","irregular","ask","condicional","social"],"nota":"«If I were» com «were» na primeira pessoa é o subjuntivo antigo, e é a forma que o conselho pede: «if I was you» se ouve na fala e é marcado como descuido. O «if» nunca leva «would» do seu lado.","v":"ecd2e075"},{"idioma":"en","id":"en-v157","tipo":"frase","en":"The letter has been sent.","pt":"A carta já foi enviada.","aceitas":["a carta ja foi enviada","a carta ja foi mandada","ja enviaram a carta","a carta ja saiu"],"aceitasEn":["the letter has been sent","the letters been sent"],"distratores":["A carta foi enviada ontem.","A carta será enviada amanhã.","A carta seria enviada hoje.","A carta tinha sido enviada antes."],"formasEn":{"The letter was sent":"pretérito","The letter will be sent":"futuro","The letter would be sent":"condicional","The letter had been sent":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","send","present perfect","trabalho"],"nota":"A passiva no present perfect empilha «has» mais «been» mais o particípio, e serve ao que já está feito e ainda conta agora. É a forma do aviso de sistema: «your message has been sent».","v":"b9ce87ac"},{"idioma":"en","id":"en-v158","tipo":"frase","en":"We had been walking for hours.","pt":"A gente já andava há horas.","aceitas":["a gente ja andava ha horas","nos ja andavamos ha horas","a gente estava andando ha horas","fazia horas que a gente andava"],"aceitasEn":["we had been walking for hours"],"distratores":["A gente andou por horas.","A gente anda por horas.","A gente andaria por horas.","A gente vai andar por horas."],"formasEn":{"We walked for hours":"pretérito","We walk for hours":"presente","We would walk for hours":"condicional","We will walk for hours":"futuro"},"nivel":"B1","tags":["conjugação","regular","walk","mais-que-perfeito","viagem"],"nota":"É o contínuo do mais-que-perfeito: a caminhada já durava quando outra coisa aconteceu. Empilha «had» mais «been» mais o -ing, e o português resolve com o imperfeito e um «já».","v":"f51e8792"},{"idioma":"en","id":"en-v159","tipo":"frase","en":"I couldn't find it.","pt":"Eu não consegui achar.","aceitas":["eu nao consegui achar","nao consegui achar","nao consegui encontrar","eu nao achei","nao deu para achar"],"aceitasEn":["i couldnt find it","i could not find it"],"distratores":["Eu não consigo achar.","Eu não vou conseguir achar.","Eu não conseguiria achar.","Eu não tinha conseguido achar."],"formasEn":{"I can't find it":"presente","I won't be able to find it":"futuro","I wouldn't be able to find it":"condicional","I hadn't been able to find it":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","find","pretérito"],"nota":"«Couldn't» é o passado de «can't», e serve à tentativa que falhou: «I couldn't find it» é «procurei e não achei». No afirmativo o passado muda de sentido — «I could find it» soa a capacidade geral, e para o episódio único se diz «I managed to find it».","v":"5b5e8424"},{"idioma":"en","id":"en-v160","tipo":"frase","en":"I've got to go.","pt":"Tenho que ir.","aceitas":["tenho que ir","eu tenho que ir","preciso ir","tenho que ir embora","tenho que ir nessa"],"aceitasEn":["ive got to go","i have got to go","ive gotta go"],"distratores":["Tinha que ir.","Vou ter que ir.","Teria que ir.","Tinha tido que ir."],"formasEn":{"I had to go":"pretérito","I will have to go":"futuro","I would have to go":"condicional","I had had to go":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","go","presente","social"],"nota":"«Have got to» é «have to» da conversa, e na fala vira «gotta»: «I gotta go». Só existe no presente — o passado volta a ser «had to» —, e é como se encerra uma conversa em inglês sem explicar por quê.","v":"19bfce53"},{"idioma":"en","id":"en-v161","tipo":"frase","en":"I wasn't able to come.","pt":"Eu não pude vir.","aceitas":["eu nao pude vir","nao pude vir","nao consegui vir","nao deu para eu vir"],"aceitasEn":["i wasnt able to come","i was not able to come"],"distratores":["Eu não posso vir.","Eu não poderei vir.","Eu não poderia vir.","Eu não tinha podido vir."],"formasEn":{"I'm not able to come":"presente","I won't be able to come":"futuro","I wouldn't be able to come":"condicional","I hadn't been able to come":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","come","pretérito","social"],"nota":"«Be able to» é o suplente de «can», e entra onde o modal não vai: no infinitivo, no futuro e no particípio. No passado é mais formal que «couldn't», e é o que se escreve numa justificativa.","v":"6631b0ef"},{"idioma":"en","id":"en-v162","tipo":"frase","en":"I didn't use to like coffee.","pt":"Eu não gostava de café antes.","aceitas":["eu nao gostava de cafe antes","antes eu nao gostava de cafe","eu nao costumava gostar de cafe","eu nao gostava de cafe no passado"],"aceitasEn":["i didnt use to like coffee","i did not use to like coffee","i didnt used to like coffee"],"distratores":["Eu não gosto de café.","Eu não vou gostar de café.","Eu não gostaria de café.","Eu não tinha gostado de café."],"formasEn":{"I don't like coffee":"presente","I won't like coffee":"futuro","I wouldn't like coffee":"condicional","I hadn't liked coffee":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","regular","like","imperfeito","comida"],"nota":"Na negativa e na pergunta, «used to» perde o «-d»: «didn't use to», porque o «did» já marca o passado. A grafia com «-d» se ouve e se escreve bastante, e os dois passam — mas a sem «-d» é a que a gramática pede.","v":"33e99f34"},{"idioma":"en","id":"en-v163","tipo":"frase","en":"She can't have known.","pt":"Ela não pode ter sabido.","aceitas":["ela nao pode ter sabido","ela nao podia saber","e impossivel que ela soubesse","ela nao tinha como saber","nao e possivel que ela soubesse"],"aceitasEn":["she cant have known","she can not have known"],"distratores":["Ela não pode saber.","Ela não poderá saber.","Ela não quis saber.","Ela não precisava saber."],"formasEn":{"She can't know":"presente","She won't be able to know":"futuro","She wouldn't have known":"condicional composto","She hadn't known":"mais-que-perfeito"},"nivel":"B2","tags":["conjugação","irregular","know","condicional composto"],"nota":"«Can't have» não é falta de permissão: é a conclusão de que aquilo era impossível. O par dela é «must have», que é a conclusão de que aquilo certamente aconteceu — as duas olham para o passado a partir de hoje.","v":"80f184f2"},{"idioma":"en","id":"en-v164","tipo":"frase","en":"You needn't worry.","pt":"Você não precisa se preocupar.","aceitas":["voce nao precisa se preocupar","nao precisa se preocupar","voce nao tem que se preocupar","nao e preciso se preocupar"],"aceitasEn":["you neednt worry","you need not worry","you dont need to worry"],"distratores":["Você não quis se preocupar.","Você não deve se preocupar tanto.","Você não vai se preocupar.","Você não se preocupou."],"formasEn":{"You didn't need to worry":"pretérito","You won't need to worry":"futuro","You wouldn't need to worry":"condicional","You hadn't needed to worry":"mais-que-perfeito"},"nivel":"B2","tags":["conjugação","regular","worry","presente","social"],"nota":"«Needn't» é o «need» virando modal: sem «to» depois e sem «-s» na terceira pessoa. É de registro mais alto que «don't need to», que diz o mesmo e é o que se fala.","v":"2e16ecf9"},{"idioma":"en","id":"en-v165","tipo":"frase","en":"You might as well start.","pt":"Melhor já começar.","aceitas":["melhor ja comecar","e melhor comecar logo","ja que e assim comece","pode comecar entao","nao custa nada comecar"],"aceitasEn":["you might as well start","you may as well start"],"distratores":["Você poderia começar bem.","Você começa tão bem quanto.","Você talvez comece agora.","Você deveria ter começado."],"formasEn":{"You might as well have started":"condicional composto","You started anyway":"pretérito","You will start anyway":"futuro","You had started anyway":"mais-que-perfeito"},"nivel":"B2","tags":["conjugação","regular","start","presente","trabalho"],"nota":"«Might as well» é «já que não há nada melhor, faça isso»: a sugestão sem entusiasmo. As três palavras andam colados e não se traduzem uma a uma — o português diz a mesma coisa com «melhor já».","v":"e1db1ebb"},{"idioma":"en","id":"en-v166","tipo":"frase","en":"I'd have thought he'd know.","pt":"Eu imaginaria que ele soubesse.","aceitas":["eu imaginaria que ele soubesse","eu teria imaginado que ele soubesse","eu achava que ele soubesse","eu suporia que ele soubesse"],"aceitasEn":["id have thought hed know","i would have thought he would know"],"distratores":["Eu imaginei que ele sabia.","Eu imagino que ele saiba.","Eu vou imaginar que ele sabe.","Eu tinha imaginado que ele sabia."],"formasEn":{"I think he knows":"presente","I thought he knew":"pretérito","I will think he knows":"futuro","I had thought he knew":"mais-que-perfeito"},"nivel":"C1","tags":["conjugação","irregular","know","condicional composto","social"],"nota":"Duas contrações de «would» na mesma frase, e é assim que ela sai na fala: «I'd have thought he'd know». A fórmula é crítica educada — quem diz isso está apontando que o outro devia saber e não sabia.","v":"837f3f6b"},{"idioma":"en","id":"en-p185","tipo":"palavra","en":"the kitchen","pt":"a cozinha","aceitas":["a cozinha","cozinha","as cozinhas"],"aceitasEn":["the kitchen","kitchen","a kitchen","kitchens"],"distratores":["a sala","o quarto","o banheiro","a varanda"],"nivel":"A1","tags":["substantivo","casa"],"nota":"«Kitchen» é só o lugar: cozinhar é «to cook» e quem cozinha é «a cook». O armário de cozinha é «cupboard», a pia é «sink», e a cozinha de restaurante também é «the kitchen».","v":"d8bb8c85"},{"idioma":"en","id":"en-p186","tipo":"palavra","en":"the knife","pt":"a faca","aceitas":["a faca","faca","as facas"],"aceitasEn":["the knife","knife","a knife","knives"],"distratores":["a colher","o garfo","a tesoura","o prato"],"nivel":"A1","tags":["substantivo","comida","objetos"],"nota":"O plural é «knives», com v, e o verbo «to knife» é esfaquear. Na mesa o jogo inteiro sai nesta ordem: «a knife, a fork and a spoon».","v":"fb2685db"},{"idioma":"en","id":"en-p187","tipo":"palavra","en":"the weather","pt":"o tempo","aceitas":["o tempo","tempo","o clima","clima"],"aceitasEn":["the weather","weather"],"distratores":["o céu","a chuva","a estação","a previsão"],"nivel":"A1","tags":["substantivo","natureza"],"nota":"São duas palavras onde temos uma: «weather» é o do céu e «time» é o que passa, e nunca se trocam. Pergunta-se «What's the weather like?», e a resposta começa por «it»: «it's cold», «it's raining».\n🇺🇸 weather → 🇧🇷 o tempo do céu\n🇺🇸 time → 🇧🇷 o tempo que passa","v":"6b7ac8e0"},{"idioma":"en","id":"en-p188","tipo":"palavra","en":"the bird","pt":"o pássaro","aceitas":["o passaro","passaro","os passaros","a ave","ave"],"aceitasEn":["the bird","bird","a bird","birds"],"distratores":["o peixe","o rato","o inseto","o morcego"],"nivel":"A1","tags":["substantivo","animais"],"nota":"Uma palavra só para pássaro e ave: «bird» serve ao pardal e à galinha. O filhote é «a chick», o bico é «the beak», e «to fly» é o verbo que quase sempre vem com ela.","v":"a1b904b8"},{"idioma":"en","id":"en-p189","tipo":"palavra","en":"lunch","pt":"o almoço","aceitas":["o almoco","almoco","os almocos"],"aceitasEn":["lunch","the lunch","a lunch"],"distratores":["o jantar","o café da manhã","a sobremesa","a entrada"],"nivel":"A1","tags":["substantivo","comida"],"nota":"As refeições vão sem artigo: «after lunch», «before dinner». O verbo «to lunch» existe mas soa afetado — quem fala diz «have lunch». A pausa do almoço é «the lunch break».","v":"99d70d5b"},{"idioma":"en","id":"en-p190","tipo":"palavra","en":"the job","pt":"o trabalho","aceitas":["o trabalho","trabalho","o emprego","emprego","a tarefa"],"aceitasEn":["the job","job","a job","jobs"],"distratores":["o salário","o chefe","o escritório","a carreira"],"nivel":"A1","tags":["substantivo","trabalho"],"nota":"«Job» é o posto e também a tarefa: «it's a tough job». O trabalho como atividade é «work», e esse não tem plural: diz-se «two jobs», nunca «two works». E «Good job!» é «muito bem!».","v":"a51e5aaa"},{"idioma":"en","id":"en-p191","tipo":"palavra","en":"the fridge","pt":"a geladeira","aceitas":["a geladeira","geladeira","as geladeiras","o frigorifico"],"aceitasEn":["the fridge","fridge","a fridge","the refrigerator","refrigerator"],"distratores":["o congelador","o forno","o armário","a pia"],"nivel":"A2","tags":["substantivo","casa","comida"],"nota":"«Fridge» é como todo mundo diz; «refrigerator» fica para o manual e a etiqueta da loja. O congelador de dentro é «the freezer», e nada disso tem a ver com «frigid», que é glacial.","v":"43bcc56d"},{"idioma":"en","id":"en-p192","tipo":"palavra","en":"the roof","pt":"o telhado","aceitas":["o telhado","telhado","os telhados","o teto"],"aceitasEn":["the roof","roof","a roof","roofs"],"distratores":["a parede","o chão","a janela","a chaminé"],"nivel":"A2","tags":["substantivo","casa"],"nota":"O plural é «roofs», sem o v de «knives». «Roof» serve ao telhado da casa e ao teto do carro, e «rooftop» é o terraço de cima, onde se faz festa.","v":"a50dee45"},{"idioma":"en","id":"en-p193","tipo":"palavra","en":"the glove","pt":"a luva","aceitas":["a luva","luva","as luvas"],"aceitasEn":["the glove","glove","a glove","gloves"],"distratores":["a meia","o cachecol","a manga","o chapéu"],"nivel":"A2","tags":["substantivo","roupa"],"nota":"«Glove» tem dedos; a luva fechada, de uma peça, é «a mitten». «It fits like a glove» é o mesmo elogio que se faz aqui, e no carro o porta-luvas é «the glove compartment».","v":"55c4bd00"},{"idioma":"en","id":"en-p194","tipo":"palavra","en":"the scarf","pt":"o cachecol","aceitas":["o cachecol","cachecol","os cachecois","a echarpe"],"aceitasEn":["the scarf","scarf","a scarf","scarves","scarfs"],"distratores":["o boné","a gravata","o cinto","a touca"],"nivel":"A2","tags":["substantivo","roupa"],"nota":"«Scarf» é o do frio e também o lenço de cabeça ou de pescoço — o contexto escolhe. O plural tem duas formas de pé, «scarves» e «scarfs», e a primeira é a mais comum.","v":"23e4c65d"},{"idioma":"en","id":"en-p195","tipo":"palavra","en":"the backpack","pt":"a mochila","aceitas":["a mochila","mochila","as mochilas"],"aceitasEn":["the backpack","backpack","a backpack","backpacks"],"regionaisEn":{"the rucksack":"na Inglaterra","rucksack":"na Inglaterra"},"distratores":["a mala","a bolsa","a sacola","o estojo"],"nivel":"A2","tags":["substantivo","objetos","viagem"],"nota":"«Backpack» é a de costas, com duas alças; a de uma alça só é «a shoulder bag». Quem viaja com ela é «a backpacker», e o verbo «to backpack» é viajar assim.","v":"d6a7b241"},{"idioma":"en","id":"en-p196","tipo":"palavra","en":"the bowl","pt":"a tigela","aceitas":["a tigela","tigela","as tigelas","a vasilha"],"aceitasEn":["the bowl","bowl","a bowl","bowls"],"distratores":["o prato","a panela","a bandeja","a jarra"],"nivel":"A2","tags":["substantivo","comida","objetos"],"nota":"«Bowl» é qualquer recipiente fundo e redondo: o da sopa, o do cereal, o do cachorro. Serve também para o conteúdo — «a bowl of rice» — e, como verbo, é jogar boliche.","v":"22dc9c47"},{"idioma":"en","id":"en-p197","tipo":"palavra","en":"the napkin","pt":"o guardanapo","aceitas":["o guardanapo","guardanapo","os guardanapos"],"aceitasEn":["the napkin","napkin","a napkin","napkins"],"distratores":["a toalha","o pano","o avental","a esponja"],"nivel":"A2","tags":["substantivo","comida","objetos"],"nota":"«Napkin» é o de pano e o de papel, os dois. Cuidado com o parente britânico: lá «nappy» é fralda, e o de papel aparece em cardápio antigo como «serviette».","v":"7df97b4e"},{"idioma":"en","id":"en-p198","tipo":"palavra","en":"the garlic","pt":"o alho","aceitas":["o alho","alho"],"aceitasEn":["the garlic","garlic"],"distratores":["a cebola","o gengibre","o salsão","o tomilho"],"nivel":"A2","tags":["substantivo","comida"],"nota":"«Garlic» não tem plural: um dente é «a clove of garlic» e a cabeça inteira, «a head of garlic». O pão de alho é «garlic bread», e quem comeu demais tem «garlic breath».","v":"9506ba69"},{"idioma":"en","id":"en-p199","tipo":"palavra","en":"the strawberry","pt":"o morango","aceitas":["o morango","morango","os morangos"],"aceitasEn":["the strawberry","strawberry","a strawberry","strawberries"],"distratores":["a framboesa","a amora","a cereja","o mirtilo"],"nivel":"A2","tags":["substantivo","comida"],"nota":"O plural é «strawberries»: palavra acabada em consoante mais y troca o y por -ies. O «straw» de dentro é a palha, e de onde ele veio ninguém sabe ao certo.","v":"67cc7a80"},{"idioma":"en","id":"en-p200","tipo":"palavra","en":"the peach","pt":"o pêssego","aceitas":["o pessego","pessego","os pessegos"],"aceitasEn":["the peach","peach","a peach","peaches"],"distratores":["a ameixa","a pera","o damasco","o figo"],"nivel":"A2","tags":["substantivo","comida"],"nota":"Plural «peaches», com -es depois do ch, como «beaches» e «matches». «Peachy» é ótimo na conversa, e quem é um doce de pessoa também é «a peach».","v":"8f99a1ac"},{"idioma":"en","id":"en-p201","tipo":"palavra","en":"to sweep","pt":"varrer","aceitas":["varrer"],"aceitasEn":["to sweep","sweep","sweeping"],"distratores":["esfregar","polir","sacudir","peneirar"],"nivel":"A2","tags":["verbo","casa"],"nota":"Verbo irregular de uma forma só: «swept» serve de passado e de particípio. Vale para tudo que passa de ponta a ponta — quem ganha todas as cadeiras «sweeps the election».","v":"bfb1a0fa"},{"idioma":"en","id":"en-p202","tipo":"palavra","en":"to boil","pt":"ferver","aceitas":["ferver"],"aceitasEn":["to boil","boil","boiling"],"distratores":["assar","fritar","derreter","escorrer"],"nivel":"A2","tags":["verbo","comida"],"nota":"«Boil» é a água no ponto e também o que está dentro dela: «boil the eggs». O ovo cozido é «a boiled egg», e quem perde a paciência «boils over».","v":"b46f37f2"},{"idioma":"en","id":"en-p203","tipo":"palavra","en":"to peel","pt":"descascar","aceitas":["descascar","tirar a casca"],"aceitasEn":["to peel","peel","peeling"],"distratores":["picar","ralar","amassar","temperar"],"nivel":"A2","tags":["verbo","comida"],"nota":"«Peel» é o verbo e a casca que sai dele: «orange peel». A batata já descascada fica «peeled», e quem tomou sol demais «peels» — a pele é que descasca.","v":"83357551"},{"idioma":"en","id":"en-p204","tipo":"palavra","en":"the leaf","pt":"a folha","aceitas":["a folha","folha","as folhas"],"aceitasEn":["the leaf","leaf","a leaf","leaves"],"distratores":["o galho","a raiz","a casca","a semente"],"nivel":"A2","tags":["substantivo","natureza"],"nota":"Plural «leaves», com v, como «knives» e «wives». «Leaf» é a folha da árvore e a do livro; a de papel solta é «a sheet». E «to leaf through a book» é folhear.","v":"83363bf7"},{"idioma":"en","id":"en-p205","tipo":"palavra","en":"the wage","pt":"o salário","aceitas":["o salario","salario","os salarios","o ordenado"],"aceitasEn":["the wage","wage","wages","the wages","a wage"],"distratores":["o imposto","o bônus","a dívida","o orçamento"],"nivel":"B1","tags":["substantivo","economia","trabalho"],"nota":"«Wage» é o pago por hora ou por semana, e aparece quase sempre no plural: «weekly wages». O do mês fechado é «salary», e o piso legal é «the minimum wage».","v":"326964b4"},{"idioma":"en","id":"en-p206","tipo":"palavra","en":"the loan","pt":"o empréstimo","aceitas":["o emprestimo","emprestimo","os emprestimos"],"aceitasEn":["the loan","loan","a loan","loans"],"distratores":["a dívida","a hipoteca","o juro","a prestação"],"nivel":"B1","tags":["substantivo","economia"],"nota":"«Loan» é o dinheiro emprestado. Quem empresta «lends» — nos Estados Unidos «loans» também corre —, quem pede é «the borrower», e pedir é «to take out a loan».","v":"11c2ad89"},{"idioma":"en","id":"en-p207","tipo":"palavra","en":"to stir","pt":"mexer","aceitas":["mexer","misturar"],"aceitasEn":["to stir","stir","stirring"],"distratores":["bater","escorrer","provar","aquecer"],"nivel":"B1","tags":["verbo","comida"],"nota":"«Stir» é a colher girando devagar; bater com força é «to beat» ou «to whisk». Fora da cozinha serve a mexer com as pessoas: «the news stirred the crowd».","v":"787e3af4"},{"idioma":"en","id":"en-p208","tipo":"palavra","en":"the fitting room","pt":"o provador","aceitas":["o provador","provador","os provadores","a cabine de prova"],"aceitasEn":["the fitting room","fitting room","a fitting room","the dressing room","dressing room"],"distratores":["o balcão","o caixa","a vitrine","o depósito"],"nivel":"B1","tags":["substantivo","compras","roupa"],"nota":"«Fitting room» e «dressing room» valem as duas na loja; a segunda é também o camarim do teatro. Para experimentar se pergunta «Can I try this on?», com o «on» no fim.","v":"45a94b04"},{"idioma":"en","id":"en-p209","tipo":"palavra","en":"the lightning","pt":"o relâmpago","aceitas":["o relampago","relampago","os relampagos","o raio"],"aceitasEn":["the lightning","lightning"],"distratores":["o trovão","o granizo","o vendaval","o arco-íris"],"nivel":"B1","tags":["substantivo","natureza"],"nota":"«Lightning» não tem plural nem artigo indefinido: «lightning struck the tree». O estrondo é «thunder», e os dois juntos fazem «a thunderstorm». Nada a ver com «lightening», que é clarear.","v":"5e917505"},{"idioma":"en","id":"en-p210","tipo":"palavra","en":"to rinse","pt":"enxaguar","aceitas":["enxaguar"],"aceitasEn":["to rinse","rinse","rinsing"],"distratores":["esfregar","secar","torcer","mergulhar"],"nivel":"B1","tags":["verbo","casa"],"nota":"«Rinse» é passar água, sem sabão: «rinse your mouth», «rinse the dishes». A última água da louça é «the rinse», e «rinse and repeat» virou piada para o que se faz sempre igual.","v":"b6cbd5bb"},{"idioma":"en","id":"en-p211","tipo":"palavra","en":"the hunch","pt":"o palpite","aceitas":["o palpite","palpite","os palpites","a intuicao","o pressentimento"],"aceitasEn":["the hunch","hunch","a hunch","hunches"],"distratores":["o boato","a aposta","a lembrança","a certeza"],"nivel":"B2","tags":["substantivo","cotidiano"],"nota":"«Hunch» é o palpite que não se explica: «I had a hunch». O verbo é outra coisa — «to hunch» é curvar as costas —, e dele vem «hunchback», o corcunda.","v":"3258b79d"},{"idioma":"en","id":"en-u185","tipo":"frase","requer":"en-p185","en":"The kitchen is small.","pt":"A cozinha é pequena.","aceitas":["a cozinha e pequena","a cozinha e pequenina","a cozinha e apertada"],"aceitasEn":["the kitchen is small","the kitchens small","the kitchen is little"],"distratores":["A sala é pequena.","A janela é pequena.","A porta é pequena.","A escada é pequena."],"nivel":"A1","tags":["substantivo","casa"],"nota":"«Small» é a medida; «little» carrega afeto ou desprezo, e «a little kitchen» soa a comentário, não a tamanho. Cômodo apertado de verdade é «cramped».","v":"b0ad0a7a"},{"idioma":"en","id":"en-u186","tipo":"frase","requer":"en-p186","en":"This knife doesn't cut.","pt":"Esta faca não corta.","aceitas":["esta faca nao corta","essa faca nao corta","a faca nao corta","esta faca esta cega"],"aceitasEn":["this knife doesnt cut","this knife does not cut","this knife wont cut"],"distratores":["Esta tesoura não corta.","Esta serra não corta.","Esta navalha não corta.","Esta espada não corta."],"nivel":"A1","tags":["substantivo","comida","objetos"],"nota":"Faca sem corte é «dull» nos Estados Unidos e «blunt» na Inglaterra; afiada é «sharp», e amolar é «to sharpen». O fio em si é «the edge».","v":"1d7652db"},{"idioma":"en","id":"en-u187","tipo":"frase","requer":"en-p187","en":"The weather was awful.","pt":"O tempo estava horrível.","aceitas":["o tempo estava horrivel","o tempo estava terrivel","o tempo estava pessimo","o clima estava horrivel"],"aceitasEn":["the weather was awful","the weather was terrible","the weather was horrible"],"distratores":["O cheiro estava horrível.","O barulho estava horrível.","O caminho estava horrível.","O serviço estava horrível."],"nivel":"A1","tags":["substantivo","natureza"],"nota":"«Awful» é forte: é o tempo que estragou o dia. O tempo bom se diz com «nice» ou «lovely», e a notícia dele se pede com «How's the weather?».","v":"3d3b0ba3"},{"idioma":"en","id":"en-u188","tipo":"frase","requer":"en-p188","en":"A bird landed on the car.","pt":"Um pássaro pousou no carro.","aceitas":["um passaro pousou no carro","um passaro pousou sobre o carro","um passaro desceu no carro"],"aceitasEn":["a bird landed on the car","the bird landed on the car","a bird landed on top of the car"],"distratores":["Um inseto pousou no carro.","Um morcego pousou no carro.","Um besouro pousou no carro.","Um mosquito pousou no carro."],"nivel":"A1","tags":["substantivo","animais"],"nota":"«To land» é pousar, e serve ao pássaro, ao avião e a quem salta e cai de pé. Como substantivo, «landing» é a aterrissagem e também o patamar da escada.","v":"52cba7b8"},{"idioma":"en","id":"en-u189","tipo":"frase","requer":"en-p189","en":"Lunch is at noon.","pt":"O almoço é ao meio-dia.","aceitas":["o almoco e ao meio dia","o almoco e meio dia","o almoco sai ao meio dia","almoco ao meio dia"],"aceitasEn":["lunch is at noon","lunch is at twelve","lunch is at midday"],"distratores":["O jantar é ao meio-dia.","O ensaio é ao meio-dia.","O desfile é ao meio-dia.","O exame é ao meio-dia."],"nivel":"A1","tags":["substantivo","comida"],"nota":"«Noon» é o meio-dia e «midday» vale igual; na prática se diz «at twelve». Meia-noite é «midnight», e «afternoon» é, ao pé da letra, o depois do meio-dia.","v":"4e38d952"},{"idioma":"en","id":"en-u190","tipo":"frase","requer":"en-p190","en":"She got the job.","pt":"Ela conseguiu o emprego.","aceitas":["ela conseguiu o emprego","ela conseguiu o trabalho","ela pegou o emprego","ela foi contratada"],"aceitasEn":["she got the job","she has got the job","she landed the job"],"distratores":["Ela conseguiu o aumento.","Ela conseguiu o visto.","Ela conseguiu o desconto.","Ela conseguiu o assento."],"nivel":"A1","tags":["substantivo","trabalho"],"nota":"«To get the job» é ser escolhido. O caminho até lá é «to apply for a job» e depois «a job interview», e quem conta com entusiasmo diz «she landed the job».","v":"5025dc00"},{"idioma":"en","id":"en-u191","tipo":"frase","requer":"en-p191","en":"The fridge is empty.","pt":"A geladeira está vazia.","aceitas":["a geladeira esta vazia","a geladeira ta vazia","nao tem nada na geladeira"],"aceitasEn":["the fridge is empty","the fridges empty","theres nothing in the fridge","the refrigerator is empty"],"distratores":["A garrafa está vazia.","A despensa está vazia.","A piscina está vazia.","A mala está vazia."],"nivel":"A2","tags":["substantivo","casa","comida"],"nota":"«Empty» é o adjetivo e o verbo na mesma forma: «an empty fridge», «empty the fridge». O contrário é «full», e o meio é «half empty» ou «half full», como no otimista da piada.","v":"5f8e7f9f"},{"idioma":"en","id":"en-u192","tipo":"frase","requer":"en-p192","en":"The roof is leaking.","pt":"O telhado está vazando.","aceitas":["o telhado esta vazando","o telhado ta vazando","o telhado esta gotejando","o teto esta vazando","entra agua pelo telhado"],"aceitasEn":["the roof is leaking","the roof leaks","theres a leak in the roof"],"distratores":["O cano está vazando.","O tanque está vazando.","O barco está vazando.","O filtro está vazando."],"nivel":"A2","tags":["substantivo","casa"],"nota":"«To leak» é vazar nos dois sentidos: a água do telhado e a notícia que escapa — «the report leaked». O furo em si é «a leak», e quem vazou é «the leaker».","v":"830f2da2"},{"idioma":"en","id":"en-u193","tipo":"frase","requer":"en-p193","en":"I lost a glove.","pt":"Perdi uma luva.","aceitas":["perdi uma luva","eu perdi uma luva","perdi uma das luvas"],"aceitasEn":["i lost a glove","ive lost a glove","i lost one glove"],"distratores":["Perdi uma meia.","Perdi uma sandália.","Perdi uma caneta.","Perdi uma pulseira."],"nivel":"A2","tags":["substantivo","roupa"],"nota":"«Lost» é passado e particípio de «lose»: «I lost it» e «I have lost it» se escrevem igual. A que ficou sem par é «the odd glove», e o achados e perdidos é «lost and found».","v":"995eb93c"},{"idioma":"en","id":"en-u194","tipo":"frase","requer":"en-p194","en":"She was wearing a red scarf.","pt":"Ela usava um cachecol vermelho.","aceitas":["ela usava um cachecol vermelho","ela estava de cachecol vermelho","ela vestia um cachecol vermelho","usava um cachecol vermelho"],"aceitasEn":["she was wearing a red scarf","she wore a red scarf","she had a red scarf on"],"distratores":["Ela usava um chapéu vermelho.","Ela usava um vestido vermelho.","Ela usava um casaco vermelho.","Ela usava um colar vermelho."],"nivel":"A2","tags":["substantivo","roupa"],"nota":"«To wear» é o verbo de tudo que está no corpo: roupa, óculos, perfume, barba. Vestir-se é «to get dressed», e pôr uma peça agora é «to put on».","v":"2ce66b3b"},{"idioma":"en","id":"en-u195","tipo":"frase","requer":"en-p195","en":"My backpack is too heavy.","pt":"Minha mochila está muito pesada.","aceitas":["minha mochila esta muito pesada","minha mochila ta muito pesada","a minha mochila esta pesada demais"],"aceitasEn":["my backpack is too heavy","my backpacks too heavy","my backpack is really heavy"],"distratores":["Minha mala está muito pesada.","Minha bolsa está muito pesada.","Minha bicicleta está muito pesada.","Minha caixa está muito pesada."],"nivel":"A2","tags":["substantivo","objetos","viagem"],"nota":"«Too» antes do adjetivo é «demais», não «muito»: «too heavy» é pesada além do que serve, e «very heavy» é só muito pesada. Trocar um pelo outro muda o recado.","v":"ae5df42f"},{"idioma":"en","id":"en-u196","tipo":"frase","requer":"en-p196","en":"The bowl broke.","pt":"A tigela quebrou.","aceitas":["a tigela quebrou","a tigela se quebrou","a tigela esta quebrada","a tigela partiu"],"aceitasEn":["the bowl broke","the bowl is broken","the bowl got broken"],"distratores":["A garrafa quebrou.","A janela quebrou.","A xícara quebrou.","A jarra quebrou."],"nivel":"A2","tags":["substantivo","comida","objetos"],"nota":"«Broke» é o passado de «break», e em inglês o verbo vai sozinho: «the bowl broke», sem o «se» que o português pede. Quebrar alguma coisa é «to break something».","v":"6bffb044"},{"idioma":"en","id":"en-u197","tipo":"frase","requer":"en-p197","en":"Could I have a napkin?","pt":"Pode me dar um guardanapo?","aceitas":["pode me dar um guardanapo","me da um guardanapo","poderia me dar um guardanapo","queria um guardanapo"],"aceitasEn":["could i have a napkin","can i have a napkin","may i have a napkin"],"distratores":["Pode me dar um copo?","Pode me dar um garfo?","Pode me dar um palito?","Pode me dar um canudo?"],"nivel":"A2","tags":["substantivo","comida","objetos"],"nota":"«Could I have…?» é o pedido de mesa, mais usado que «can» e muito mais que «I want», que soa a ordem. A resposta costuma vir com «Here you go».","v":"680fae44"},{"idioma":"en","id":"en-u198","tipo":"frase","requer":"en-p198","en":"This sauce has too much garlic.","pt":"Este molho tem alho demais.","aceitas":["este molho tem alho demais","esse molho tem alho demais","este molho esta com alho demais","tem alho demais neste molho"],"aceitasEn":["this sauce has too much garlic","this sauce has too much garlic in it","theres too much garlic in this sauce"],"distratores":["Este molho tem açúcar demais.","Este molho tem tomate demais.","Este molho tem vinagre demais.","Este molho tem óleo demais."],"nivel":"A2","tags":["substantivo","comida"],"nota":"«Too much» vai com o que não se conta — «too much garlic» —, e «too many» com o que se conta: «too many cloves». É o deslize mais comum de quem já fala bem.","v":"e453cc04"},{"idioma":"en","id":"en-u199","tipo":"frase","requer":"en-p199","en":"The strawberries are ripe.","pt":"Os morangos estão maduros.","aceitas":["os morangos estao maduros","os morangos ja estao maduros","os morangos estao no ponto"],"aceitasEn":["the strawberries are ripe","the strawberries are already ripe"],"distratores":["Os figos estão maduros.","Os limões estão maduros.","Os abacates estão maduros.","Os tomates estão maduros."],"nivel":"A2","tags":["substantivo","comida"],"nota":"«Ripe» é o ponto da fruta: passada é «overripe», e verde é «unripe». Fora da feira, «the time is ripe» é a hora certa de agir.","v":"ef3a25d6"},{"idioma":"en","id":"en-u200","tipo":"frase","requer":"en-p200","en":"The peach is still hard.","pt":"O pêssego ainda está duro.","aceitas":["o pessego ainda esta duro","o pessego esta duro ainda","o pessego ainda nao esta maduro"],"aceitasEn":["the peach is still hard","the peachs still hard","the peach is still firm"],"distratores":["O abacate ainda está duro.","O pão ainda está duro.","O queijo ainda está duro.","O biscoito ainda está duro."],"nivel":"A2","tags":["substantivo","comida"],"nota":"«Hard» é o duro de morder; «tough» é o duro de cortar e mastigar, que serve mais à carne. A fruta no ponto fica «soft», sem chegar a «mushy».","v":"8e86d6b5"},{"idioma":"en","id":"en-u201","tipo":"frase","requer":"en-p201","en":"I have to sweep the floor.","pt":"Tenho que varrer o chão.","aceitas":["tenho que varrer o chao","preciso varrer o chao","eu tenho que varrer o chao","tenho de varrer o chao"],"aceitasEn":["i have to sweep the floor","ive got to sweep the floor","i need to sweep the floor"],"distratores":["Tenho que lavar o chão.","Tenho que secar o chão.","Tenho que encerar o chão.","Tenho que consertar o chão."],"nivel":"A2","tags":["verbo","casa"],"nota":"O chão de dentro é «the floor» e o de fora, a terra, é «the ground» — dois substantivos para o nosso único chão. A vassoura é «a broom».","v":"b5f2deb1"},{"idioma":"en","id":"en-u202","tipo":"frase","requer":"en-p202","en":"Let the water boil.","pt":"Deixe a água ferver.","aceitas":["deixe a agua ferver","deixa a agua ferver","espere a agua ferver","deixe ferver a agua"],"aceitasEn":["let the water boil","let the water come to a boil","wait for the water to boil"],"distratores":["Deixe a água esfriar.","Deixe a água escorrer.","Deixe a água assentar.","Deixe a água secar."],"nivel":"A2","tags":["verbo","comida"],"nota":"Depois de «let» o infinitivo vai sem «to»: «let it boil», «let me see», «let him go». E a água no ponto é «boiling water».","v":"4837a816"},{"idioma":"en","id":"en-u203","tipo":"frase","requer":"en-p203","en":"Can you peel the potatoes?","pt":"Você pode descascar as batatas?","aceitas":["voce pode descascar as batatas","pode descascar as batatas","da para descascar as batatas","descasca as batatas"],"aceitasEn":["can you peel the potatoes","could you peel the potatoes","would you peel the potatoes"],"distratores":["Você pode cozinhar as batatas?","Você pode picar as batatas?","Você pode lavar as batatas?","Você pode amassar as batatas?"],"nivel":"A2","tags":["verbo","comida"],"nota":"«Potato» faz o plural em «potatoes», com -es, e a doce é «sweet potato». Entre gente próxima, «Can you…?» é pedido, não pergunta sobre ser capaz.","v":"b654df93"},{"idioma":"en","id":"en-u204","tipo":"frase","requer":"en-p204","en":"A leaf fell on the table.","pt":"Uma folha caiu na mesa.","aceitas":["uma folha caiu na mesa","caiu uma folha na mesa","uma folha caiu sobre a mesa"],"aceitasEn":["a leaf fell on the table","a leaf fell onto the table","a leaf landed on the table"],"distratores":["Uma gota caiu na mesa.","Uma moeda caiu na mesa.","Uma migalha caiu na mesa.","Uma pena caiu na mesa."],"nivel":"A2","tags":["substantivo","natureza"],"nota":"«Fell» é o passado de «fall», e «fallen» o particípio. São essas folhas que dão à estação o nome americano: o outono é «fall».","v":"b0215669"},{"idioma":"en","id":"en-u205","tipo":"frase","requer":"en-p205","en":"Wages haven't gone up.","pt":"Os salários não subiram.","aceitas":["os salarios nao subiram","os salarios nao aumentaram","nao houve aumento de salario"],"aceitasEn":["wages havent gone up","wages have not gone up","wages havent risen"],"distratores":["Os preços não subiram.","Os juros não subiram.","Os impostos não subiram.","Os aluguéis não subiram."],"nivel":"B1","tags":["substantivo","economia","trabalho"],"nota":"«To go up» é o subir do dia a dia e «to rise» o do noticiário. O aumento em si é «a raise» nos Estados Unidos e «a rise» na Inglaterra.","v":"edf474fd"},{"idioma":"en","id":"en-u206","tipo":"frase","requer":"en-p206","en":"They took out a loan.","pt":"Eles fizeram um empréstimo.","aceitas":["eles fizeram um emprestimo","eles pegaram um emprestimo","eles tomaram um emprestimo","fizeram um emprestimo"],"aceitasEn":["they took out a loan","they got a loan","they took a loan out"],"distratores":["Eles fizeram um seguro.","Eles fizeram um orçamento.","Eles fizeram um depósito.","Eles fizeram um acordo."],"nivel":"B1","tags":["substantivo","economia"],"nota":"«To take out» é o verbo de contratar no banco: «take out a loan», «take out insurance». Quitar é «to pay off», e deixar de pagar é «to default».","v":"026f9fb6"},{"idioma":"en","id":"en-u207","tipo":"frase","requer":"en-p207","en":"You have to stir it constantly.","pt":"Você tem que mexer sem parar.","aceitas":["voce tem que mexer sem parar","tem que mexer sem parar","e preciso mexer sem parar","voce tem que mexer o tempo todo"],"aceitasEn":["you have to stir it constantly","you have to keep stirring","you need to stir it constantly"],"distratores":["Você tem que bater sem parar.","Você tem que soprar sem parar.","Você tem que provar sem parar.","Você tem que vigiar sem parar."],"nivel":"B1","tags":["verbo","comida"],"nota":"«Constantly» é sem parar, e «to keep stirring» diz o mesmo pelo verbo. Na frigideira funda, o refogado rápido é «a stir-fry».","v":"782a1f83"},{"idioma":"en","id":"en-u208","tipo":"frase","requer":"en-p208","en":"The fitting room is occupied.","pt":"O provador está ocupado.","aceitas":["o provador esta ocupado","o provador ta ocupado","tem alguem no provador"],"aceitasEn":["the fitting room is occupied","the fitting rooms occupied","the fitting room is taken","someones in the fitting room"],"distratores":["O banheiro está ocupado.","O caixa está ocupado.","O elevador está ocupado.","O estacionamento está ocupado."],"nivel":"B1","tags":["substantivo","compras","roupa"],"nota":"«Occupied» é o aviso escrito na porta; na fala se diz «it's taken» ou «someone's in there». Quem está ocupado de trabalho é «busy», que é outra palavra.","v":"a2b476e6"},{"idioma":"en","id":"en-u209","tipo":"frase","requer":"en-p209","en":"Lightning hit the tower.","pt":"Um raio atingiu a torre.","aceitas":["um raio atingiu a torre","um relampago atingiu a torre","a torre foi atingida por um raio","caiu um raio na torre"],"aceitasEn":["lightning hit the tower","lightning struck the tower","the lightning hit the tower"],"distratores":["Um míssil atingiu a torre.","Um drone atingiu a torre.","Um caminhão atingiu a torre.","Um tiro atingiu a torre."],"nivel":"B1","tags":["substantivo","natureza"],"nota":"«Lightning» vai sem artigo: «lightning hit», nunca «a lightning». O verbo do noticiário é «to strike», com passado «struck», e o para-raios é «a lightning rod».","v":"e07e605e"},{"idioma":"en","id":"en-u210","tipo":"frase","requer":"en-p210","en":"You should rinse the glass first.","pt":"É melhor enxaguar o copo primeiro.","aceitas":["e melhor enxaguar o copo primeiro","melhor enxaguar o copo primeiro","e melhor passar o copo na agua primeiro"],"aceitasEn":["you should rinse the glass first","its better to rinse the glass first","you ought to rinse the glass first"],"distratores":["É melhor secar o copo primeiro.","É melhor esquentar o copo primeiro.","É melhor cheirar o copo primeiro.","É melhor guardar o copo primeiro."],"nivel":"B1","tags":["verbo","casa"],"nota":"«You should» é conselho, não ordem: equivale a «é melhor». O copo de água é «a glass» e o de vinho, «a wine glass»; o de plástico da festa é «a cup».","v":"cffd1204"},{"idioma":"en","id":"en-u211","tipo":"frase","requer":"en-p211","en":"I had a hunch about him.","pt":"Eu tinha um palpite sobre ele.","aceitas":["eu tinha um palpite sobre ele","tinha um palpite sobre ele","eu tinha um pressentimento sobre ele","eu tinha uma intuicao sobre ele"],"aceitasEn":["i had a hunch about him","ive had a hunch about him"],"distratores":["Eu tinha um dossiê sobre ele.","Eu tinha um recado sobre ele.","Eu tinha um relato sobre ele.","Eu tinha um livro sobre ele."],"nivel":"B2","tags":["substantivo","cotidiano"],"nota":"A preposição do palpite é «about»: «a hunch about him», nunca «of him». E quando dá certo se diz «my hunch was right».","v":"09f762a5"},{"idioma":"en","id":"en-v167","tipo":"frase","en":"I'm going to call her.","pt":"Vou ligar para ela.","aceitas":["vou ligar para ela","eu vou ligar para ela","vou telefonar para ela","vou ligar pra ela"],"aceitasEn":["im going to call her","i am going to call her","im gonna call her"],"distratores":["Liguei para ela.","Ligarei para ela.","Ligaria para ela.","Tinha ligado para ela."],"formasEn":{"I called her":"pretérito","I call her":"presente","I would call her":"condicional","I had called her":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","regular","call","futuro","social"],"nota":"«Be going to» é o futuro de quem já decidiu; «will» é o que se resolve na hora da fala. Na conversa «going to» encolhe: «I'm gonna call her».","v":"10648d9b"},{"idioma":"en","id":"en-v168","tipo":"frase","en":"She doesn't speak English.","pt":"Ela não fala inglês.","aceitas":["ela nao fala ingles","ela nao sabe ingles","ela nao fala o ingles"],"aceitasEn":["she doesnt speak english","she does not speak english","she doesnt speak any english"],"distratores":["Ela não falou inglês.","Ela não falará inglês.","Ela não falaria inglês.","Ela não tinha falado inglês."],"formasEn":{"She didn't speak English":"pretérito","She won't speak English":"futuro","She wouldn't speak English":"condicional","She hadn't spoken English":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","irregular","speak","presente"],"nota":"A negativa do presente pede «doesn't» mais o infinitivo nu: «she doesn't speak», nunca «she doesn't speaks». O -s da terceira pessoa migra para o «does» e sai do verbo.","v":"ac7c5226"},{"idioma":"en","id":"en-v169","tipo":"frase","en":"We were eating when he arrived.","pt":"Estávamos comendo quando ele chegou.","aceitas":["estavamos comendo quando ele chegou","nos estavamos comendo quando ele chegou","estavamos a comer quando ele chegou"],"aceitasEn":["we were eating when he arrived","we were eating when he came"],"distratores":["Comemos quando ele chegou.","Comeremos quando ele chegar.","Comeríamos quando ele chegasse.","Tínhamos comido quando ele chegou."],"formasEn":{"We ate when he arrived":"pretérito","We eat when he arrives":"presente","We will eat when he arrives":"futuro","We had eaten when he arrived":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","irregular","eat","imperfeito","comida"],"nota":"O «was/were + -ing» é a ação em curso que outra interrompe. Na mesma frase cada verbo fica no seu tempo: o que durava no contínuo, o que cortou no passado simples.","v":"a0726270"},{"idioma":"en","id":"en-v170","tipo":"frase","en":"Have you ever been to Spain?","pt":"Você já foi à Espanha?","aceitas":["voce ja foi a espanha","ja foi a espanha","voce ja esteve na espanha","voce ja visitou a espanha"],"aceitasEn":["have you ever been to spain","have you been to spain"],"distratores":["Você foi à Espanha no ano passado?","Você irá à Espanha?","Você iria à Espanha?","Você tinha ido à Espanha?"],"formasEn":{"Did you go to Spain?":"pretérito","Will you go to Spain?":"futuro","Would you go to Spain?":"condicional","Had you been to Spain?":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","irregular","be","present perfect","viagem"],"nota":"Para experiência de vida o inglês usa o present perfect com «ever». E o verbo é «be», não «go»: quem esteve lá «has been to Spain»; «has gone to Spain» é quem está lá agora.","v":"9de04e72"},{"idioma":"en","id":"en-v171","tipo":"frase","en":"It must be broken.","pt":"Deve estar quebrado.","aceitas":["deve estar quebrado","deve estar com defeito","deve ter quebrado","provavelmente esta quebrado"],"aceitasEn":["it must be broken","it must be broken down","it has to be broken"],"distratores":["Devia estar quebrado.","Deverá estar quebrado.","Deveria estar quebrado.","Devia ter quebrado."],"formasEn":{"It was broken":"pretérito","It will be broken":"futuro","It would be broken":"condicional","It had been broken":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","be","presente"],"nota":"«Must» aqui não é obrigação: é a dedução de quem olha e conclui. O passado disso é «it must have been broken», e a dúvida pelo outro lado é «it can't be broken».","v":"f4d21797"},{"idioma":"en","id":"en-v172","tipo":"frase","en":"I was told to wait.","pt":"Me disseram para esperar.","aceitas":["me disseram para esperar","disseram para eu esperar","mandaram eu esperar","me pediram para esperar"],"aceitasEn":["i was told to wait","they told me to wait"],"distratores":["Me diziam para esperar.","Vão me dizer para esperar.","Me diriam para esperar.","Tinham me dito para esperar."],"formasEn":{"I am told to wait":"presente","I will be told to wait":"futuro","I would be told to wait":"condicional","I had been told to wait":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","tell","pretérito","trabalho"],"nota":"A passiva resolve o que em português pede sujeito indeterminado: «I was told» no lugar de «me disseram». É comuníssima, e quem mandou só aparece se interessar: «I was told by the manager».","v":"13689ac8"},{"idioma":"en","id":"en-v173","tipo":"frase","en":"The bridge was built in 1920.","pt":"A ponte foi construída em 1920.","aceitas":["a ponte foi construida em 1920","a ponte foi feita em 1920","construiram a ponte em 1920"],"aceitasEn":["the bridge was built in 1920","the bridge was constructed in 1920"],"distratores":["A ponte é construída em 1920.","A ponte será construída em 1920.","A ponte seria construída em 1920.","A ponte tinha sido construída em 1920."],"formasEn":{"The bridge is built in 1920":"presente","The bridge will be built in 1920":"futuro","The bridge would be built in 1920":"condicional","The bridge had been built in 1920":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","build","pretérito"],"nota":"A passiva é «be» mais particípio: «was built». Quem fez entra com «by» — «built by the Romans» — e, quando não interessa, simplesmente não aparece, que é o caso mais comum.","v":"94b9ca42"},{"idioma":"en","id":"en-v174","tipo":"frase","en":"The house is being painted.","pt":"A casa está sendo pintada.","aceitas":["a casa esta sendo pintada","estao pintando a casa","a casa ta sendo pintada"],"aceitasEn":["the house is being painted","theyre painting the house"],"distratores":["A casa foi pintada.","A casa será pintada.","A casa seria pintada.","A casa tinha sido pintada."],"formasEn":{"The house was being painted":"imperfeito","The house will be painted":"futuro","The house would be painted":"condicional","The house had been painted":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","regular","paint","presente","casa"],"nota":"A passiva em curso junta o «be» duas vezes: «is being painted». Soa pesada e é mesmo assim que se diz; em português se prefere a ativa, «estão pintando a casa».","v":"0fad8330"},{"idioma":"en","id":"en-v175","tipo":"frase","en":"He's lived here for ten years.","pt":"Ele mora aqui há dez anos.","aceitas":["ele mora aqui ha dez anos","ele vive aqui ha dez anos","mora aqui ha dez anos","ele esta morando aqui ha dez anos"],"aceitasEn":["hes lived here for ten years","he has lived here for ten years","hes been living here for ten years"],"distratores":["Ele morou aqui dez anos.","Ele morará aqui dez anos.","Ele moraria aqui dez anos.","Ele tinha morado aqui dez anos."],"formasEn":{"He lived here for ten years":"pretérito","He will live here for ten years":"futuro","He would live here for ten years":"condicional","He had lived here for ten years":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","regular","live","present perfect"],"nota":"O que começou e continua vai no present perfect. «He lives here for ten years» é erro, e «he lived here» joga tudo para o passado — nesse caso ele já se mudou.","v":"8febeadb"},{"idioma":"en","id":"en-v176","tipo":"frase","en":"He would have won.","pt":"Ele teria ganhado.","aceitas":["ele teria ganhado","ele teria ganho","ele teria vencido","teria ganhado"],"aceitasEn":["he would have won","he wouldve won","hed have won"],"distratores":["Ele ganhou.","Ele ganhará.","Ele ganharia.","Ele tinha ganhado."],"formasEn":{"He won":"pretérito","He will win":"futuro","He would win":"condicional","He had won":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","win","condicional composto"],"nota":"«Would have» mais particípio é o que não aconteceu: «he would have won if…». Na fala vira «he would've won» ou «he'd have won», e «won» se diz como «one».","v":"00f46631"},{"idioma":"en","id":"en-v177","tipo":"frase","en":"I'm used to it.","pt":"Já estou acostumado.","aceitas":["ja estou acostumado","estou acostumado","ja me acostumei","ja estou habituado"],"aceitasEn":["im used to it","i am used to it","im used to it now"],"distratores":["Eu estava acostumado.","Vou ficar acostumado.","Eu ficaria acostumado.","Eu tinha ficado acostumado."],"formasEn":{"I was used to it":"imperfeito","I will be used to it":"futuro","I would be used to it":"condicional","I had been used to it":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","be","presente","cotidiano"],"nota":"São dois «used to» diferentes: «I used to smoke» é o que eu fazia e não faço mais; «I'm used to it» é estar acostumado. O segundo pede o verbo «be» e nunca dispensa o «to».","v":"36a51005"},{"idioma":"en","id":"en-v178","tipo":"frase","en":"I'd rather walk.","pt":"Prefiro ir andando.","aceitas":["prefiro ir andando","prefiro ir a pe","eu prefiro ir andando","prefiro caminhar"],"aceitasEn":["id rather walk","i would rather walk","id prefer to walk"],"distratores":["Preferi ir andando.","Vou preferir ir andando.","Preferiria ir andando.","Tinha preferido ir andando."],"formasEn":{"I preferred to walk":"pretérito","I prefer to walk":"presente","I would rather have walked":"condicional composto","I had preferred to walk":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","regular","walk","condicional"],"nota":"«Would rather» pede infinitivo sem «to»: «I'd rather walk», nunca «I'd rather to walk». O que se recusa entra com «than»: «I'd rather walk than wait».","v":"20755f72"},{"idioma":"en","id":"en-v179","tipo":"frase","en":"They may not have heard.","pt":"Pode ser que não tenham ouvido.","aceitas":["pode ser que nao tenham ouvido","talvez nao tenham ouvido","e possivel que nao tenham ouvido"],"aceitasEn":["they may not have heard","they might not have heard","they may not have heard it"],"distratores":["Pode ser que não ouçam.","Pode ser que não ouvissem.","Eles não ouviram.","Eles não tinham ouvido."],"formasEn":{"They didn't hear":"pretérito","They don't hear":"presente","They won't hear":"futuro","They hadn't heard":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","hear","condicional composto"],"nota":"«May» e «might» valem igual aqui, e o «have» mais particípio joga a dúvida para o passado. «May not have heard» é «talvez não tenham ouvido», e não «não podem ter ouvido».","v":"a7659e1f"},{"idioma":"en","id":"en-v180","tipo":"frase","en":"He keeps forgetting.","pt":"Ele vive esquecendo.","aceitas":["ele vive esquecendo","ele esquece sempre","ele fica esquecendo","ele nao para de esquecer"],"aceitasEn":["he keeps forgetting","he keeps on forgetting","he keeps forgetting it"],"distratores":["Ele esqueceu.","Ele vai esquecer.","Ele esqueceria.","Ele tinha esquecido."],"formasEn":{"He kept forgetting":"pretérito","He will keep forgetting":"futuro","He would keep forgetting":"condicional","He had kept forgetting":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","forget","gerúndio"],"nota":"«Keep» mais gerúndio é o que não para de acontecer: «he keeps forgetting», «it keeps raining». «Keep on» diz o mesmo com mais ênfase, e o infinitivo não entra aí.","v":"c32a0a17"},{"idioma":"en","id":"en-v181","tipo":"frase","en":"Had we left earlier, we'd have made it.","pt":"Se tivéssemos saído mais cedo, teríamos chegado.","aceitas":["se tivessemos saido mais cedo teriamos chegado","se tivessemos saido antes teriamos chegado","teriamos chegado se tivessemos saido mais cedo"],"aceitasEn":["had we left earlier wed have made it","if we had left earlier we would have made it","had we left earlier we would have made it"],"distratores":["Se saíssemos mais cedo, chegaríamos.","Se sairmos mais cedo, chegaremos.","Saímos mais cedo e chegamos.","Tínhamos saído mais cedo e chegamos."],"formasEn":{"If we left earlier, we would make it":"condicional","If we leave earlier, we will make it":"presente","We left earlier":"pretérito","We had left earlier":"mais-que-perfeito"},"nivel":"B2","tags":["conjugação","irregular","leave","condicional composto"],"nota":"Tirando o «if» e pondo o verbo na frente, a condicional sobe de registro: «had we left» vale «if we had left» e soa a escrito. A inversão serve também com «were» e com «should».","v":"23601f03"},{"idioma":"en","id":"en-v182","tipo":"frase","en":"It is said to be the oldest.","pt":"Dizem que é o mais antigo.","aceitas":["dizem que e o mais antigo","dizem ser o mais antigo","e tido como o mais antigo","consta que e o mais antigo"],"aceitasEn":["it is said to be the oldest","its said to be the oldest","it is said to be the oldest one"],"distratores":["Diziam que era o mais antigo.","Dirão que é o mais antigo.","Diriam que é o mais antigo.","Tinham dito que era o mais antigo."],"formasEn":{"It was said to be the oldest":"pretérito","It will be said to be the oldest":"futuro","It would be said to be the oldest":"condicional","It had been said to be the oldest":"mais-que-perfeito"},"nivel":"B2","tags":["conjugação","irregular","say","presente","mídia"],"nota":"A passiva com infinitivo encurta o relato: «it is said to be» no lugar de «people say that it is». É a forma do jornal e do verbete, e vale com «believed», «thought» e «known».","v":"ea056e1b"},{"idioma":"en","id":"en-v183","tipo":"frase","en":"There's no telling what he'll do.","pt":"Não há como saber o que ele vai fazer.","aceitas":["nao ha como saber o que ele vai fazer","nao da para saber o que ele vai fazer","e impossivel saber o que ele vai fazer","nao se sabe o que ele vai fazer"],"aceitasEn":["theres no telling what hell do","there is no telling what he will do","theres no telling what hes going to do"],"distratores":["Não havia como saber o que ele faria.","Não haverá como saber o que ele vai fazer.","Não haveria como saber o que ele faria.","Não tinha havido como saber o que ele faria."],"formasEn":{"There was no telling what he would do":"pretérito","There will be no telling what he will do":"futuro","There would be no telling what he would do":"condicional","There had been no telling what he would do":"mais-que-perfeito"},"nivel":"B2","tags":["conjugação","irregular","tell","gerúndio"],"nota":"«There's no» mais gerúndio é a construção do impossível: «there's no telling», «there's no knowing», «there's no stopping him». Aqui «tell» é saber, e não contar.","v":"94fbebe6"},{"idioma":"en","id":"en-f297","tipo":"frase","en":"Do you take cards?","pt":"Vocês aceitam cartão?","aceitas":["voces aceitam cartao","aceitam cartao","da para pagar com cartao","posso pagar com cartao"],"aceitasEn":["do you take cards","do you take card","do you accept cards"],"distratores":["Vocês aceitam cheque?","Vocês aceitam devolução?","Vocês aceitam reserva?","Vocês aceitam encomenda?"],"nivel":"A2","tags":["expressão","compras"],"nota":"«To take» é o verbo do caixa: «we take cards», «we don't take checks». O de crédito é «a credit card» e o de débito «a debit card» — «card» sozinho serve aos dois.","v":"c1c65df6"},{"idioma":"en","id":"en-f298","tipo":"frase","en":"Could you spell that?","pt":"Pode soletrar?","aceitas":["pode soletrar","pode soletrar isso","poderia soletrar","como se escreve"],"aceitasEn":["could you spell that","can you spell that","could you spell it"],"distratores":["Pode repetir?","Pode explicar?","Pode traduzir?","Pode anotar?"],"nivel":"A2","tags":["expressão","social"],"nota":"«To spell» é dizer letra por letra, e não tem verbo correspondente em português. O substantivo é «spelling», e «How do you spell it?» é o jeito mais direto de pedir.","v":"f9bc83bc"},{"idioma":"en","id":"en-f299","tipo":"frase","en":"Can you take a picture of us?","pt":"Pode tirar uma foto da gente?","aceitas":["pode tirar uma foto da gente","pode tirar uma foto nossa","voce pode tirar uma foto da gente","tira uma foto da gente"],"aceitasEn":["can you take a picture of us","could you take a picture of us","can you take our picture"],"distratores":["Pode tirar uma foto com a gente?","Pode mandar a foto para a gente?","Pode mostrar a foto para a gente?","Pode apagar a foto da gente?"],"nivel":"A2","tags":["expressão","viagem"],"nota":"«Of us» é a foto em que aparecemos nós; «with us» é a foto em que a pessoa entra junto. A preposição decide quem sai no retrato.","v":"7c74167e"},{"idioma":"en","id":"en-f300","tipo":"frase","en":"I'll take it.","pt":"Vou levar.","aceitas":["vou levar","eu vou levar","vou ficar com ele","vou levar esse"],"aceitasEn":["ill take it","i will take it","ill take this one"],"distratores":["Vou pensar.","Vou pegar depois.","Vou devolver.","Vou experimentar."],"nivel":"A2","tags":["expressão","compras"],"nota":"«I'll take it» é como se fecha a compra; «I'll buy it» soa a declaração de intenção. E o verbo é «take», não «carry»: quem decide levar «takes», quem carrega no braço «carries».","v":"8a89c5a6"},{"idioma":"en","id":"en-f301","tipo":"frase","en":"Let's get down to business.","pt":"Vamos ao que interessa.","aceitas":["vamos ao que interessa","vamos direto ao assunto","vamos ao trabalho","maos a obra"],"aceitasEn":["lets get down to business","let us get down to business","lets get down to it"],"distratores":["Vamos descer ao comércio.","Vamos abrir um negócio.","Vamos encerrar o assunto.","Vamos deixar para amanhã."],"nivel":"B1","tags":["expressão","trabalho"],"nota":"«Business» aqui não é empresa nem comércio: é o assunto que interessa. «Get down to» é pôr-se a fazer, e «get down to brass tacks» é a versão antiga da mesma frase.","v":"1d3b2d18"},{"idioma":"en","id":"en-f302","tipo":"frase","en":"I didn't catch that.","pt":"Não peguei o que você disse.","aceitas":["nao peguei o que voce disse","nao entendi o que voce disse","nao captei","nao ouvi bem"],"aceitasEn":["i didnt catch that","i did not catch that","i didnt catch what you said"],"distratores":["Não peguei o que você jogou.","Não aceitei o que você disse.","Não acreditei no que você disse.","Não gostei do que você disse."],"nivel":"B1","tags":["expressão","social"],"nota":"«To catch» é pegar com o ouvido: «I didn't catch your name». É mais educado que «I didn't understand», porque joga a culpa no barulho e não em quem falou.","v":"954138f3"},{"idioma":"en","id":"en-f303","tipo":"frase","en":"Let me get this straight.","pt":"Deixa eu ver se entendi.","aceitas":["deixa eu ver se entendi","deixe eu ver se entendi","so para eu entender","entao deixa eu ver se entendi"],"aceitasEn":["let me get this straight","let me get this right","so let me get this straight"],"distratores":["Deixa eu endireitar isso.","Deixa eu alinhar isso aqui.","Deixa eu falar sem rodeios.","Deixa eu resolver isso logo."],"nivel":"B1","tags":["expressão","social"],"nota":"«Straight» é reto, e «to get something straight» é pôr a informação em ordem. Vem quase sempre antes de repetir o que se ouviu, para confirmar.","v":"0045b92d"},{"idioma":"en","id":"en-f304","tipo":"frase","en":"That's news to me.","pt":"Essa é nova para mim.","aceitas":["essa e nova para mim","essa e novidade para mim","nao sabia disso","e a primeira vez que ouco isso"],"aceitasEn":["thats news to me","that is news to me","well thats news to me"],"distratores":["Essa é a notícia que eu tenho.","Essa é a notícia para mim.","Essa é velha para mim.","Essa é fácil para mim."],"nivel":"B1","tags":["expressão","social"],"nota":"«News» é sempre singular: «that's news», «the news is good». Aqui não é notícia de jornal, e sim o espanto de quem acaba de ser informado — costuma vir com um «well» na frente.","v":"cd4149b7"},{"idioma":"en","id":"en-f305","tipo":"frase","en":"What's the catch?","pt":"Qual é a pegadinha?","aceitas":["qual e a pegadinha","onde esta a pegadinha","qual e o truque","onde e que esta a armadilha"],"aceitasEn":["whats the catch","what is the catch","so whats the catch"],"distratores":["Qual é a captura?","Qual é o pescado do dia?","Qual é a vantagem disso?","Qual é o preço final?"],"nivel":"B1","tags":["expressão","social"],"nota":"«The catch» é a condição escondida que estraga a oferta boa demais. Vem do que se prende: a trava da porta e o peixe pescado também são «catch».","v":"edc53aa5"},{"idioma":"en","id":"en-f306","tipo":"frase","en":"I can't help it.","pt":"Não consigo evitar.","aceitas":["nao consigo evitar","nao posso evitar","e mais forte que eu","nao da para evitar"],"aceitasEn":["i cant help it","i can not help it","i cannot help it"],"distratores":["Não consigo ajudar.","Não consigo ajudar nisso.","Não consigo melhorar.","Não consigo decidir."],"nivel":"B1","tags":["expressão","falso-amigo","social"],"nota":"«Can't help» mais gerúndio é não conseguir deixar de fazer: «I can't help laughing». Sozinho, «I can't help it» é a desculpa de quem não se controla — e nada tem de ajudar.","v":"d035c20e"},{"idioma":"en","id":"en-f307","tipo":"frase","en":"Don't bother.","pt":"Não precisa se incomodar.","aceitas":["nao precisa se incomodar","nao se incomode","nao precisa","deixa que nao precisa"],"aceitasEn":["dont bother","do not bother","dont bother with it"],"distratores":["Não precisa insistir.","Não precisa reclamar.","Não precisa agradecer.","Não precisa repetir."],"nivel":"B1","tags":["expressão","social"],"nota":"«Bother» é dar-se o trabalho, e «don't bother» recusa o favor antes que a pessoa se levante. Com objeto o verbo muda de lado: «don't bother him» é não o incomodar.","v":"6228d5b6"},{"idioma":"en","id":"en-f308","tipo":"frase","en":"That's beside the point.","pt":"Isso não é a questão.","aceitas":["isso nao e a questao","isso nao vem ao caso","isso e irrelevante","isso foge do assunto"],"aceitasEn":["thats beside the point","that is beside the point","thats not the point"],"distratores":["Isso não é o ponto final.","Isso não é a ponta do lápis.","Isso é o principal do caso.","Isso prova o que eu digo."],"nivel":"B1","tags":["expressão","social"],"nota":"«The point» é o assunto em discussão, não o ponto gráfico. «Beside the point» é ficar ao lado dele, «to the point» é ir direto, e «you've got a point» é dar razão a alguém.","v":"9aab3f5e"},{"idioma":"en","id":"en-f309","tipo":"frase","en":"I'm running late.","pt":"Vou chegar atrasado.","aceitas":["vou chegar atrasado","estou atrasado","vou me atrasar","vou chegar tarde"],"aceitasEn":["im running late","i am running late","im going to be late"],"distratores":["Vou chegar correndo.","Vou sair correndo.","Vou chegar antes.","Vou chegar de bicicleta."],"nivel":"B1","tags":["expressão","cotidiano"],"nota":"«To run late» não é correr: é estar fora do horário, e serve à pessoa, à reunião e ao trem. O contrário é «to run early», e quem está no horário «is on time».","v":"1430584a"},{"idioma":"en","id":"en-f310","tipo":"frase","en":"There's no rush.","pt":"Não há pressa.","aceitas":["nao ha pressa","nao tem pressa","nao precisa correr","nao e urgente"],"aceitasEn":["theres no rush","there is no rush","no rush"],"distratores":["Não há corrida.","Não há fila.","Não há tempo.","Não há saída."],"nivel":"B1","tags":["expressão","social"],"nota":"«Rush» é a pressa e também o empurrão da multidão: «rush hour» é a hora do aperto. «There's no rush» acalma quem está se apressando, e «don't rush me» é o pedido contrário.","v":"13ccbd9c"},{"idioma":"en","id":"en-f311","tipo":"frase","en":"I'm drawing a blank.","pt":"Estou com um branco.","aceitas":["estou com um branco","deu um branco em mim","deu um branco","nao consigo lembrar"],"aceitasEn":["im drawing a blank","i am drawing a blank","im drawing a complete blank"],"distratores":["Estou desenhando no papel branco.","Estou tirando um papel em branco.","Estou deixando o espaço vazio.","Estou começando do zero."],"nivel":"B2","tags":["expressão","cotidiano"],"nota":"«To draw» aqui é tirar na sorte, como quem puxa um bilhete — e o bilhete sai em branco. Diz-se de quem tenta lembrar e não encontra nada.","v":"33877440"},{"idioma":"en","id":"en-f312","tipo":"frase","en":"It doesn't add up.","pt":"Isso não fecha.","aceitas":["isso nao fecha","isso nao faz sentido","nao bate","isso nao se encaixa"],"aceitasEn":["it doesnt add up","it does not add up","that doesnt add up"],"distratores":["Isso não soma.","Isso não aumenta.","Isso não ajuda em nada.","Isso não muda nada."],"nivel":"B2","tags":["expressão","social"],"nota":"«To add up» é somar e dar certo: a conta que fecha e a história que se sustenta. A negativa é desconfiança — «his story doesn't add up» —, e «it all adds up» é a ficha caindo.","v":"9f4265ab"},{"idioma":"en","id":"en-f313","tipo":"frase","en":"That's a stretch.","pt":"Isso é forçar a barra.","aceitas":["isso e forcar a barra","isso e exagerar","isso e muita viagem","isso e forcado"],"aceitasEn":["thats a stretch","that is a stretch","thats a bit of a stretch"],"distratores":["Isso é um alongamento.","Isso é um trecho da estrada.","Isso é um passo adiante.","Isso é uma boa saída."],"nivel":"B2","tags":["expressão","social"],"nota":"«A stretch» é o que se esticou além do que dava: a conclusão que não cabe nos fatos. Também é o alongamento e o trecho de estrada, e aqui não é nenhum dos dois.","v":"cea284db"},{"idioma":"en","id":"en-f314","tipo":"frase","en":"That went over my head.","pt":"Isso passou longe de mim.","aceitas":["isso passou longe de mim","isso passou por cima da minha cabeca","eu nao entendi nada disso","isso foi alem de mim"],"aceitasEn":["that went over my head","it went over my head","that one went over my head"],"distratores":["Isso passou acima da porta.","Isso bateu na minha cabeça.","Isso ficou gravado em mim.","Isso me pegou de jeito."],"nivel":"B2","tags":["expressão","social"],"nota":"«To go over someone's head» é passar por cima sem ser entendido: a piada ou a explicação que não pega. Com gente no meio muda de sentido — decidir «over my head» é me passar por cima.","v":"a16caa7e"},{"idioma":"en","id":"en-f315","tipo":"frase","en":"He left no stone unturned.","pt":"Ele não deixou nada por tentar.","aceitas":["ele nao deixou nada por tentar","ele tentou de tudo","ele revirou tudo","ele nao deixou nada sem procurar"],"aceitasEn":["he left no stone unturned","he has left no stone unturned"],"distratores":["Ele não deixou pedra sobre pedra.","Ele não virou nenhuma pedra.","Ele não deixou nada no lugar.","Ele não desistiu no meio."],"nivel":"C1","tags":["expressão","formal","social"],"nota":"A imagem é de quem vira todas as pedras à procura de algo: esgotar os recursos. Em português a pedra entra em outra expressão, de destruição — e aqui é o contrário, é empenho.","v":"e29162d5"},{"idioma":"en","id":"en-f316","tipo":"frase","en":"It cuts both ways.","pt":"Isso vale para os dois lados.","aceitas":["isso vale para os dois lados","vale para os dois lados","e uma faca de dois gumes","o argumento serve para os dois lados"],"aceitasEn":["it cuts both ways","it can cut both ways","this cuts both ways"],"distratores":["Isso corta de um lado só.","Isso corta o caminho pela metade.","Isso agrada aos dois lados.","Isso resolve os dois problemas."],"nivel":"C1","tags":["expressão","social","formal"],"nota":"«To cut both ways» é o argumento que serve igual ao adversário: quem o usa pode ser atingido por ele. A imagem é da lâmina de dois fios, que também dá «a double-edged sword».","v":"130494a1"},{"idioma":"en","id":"en-f317","tipo":"frase","en":"He paid lip service to it.","pt":"Ele só apoiou da boca para fora.","aceitas":["ele so apoiou da boca para fora","ele apoiou so de boca","ele fingiu apoiar","ele apoiou so na aparencia"],"aceitasEn":["he paid lip service to it","he only paid lip service to it"],"distratores":["Ele pagou o serviço de lábios.","Ele pagou pelo serviço à vista.","Ele apoiou com entusiasmo.","Ele recusou apoiar o projeto."],"nivel":"C1","tags":["expressão","política","formal"],"nota":"«Lip service» é o apoio que fica nos lábios e não chega aos atos. Vem quase sempre com «to pay», e é acusação: quem paga assim diz que concorda e não faz nada.","v":"168a8ddf"},{"idioma":"en","id":"en-f318","tipo":"frase","en":"I'll go out on a limb here.","pt":"Vou me arriscar a dizer uma coisa.","aceitas":["vou me arriscar a dizer uma coisa","vou arriscar um palpite","vou me expor aqui","vou dar uma opiniao arriscada"],"aceitasEn":["ill go out on a limb here","i will go out on a limb here","ill go out on a limb"],"distratores":["Vou subir no galho mais alto.","Vou sair pela porta de trás.","Vou mudar de assunto agora.","Vou ficar fora dessa discussão."],"nivel":"C1","tags":["expressão","social","formal"],"nota":"«A limb» é o galho, e quem vai até a ponta dele fica onde pode quebrar. Diz-se antes da opinião que talvez não se sustente, e ficar lá depois é «to be out on a limb».","v":"04dca072"},{"idioma":"en","id":"en-f319","tipo":"frase","en":"He's hedging his bets.","pt":"Ele está jogando nos dois times.","aceitas":["ele esta jogando nos dois times","ele esta se garantindo dos dois lados","ele esta em cima do muro","ele nao quer se comprometer"],"aceitasEn":["hes hedging his bets","he is hedging his bets","hes hedging"],"distratores":["Ele está podando a cerca viva.","Ele está apostando tudo numa só.","Ele está perdendo as apostas.","Ele está cobrando as apostas."],"nivel":"C1","tags":["expressão","economia","formal"],"nota":"«A hedge» é a cerca viva, e «to hedge» é cercar-se: repartir as apostas para não perder tudo numa só. No mercado é a operação de proteção; na conversa, é não se comprometer.","v":"ad6b8bc0"},{"idioma":"en","id":"en-f320","tipo":"frase","en":"By the same token, we owe him an apology.","pt":"Pela mesma razão, devemos uma desculpa a ele.","aceitas":["pela mesma razao devemos uma desculpa a ele","pelo mesmo motivo devemos desculpas a ele","na mesma linha devemos uma desculpa a ele"],"aceitasEn":["by the same token we owe him an apology","by the same token we also owe him an apology"],"distratores":["Pela mesma ficha, devemos uma desculpa a ele.","Pelo mesmo símbolo, devemos uma desculpa a ele.","Pela primeira vez, devemos uma desculpa a ele.","Por outro lado, devemos uma desculpa a ele."],"nivel":"C2","tags":["expressão","formal"],"nota":"«By the same token» liga duas conclusões tiradas do mesmo princípio: se vale uma, vale a outra. «Token» aqui é o sinal, a prova — e não a ficha nem a senha.","v":"6a055d50"},{"idioma":"en","id":"en-f321","tipo":"frase","en":"For all intents and purposes, it's over.","pt":"Para todos os efeitos, está encerrado.","aceitas":["para todos os efeitos esta encerrado","para todos os efeitos acabou","na pratica esta encerrado","para todos os fins esta encerrado"],"aceitasEn":["for all intents and purposes its over","for all intents and purposes it is over"],"regionaisEn":{"to all intents and purposes its over":"na Inglaterra"},"distratores":["Para todas as intenções, está encerrado.","Para todos os propósitos, está encerrado.","Para alguns efeitos, está encerrado.","Para o que der e vier, está encerrado."],"nivel":"C2","tags":["expressão","jurídico","formal"],"nota":"Fórmula de contrato que entrou na fala: diz que, na prática, a coisa já se dá por feita. Nos Estados Unidos é «for all intents and purposes»; na Inglaterra, «to all intents and purposes».","v":"0a2561d4"},{"idioma":"en","id":"en-f322","tipo":"frase","en":"Be that as it may, the deadline stands.","pt":"Seja como for, o prazo está mantido.","aceitas":["seja como for o prazo esta mantido","de todo modo o prazo esta mantido","ainda assim o prazo esta mantido","seja como for o prazo continua"],"aceitasEn":["be that as it may the deadline stands","be that as it may the deadline still stands"],"distratores":["Que isso seja assim, o prazo está mantido.","Como isso pode ser, o prazo está mantido.","Por esse motivo, o prazo está mantido.","Se for assim, o prazo está mantido."],"nivel":"C2","tags":["expressão","formal","trabalho"],"nota":"«Be that as it may» é a concessão que não cede nada: admite o argumento e mantém a decisão. É o «seja como for» do registro escrito, com o verbo num subjuntivo antigo.","v":"5201033a"},{"idioma":"en","id":"en-f323","tipo":"frase","en":"I beg to differ.","pt":"Permita-me discordar.","aceitas":["permita me discordar","com todo respeito eu discordo","peco licenca para discordar","discordo"],"aceitasEn":["i beg to differ","id beg to differ"],"distratores":["Imploro que seja diferente.","Peço uma coisa diferente.","Concordo inteiramente.","Prefiro não opinar."],"nivel":"C2","tags":["expressão","formal"],"nota":"«To beg» aqui não é implorar: é a fórmula cortês de quem pede licença, a mesma de «I beg your pardon». Serve para discordar sem brigar, e é dos modos mais educados de dizer não.","v":"0734b177"},{"idioma":"en","id":"en-f324","tipo":"frase","en":"It has run its course.","pt":"Já cumpriu seu ciclo.","aceitas":["ja cumpriu seu ciclo","ja deu o que tinha que dar","ja se esgotou","chegou ao fim natural"],"aceitasEn":["it has run its course","its run its course"],"distratores":["Já correu o percurso todo.","Já fez o curso inteiro.","Já começou a dar certo.","Já mudou de direção."],"nivel":"C2","tags":["expressão","formal"],"nota":"«To run its course» é chegar ao fim por si, sem que ninguém interrompa: a febre, a moda, a discussão. «Course» aqui é o percurso, e não o curso de estudar.","v":"3c8bd77e"},{"idioma":"en","id":"en-f325","tipo":"frase","en":"Suffice it to say, we won't be back.","pt":"Basta dizer que não voltaremos.","aceitas":["basta dizer que nao voltaremos","basta dizer que nao vamos voltar","e suficiente dizer que nao voltaremos"],"aceitasEn":["suffice it to say we wont be back","suffice it to say that we wont be back"],"distratores":["Sofremos ao dizer que não voltaremos.","Insistimos em dizer que não voltaremos.","Resta dizer que não voltaremos.","Convém dizer que não voltaremos."],"nivel":"C2","tags":["expressão","formal"],"nota":"«Suffice it to say» avisa que se vai resumir e não detalhar, com um subjuntivo antigo fossilizado na fórmula. Nada a ver com sofrer: a raiz é a de «sufficient».","v":"eecf71ee"},{"idioma":"en","id":"en-p212","tipo":"palavra","en":"the fish","pt":"o peixe","aceitas":["o peixe","peixe","os peixes"],"aceitasEn":["the fish","fish","a fish"],"distratores":["o sapo","o caranguejo","o polvo","o jacaré"],"nivel":"A1","tags":["substantivo","animais","comida"],"nota":"«Fish» não muda no plural: «two fish», «a lot of fish». «Fishes» existe, mas só na boca do biólogo, para falar de espécies diferentes. Pescar é «to fish».","v":"93fb748c"},{"idioma":"en","id":"en-p213","tipo":"palavra","en":"the dog","pt":"o cachorro","aceitas":["o cachorro","cachorro","os cachorros","o cao"],"aceitasEn":["the dog","dog","a dog","dogs"],"distratores":["o gato","o cavalo","o coelho","o porco"],"nivel":"A1","tags":["substantivo","animais"],"nota":"«Dog» é o animal e também o verbo de perseguir sem dar trégua: «the question dogged him». O filhote é «a puppy», e «the dog days» são os dias mais quentes do ano.","v":"5f3be0e2"},{"idioma":"en","id":"en-p214","tipo":"palavra","en":"the stairs","pt":"a escada","aceitas":["a escada","escada","as escadas","a escadaria"],"aceitasEn":["the stairs","stairs","the staircase"],"distratores":["o corredor","a rampa","o portão","a sacada"],"nivel":"A1","tags":["substantivo","casa"],"nota":"«Stairs» vive no plural: «down the stairs». A de encostar na parede é «a ladder» e a rolante é «an escalator» — três palavras onde o português tem uma.","v":"4dfc2a7c"},{"idioma":"en","id":"en-p215","tipo":"palavra","en":"the glass","pt":"o copo","aceitas":["o copo","copo","os copos"],"aceitasEn":["the glass","glass","a glass","glasses"],"distratores":["o pires","o funil","o balde","o cinzeiro"],"nivel":"A2","tags":["substantivo","comida","objetos"],"nota":"«Glass» é o copo e é o vidro: «a glass of water», «broken glass». No plural, «glasses» são os óculos, e o de vinho é «a wine glass».","v":"efaba245"},{"idioma":"en","id":"en-p216","tipo":"palavra","en":"the onion","pt":"a cebola","aceitas":["a cebola","cebola","as cebolas"],"aceitasEn":["the onion","onion","an onion","onions"],"distratores":["a abóbora","a beterraba","a cenoura","a alface"],"nivel":"A2","tags":["substantivo","comida"],"nota":"Plural «onions», e verbo não há. A camada fina de fora é «the onion skin», e «to know your onions» é entender do assunto — expressão antiga, e britânica.","v":"8dc6c8b2"},{"idioma":"en","id":"en-p217","tipo":"palavra","en":"the butter","pt":"a manteiga","aceitas":["a manteiga","manteiga"],"aceitasEn":["the butter","butter"],"distratores":["a geleia","a nata","a margarina","a banha"],"nivel":"A2","tags":["substantivo","comida"],"nota":"«Butter» não tem plural, e o verbo é passar manteiga: «butter the bread». «To butter someone up» é fazer média com alguém, à base de elogio.","v":"50630098"},{"idioma":"en","id":"en-p218","tipo":"palavra","en":"the honey","pt":"o mel","aceitas":["o mel","mel"],"aceitasEn":["the honey","honey"],"distratores":["o açúcar","o melado","o xarope","o caramelo"],"nivel":"A2","tags":["substantivo","comida"],"nota":"«Honey» não tem plural, e é também o apelido afetuoso: «hey, honey». Quem o faz é «a bee», a colmeia é «a hive», e a lua de mel é «the honeymoon».","v":"bf00b7ba"},{"idioma":"en","id":"en-p219","tipo":"palavra","en":"the sock","pt":"a meia","aceitas":["a meia","meia","as meias"],"aceitasEn":["the sock","sock","a sock","socks"],"distratores":["a luva","a sandália","a bota","a camisa"],"nivel":"A2","tags":["substantivo","roupa"],"nota":"«Sock» é a meia curta; a comprida é «a stocking» e a de corpo inteiro é «pantyhose». O verbo «to sock» é dar um soco, e nada tem a ver com roupa.","v":"7c8b97c5"},{"idioma":"en","id":"en-p220","tipo":"palavra","en":"the coat","pt":"o casaco","aceitas":["o casaco","casaco","os casacos","o sobretudo"],"aceitasEn":["the coat","coat","a coat","coats"],"distratores":["o cinto","o colete","o chapéu","o terno"],"nivel":"A2","tags":["substantivo","roupa"],"nota":"«Coat» é a peça de fora, a do frio. É também a camada — «a coat of paint» é uma camada de tinta — e o pelo do animal, «a thick coat».","v":"20934f0d"},{"idioma":"en","id":"en-p221","tipo":"palavra","en":"to hug","pt":"abraçar","aceitas":["abracar","dar um abraco"],"aceitasEn":["to hug","hug","hugging"],"distratores":["beijar","cumprimentar","empurrar","acenar"],"nivel":"A2","tags":["verbo","social"],"nota":"«Hug» é verbo e substantivo sem mudar de forma: «give me a hug». O aperto de mão é «a handshake», e abraçar uma ideia é «to embrace», não «to hug».","v":"e835251f"},{"idioma":"en","id":"en-p222","tipo":"palavra","en":"to bake","pt":"assar","aceitas":["assar","assar no forno","fazer no forno"],"aceitasEn":["to bake","bake","baking"],"distratores":["fritar","grelhar","refogar","gelar"],"nivel":"A2","tags":["verbo","comida"],"nota":"«Bake» é assar no forno, com calor seco: pão, bolo, batata. Na grelha é «to grill», e a peça grande de carne no forno é «to roast». Quem faz pão é «a baker».","v":"2b933a5e"},{"idioma":"en","id":"en-p223","tipo":"palavra","en":"the bee","pt":"a abelha","aceitas":["a abelha","abelha","as abelhas"],"aceitasEn":["the bee","bee","a bee","bees"],"distratores":["a vespa","a mosca","a formiga","a aranha"],"nivel":"A2","tags":["substantivo","animais"],"nota":"«Bee» é a abelha, e a vespa é «a wasp». A colmeia é «a hive», e quem está com uma ideia fixa «has a bee in his bonnet» — uma abelha debaixo do chapéu.","v":"80cfb0cd"},{"idioma":"en","id":"en-p224","tipo":"palavra","en":"the tax","pt":"o imposto","aceitas":["o imposto","imposto","os impostos","o tributo"],"aceitasEn":["the tax","tax","a tax","taxes"],"distratores":["o juro","o aluguel","o pedágio","o seguro"],"nivel":"B1","tags":["substantivo","economia"],"nota":"Plural «taxes». O verbo «to tax» é cobrar imposto e também pesar sobre alguém: «it taxed my patience». A declaração anual é «a tax return».","v":"2528c3c3"},{"idioma":"en","id":"en-p225","tipo":"palavra","en":"the fee","pt":"a taxa","aceitas":["a taxa","taxa","as taxas","o honorario","a quota"],"aceitasEn":["the fee","fee","a fee","fees"],"distratores":["a multa","a gorjeta","a dívida","a fiança"],"nivel":"B1","tags":["substantivo","economia"],"nota":"«Fee» é o que se cobra por um serviço: a matrícula, o advogado, o banco. A multa é «a fine», a gorjeta é «a tip», e de graça é «free of charge».","v":"672ee58f"},{"idioma":"en","id":"en-p226","tipo":"palavra","en":"to iron","pt":"passar roupa","aceitas":["passar roupa","passar a roupa","passar a ferro"],"aceitasEn":["to iron","iron","ironing"],"distratores":["lavar roupa","dobrar roupa","costurar roupa","secar roupa"],"nivel":"B1","tags":["verbo","casa","roupa"],"nota":"«Iron» é o ferro de passar, o metal e o verbo — tudo na mesma palavra. A tábua é «an ironing board», e «to iron out» é aparar as arestas de um problema.","v":"00d36e52"},{"idioma":"en","id":"en-p227","tipo":"palavra","en":"to sew","pt":"costurar","aceitas":["costurar"],"aceitasEn":["to sew","sew","sewing"],"distratores":["tecer","bordar","tricotar","cortar"],"nivel":"B1","tags":["verbo","casa","roupa"],"nota":"«Sew» é irregular — «sewed» e «sewn» — e se diz como «so», sem o som de «ew». A máquina é «a sewing machine», e «to sew up» é fechar o acordo.","v":"f32534ce"},{"idioma":"en","id":"en-p228","tipo":"palavra","en":"the quirk","pt":"a peculiaridade","aceitas":["a peculiaridade","peculiaridade","a mania","o cacoete","a esquisitice"],"aceitasEn":["the quirk","quirk","a quirk","quirks"],"distratores":["a qualidade","a virtude","a dúvida","a queixa"],"nivel":"B2","tags":["substantivo","cotidiano"],"nota":"«Quirk» é o detalhe estranho que alguém ou algo tem: «one of his quirks». «A quirk of fate» é a reviravolta do destino, e «quirky» é elogio a quem é original.","v":"dc70c817"},{"idioma":"en","id":"en-u212","tipo":"frase","requer":"en-p212","en":"The fish is fresh.","pt":"O peixe está fresco.","aceitas":["o peixe esta fresco","o peixe e fresco","o peixe esta fresquinho"],"aceitasEn":["the fish is fresh","the fishs fresh","this fish is fresh"],"distratores":["O pão está fresco.","O queijo está fresco.","O ar está fresco.","O marisco está fresco."],"nivel":"A1","tags":["substantivo","animais","comida"],"nota":"«Fresh» é o recém-feito e o recém-pescado, e serve ao ar: «fresh air». Para a temperatura, fresco é «cool» — «a cool evening», nunca «a fresh evening».","v":"566e576e"},{"idioma":"en","id":"en-u213","tipo":"frase","requer":"en-p213","en":"The dog is in the yard.","pt":"O cachorro está no quintal.","aceitas":["o cachorro esta no quintal","o cao esta no quintal","o cachorro ta no quintal"],"aceitasEn":["the dog is in the yard","the dogs in the yard","the dog is out in the yard"],"regionaisEn":{"the dog is in the garden":"na Inglaterra"},"distratores":["O gato está no quintal.","O cavalo está no quintal.","O vizinho está no quintal.","O carro está no quintal."],"nivel":"A1","tags":["substantivo","animais","casa"],"nota":"«Yard» é o quintal, de terra ou de cimento; o jardim com planta é «a garden». Na Inglaterra «yard» é só o pátio duro, e o de grama já é «garden».","v":"df61b1fa"},{"idioma":"en","id":"en-u214","tipo":"frase","requer":"en-p214","en":"The stairs are narrow.","pt":"A escada é estreita.","aceitas":["a escada e estreita","a escada e apertada","a escadaria e estreita"],"aceitasEn":["the stairs are narrow","the staircase is narrow"],"distratores":["A porta é estreita.","A rua é estreita.","A cama é estreita.","A janela é estreita."],"nivel":"A1","tags":["substantivo","casa"],"nota":"«Stairs» é plural e o verbo concorda: «the stairs are», nunca «the stairs is». O contrário de «narrow» é «wide», e o corredor apertado é «a narrow hallway».","v":"0dc8f322"},{"idioma":"en","id":"en-u215","tipo":"frase","requer":"en-p215","en":"The glass is dirty.","pt":"O copo está sujo.","aceitas":["o copo esta sujo","o copo ta sujo","esse copo esta sujo"],"aceitasEn":["the glass is dirty","the glasss dirty","this glass is dirty"],"distratores":["O prato está sujo.","O garfo está sujo.","O chão está sujo.","O pano está sujo."],"nivel":"A2","tags":["substantivo","comida","objetos"],"nota":"«Dirty» é sujo. O verbo «to dirty» existe mas quase não se usa: diz-se «to get something dirty». E lavar a louça é «to do the dishes».","v":"abe3d46f"},{"idioma":"en","id":"en-u216","tipo":"frase","requer":"en-p216","en":"The onion makes me cry.","pt":"A cebola me faz chorar.","aceitas":["a cebola me faz chorar","cebola me faz chorar","a cebola faz eu chorar"],"aceitasEn":["the onion makes me cry","onions make me cry","the onion is making me cry"],"distratores":["A música me faz chorar.","A notícia me faz chorar.","A pimenta me faz chorar.","A poeira me faz chorar."],"nivel":"A2","tags":["substantivo","comida"],"nota":"Depois de «make» o infinitivo vai sem «to»: «it makes me cry», nunca «makes me to cry». É o mesmo com «let» e com «have»: «have him call me».","v":"049505a7"},{"idioma":"en","id":"en-u217","tipo":"frase","requer":"en-p217","en":"There's no butter left.","pt":"Não tem mais manteiga.","aceitas":["nao tem mais manteiga","acabou a manteiga","nao sobrou manteiga","a manteiga acabou"],"aceitasEn":["theres no butter left","there is no butter left","we are out of butter"],"distratores":["Não tem mais farinha.","Não tem mais água.","Não tem mais cerveja.","Não tem mais massa."],"nivel":"A2","tags":["substantivo","comida"],"nota":"«Left» no fim da frase é o que sobrou: «there's nothing left». É o mesmo «left» da esquerda e do passado de «leave» — três sentidos na mesma palavra.","v":"44dcab73"},{"idioma":"en","id":"en-u218","tipo":"frase","requer":"en-p218","en":"I put honey in my tea.","pt":"Eu ponho mel no chá.","aceitas":["eu ponho mel no cha","ponho mel no cha","eu coloco mel no cha","eu tomo cha com mel"],"aceitasEn":["i put honey in my tea","i put honey in the tea","i have honey in my tea"],"distratores":["Eu ponho açúcar no chá.","Eu ponho limão no chá.","Eu ponho gelo no chá.","Eu ponho rum no chá."],"nivel":"A2","tags":["substantivo","comida"],"nota":"«Put» não muda no passado nem no particípio: «I put it there yesterday». O que vai dentro entra com «in», e o que fica em cima, com «on».","v":"6190e143"},{"idioma":"en","id":"en-u219","tipo":"frase","requer":"en-p219","en":"There's a hole in my sock.","pt":"Tem um buraco na minha meia.","aceitas":["tem um buraco na minha meia","minha meia esta furada","tem um furo na minha meia"],"aceitasEn":["theres a hole in my sock","there is a hole in my sock","my sock has a hole in it"],"distratores":["Tem um buraco na minha calça.","Tem um buraco na minha bota.","Tem um buraco na minha blusa.","Tem um buraco na minha mochila."],"nivel":"A2","tags":["substantivo","roupa"],"nota":"O buraco de alguma coisa vai com «in», e não com «of». E a peça furada é «a sock with a hole in it»: o inglês repete o «in» no fim, por estranho que pareça.","v":"fd9ca863"},{"idioma":"en","id":"en-u220","tipo":"frase","requer":"en-p220","en":"Take your coat, it's cold.","pt":"Leve o casaco, está frio.","aceitas":["leve o casaco esta frio","leva o casaco esta frio","pegue o casaco esta frio","leve o casaco que esta frio"],"aceitasEn":["take your coat its cold","take your coat it is cold","bring your coat its cold"],"distratores":["Leve o guarda-chuva, está frio.","Leve o gorro, está frio.","Leve o chapéu, está frio.","Leve o suéter, está frio."],"nivel":"A2","tags":["substantivo","roupa"],"nota":"O frio pede «it»: «it's cold», nunca «is cold» sozinho. E «take» é levar daqui para lá; trazer para cá é «bring» — quem escolhe é o ponto de vista de quem fala.","v":"7d121aa1"},{"idioma":"en","id":"en-u221","tipo":"frase","requer":"en-p221","en":"He didn't want to hug anyone.","pt":"Ele não quis abraçar ninguém.","aceitas":["ele nao quis abracar ninguem","ele nao quis dar abraco em ninguem","nao quis abracar ninguem"],"aceitasEn":["he didnt want to hug anyone","he did not want to hug anyone","he didnt want to hug anybody"],"distratores":["Ele não quis cumprimentar ninguém.","Ele não quis beijar ninguém.","Ele não quis olhar ninguém.","Ele não quis ouvir ninguém."],"nivel":"A2","tags":["verbo","social"],"nota":"Uma negativa só por frase: «didn't want to hug anyone», e não «nobody» de novo depois do «didn't». «Nobody» entra quando é o sujeito: «nobody hugged him».","v":"45f06a9e"},{"idioma":"en","id":"en-u222","tipo":"frase","requer":"en-p222","en":"I'm going to bake a cake.","pt":"Vou assar um bolo.","aceitas":["vou assar um bolo","vou fazer um bolo","eu vou assar um bolo","vou fazer um bolo no forno"],"aceitasEn":["im going to bake a cake","i am going to bake a cake","ill bake a cake"],"distratores":["Vou comprar um bolo.","Vou cortar um bolo.","Vou provar um bolo.","Vou decorar um bolo."],"nivel":"A2","tags":["verbo","comida"],"nota":"«To bake a cake» é a combinação fixa: o bolo se assa, e não se faz. E «baked goods» é tudo que sai do forno — pão, bolo, biscoito.","v":"bd41320e"},{"idioma":"en","id":"en-u223","tipo":"frase","requer":"en-p223","en":"A bee stung me.","pt":"Uma abelha me picou.","aceitas":["uma abelha me picou","me picou uma abelha","fui picado por uma abelha","uma abelha me ferroou"],"aceitasEn":["a bee stung me","i was stung by a bee","a bee has stung me"],"distratores":["Uma vespa me picou.","Uma formiga me picou.","Uma aranha me picou.","Uma mosca me picou."],"nivel":"A2","tags":["substantivo","animais","saúde"],"nota":"«Sting» é irregular: «stung» no passado e no particípio. A ferroada é «a sting», e a abelha morre depois de dar a dela — a vespa não.","v":"de611cca"},{"idioma":"en","id":"en-u224","tipo":"frase","requer":"en-p224","en":"Taxes went up again.","pt":"Os impostos subiram de novo.","aceitas":["os impostos subiram de novo","os impostos aumentaram de novo","subiram os impostos de novo"],"aceitasEn":["taxes went up again","the taxes went up again","taxes have gone up again"],"distratores":["Os preços subiram de novo.","Os juros subiram de novo.","Os aluguéis subiram de novo.","Os pedágios subiram de novo."],"nivel":"B1","tags":["substantivo","economia"],"nota":"«Taxes», no plural, é o conjunto do que se paga; no singular vem com o nome do imposto: «income tax», «sales tax». Sonegar é «tax evasion».","v":"5ccb06e4"},{"idioma":"en","id":"en-u225","tipo":"frase","requer":"en-p225","en":"The fee is non-refundable.","pt":"A taxa não é reembolsável.","aceitas":["a taxa nao e reembolsavel","a taxa nao tem devolucao","a taxa nao volta","a taxa nao e devolvida"],"aceitasEn":["the fee is non refundable","the fee is nonrefundable","the fee isnt refundable"],"distratores":["A multa não é reembolsável.","A gorjeta não é reembolsável.","A passagem não é reembolsável.","A entrada não é reembolsável."],"nivel":"B1","tags":["substantivo","economia"],"nota":"«Non-» nega sem julgar: «non-refundable», «non-smoking», «non-stop». O que dá direito a devolução é «refundable», e o dinheiro de volta é «a refund».","v":"973dfb89"},{"idioma":"en","id":"en-u226","tipo":"frase","requer":"en-p226","en":"I hate to iron.","pt":"Odeio passar roupa.","aceitas":["odeio passar roupa","eu odeio passar roupa","detesto passar roupa","nao suporto passar roupa"],"aceitasEn":["i hate to iron","i hate ironing","i hate having to iron"],"distratores":["Odeio lavar roupa.","Odeio dobrar roupa.","Odeio separar roupa.","Odeio comprar roupa."],"nivel":"B1","tags":["verbo","casa","roupa"],"nota":"Depois de «hate», «love» e «like» cabem os dois: «I hate to iron» e «I hate ironing». Com gerúndio soa mais ao hábito; com infinitivo, à vez de agora.","v":"57c37362"},{"idioma":"en","id":"en-u227","tipo":"frase","requer":"en-p227","en":"My grandmother taught me to sew.","pt":"Minha avó me ensinou a costurar.","aceitas":["minha avo me ensinou a costurar","foi minha avo que me ensinou a costurar","minha avo que me ensinou a costurar"],"aceitasEn":["my grandmother taught me to sew","my grandma taught me to sew","my grandmother taught me how to sew"],"distratores":["Minha avó me ensinou a cozinhar.","Minha avó me ensinou a tecer.","Minha avó me ensinou a bordar.","Minha avó me ensinou a rezar."],"nivel":"B1","tags":["verbo","casa","família"],"nota":"«Teach» é irregular: «taught», que se diz como «tort». Depois dele vem «to» mais infinitivo, ou «how to» quando o que se ensina é o jeito de fazer.","v":"e685aa93"},{"idioma":"en","id":"en-u228","tipo":"frase","requer":"en-p228","en":"That's just a quirk of his.","pt":"Isso é só uma mania dele.","aceitas":["isso e so uma mania dele","e so uma mania dele","isso e so um cacoete dele","isso e so uma peculiaridade dele"],"aceitasEn":["thats just a quirk of his","that is just a quirk of his","its just one of his quirks"],"distratores":["Isso é só uma piada dele.","Isso é só uma teoria dele.","Isso é só uma desculpa dele.","Isso é só uma birra dele."],"nivel":"B2","tags":["substantivo","cotidiano"],"nota":"«A quirk of his» é como o inglês diz «uma mania dele»: a posse vai para o fim, com «of» mais o possessivo. E o «just» ali ameniza — não é defeito, é detalhe.","v":"c7f3046f"},{"idioma":"en","id":"en-v184","tipo":"frase","en":"Are you coming with us?","pt":"Você vem com a gente?","aceitas":["voce vem com a gente","voces vem com a gente","vem com a gente","voce vai com a gente"],"aceitasEn":["are you coming with us","are you coming with us too","are you coming along"],"distratores":["Você veio com a gente?","Você viria com a gente?","Você tinha vindo com a gente?","Você virá com a gente?"],"formasEn":{"Did you come with us?":"pretérito","Would you come with us?":"condicional","Had you come with us?":"mais-que-perfeito","Will you come with us?":"futuro"},"nivel":"A2","tags":["conjugação","irregular","come","presente","social"],"nota":"O presente contínuo serve de futuro quando o plano já está combinado: «are you coming?» é «você vem?», e não «você está vindo agora». «Will you come?» soa a convite formal.","v":"ebf82fe9"},{"idioma":"en","id":"en-v185","tipo":"frase","en":"We didn't go out.","pt":"Não saímos.","aceitas":["nao saimos","nos nao saimos","nao saimos de casa","a gente nao saiu"],"aceitasEn":["we didnt go out","we did not go out","we didnt go out at all"],"distratores":["Não sairemos.","Não sairíamos.","Não tínhamos saído.","Não saíamos."],"formasEn":{"We don't go out":"presente","We won't go out":"futuro","We wouldn't go out":"condicional","We hadn't gone out":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","irregular","go","pretérito","social"],"nota":"O passado negativo é «didn't» mais o infinitivo nu: «didn't go», nunca «didn't went». O «did» leva o tempo, e o verbo volta à forma crua.","v":"6ee70a9c"},{"idioma":"en","id":"en-v186","tipo":"frase","en":"It was raining.","pt":"Estava chovendo.","aceitas":["estava chovendo","chovia","estava caindo chuva","tava chovendo"],"aceitasEn":["it was raining","it was raining outside"],"distratores":["Choveu.","Vai chover.","Choveria.","Tinha chovido."],"formasEn":{"It rained":"pretérito","It rains":"presente","It will rain":"futuro","It had rained":"mais-que-perfeito"},"nivel":"A2","tags":["conjugação","regular","rain","imperfeito","natureza"],"nota":"O tempo pede «it», sempre: «it was raining», e nunca «was raining» sozinho. O contínuo diz que a chuva durava; «it rained» fecha a chuva num ponto do passado.","v":"be7b617c"},{"idioma":"en","id":"en-v187","tipo":"frase","en":"It needs to be fixed.","pt":"Precisa ser consertado.","aceitas":["precisa ser consertado","precisa de conserto","tem que ser consertado","precisa arrumar"],"aceitasEn":["it needs to be fixed","it needs fixing","it has to be fixed"],"distratores":["Precisou ser consertado.","Vai precisar ser consertado.","Precisaria ser consertado.","Tinha precisado ser consertado."],"formasEn":{"It needed to be fixed":"pretérito","It will need to be fixed":"futuro","It would need to be fixed":"condicional","It had needed to be fixed":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","be","presente","casa"],"nota":"«Need» aceita os dois caminhos: «it needs to be fixed», com a passiva inteira, e «it needs fixing», com o gerúndio no lugar dela. O segundo é mais curto e mais falado.","v":"09e77d73"},{"idioma":"en","id":"en-v188","tipo":"frase","en":"She was given a prize.","pt":"Ela recebeu um prêmio.","aceitas":["ela recebeu um premio","ela ganhou um premio","deram um premio a ela","ela foi premiada"],"aceitasEn":["she was given a prize","she was given an award","a prize was given to her"],"distratores":["Ela recebe um prêmio.","Ela receberá um prêmio.","Ela receberia um prêmio.","Ela tinha recebido um prêmio."],"formasEn":{"She is given a prize":"presente","She will be given a prize":"futuro","She would be given a prize":"condicional","She had been given a prize":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","give","pretérito"],"nota":"Com «give» a passiva começa por quem recebeu: «she was given a prize», e não «a prize was given her». É o mesmo com «tell», «send» e «offer».","v":"acf0ea3e"},{"idioma":"en","id":"en-v189","tipo":"frase","en":"You're not supposed to park here.","pt":"Não se pode estacionar aqui.","aceitas":["nao se pode estacionar aqui","nao e permitido estacionar aqui","aqui nao pode estacionar","nao pode estacionar aqui"],"aceitasEn":["youre not supposed to park here","you are not supposed to park here","youre not allowed to park here"],"distratores":["Não se podia estacionar aqui.","Não se poderá estacionar aqui.","Não se poderia estacionar aqui.","Não se tinha podido estacionar aqui."],"formasEn":{"You weren't supposed to park here":"pretérito","You won't be supposed to park here":"futuro","You wouldn't be supposed to park here":"condicional","You hadn't been supposed to park here":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","be","presente","cidade"],"nota":"«To be supposed to» é a regra que alguém pôs: «you're not supposed to» é «não é permitido», e não «você não consegue». No passado muda de cor: «I was supposed to call» é o que eu devia ter feito.","v":"3f07c91a"},{"idioma":"en","id":"en-v190","tipo":"frase","en":"I've never seen it.","pt":"Nunca vi isso.","aceitas":["nunca vi isso","eu nunca vi isso","nunca vi","jamais vi isso"],"aceitasEn":["ive never seen it","i have never seen it","ive never seen that"],"distratores":["Nunca via isso.","Nunca verei isso.","Nunca veria isso.","Nunca tinha visto isso."],"formasEn":{"I never saw it":"pretérito","I never see it":"presente","I will never see it":"futuro","I had never seen it":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","see","present perfect"],"nota":"Para a experiência que vai até agora, o present perfect: «I've never seen it». «I never saw it» fecha num momento passado — na escola, naquela viagem —, e as duas não se trocam.","v":"01dad496"},{"idioma":"en","id":"en-v191","tipo":"frase","en":"They'll have left by then.","pt":"Eles já terão saído.","aceitas":["eles ja terao saido","eles ja terao ido","ja terao saido","eles ja vao ter saido"],"aceitasEn":["theyll have left by then","they will have left by then","theyll have gone by then"],"distratores":["Eles já saíram.","Eles já sairão.","Eles já sairiam.","Eles já tinham saído."],"formasEn":{"They left":"pretérito","They will leave":"futuro","They would have left":"condicional composto","They had left":"mais-que-perfeito"},"nivel":"B1","tags":["conjugação","irregular","leave","futuro"],"nota":"«Will have» mais particípio é o futuro já cumprido: a tal hora, a coisa estará feita. Quase sempre vem com «by»: «by then», «by Friday», «by the time we arrive».","v":"36c493f6"},{"idioma":"en","id":"en-v192","tipo":"frase","en":"I wish I knew.","pt":"Quem me dera saber.","aceitas":["quem me dera saber","ah se eu soubesse","eu bem que queria saber","se eu soubesse"],"aceitasEn":["i wish i knew","i wish i knew that","i do wish i knew"],"distratores":["Quem me dera ter sabido.","Eu gostaria de saber.","Eu vou querer saber.","Eu tinha querido saber."],"formasEn":{"I wish I had known":"mais-que-perfeito","I would like to know":"condicional","I wanted to know":"pretérito","I want to know":"presente"},"nivel":"B1","tags":["conjugação","irregular","know","subjuntivo"],"nota":"«I wish» pede o passado para falar do presente: «I wish I knew» é quem me dera saber agora. Com «had» a frase vira arrependimento: «I wish I had known».","v":"fdd23bf4"},{"idioma":"en","id":"en-v193","tipo":"frase","en":"Should you need anything, call me.","pt":"Se precisar de algo, me ligue.","aceitas":["se precisar de algo me ligue","qualquer coisa me liga","se precisar de alguma coisa me ligue","se precisar me ligue"],"aceitasEn":["should you need anything call me","should you need anything just call me","should you require anything call me"],"distratores":["Se precisava de algo, me ligava.","Se precisasse de algo, me ligaria.","Precisou de algo e me ligou.","Tinha precisado de algo e me ligou."],"formasEn":{"If you need anything, call me":"presente","If you needed anything, you would call me":"condicional","You needed something and called me":"pretérito","You had needed something and called me":"mais-que-perfeito"},"nivel":"B2","tags":["conjugação","regular","call","condicional","formal"],"nota":"«Should» no começo substitui o «if» e sobe o registro: «should you need» é «caso precise», de carta e de aviso. A inversão serve também com «were» e com «had».","v":"f7777b63"},{"idioma":"en","id":"en-v194","tipo":"frase","en":"Not until later did we find out.","pt":"Só mais tarde é que soubemos.","aceitas":["so mais tarde e que soubemos","so depois e que soubemos","so soubemos mais tarde","foi so mais tarde que soubemos"],"aceitasEn":["not until later did we find out","not until later did we find it out"],"distratores":["Só mais tarde é que sabemos.","Só mais tarde é que saberemos.","Só mais tarde é que saberíamos.","Só mais tarde é que tínhamos sabido."],"formasEn":{"Not until later do we find out":"presente","Not until later will we find out":"futuro","Not until later would we find out":"condicional","Not until later had we found out":"mais-que-perfeito"},"nivel":"B2","tags":["conjugação","irregular","find","pretérito"],"nota":"Começar por «not until» força a inversão: vem «did we», e não «we did». É a mesma regra de «never have I» e «rarely does he», e serve para dar ênfase no escrito.","v":"095ca27d"},{"idioma":"en","id":"en-f326","tipo":"frase","en":"What's your name?","pt":"Como você se chama?","aceitas":["como voce se chama","qual e o seu nome","qual seu nome","como e seu nome"],"aceitasEn":["whats your name","what is your name","may i have your name"],"distratores":["Como você está?","Onde você mora?","Quantos anos você tem?","De onde você é?"],"nivel":"A1","tags":["expressão","social"],"nota":"O nome é «name», e o inglês pergunta com o verbo «be»: «what's your name?», nunca «how is your name?». Quem se apresenta primeiro diz «I'm…».","v":"e96b8188"},{"idioma":"en","id":"en-f327","tipo":"frase","en":"I'd like a table for two.","pt":"Queria uma mesa para dois.","aceitas":["queria uma mesa para dois","gostaria de uma mesa para dois","uma mesa para dois por favor","tem mesa para dois"],"aceitasEn":["id like a table for two","i would like a table for two","a table for two please"],"distratores":["Queria uma mesa para fora.","Queria uma mesa na janela.","Queria uma conta para dois.","Queria um cardápio para dois."],"nivel":"A2","tags":["expressão","comida","viagem"],"nota":"«I'd like» é o pedido educado padrão, e serve para mesa, prato e bebida; «I want» soa a exigência. O número de pessoas vai com «for»: «for two», nunca «of two».","v":"f092b1e6"},{"idioma":"en","id":"en-f328","tipo":"frase","en":"Can I get this to go?","pt":"Pode embalar para viagem?","aceitas":["pode embalar para viagem","para viagem por favor","e para viagem","pode ser para viagem"],"aceitasEn":["can i get this to go","can i get it to go","to go please"],"regionaisEn":{"can i get this to take away":"na Inglaterra"},"distratores":["Pode embalar para presente?","Pode esquentar para mim?","Pode dividir em dois pratos?","Pode trazer para a mesa?"],"nivel":"A2","tags":["expressão","comida","viagem"],"nota":"«To go» é para levar, nos Estados Unidos: «two coffees to go». Na Inglaterra se diz «to take away», e comer no lugar é «for here» ou «eat in».","v":"2413e2b0"},{"idioma":"en","id":"en-f329","tipo":"frase","en":"I'm looking for a gift.","pt":"Estou procurando um presente.","aceitas":["estou procurando um presente","to procurando um presente","queria um presente","estou buscando um presente"],"aceitasEn":["im looking for a gift","i am looking for a gift","im looking for a present"],"distratores":["Estou embrulhando um presente.","Estou devolvendo um presente.","Estou esperando um presente.","Estou guardando um presente."],"nivel":"A2","tags":["expressão","compras"],"nota":"«To look for» é procurar, e o «for» nunca cai. Sem ele, «look» é olhar, e «look at» é olhar para alguma coisa: a preposição é que diz qual dos três verbos é.","v":"a32c9508"},{"idioma":"en","id":"en-f330","tipo":"frase","en":"I'll see what I can do.","pt":"Vou ver o que dá para fazer.","aceitas":["vou ver o que da para fazer","vou ver o que eu posso fazer","vou ver o que consigo fazer","vou dar uma olhada no que da"],"aceitasEn":["ill see what i can do","i will see what i can do","let me see what i can do"],"distratores":["Vou ver o que você fez.","Vou ver o que falta fazer.","Vou ver quem pode fazer.","Vou ver onde dá para fazer."],"nivel":"B1","tags":["expressão","trabalho"],"nota":"É a promessa cautelosa de quem não garante nada, e o padrão no trabalho. «I'll do what I can» promete mais; «there's nothing I can do» fecha a porta de vez.","v":"1975236a"},{"idioma":"en","id":"en-f331","tipo":"frase","en":"Let me think about it.","pt":"Deixa eu pensar.","aceitas":["deixa eu pensar","deixe eu pensar","vou pensar","me deixa pensar"],"aceitasEn":["let me think about it","let me think","ill think about it"],"distratores":["Deixa eu decidir.","Deixa eu perguntar.","Deixa eu explicar.","Deixa eu terminar."],"nivel":"B1","tags":["expressão","social"],"nota":"«Let me» mais infinitivo sem «to»: «let me think», «let me see». E «think about» é pensar sobre; «think of» é lembrar ou ter uma ideia — «I can't think of his name».","v":"1c503018"},{"idioma":"en","id":"en-f332","tipo":"frase","en":"I'll get back to you.","pt":"Eu te dou um retorno.","aceitas":["eu te dou um retorno","vou te dar um retorno","depois eu te falo","eu te respondo depois"],"aceitasEn":["ill get back to you","i will get back to you","ill get back to you on that"],"distratores":["Eu volto para você.","Eu te devolvo depois.","Eu te acompanho de volta.","Eu te pago de volta."],"nivel":"B1","tags":["expressão","trabalho"],"nota":"«Get back to someone» é dar retorno, e não voltar a alguém. Com «on» entra o assunto: «I'll get back to you on the price». Sem o «to», «get back» é voltar mesmo.","v":"6f8428d5"},{"idioma":"en","id":"en-f333","tipo":"frase","en":"Something came up.","pt":"Surgiu um imprevisto.","aceitas":["surgiu um imprevisto","apareceu um imprevisto","deu um imprevisto","surgiu uma coisa"],"aceitasEn":["something came up","something has come up","somethings come up"],"distratores":["Subiu alguma coisa.","Chegou alguma coisa.","Sobrou um imprevisto.","Passou o imprevisto."],"nivel":"B1","tags":["expressão","social"],"nota":"«To come up» é aparecer de repente: um assunto na reunião, um problema no meio do dia. É a desculpa padrão para desmarcar, e de propósito não diz o que foi.","v":"e14ba3e3"},{"idioma":"en","id":"en-f334","tipo":"frase","en":"I'm on the fence.","pt":"Estou em dúvida.","aceitas":["estou em duvida","estou na duvida","nao me decidi ainda","estou indeciso"],"aceitasEn":["im on the fence","i am on the fence","im still on the fence"],"distratores":["Estou na cerca.","Estou no muro.","Estou do lado de fora.","Estou de um lado só."],"nivel":"B1","tags":["expressão","social"],"nota":"«The fence» é a cerca, e quem está sentado nela não desceu por nenhum dos dois lados. «To sit on the fence» é o mesmo, e «a fence-sitter» é quem vive assim.","v":"552e0d40"},{"idioma":"en","id":"en-f335","tipo":"frase","en":"Let's call it even.","pt":"Vamos ficar quites.","aceitas":["vamos ficar quites","estamos quites","vamos considerar quitado","ninguem deve nada a ninguem"],"aceitasEn":["lets call it even","let us call it even","well call it even"],"distratores":["Vamos chamar de igual.","Vamos ligar mesmo assim.","Vamos dividir no meio.","Vamos marcar outro dia."],"nivel":"B1","tags":["expressão","social"],"nota":"«To call it» é dar algo por encerrado de certo modo: «let's call it even», «let's call it a draw», «let's call it a day». E «even» aqui é empatado, sem saldo de lado nenhum.","v":"0f810702"},{"idioma":"en","id":"en-f336","tipo":"frase","en":"I didn't mean to.","pt":"Não foi por querer.","aceitas":["nao foi por querer","nao foi de proposito","foi sem querer","nao fiz por mal"],"aceitasEn":["i didnt mean to","i did not mean to","i really didnt mean to"],"distratores":["Não quis dizer isso.","Não quis significar nada.","Não entendi a intenção.","Não concordei com isso."],"nivel":"B1","tags":["expressão","falso-amigo","social"],"nota":"«To mean to» é ter a intenção; «to mean» sozinho é significar. «I didn't mean to» é a desculpa de quem fez sem querer, e o verbo fica solto no fim, sem repetir o que foi.","v":"99910a9d"},{"idioma":"en","id":"en-f337","tipo":"frase","en":"Count me in.","pt":"Conte comigo.","aceitas":["conte comigo","conta comigo","eu entro","estou dentro"],"aceitasEn":["count me in","count me in too","im in"],"distratores":["Me conte tudo.","Me inclua na conta.","Me conte depois.","Me tire da lista."],"nivel":"B1","tags":["expressão","social"],"nota":"«Count me in» é entrar no plano, e «count me out» é ficar de fora. O verbo é o de contar números — contar uma história é «to tell», e os dois não se trocam.","v":"ce3ed2ad"},{"idioma":"en","id":"en-f338","tipo":"frase","en":"He's got a lot on his plate.","pt":"Ele está com muita coisa na mão.","aceitas":["ele esta com muita coisa na mao","ele esta sobrecarregado","ele esta com muita coisa para resolver","ele tem muita coisa na cabeca"],"aceitasEn":["hes got a lot on his plate","he has a lot on his plate","hes got too much on his plate"],"distratores":["Ele está com muita comida no prato.","Ele está com o prato cheio de comida.","Ele está com muita sorte agora.","Ele está com muita pressa hoje."],"nivel":"B2","tags":["expressão","trabalho"],"nota":"«A lot on your plate» é o prato cheio de tarefas, e não de comida. É como se diz que alguém não dá conta de mais nada, e serve de recusa educada a um pedido novo.","v":"887ce8df"},{"idioma":"en","id":"en-f339","tipo":"frase","en":"That's a hard sell.","pt":"Isso é difícil de emplacar.","aceitas":["isso e dificil de emplacar","isso e dificil de convencer","isso nao vai colar","isso e dificil de vender"],"aceitasEn":["thats a hard sell","that is a hard sell","its a hard sell"],"distratores":["Isso é uma liquidação difícil.","Isso é um vendedor difícil.","Isso é fácil de aceitar.","Isso é bom de negociar."],"nivel":"B2","tags":["expressão","trabalho"],"nota":"«A hard sell» é a ideia que custa a convencer, e também a venda insistente do vendedor chato. O contrário é «an easy sell», e convencer alguém é «to sell someone on an idea».","v":"f9dc9e6c"},{"idioma":"en","id":"en-f340","tipo":"frase","en":"She didn't mince her words.","pt":"Ela não poupou palavras.","aceitas":["ela nao poupou palavras","ela falou sem rodeios","ela foi direta","ela nao fez cerimonia"],"aceitasEn":["she didnt mince her words","she did not mince her words","she didnt mince words"],"distratores":["Ela não picou as palavras.","Ela não moeu as palavras.","Ela não disse nada.","Ela escolheu bem as palavras."],"nivel":"C1","tags":["expressão","social","formal"],"nota":"«To mince» é picar miúdo — a carne moída é «minced meat». Quem não pica as palavras diz o que pensa sem amaciar, e o que se elogia aí é a coragem, não a gentileza.","v":"1841a78e"},{"idioma":"en","id":"en-f341","tipo":"frase","en":"It was touch and go.","pt":"Foi por um fio.","aceitas":["foi por um fio","foi por pouco","esteve por um fio","foi no limite"],"aceitasEn":["it was touch and go","it was touch and go for a while"],"distratores":["Foi tocar e sair.","Foi chegar e passar.","Foi tranquilo até o fim.","Foi rápido e fácil."],"nivel":"C1","tags":["expressão","saúde","formal"],"nota":"«Touch and go» é o momento em que a coisa podia desandar: a cirurgia, o pouso, o negócio. Vem da navegação, do barco que toca o fundo e segue sem encalhar.","v":"544df119"},{"idioma":"en","id":"en-f342","tipo":"frase","en":"He's of two minds about it.","pt":"Ele está dividido quanto a isso.","aceitas":["ele esta dividido quanto a isso","ele esta dividido","ele nao se decidiu","ele esta dividido sobre isso"],"aceitasEn":["hes of two minds about it","he is of two minds about it"],"regionaisEn":{"hes in two minds about it":"na Inglaterra","he is in two minds about it":"na Inglaterra"},"distratores":["Ele está com duas ideias na cabeça.","Ele tem duas opiniões diferentes.","Ele está decidido quanto a isso.","Ele está distraído quanto a isso."],"nivel":"C1","tags":["expressão","social","formal"],"nota":"«Of two minds» é estar dividido, com a cabeça puxando para os dois lados ao mesmo tempo. Na Inglaterra se diz «in two minds» — a preposição é a única diferença.","v":"1a27d86a"},{"idioma":"en","id":"en-f343","tipo":"frase","en":"That's the long and short of it.","pt":"Em poucas palavras, é isso.","aceitas":["em poucas palavras e isso","resumindo e isso","em resumo e isso","no fim das contas e isso"],"aceitasEn":["thats the long and short of it","that is the long and short of it"],"distratores":["É o longo e o curto da história.","É o comprimento e a largura.","É só o começo da conversa.","É o melhor de tudo isso."],"nivel":"C1","tags":["expressão","formal"],"nota":"«The long and short of it» é o resumo depois de muita explicação: tudo que importa, numa frase. Vem antes ou depois do resumo, e nunca no meio dele.","v":"54b36c29"},{"idioma":"en","id":"en-f344","tipo":"frase","en":"They were at loggerheads.","pt":"Eles estavam às turras.","aceitas":["eles estavam as turras","eles estavam brigados","eles nao se entendiam","eles estavam em pe de guerra"],"aceitasEn":["they were at loggerheads","they were at loggerheads over it"],"distratores":["Eles estavam de cabeça baixa.","Eles estavam no mesmo barco.","Eles estavam de acordo.","Eles estavam de luto."],"nivel":"C1","tags":["expressão","social","formal"],"nota":"«At loggerheads» é em choque aberto, sem saída: duas partes que não cedem. É de registro escrito, e quase sempre vem com «over» — «at loggerheads over the budget».","v":"fe2c5144"},{"idioma":"en","id":"en-f345","tipo":"frase","en":"I'd be remiss not to mention it.","pt":"Seria falta minha não mencionar.","aceitas":["seria falta minha nao mencionar","nao posso deixar de mencionar","seria negligencia minha nao mencionar","seria falha minha nao mencionar"],"aceitasEn":["id be remiss not to mention it","i would be remiss not to mention it"],"distratores":["Seria remissão minha não mencionar.","Seria remoto não mencionar.","Seria melhor não mencionar.","Seria indiferente não mencionar."],"nivel":"C2","tags":["expressão","formal"],"nota":"«Remiss» é negligente no dever, e vive nesta fórmula: «I'd be remiss not to…», de discurso e de agradecimento. Nada tem de remissão nem de remoto, por mais que a letra pareça.","v":"c80b35b5"},{"idioma":"en","id":"en-f346","tipo":"frase","en":"It is incumbent on us to act.","pt":"Cabe a nós agir.","aceitas":["cabe a nos agir","e nossa obrigacao agir","temos o dever de agir","e nosso dever agir"],"aceitasEn":["it is incumbent on us to act","it is incumbent upon us to act"],"distratores":["É incômodo para nós agir.","É incerto que nós ajamos.","É melhor nós não agirmos.","É opcional para nós agir."],"nivel":"C2","tags":["expressão","jurídico","formal"],"nota":"«Incumbent on» é o dever que recai sobre alguém. O mesmo adjetivo tem outro uso: «the incumbent president» é o que está no cargo. «Upon» vale igual e soa mais solene.","v":"4f5893bf"},{"idioma":"en","id":"en-f347","tipo":"frase","en":"He has an axe to grind.","pt":"Ele tem interesse na causa.","aceitas":["ele tem interesse na causa","ele tem interesse proprio nisso","ele nao e imparcial","ele tem um interesse pessoal"],"aceitasEn":["he has an axe to grind","hes got an axe to grind"],"distratores":["Ele tem um machado para afiar.","Ele tem lenha para cortar.","Ele tem pressa de resolver.","Ele é totalmente imparcial."],"nivel":"C2","tags":["expressão","política","formal"],"nota":"«An axe to grind» é o interesse próprio escondido atrás do argumento: quem tem um não discute de graça. A imagem é do machado que se afia na pedra, com calma e com propósito.","v":"b9e4afb2"},{"idioma":"en","id":"en-f348","tipo":"frase","en":"She gave the idea short shrift.","pt":"Ela descartou a ideia sem cerimônia.","aceitas":["ela descartou a ideia sem cerimonia","ela rejeitou a ideia na hora","ela nem considerou a ideia","ela despachou a ideia"],"aceitasEn":["she gave the idea short shrift","she gave short shrift to the idea"],"distratores":["Ela deu um prazo curto para a ideia.","Ela fez um resumo curto da ideia.","Ela reforçou a ideia na hora.","Ela esperou a ideia amadurecer."],"nivel":"C2","tags":["expressão","formal"],"nota":"«Short shrift» era o tempo curto de confissão dado ao condenado antes da pena. Hoje é o descaso rápido com que se recusa alguma coisa, e vem sempre com «give».","v":"d4468c9f"},{"idioma":"en","id":"en-f349","tipo":"frase","en":"That is a moot point.","pt":"Isso já perdeu a importância.","aceitas":["isso ja perdeu a importancia","isso ja nao importa","isso ficou sem importancia","isso e discutivel"],"aceitasEn":["that is a moot point","thats a moot point","its a moot point"],"distratores":["Isso é um ponto mudo.","Isso é um ponto fraco.","Isso é o mais importante.","Isso é um detalhe novo."],"nivel":"C2","tags":["expressão","formal","jurídico"],"nota":"«Moot» tem dois sentidos que se cruzam: nos Estados Unidos é o que já não importa porque está resolvido; na Inglaterra, o que ainda se discute. E nada tem de «mute», que é mudo.","v":"cd20f923"},{"idioma":"en","id":"en-f350","tipo":"frase","en":"He took it in stride.","pt":"Ele encarou com naturalidade.","aceitas":["ele encarou com naturalidade","ele nem se abalou","ele levou na boa","ele lidou com isso sem drama"],"aceitasEn":["he took it in stride","he took everything in stride"],"regionaisEn":{"he took it in his stride":"na Inglaterra"},"distratores":["Ele levou no passo dele.","Ele entrou no ritmo.","Ele ficou abalado com isso.","Ele reclamou de tudo."],"nivel":"C2","tags":["expressão","social","formal"],"nota":"«In stride» é a passada de quem caminha: absorve o problema sem perder o passo. Nos Estados Unidos vai sem possessivo; na Inglaterra se diz «in his stride».","v":"32cd4833"}]};
